    "INVOIC":{ name: "Invoice (EDIFACT)",          family: "commercial", std: "EDIFACT",  triggers: ["shipping","selling"] },
    "PRICAT":{ name: "Price Catalogue (EDIFACT)",  family: "commercial", std: "EDIFACT",  triggers: ["cataloging"] },
