    "BOL":  { name: "Bill of Lading (Ocean eBL)",  family: "logistics",  std: "BIMCO/DCSA", triggers: ["shipping","loading"] },
    "AWB":  { name: "Air Waybill (eAWB)",          family: "logistics",  std: "IATA",     triggers: ["shipping"] },
    "CMR":  { name: "CMR Road Consignment Note",   family: "logistics",  std: "UNECE",    triggers: ["shipping"] },
