    "BATCH":{ name: "Batch Manufacturing Record",  family: "quality",   std: "GMP",      triggers: ["transforming","commissioning"] },
    "DSCSA-T3":{ name: "DSCSA Transaction Document (T3)", family: "regulatory", std: "DSCSA/FDA", triggers: ["shipping","transferring"], industry: ["pharma"] },
