    "8130-3":{ name: "FAA Form 8130-3 Airworthiness", family: "regulatory", std: "FAA",  triggers: ["shipping","repairing","commissioning"], industry: ["aerospace"] },
    "SPEC2000-SHIP":{ name: "SPEC 2000 Shipping Document (Ch.9)", family: "commercial", std: "AIA",triggers: ["shipping"], industry: ["aerospace"] },
    "NADCAP":{ name: "NADCAP Approval Record",     family: "quality",   std: "PRI/SAE", triggers: ["commissioning"], industry: ["aerospace"] },
    // QUALITY / REGULATORY — FOOD & BEVERAGE
    "FSMA204":{ name: "FSMA 204 Traceability Record", family: "regulatory", std: "FDA FSMA", triggers: ["shipping","receiving","transforming"], industry: ["food"] },
    "COOL": { name: "Country of Origin Label",     family: "regulatory", std: "USDA",    triggers: ["shipping"], industry: ["food"] },
    "HACCP":{ name: "HACCP/HARPC Record",          family: "quality",   std: "FDA/Codex",triggers: ["transforming","storing","inspecting"], industry: ["food"] },
    "TEMP": { name: "Temperature/Cold Chain Log",  family: "quality",   std: "GFSI",     triggers: ["shipping","storing","monitoring"], industry: ["food","pharma"] },
