  // ── SimCiv state (separate from civ; allows both to coexist) ──────────────
  const simCiv = {
    booted: false,
    instruments: new Map(),  // giai → instrument record
    sensors:     new Map(),  // cpi  → sensor record
    sites:       new Map(),  // sgln → site record
    operators:   new Map(),  // gsrn → operator record
    eventLog:    [],         // rolling window — last 200 events
    tickCount:   0,
    alertCount:  0,
    runCount:    0,
    calibCount:  0,
  };

  // ── Mint one instrument's full identity tree ───────────────────────────────
  function simBootInstrument(vendor, instr, serialNum) {
    const sn = serialNum || String(1000 + simCiv.instruments.size);
    const giai   = "urn:epc:id:giai:" + vendor.prefix + "." + instr.ref + "-" + sn;
    const site   = "urn:epc:id:sgln:" + vendor.prefix + ".LAB-" + String(Math.floor(Math.random()*9)+1).padStart(3,"0") + ".0";
    const opGsrn = "urn:epc:id:gsrn:" + vendor.prefix + ".OP-" + String(100 + Math.floor(Math.random()*50));
    const gdti   = "urn:epc:id:gdti:" + vendor.prefix + ".SOP." + instr.ref;

    // Register instrument
    try { registerThing({ id: giai, type: "instrument", party: vendor.prefix, source: vendor.source || "gdsn", metadata: { model: instr.model, adf: instr.adf, instrumentType: instr.type } }); } catch(_e) {}

    // Register site + operator
    try { registerThing({ id: site,   type: "location", party: vendor.prefix, source: "gdsn" }); } catch(_e) {}
    try { registerThing({ id: opGsrn, type: "GSRN",     party: vendor.prefix, source: "gdsn" }); } catch(_e) {}

    // Bind SOP document rules
    try { bindDocumentRules(giai, { id: gdti, kind: "sop", limits: instr.sensors.map(s => ({ param: s.param, max: s.nominalMax, alertThreshold: s.alertMax })) }); } catch(_e) {}

    // Commissioning ObjectEvent
    try { writeGraphEvent({ subjectId: giai, type: "ObjectEvent", bizStep: "commissioning", readPoint: site, assertedBy: vendor.prefix, source: "sim-boot" }); } catch(_e) {}

    // Register data carriers
    try { registerCarrier(giai, { carrier: "rfid-epc", tagId: "RFID-" + instr.ref + "-" + sn }); } catch(_e) {}
    try { registerCarrier(giai, { carrier: "qr-urn",   tagId: "QR-"   + instr.ref + "-" + sn }); } catch(_e) {}

    // Bind embedded sensors (CPIs)
    const embeddedChips = [];
    const sensorIds = [];
    instr.sensors.forEach((s, si) => {
      const cpi = "urn:epc:id:cpi:" + s.vendorPrefix + "." + s.partRef + "." + String(sn) + String(si);
      try {
        registerThing({ id: cpi, type: "sensor", party: s.vendorPrefix, source: "gdsn",
          metadata: { model: s.partName, vendor: s.vendorName, param: s.param, nominalMin: s.nominalMin, nominalMax: s.nominalMax, alertMax: s.alertMax }
        });
      } catch(_e) {}
      embeddedChips.push({ id: cpi, type: "sensor", vendorPrefix: s.vendorPrefix, partRef: s.partRef,
        rules: [{ id: "LIMIT-" + s.partRef + "-" + si, kind: "operating-limit", param: s.param, max: s.alertMax }] });
      sensorIds.push(cpi);
      simCiv.sensors.set(cpi, { cpi, param: s.param, nominalMin: s.nominalMin, nominalMax: s.nominalMax, alertMax: s.alertMax,
        vendorName: s.vendorName, partName: s.partName, parentGiai: giai });
    });

    // Boot with embedded chip graph (sets up parent→child rule inheritance)
    try { deviceStartup(giai, { embeddedChips, firmware: "1.0.0", atLocation: site }); } catch(_e) {}

    // ADF protocol binding
    try { bindIndustryVocabulary(giai, vendor.sector === "pharmaceutical" ? "life-science" : "industrial"); } catch(_e) {}

    // Build typed edges: instrument→site (INSTALLED_AT), instrument→operator (OPERATED_BY)
    try { recordEdgeEvent({ fromId: giai, toId: site, rel: "INSTALLED_AT", assertedBy: vendor.prefix, source: "sim-boot" }); } catch(_e) {}
    try { recordEdgeEvent({ fromId: giai, toId: opGsrn, rel: "OPERATED_BY", assertedBy: vendor.prefix, source: "sim-boot" }); } catch(_e) {}

    // Store in simCiv fleet
    const rec = { giai, vendor: vendor.name, prefix: vendor.prefix, model: instr.model, type: instr.type,
      adf: instr.adf, site, opGsrn, sensorIds, sector: vendor.sector,
      lastReading: {}, alerts: [], runs: 0, state: "IDLE", bootedAt: new Date().toISOString() };
    simCiv.instruments.set(giai, rec);
    simCiv.sites.set(site, { site, giai });
    simCiv.operators.set(opGsrn, { opGsrn, giai });
    return rec;
  }

  // ── Boot the full simulated civilization (idempotent) ────────────────────
  function simBootCivilization() {
    if (simCiv.booted) return simFleetStats();
    SIM_VENDORS.forEach(vendor => {
      vendor.instruments.forEach((instr, idx) => {
        simBootInstrument(vendor, instr, String(1000 + idx));
      });
    });
    simCiv.booted = true;
    return simFleetStats();
  }

  // ── Single simulation tick — fires realistic EPCIS events across the fleet ─
  function simTick(opts) {
    var n = (opts && opts.events) || 10;
    var instrKeys = [];
    simCiv.instruments.forEach(function(v, k) { instrKeys.push(k); });
    if (!instrKeys.length) return simFleetStats();

    var SENSOR_EVENTS  = ["SensorEvent"];
    var OBJECT_EVENTS  = ["ObjectEvent"];
    var BIZ_STEPS_OBJ  = ["commissioning","receiving","storing","shipping","inspecting","maintaining"];
    var BIZ_STEPS_SENS = ["iot_sensor_reading","lab_measurement","telemetry","calibration_check"];
    var PROTOCOL_STEPS = ["sample_prep","run_start","data_acquire","run_complete","results_export"];

    for (var i = 0; i < n; i++) {
      var giai = instrKeys[Math.floor(Math.random() * instrKeys.length)];
      var rec  = simCiv.instruments.get(giai);
      if (!rec) continue;

      var roll = Math.random();

      // 50% sensor reading
      if (roll < 0.50 && rec.sensorIds.length) {
        var cpi = rec.sensorIds[Math.floor(Math.random() * rec.sensorIds.length)];
        var sd  = simCiv.sensors.get(cpi);
        if (sd) {
          var span  = sd.nominalMax - sd.nominalMin;
          var reading = sd.nominalMin + Math.random() * span * 1.05; // occasionally drift out
          var isAlert = reading > sd.alertMax;
          rec.lastReading[sd.param] = parseFloat(reading.toFixed(3));
          if (isAlert) { simCiv.alertCount++; rec.alerts.push({ param: sd.param, value: reading, at: new Date().toISOString() }); if (rec.alerts.length > 10) rec.alerts.shift(); }
          try {
            writeGraphEvent({ subjectId: cpi, type: "SensorEvent", bizStep: "iot_sensor_reading",
              readPoint: rec.site, assertedBy: rec.prefix, source: "sim-tick",
              payload: { param: sd.param, value: parseFloat(reading.toFixed(3)), unit: "auto", alert: isAlert } });
          } catch(_e) {}
          // associate reading event to parent instrument too
          try { writeGraphEvent({ subjectId: giai, type: "ObjectEvent", bizStep: "iot_sensor_reading", readPoint: rec.site, assertedBy: rec.prefix, source: "sim-tick" }); } catch(_e) {}
          simCiv.eventLog.push({ at: new Date().toISOString(), type: "SensorEvent", giai, cpi, param: sd.param, value: parseFloat(reading.toFixed(3)), alert: isAlert });
        }
      }
      // 20% protocol run
      else if (roll < 0.70) {
        rec.state = "RUNNING"; rec.runs++; simCiv.runCount++;
        var step = PROTOCOL_STEPS[Math.floor(Math.random() * PROTOCOL_STEPS.length)];
        try { writeGraphEvent({ subjectId: giai, type: "ObjectEvent", bizStep: step, readPoint: rec.site, assertedBy: rec.prefix, source: "sim-tick" }); } catch(_e) {}
        if (step === "run_complete") { rec.state = "IDLE"; }
        simCiv.eventLog.push({ at: new Date().toISOString(), type: "ProtocolEvent", giai, step, model: rec.model });
      }
      // 12% maintenance / calibration
      else if (roll < 0.82) {
        simCiv.calibCount++;
        try { writeGraphEvent({ subjectId: giai, type: "ObjectEvent", bizStep: "maintaining", readPoint: rec.site, assertedBy: rec.prefix, source: "sim-tick" }); } catch(_e) {}
        simCiv.eventLog.push({ at: new Date().toISOString(), type: "MaintenanceEvent", giai, model: rec.model });
      }
      // 10% shipment / receiving
      else if (roll < 0.92) {
        var step2 = BIZ_STEPS_OBJ[Math.floor(Math.random() * BIZ_STEPS_OBJ.length)];
        try { writeGraphEvent({ subjectId: giai, type: "ObjectEvent", bizStep: step2, readPoint: rec.site, assertedBy: rec.prefix, source: "sim-tick" }); } catch(_e) {}
        simCiv.eventLog.push({ at: new Date().toISOString(), type: "ObjectEvent", giai, step: step2, model: rec.model });
      }
      // 8% AI resolution / organic ask
      else {
        var aiId = "urn:epc:id:gsrn:" + rec.prefix + ".AI-SIM-01";
        try { addThingFact({ id: giai, fact: "sim-resolution", value: "ai-resolved", assertedBy: aiId, confidence: 0.91, source: "sim-tick" }); simCiv.eventLog.push({ at: new Date().toISOString(), type: "AIResolution", giai, model: rec.model }); } catch(_e) {}
      }

      // keep log trimmed
      if (simCiv.eventLog.length > 200) simCiv.eventLog.shift();
    }

    simCiv.tickCount++;
    return simFleetStats();
  }

  // ── Fleet stats — what the dashboard reads ────────────────────────────────
  function simFleetStats() {
    var totalInstr   = simCiv.instruments.size;
    var totalSensors = simCiv.sensors.size;
    var running      = 0;
    var totalEvents  = 0;
    var byType       = {};
    var byVendor     = {};
    var bySector     = {};
    simCiv.instruments.forEach(function(r) {
      if (r.state === "RUNNING") running++;
      var evs = [];
      try { evs = (queryEvents && queryEvents({ subjectId: r.giai })) || []; } catch(_e) {}
      totalEvents += evs.length;
      byType[r.type]     = (byType[r.type] || 0) + 1;
      byVendor[r.vendor] = (byVendor[r.vendor] || 0) + 1;
      bySector[r.sector] = (bySector[r.sector] || 0) + 1;
    });
    var topType   = Object.entries(byType).sort(function(a,b){return b[1]-a[1];});
    var topVendor = Object.entries(byVendor).sort(function(a,b){return b[1]-a[1];});
    var topSector = Object.entries(bySector).sort(function(a,b){return b[1]-a[1];});
    return {
      booted:       simCiv.booted,
      instruments:  totalInstr,
      sensors:      totalSensors,
      vendors:      topVendor.length,
      sites:        simCiv.sites.size,
      operators:    simCiv.operators.size,
      tickCount:    simCiv.tickCount,
      runCount:     simCiv.runCount,
      calibCount:   simCiv.calibCount,
      alertCount:   simCiv.alertCount,
      totalEvents:  totalEvents,
      running:      running,
      byType:       topType.map(function(x){return{name:x[0],count:x[1]};}),
      byVendor:     topVendor.map(function(x){return{name:x[0],count:x[1]};}),
      bySector:     topSector.map(function(x){return{name:x[0],count:x[1]};}),
      recentLog:    simCiv.eventLog.slice(-20).reverse(),
    };
  }

  // ── Inspect one simulated instrument deeply ───────────────────────────────
  function simInspectInstrument(giai) {
    var rec = simCiv.instruments.get(giai);
    if (!rec) return { ok: false, error: "not-found" };
    var evs = [];
    try { evs = (queryEvents && queryEvents({ subjectId: giai })) || []; } catch(_e) {}
    var sensorDetails = rec.sensorIds.map(function(cpi) {
      var sd = simCiv.sensors.get(cpi);
      if (!sd) return null;
      var sEvs = [];
      try { sEvs = (queryEvents && queryEvents({ subjectId: cpi })) || []; } catch(_e) {}
      return { cpi, param: sd.param, nominalMin: sd.nominalMin, nominalMax: sd.nominalMax, alertMax: sd.alertMax,
        vendorName: sd.vendorName, partName: sd.partName,
        lastValue: rec.lastReading[sd.param] != null ? rec.lastReading[sd.param] : null,
        sensorEvents: sEvs.length, isAlert: rec.lastReading[sd.param] != null && rec.lastReading[sd.param] > sd.alertMax };
    }).filter(Boolean);
    // graph edges (connections)
    var edges = [];
    try { var th = things.get(giai); if (th) { var eList = edgesBy.get(giai) || []; eList.forEach(function(e){ edges.push(e); }); } } catch(_e) {}
    return {
      ok: true, giai, model: rec.model, type: rec.type, vendor: rec.vendor, prefix: rec.prefix,
      adf: rec.adf, sector: rec.sector, site: rec.site, operator: rec.opGsrn,
      state: rec.state, runs: rec.runs, alerts: rec.alerts.slice(-5),
      lastReading: rec.lastReading, sensorDetails,
      eventCount: evs.length, recentEvents: evs.slice(-8).reverse(),
      edgeCount: edges.length, edges: edges.slice(0, 10),
      bootedAt: rec.bootedAt,
    };
  }

  // ── List all simulated instruments (for the fleet table) ─────────────────
  function simListInstruments(opts) {
    var filter = opts && opts.vendor ? opts.vendor : null;
    var sector = opts && opts.sector ? opts.sector : null;
    var rows = [];
    simCiv.instruments.forEach(function(r, k) {
      if (filter && r.vendor !== filter) return;
      if (sector && r.sector !== sector) return;
      var evCount = 0;
      try { evCount = (queryEvents && queryEvents({ subjectId: k }) || []).length; } catch(_e) {}
      rows.push({ giai: k, model: r.model, type: r.type, vendor: r.vendor, sector: r.sector,
        state: r.state, runs: r.runs, sensors: r.sensorIds.length,
        alerts: r.alerts.length, events: evCount, bootedAt: r.bootedAt });
    });
    return rows;
  }

