  // Computed total — matches slide 35: 2,449
  var _ALLOTROPE_TOTAL = ALLOTROPE_TECHNIQUE_FAMILIES.reduce(function(s,f){return s+f.count;},0);

  // Bind a GS1 GDTI URN to each Allotrope protocol concept
  // Pattern: urn:epc:id:gdti:{vendor_prefix}.{gdtiBase}{conceptIdx}
  // Using Allotrope Foundation's illustrative prefix 0085126 (Thermo Fisher, the primary contributor)
  var _ALLOTROPE_URN_CACHE = new Map();
  var ALLOTROPE_VENDOR_PREFIX = "0085126";  // Thermo Fisher — primary Allotrope contributor

  function allotropeBindURN(techFamily, protocolIdx) {
    var fam = ALLOTROPE_TECHNIQUE_FAMILIES.find(function(f){return f.tech===techFamily;});
    if (!fam) return null;
    var key = techFamily + ":" + protocolIdx;
    if (_ALLOTROPE_URN_CACHE.has(key)) return _ALLOTROPE_URN_CACHE.get(key);
    var protocolName = (fam.protocols[protocolIdx] || fam.protocols[0] || techFamily).replace(/[\s\/\-]/g,"_");
    var urn = "urn:epc:id:gdti:" + ALLOTROPE_VENDOR_PREFIX + "." + fam.gdtiBase + "." + String(protocolIdx+1).padStart(4,"0");
    // Register in the thing graph so it's live state
    try {
      registerThing({ id: urn, type: "allotrope-protocol", party: ALLOTROPE_VENDOR_PREFIX,
        source: "allotrope-adf", metadata: { technique: techFamily, protocol: protocolName,
          adfSchema: fam.adfSchema, silaFeature: fam.silaFeature, count: fam.count } });
    } catch(_e) {}
    _ALLOTROPE_URN_CACHE.set(key, { urn, techFamily, protocolName, adfSchema: fam.adfSchema, color: fam.color });
    return _ALLOTROPE_URN_CACHE.get(key);
  }

  function allotropeGetByTechnique(techFamily) {
    var fam = ALLOTROPE_TECHNIQUE_FAMILIES.find(function(f){return f.tech===techFamily;});
    if (!fam) return null;
    var bindings = [];
    var limit = Math.min(fam.protocols.length, 15);
    for (var i = 0; i < limit; i++) {
      var b = allotropeBindURN(techFamily, i);
      if (b) bindings.push(b);
    }
    return { family: fam, bindings: bindings, totalConcepts: fam.count };
  }

  function allotropeStats() {
    return {
      totalConcepts:  _ALLOTROPE_TOTAL,
      families:       ALLOTROPE_TECHNIQUE_FAMILIES.length,
      boundURNs:      _ALLOTROPE_URN_CACHE.size,
      topFamily:      ALLOTROPE_TECHNIQUE_FAMILIES[0],
      vendorPrefix:   ALLOTROPE_VENDOR_PREFIX,
      families_list:  ALLOTROPE_TECHNIQUE_FAMILIES.map(function(f){return { tech:f.tech, count:f.count, color:f.color, adfSchema:f.adfSchema }; })
    };
  }

  // Expose the raw catalog so the UI can read it without calling functions
  var ALLOTROPE_RDF = {
    families:        ALLOTROPE_TECHNIQUE_FAMILIES,
    total:           _ALLOTROPE_TOTAL,
    vendorPrefix:    ALLOTROPE_VENDOR_PREFIX,
    description:     "Allotrope Foundation ADF ontology — 2,449 protocol concepts across 15 technique families. Every concept binds a GS1 GDTI URN @id via allotropeBindURN(). Source: Allotrope Foundation Creation of Allotrope Ontology and Usage as Rich Metadata (slide 35, IIOT_Network_life_science.pptx — KJ Kail IP).",
    shacl_note:      "Ontologies provide unconstrained vocabulary (= what it is). Data structures (schemas) describe how to use ontologies in a standardized way. SHACL (expressed as RDF) is the W3C standard used for Allotrope Data Models. ThingDaddy adds the GS1 URN @id to every SHACL shape."
  };

