  // ── PharmaCiv state ─────────────────────────────────────────────────────────
  var pharmaCiv = {
    booted:    false,
    companies: new Map(),   // prefix → { company, labs: Map<glnId, labRec> }
    labIndex:  new Map(),   // glnId → labRec
    instrIndex: new Map(),  // giai  → { labGln, companyPrefix, instrRef }
  };

  // ── Mint a GLN URN for a lab ────────────────────────────────────────────────
  function _glnUrn(companyPrefix, labRef, ext) {
    var ext2 = ext || "0";
    return "urn:epc:id:sgln:" + companyPrefix + "." + labRef.replace(/[^A-Z0-9]/gi, "").slice(0,7).padEnd(6,"0") + "." + ext2;
  }

  // ── Get instruments from simCiv that match a list of refs ──────────────────
  function _instrForRefs(refs) {
    var matched = [];
    simCiv.instruments.forEach(function(rec, giai) {
      SIM_VENDORS.forEach(function(v) {
        v.instruments.forEach(function(instr) {
          if (refs.indexOf(instr.ref) !== -1 && giai.indexOf(instr.ref) !== -1 && matched.length < refs.length) {
            matched.push({ giai: giai, ref: instr.ref, model: instr.model, type: instr.type, adf: instr.adf,
              vendor: v.name, vendorPrefix: v.prefix });
          }
        });
      });
    });
    return matched;
  }

  // ── Boot the pharma civilization ───────────────────────────────────────────
  function pharmaBootCivilization() {
    if (pharmaCiv.booted) return pharmaStats();
    // Ensure simCiv is booted first so instruments exist
    if (!simCiv.booted) simBootCivilization();

    PHARMA_COMPANIES.forEach(function(co) {
      var coData = { company: co, labs: new Map(), identities: [] };

      // Register company PGLN
      var pgln = "urn:epc:id:pgln:" + co.prefix + ".0";
      try { registerThing({ id: pgln, type: "party", party: co.prefix, source: co.source,
        metadata: { name: co.name, hq: co.hq, products: co.products } }); } catch(_e) {}

      // Get instruments that match this company's refs
      var instrMatches = _instrForRefs(co.instrumentRefs);

      // Mint each lab
      co.labs.forEach(function(lab, labIdx) {
        var glnId   = _glnUrn(co.prefix, lab.ref, "0");
        var glnBay1 = _glnUrn(co.prefix, lab.ref, "1");
        var glnBay2 = _glnUrn(co.prefix, lab.ref, "2");

        // Register the lab GLN + sub-GLNs (bays)
        try { registerThing({ id: glnId, type: "location", party: co.prefix, source: co.source,
          metadata: { name: lab.name, address: lab.address, country: lab.country, focus: lab.focus } }); } catch(_e) {}
        try { registerThing({ id: glnBay1, type: "location", party: co.prefix, source: co.source,
          metadata: { name: lab.name + " Bay 1", parent: glnId } }); } catch(_e) {}
        try { registerThing({ id: glnBay2, type: "location", party: co.prefix, source: co.source,
          metadata: { name: lab.name + " Bay 2", parent: glnId } }); } catch(_e) {}

        // Operator GSRN for this lab
        var opGsrn = "urn:epc:id:gsrn:" + co.prefix + ".LAB-OP-" + String(labIdx+1).padStart(3,"0");
        try { registerThing({ id: opGsrn, type: "GSRN", party: co.prefix, source: co.source }); } catch(_e) {}

        // Mint consumable lots for this lab (LGTIN = lot-level SGTIN)
        var consumables = [];
        co.products.slice(0, 2).forEach(function(prod, pi) {
          var lgtin = "urn:epc:class:lgtin:" + co.prefix + "." + String(100 + pi).padStart(6,"0") + ".LOT" + String(labIdx+1) + String(pi+1);
          try { registerThing({ id: lgtin, type: "consumable-lot", party: co.prefix, source: co.source,
            metadata: { product: prod, lab: lab.name, lot: "LOT" + String(labIdx+1) + String(pi+1) } }); } catch(_e) {}
          consumables.push({ lgtin, product: prod });
        });

        // Assign instruments to this lab (distribute across labs)
        var labInstrs = instrMatches.filter(function(_,i){ return i % co.labs.length === labIdx; });
        var assignedGIAIs = [];

        labInstrs.forEach(function(instr) {
          // INSTALLED_AT edge: instrument → lab GLN
          try { recordEdgeEvent({ fromId: instr.giai, toId: glnBay1, rel: "INSTALLED_AT",
            assertedBy: co.prefix, source: "pharma-boot" }); } catch(_e) {}
          // OPERATED_BY: instrument → operator
          try { recordEdgeEvent({ fromId: instr.giai, toId: opGsrn, rel: "OPERATED_BY",
            assertedBy: co.prefix, source: "pharma-boot" }); } catch(_e) {}
          // SUPPLIED_BY: pharma company ← vendor
          try { recordEdgeEvent({ fromId: instr.vendorPrefix, toId: co.prefix, rel: "SUPPLIES",
            assertedBy: instr.vendorPrefix, source: "pharma-boot" }); } catch(_e) {}
          // RUNS_PROTOCOL_ON: lab → instrument → ADF protocol
          var adfUrn = allotropeBindURN(
            instr.adf.replace("ResultSchema","").replace("Performance","").trim() || "Chromatography", 0);
          if (adfUrn) {
            try { recordEdgeEvent({ fromId: instr.giai, toId: adfUrn.urn, rel: "RUNS_PROTOCOL",
              assertedBy: co.prefix, source: "pharma-boot" }); } catch(_e) {}
          }
          // PRODUCES: instrument → consumable lot
          if (consumables[0]) {
            try { recordEdgeEvent({ fromId: instr.giai, toId: consumables[0].lgtin, rel: "PRODUCES",
              assertedBy: co.prefix, source: "pharma-boot" }); } catch(_e) {}
          }
          // Commissioning event at pharma lab
          try { writeGraphEvent({ subjectId: instr.giai, type: "ObjectEvent", bizStep: "receiving",
            readPoint: glnId, assertedBy: co.prefix, source: "pharma-boot" }); } catch(_e) {}

          assignedGIAIs.push(instr.giai);
          pharmaCiv.instrIndex.set(instr.giai, { labGln: glnId, companyPrefix: co.prefix,
            instrRef: instr.ref, labName: lab.name, companyName: co.name });
        });

        var labRec = { glnId, glnBay1, glnBay2, lab, opGsrn, assignedGIAIs, consumables,
          companyPrefix: co.prefix, companyName: co.name };
        coData.labs.set(glnId, labRec);
        pharmaCiv.labIndex.set(glnId, labRec);
        coData.identities.push(glnId, glnBay1, opGsrn);
      });

      pharmaCiv.companies.set(co.prefix, coData);
    });

    pharmaCiv.booted = true;
    return pharmaStats();
  }

  // ── Stats for the pharma civilization ──────────────────────────────────────
  function pharmaStats() {
    var totalLabs = 0; var totalInstrs = 0; var totalEdges = 0;
    pharmaCiv.companies.forEach(function(cd) {
      totalLabs += cd.labs.size;
      cd.labs.forEach(function(lab) { totalInstrs += lab.assignedGIAIs.length; });
    });
    pharmaCiv.instrIndex.forEach(function() { totalEdges++; });
    return {
      booted: pharmaCiv.booted,
      companies: pharmaCiv.companies.size,
      labs: totalLabs,
      instruments: totalInstrs,
      edges: totalEdges * 4,   // INSTALLED_AT + OPERATED_BY + SUPPLIES + RUNS_PROTOCOL
      companyList: PHARMA_COMPANIES.map(function(co) {
        return { prefix: co.prefix, name: co.name, hq: co.hq,
          labCount: co.labs.length, products: co.products,
          instrumentRefs: co.instrumentRefs };
      })
    };
  }

  // ── Inspect a pharma company — all labs, instruments, edges ───────────────
  function pharmaInspectCompany(prefix) {
    var cd = pharmaCiv.companies.get(prefix);
    var co = PHARMA_COMPANIES.find(function(c){ return c.prefix===prefix; });
    if (!cd || !co) return { ok: false, error: "not-found" };
    var labList = [];
    cd.labs.forEach(function(lab) {
      var instrDetails = lab.assignedGIAIs.map(function(giai) {
        var simRec = simCiv.instruments.get(giai);
        var driver = simRec ? (SILA_DRIVERS[simRec.type] || null) : null;
        var evs = [];
        try { evs = (queryEvents && queryEvents({ subjectId: giai })) || []; } catch(_e) {}
        var edges2 = [];
        try { var eList = edgesBy.get(giai) || []; eList.forEach(function(e){ edges2.push(e); }); } catch(_e) {}
        return {
          giai, model: simRec ? simRec.model : giai,
          type: simRec ? simRec.type : "instrument",
          vendor: simRec ? simRec.vendor : "unknown",
          adf: simRec ? simRec.adf : null,
          sila: driver ? { feature: driver.feature, version: driver.version,
            commandCount: driver.commands.length, observableCount: driver.observables.length } : null,
          sensorIds: simRec ? simRec.sensorIds : [],
          state: simRec ? simRec.state : "UNKNOWN",
          runs: simRec ? simRec.runs : 0,
          alerts: simRec ? simRec.alerts.length : 0,
          lastReading: simRec ? simRec.lastReading : {},
          eventCount: evs.length,
          recentEvents: evs.slice(-4).reverse(),
          edgeCount: edges2.length,
          edges: edges2.slice(0,6)
        };
      });
      labList.push({
        glnId: lab.glnId, name: lab.lab.name, address: lab.lab.address,
        country: lab.lab.country, focus: lab.lab.focus,
        opGsrn: lab.opGsrn, instruments: instrDetails,
        consumables: lab.consumables
      });
    });
    return { ok: true, prefix, name: co.name, hq: co.hq, mo: co.mo,
      pgln: "urn:epc:id:pgln:" + prefix + ".0",
      products: co.products, labs: labList,
      labCount: labList.length,
      totalInstruments: labList.reduce(function(s,l){ return s+l.instruments.length; }, 0) };
  }

  // ── Inspect a single lab — full graph ──────────────────────────────────────
  function pharmaInspectLab(glnId) {
    var lab = pharmaCiv.labIndex.get(glnId);
    if (!lab) return { ok: false, error: "not-found" };
    var co = PHARMA_COMPANIES.find(function(c){ return c.prefix===lab.companyPrefix; });
    var instrDetails = lab.assignedGIAIs.map(function(giai) {
      var simRec = simCiv.instruments.get(giai);
      var driver = simRec ? (SILA_DRIVERS[simRec.type] || null) : null;
      var evs = [];
      try { evs = (queryEvents && queryEvents({ subjectId: giai })) || []; } catch(_e) {}
      var sensorFull = (simRec ? simRec.sensorIds : []).map(function(cpi) {
        var sd = simCiv.sensors.get(cpi);
        return sd ? { cpi, param: sd.param, lastValue: simRec.lastReading[sd.param] != null ? simRec.lastReading[sd.param] : null,
          alertMax: sd.alertMax, vendorName: sd.vendorName, partName: sd.partName } : null;
      }).filter(Boolean);
      return { giai, model: simRec ? simRec.model : giai, type: simRec ? simRec.type : "instrument",
        vendor: simRec ? simRec.vendor : "unknown", adf: simRec ? simRec.adf : null,
        sila: driver, sensors: sensorFull, state: simRec ? simRec.state : "UNKNOWN",
        runs: simRec ? simRec.runs : 0, alerts: simRec ? simRec.alerts.length : 0,
        eventCount: evs.length, recentEvents: evs.slice(-6).reverse() };
    });
    return { ok: true, glnId, name: lab.lab.name, address: lab.lab.address,
      country: lab.lab.country, focus: lab.lab.focus,
      companyName: lab.companyName, companyPrefix: lab.companyPrefix,
      pgln: co ? "urn:epc:id:pgln:" + co.prefix + ".0" : null,
      opGsrn: lab.opGsrn, consumables: lab.consumables,
      instruments: instrDetails,
      instrumentCount: instrDetails.length };
  }

  // ── Inspect a single instrument in pharma context ─────────────────────────
  function pharmaInspectInstrument(giai) {
    var ctx = pharmaCiv.instrIndex.get(giai);
    var base = simInspectInstrument(giai);
    if (!base || !base.ok) return base;
    var driver = SILA_DRIVERS[base.type] || null;
    var adfFamily = null;
    if (base.adf) {
      var techKey = base.adf.replace("ResultSchema","").replace("Performance","").trim();
      adfFamily = ALLOTROPE_TECHNIQUE_FAMILIES.find(function(f){
        return f.adfSchema === base.adf || f.tech.replace(/[\s\-\/]/g,"") === techKey.replace(/[\s\-\/]/g,"");
      }) || null;
    }
    return Object.assign({}, base, {
      pharmaCiv: ctx || null,
      silaDriver: driver,
      allotropeFamily: adfFamily ? {
        tech: adfFamily.tech, count: adfFamily.count, color: adfFamily.color,
        protocols: adfFamily.protocols.slice(0,5),
        sampleUrn: "urn:epc:id:gdti:" + ALLOTROPE_VENDOR_PREFIX + "." + adfFamily.gdtiBase + ".0001"
      } : null
    });
  }

  // ── Full civilization drill-down: industry → companies → labs → instruments
  function pharmaDrilldown(level, id) {
    // level: "industry" | "company" | "lab" | "instrument"
    if (level === "industry") {
      return { level: "industry", name: "Pharmaceutical",
        companies: PHARMA_COMPANIES.map(function(co) {
          return { prefix: co.prefix, name: co.name, hq: co.hq,
            labCount: co.labs.length, products: co.products.slice(0,3) };
        }) };
    }
    if (level === "company") return pharmaInspectCompany(id);
    if (level === "lab")     return pharmaInspectLab(id);
    if (level === "instrument") return pharmaInspectInstrument(id);
    return { ok: false, error: "unknown level" };
  }

  // ── End of PharmaCiv engine ───────────────────────────────────────────────

  // ╔══════════════════════════════════════════════════════════════════════════╗
  // ║  CIVILIZATION GRAPH ENGINE                                               ║
  // ║  Builds the full node/edge dataset for the force-directed visual        ║
  // ║  Supernodes: FDA · EMA · GS1 · FedEx · UPS · AWS · Azure · Google      ║
  // ║  Hubs:       Pharma companies · Instrument vendors · Sensor makers      ║
  // ║  Leaves:     Lab GLNs · Instruments · Sensors · Consumable lots         ║
  // ╚══════════════════════════════════════════════════════════════════════════╝

  function buildCivGraph(opts) {
    var includePharma   = !opts || opts.pharma    !== false;
    var includeLogistic = !opts || opts.logistics !== false;
    var includeCloud    = !opts || opts.cloud     !== false;
    var includeRegulat  = !opts || opts.regulatory !== false;
    var includeSensors  = !opts || opts.sensors   !== false;
    var includeSemi     = !opts || opts.semi      !== false;   // TSMC, Samsung + fab ecosystem
    var includeEdi      = !opts || opts.edi       !== false;   // TradeVAN, KTNet, smart switches
    var showLabs        = !opts || opts.labs      !== false;

    var nodes = [];  // { id, label, type, size, color, sector, x0, y0 }
    var edges = [];  // { from, to, rel, color, width }
    var idSet = new Set();

    function addNode(n) {
      if (idSet.has(n.id)) return;
      idSet.add(n.id);
      nodes.push(n);
    }
    function addEdge(e) {
      edges.push(e);
    }

    // ── Color palette ─────────────────────────────────────────────────────
    var COL = {
      regulatory: "#DC2626",   // red    — FDA, EMA, GS1, WHO
      logistics:  "#D97706",   // amber  — FedEx, UPS, DHL, Maersk
      cloud:      "#0369A1",   // sky    — AWS, Azure, GCP
      pharma:     "#166534",   // green  — pharma companies
      vendor:     "#1E40AF",   // blue   — instrument vendors
      sensor:     "#7C3AED",   // purple — sensor makers
      lab:        "#059669",   // teal   — lab GLNs
      instrument: "#0891B2",   // cyan   — instruments
      consumable: "#92400E",   // brown  — lots/consumables
      ai:         "#6D28D9",   // violet — AI agents
    };

    var REL_COL = {
      REGULATES:     "#DC2626",
      CERTIFIES:     "#DC2626",
      SHIPS:         "#D97706",
      ROUTES:        "#D97706",
      HOSTS:         "#0369A1",
      SUPPLIES:      "#1E40AF",
      INSTALLED_AT:  "#0891B2",
      EMBEDDED_IN:   "#7C3AED",
      RUNS_PROTOCOL: "#059669",
      PRODUCES:      "#92400E",
      OPERATED_BY:   "#6B7280",
      REGISTERS:     "#DC2626",
    };

    // ── SUPERNODES: Regulatory ─────────────────────────────────────────────
    if (includeRegulat) {
      var regulatory = [
        { id:"FDA",  label:"FDA",  sublabel:"21 CFR · DSCSA · UDI",  size:52, gravity:1.0 },
        { id:"EMA",  label:"EMA",  sublabel:"EU MDR · Annex 11",      size:42, gravity:0.9 },
        { id:"GS1",  label:"GS1",  sublabel:"2M companies · 6B scans",size:48, gravity:0.95 },
        { id:"WHO",  label:"WHO",  sublabel:"ICH · Global GMP",       size:36, gravity:0.8 },
      ];
      regulatory.forEach(function(r) {
        addNode({ id:r.id, label:r.label, sublabel:r.sublabel, type:"regulatory",
          size:r.size, color:COL.regulatory, gravity:r.gravity });
      });
    }

    // ── SUPERNODES: Logistics ──────────────────────────────────────────────
    if (includeLogistic) {
      var logistics = [
        { id:"FEDEX",  label:"FedEx",  sublabel:"16M packages/day · SSCC",   size:44, color:"#6D1A7A" },
        { id:"UPS",    label:"UPS",    sublabel:"22M packages/day · SSCC",   size:46, color:"#7B3F00" },
        { id:"DHL",    label:"DHL",    sublabel:"Global pharma cold chain",   size:38, color:"#CC0000" },
        { id:"MAERSK", label:"Maersk", sublabel:"Ocean freight · containers", size:34, color:"#0074C8" },
      ];
      logistics.forEach(function(l) {
        addNode({ id:l.id, label:l.label, sublabel:l.sublabel, type:"logistics",
          size:l.size, color:l.color || COL.logistics, gravity:0.75 });
        // Every logistics node routes through FDA (pharma cold chain compliance)
        if (includeRegulat) {
          addEdge({ from:l.id, to:"FDA", rel:"CERTIFIES", color:REL_COL.CERTIFIES, width:1.5 });
        }
        // GS1 issues SSCCs to logistics carriers
        if (includeRegulat) {
          addEdge({ from:"GS1", to:l.id, rel:"REGISTERS", color:REL_COL.REGISTERS, width:1 });
        }
      });
    }

    // ── SUPERNODES: Cloud ──────────────────────────────────────────────────
    if (includeCloud) {
      var clouds = [
        { id:"AWS",    label:"AWS",    sublabel:"IoT Core · Greengrass",    size:46, color:"#FF9900" },
        { id:"AZURE",  label:"Azure",  sublabel:"IoT Hub · Digital Twins",  size:44, color:"#0078D4" },
        { id:"GCP",    label:"GCP",    sublabel:"IoT Core · BigQuery",      size:40, color:"#4285F4" },
        { id:"SAP",    label:"SAP",    sublabel:"ERP · iDOC · MATMAS",      size:38, color:"#0070C0" },
      ];
      clouds.forEach(function(c) {
        addNode({ id:c.id, label:c.label, sublabel:c.sublabel, type:"cloud",
          size:c.size, color:c.color, gravity:0.7 });
        if (includeRegulat) {
          addEdge({ from:c.id, to:"FDA", rel:"CERTIFIES", color:REL_COL.CERTIFIES, width:1 });
        }
      });
    }

    // ── GS1 → all prefixes (the registry role) ────────────────────────────
    // GS1 is the issuing authority for every prefix in the graph

    // ── INSTRUMENT VENDORS ─────────────────────────────────────────────────
    var vendorNodes = {};
    SIM_VENDORS.forEach(function(v) {
      var instrCount = v.instruments.length;
      var sz = 20 + instrCount * 3;
      addNode({ id:"V:"+v.prefix, label:v.name.split(" ")[0], sublabel:v.name,
        type:"vendor", size:sz, color:COL.vendor, gravity:0.6,
        prefix:v.prefix, sector:v.sector });
      vendorNodes[v.prefix] = true;
      // GS1 issues prefix to vendor
      if (includeRegulat) {
        addEdge({ from:"GS1", to:"V:"+v.prefix, rel:"REGISTERS", color:REL_COL.REGISTERS, width:1 });
      }
      // Vendor ships via FedEx/UPS
      if (includeLogistic) {
        addEdge({ from:"V:"+v.prefix, to:"FEDEX", rel:"SHIPS", color:REL_COL.SHIPS, width:1 });
        addEdge({ from:"V:"+v.prefix, to:"UPS",   rel:"SHIPS", color:REL_COL.SHIPS, width:1 });
      }
      // Vendor registered on cloud
      if (includeCloud) {
        addEdge({ from:"V:"+v.prefix, to:"AWS",   rel:"HOSTS", color:REL_COL.HOSTS, width:1 });
      }
      // FDA clears instruments (510(k) or PMA)
      if (includeRegulat && (v.sector==="medical-device"||v.sector==="pharmaceutical")) {
        addEdge({ from:"FDA", to:"V:"+v.prefix, rel:"REGULATES", color:REL_COL.REGULATES, width:1.5 });
      }

      // Sensor vendor sub-nodes
      if (includeSensors) {
        var sensorPrefixes = {};
        v.instruments.forEach(function(instr) {
          instr.sensors.forEach(function(s) {
            if (!sensorPrefixes[s.vendorPrefix]) {
              sensorPrefixes[s.vendorPrefix] = { name:s.vendorName, prefix:s.vendorPrefix };
            }
          });
        });
        Object.values(sensorPrefixes).forEach(function(sv) {
          var snid = "S:"+sv.prefix;
          if (!idSet.has(snid)) {
            addNode({ id:snid, label:sv.name.split(" ")[0], sublabel:sv.name+" (sensor)",
              type:"sensor", size:18, color:COL.sensor, gravity:0.4, prefix:sv.prefix });
            if (includeRegulat) {
              addEdge({ from:"GS1", to:snid, rel:"REGISTERS", color:REL_COL.REGISTERS, width:0.8 });
            }
          }
          // Sensor EMBEDDED_IN instrument vendor's product line
          addEdge({ from:snid, to:"V:"+v.prefix, rel:"EMBEDDED_IN",
            color:REL_COL.EMBEDDED_IN, width:1.2 });
        });
      }
    });

    // ── PHARMA COMPANIES ───────────────────────────────────────────────────
    if (includePharma && pharmaCiv.booted) {
      PHARMA_COMPANIES.forEach(function(co) {
        var sz = 28 + co.products.length * 2 + co.labs.length * 2;
        addNode({ id:"P:"+co.prefix, label:co.name.split(" ")[0], sublabel:co.name,
          type:"pharma", size:sz, color:COL.pharma, gravity:0.65,
          prefix:co.prefix, hq:co.hq });

        // GS1 issues prefix
        if (includeRegulat) {
          addEdge({ from:"GS1", to:"P:"+co.prefix, rel:"REGISTERS", color:REL_COL.REGISTERS, width:1 });
          // FDA regulates every pharma company
          addEdge({ from:"FDA", to:"P:"+co.prefix, rel:"REGULATES", color:REL_COL.REGULATES, width:2 });
          // EMA for European companies
          if (co.mo !== "GS1 US") {
            addEdge({ from:"EMA", to:"P:"+co.prefix, rel:"REGULATES", color:REL_COL.REGULATES, width:1.5 });
          }
        }
        // Cloud hosting
        if (includeCloud) {
          addEdge({ from:"P:"+co.prefix, to:"AWS",   rel:"HOSTS", color:REL_COL.HOSTS, width:1 });
          addEdge({ from:"P:"+co.prefix, to:"AZURE", rel:"HOSTS", color:REL_COL.HOSTS, width:1 });
          addEdge({ from:"P:"+co.prefix, to:"SAP",   rel:"HOSTS", color:REL_COL.HOSTS, width:1 });
        }
        // Receives shipments via FedEx/UPS
        if (includeLogistic) {
          addEdge({ from:"FEDEX", to:"P:"+co.prefix, rel:"SHIPS", color:REL_COL.SHIPS, width:1.5 });
          addEdge({ from:"UPS",   to:"P:"+co.prefix, rel:"SHIPS", color:REL_COL.SHIPS, width:1.5 });
        }

        // Instrument vendor SUPPLIES this pharma company
        var cd = pharmaCiv.companies.get(co.prefix);
        var suppliedBy = new Set();
        if (cd) {
          cd.labs.forEach(function(lab) {
            lab.assignedGIAIs.forEach(function(giai) {
              var ctx = pharmaCiv.instrIndex.get(giai);
              var simRec = simCiv.instruments.get(giai);
              if (simRec && !suppliedBy.has(simRec.prefix)) {
                suppliedBy.add(simRec.prefix);
                addEdge({ from:"V:"+simRec.prefix, to:"P:"+co.prefix,
                  rel:"SUPPLIES", color:REL_COL.SUPPLIES, width:2 });
              }
            });

            // Lab GLN sub-nodes
            if (showLabs) {
              addNode({ id:"L:"+lab.glnId, label:lab.lab.ref || lab.lab.name.slice(0,6),
                sublabel:lab.lab.name, type:"lab", size:14, color:COL.lab,
                address:lab.lab.address, focus:lab.lab.focus });
              addEdge({ from:"P:"+co.prefix, to:"L:"+lab.glnId,
                rel:"INSTALLED_AT", color:REL_COL.INSTALLED_AT, width:1.5 });
              // Instruments at this lab
              lab.assignedGIAIs.forEach(function(giai) {
                var simRec = simCiv.instruments.get(giai);
                if (simRec) {
                  var instrId = "I:"+giai;
                  addNode({ id:instrId, label:simRec.model.split(" ").slice(0,2).join(" "),
                    sublabel:simRec.model, type:"instrument", size:11, color:COL.instrument,
                    giai:giai, adf:simRec.adf, state:simRec.state });
                  addEdge({ from:"L:"+lab.glnId, to:instrId,
                    rel:"INSTALLED_AT", color:REL_COL.INSTALLED_AT, width:1 });
                  addEdge({ from:"V:"+simRec.prefix, to:instrId,
                    rel:"SUPPLIES", color:REL_COL.SUPPLIES, width:0.8 });
                  // Consumable lots
                  lab.consumables.forEach(function(cons) {
                    var consId = "C:"+cons.lgtin;
                    if (!idSet.has(consId)) {
                      addNode({ id:consId, label:cons.product.slice(0,8),
                        sublabel:cons.product+" lot", type:"consumable",
                        size:9, color:COL.consumable });
                      addEdge({ from:instrId, to:consId, rel:"PRODUCES",
                        color:REL_COL.PRODUCES, width:0.8 });
                      if (includeLogistic) {
                        addEdge({ from:"FEDEX", to:consId, rel:"SHIPS",
                          color:REL_COL.SHIPS, width:0.6 });
                      }
                      if (includeRegulat) {
                        addEdge({ from:"FDA", to:consId, rel:"REGULATES",
                          color:REL_COL.REGULATES, width:0.8 });
                      }
                    } else {}
                    idSet.add("C:"+cons.lgtin);
                  });
                }
              });
            }
          });
        }
      });
    }

    // ── AI agent node ──────────────────────────────────────────────────────
    addNode({ id:"TDAG", label:"ThingDaddy\nAI", sublabel:"Physical AI agent · GSRN",
      type:"ai", size:30, color:COL.ai, gravity:0.8 });
    // AI connects to every cloud and reads GS1
    if (includeCloud) {
      addEdge({ from:"TDAG", to:"AWS",   rel:"HOSTS", color:COL.ai, width:1.5 });
      addEdge({ from:"TDAG", to:"AZURE", rel:"HOSTS", color:COL.ai, width:1.5 });
      addEdge({ from:"TDAG", to:"GCP",   rel:"HOSTS", color:COL.ai, width:1.5 });
    }
    if (includeRegulat) {
      addEdge({ from:"TDAG", to:"GS1", rel:"REGISTERS", color:COL.ai, width:2 });
      addEdge({ from:"FDA",  to:"TDAG", rel:"CERTIFIES", color:REL_COL.CERTIFIES, width:1 });
    }

    return {
      nodes: nodes,
      edges: edges,
      stats: {
        nodeCount:  nodes.length,
        edgeCount:  edges.length,
        byType:     nodes.reduce(function(m,n){ m[n.type]=(m[n.type]||0)+1; return m; }, {}),
        supernodes: nodes.filter(function(n){ return (n.gravity||0)>=0.7; }).map(function(n){ return n.label; })
      }
    };
  }

  // ── End of CivGraph engine ────────────────────────────────────────────────

  // ╔══════════════════════════════════════════════════════════════════════════╗
  // ║  PHARMA VALUE CHAIN ENGINE                                               ║
  // ║  The complete journey: Discovery → Clinical → Mfg → Regulation →        ║
  // ║  Distribution → Retail Pharmacy → Clinical/Hospital → Patient           ║
  // ║                                                                          ║
  // ║  Includes:                                                               ║
  // ║  · Consumable catalog (plates, reagents, columns, media, lots)          ║
  // ║  · 3PL wholesalers (McKesson, AmerisourceBergen, Cardinal Health)       ║
  // ║  · CROs + CMOs (IQVIA, Lonza, Catalent, Samsung Biologics)             ║
  // ║  · Hospitals (Mayo, Cleveland, Kaiser, Mass General)                    ║
  // ║  · Retail pharmacy (CVS, Walgreens)                                     ║
  // ║  · Runnable PGx protocol simulation (real EPCIS events in sequence)    ║
  // ╚══════════════════════════════════════════════════════════════════════════╝

