  // ── Mint a consumable lot ─────────────────────────────────────────────────
  function mintConsumableLot(catItem, lotNum, companyPrefix) {
    var lotSuffix = "LOT" + String(lotNum).padStart(6,"0");
    var gtin  = "urn:epc:id:sgtin:" + catItem.vendorPrefix + "." + catItem.itemRef + ".UNIT001";
    var lgtin = "urn:epc:class:lgtin:" + catItem.vendorPrefix + "." + catItem.itemRef + "." + lotSuffix;
    var sscc  = "urn:epc:id:sscc:" + catItem.vendorPrefix + "." + String(lotNum).padStart(16,"0");
    try { registerThing({ id:gtin,  type:"trade-item",     party:catItem.vendorPrefix, source:"gdsn",
      metadata:{ name:catItem.name, type:catItem.type, unit:catItem.unit } }); } catch(_e){}
    try { registerThing({ id:lgtin, type:"consumable-lot", party:catItem.vendorPrefix, source:"gdsn",
      metadata:{ name:catItem.name+" "+lotSuffix, lot:lotSuffix, coldChain:catItem.coldChain,
        regulatedBy:catItem.regulatedBy, instruments:catItem.instruments } }); } catch(_e){}
    try { writeGraphEvent({ subjectId:lgtin, type:"ObjectEvent", bizStep:"commissioning",
      assertedBy:catItem.vendorPrefix, source:"pharma-chain" }); } catch(_e){}
    var rec = { gtin, lgtin, sscc, lotNum:lotSuffix, item:catItem, companyPrefix };
    pharmaChain.consumables.set(lgtin, rec);
    return rec;
  }

  // ── Boot the full pharma value chain ─────────────────────────────────────
  function pharmaChainBoot() {
    if (pharmaChain.booted) return pharmaChainStats();
    if (!pharmaCiv.booted) pharmaBootCivilization();

    var lotCounter = 1000;

    // 1. Mint consumable lots for every catalog item
    CONSUMABLE_CATALOG.forEach(function(item) {
      for (var i=0; i<3; i++) {
        mintConsumableLot(item, lotCounter++, item.vendorPrefix);
      }
    });

    // 2. Wire 3PL wholesalers
    PHARMA_3PL.forEach(function(tpl) {
      var pgln = "urn:epc:id:pgln:" + tpl.prefix + ".0";
      try { registerThing({ id:pgln, type:"party", party:tpl.prefix, source:"gdsn",
        metadata:{ name:tpl.name, role:tpl.role, hq:tpl.hq } }); } catch(_e){}
      tpl.dcs.forEach(function(dc, di) {
        var gln = "urn:epc:id:sgln:" + tpl.prefix + "." + dc.ref.replace(/[^A-Z0-9]/gi,"").slice(0,7).padEnd(6,"0") + ".0";
        try { registerThing({ id:gln, type:"location", party:tpl.prefix, source:"gdsn",
          metadata:{ name:dc.name, address:dc.address, focus:dc.focus } }); } catch(_e){}
        // 3PL ships product from pharma companies
        PHARMA_COMPANIES.forEach(function(co) {
          try { recordEdgeEvent({ fromId:"urn:epc:id:pgln:"+co.prefix+".0", toId:pgln,
            rel:"SHIPS_THROUGH", assertedBy:co.prefix, source:"pharma-chain" }); } catch(_e){}
        });
      });
      pharmaChain.threepl.set(tpl.prefix, tpl);
    });

    // 3. Wire CROs / CMOs
    PHARMA_CROS_CMOS.forEach(function(org) {
      var pgln = "urn:epc:id:pgln:" + org.prefix + ".0";
      try { registerThing({ id:pgln, type:"party", party:org.prefix, source:"gdsn",
        metadata:{ name:org.name, role:org.role, hq:org.hq } }); } catch(_e){}
      org.sites.forEach(function(site) {
        var gln = "urn:epc:id:sgln:" + org.prefix + "." + site.ref.replace(/[^A-Z0-9]/gi,"").slice(0,7).padEnd(6,"0") + ".0";
        try { registerThing({ id:gln, type:"location", party:org.prefix, source:"gdsn",
          metadata:{ name:site.name, address:site.address, focus:site.focus } }); } catch(_e){}
      });
      // Pharma companies contract CMOs
      PHARMA_COMPANIES.slice(0,3).forEach(function(co) {
        try { recordEdgeEvent({ fromId:"urn:epc:id:pgln:"+co.prefix+".0", toId:pgln,
          rel:"CONTRACTS", assertedBy:co.prefix, source:"pharma-chain" }); } catch(_e){}
      });
      pharmaChain.cros.set(org.prefix, org);
    });

    // 4. Wire hospitals
    PHARMA_HOSPITALS.forEach(function(hosp) {
      var pgln = "urn:epc:id:pgln:" + hosp.prefix + ".0";
      try { registerThing({ id:pgln, type:"party", party:hosp.prefix, source:"gudid",
        metadata:{ name:hosp.name, hq:hosp.hq } }); } catch(_e){}
      hosp.glns.forEach(function(loc) {
        var gln = "urn:epc:id:sgln:" + hosp.prefix + "." + loc.ref.replace(/[^A-Z0-9]/gi,"").slice(0,7).padEnd(6,"0") + ".0";
        try { registerThing({ id:gln, type:"location", party:hosp.prefix, source:"gudid",
          metadata:{ name:loc.name, address:loc.address, focus:loc.focus } }); } catch(_e){}
        // Hospital receives from 3PL
        PHARMA_3PL.forEach(function(tpl) {
          try { recordEdgeEvent({ fromId:"urn:epc:id:pgln:"+tpl.prefix+".0", toId:gln,
            rel:"DELIVERS_TO", assertedBy:tpl.prefix, source:"pharma-chain" }); } catch(_e){}
        });
      });
      pharmaChain.hospitals.set(hosp.prefix, hosp);
    });

    // 5. Wire retail pharmacy
    PHARMA_RETAIL.forEach(function(ret) {
      var pgln = "urn:epc:id:pgln:" + ret.prefix + ".0";
      try { registerThing({ id:pgln, type:"party", party:ret.prefix, source:"gdsn",
        metadata:{ name:ret.name, hq:ret.hq } }); } catch(_e){}
      ret.stores.forEach(function(store) {
        var gln = "urn:epc:id:sgln:" + ret.prefix + "." + store.ref.replace(/[^A-Z0-9]/gi,"").slice(0,7).padEnd(6,"0") + ".0";
        try { registerThing({ id:gln, type:"location", party:ret.prefix, source:"gdsn",
          metadata:{ name:store.name, address:store.address, type:store.type } }); } catch(_e){}
        PHARMA_3PL.forEach(function(tpl) {
          try { recordEdgeEvent({ fromId:"urn:epc:id:pgln:"+tpl.prefix+".0", toId:gln,
            rel:"DELIVERS_TO", assertedBy:tpl.prefix, source:"pharma-chain" }); } catch(_e){}
        });
      });
      pharmaChain.retail.set(ret.prefix, ret);
    });

    pharmaChain.booted = true;
    return pharmaChainStats();
  }

  function pharmaChainStats() {
    return {
      booted:      pharmaChain.booted,
      consumables: pharmaChain.consumables.size,
      threepl:     pharmaChain.threepl.size,
      cros:        pharmaChain.cros.size,
      hospitals:   pharmaChain.hospitals.size,
      retail:      pharmaChain.retail.size,
      catalogItems: CONSUMABLE_CATALOG.length,
    };
  }

