  // Total step count across all protocols
  var _PROTOCOL_TOTAL_STEPS = Object.values(PROTOCOL_LIBRARY).reduce(function(s,p){return s+p.steps.length;},0);

  // ── Protocol runner state (one active run at a time per registry) ──────────
  var protocolRunState = {
    active:   null,   // protocol id
    step:     0,
    runId:    null,
    prefix:   null,
    labGln:   null,
    mintedIds:{},
    events:   [],
    done:     false,
  };

  // ── Generic protocol start — works for any protocol in the library ─────────
  function protocolStart(protocolId, opts) {
    var proto = PROTOCOL_LIBRARY[protocolId];
    if (!proto) return { ok:false, error:"unknown protocol: "+protocolId };
    var prefix = (opts&&opts.companyPrefix) || "0085126";
    var labGln = (opts&&opts.labGln) || "urn:epc:id:sgln:0085126.LAB001.0";
    var runId  = "RUN-"+protocolId+"-"+Date.now();
    // Find instrument GIAI from SimCiv
    var instrGiai = null;
    simCiv.instruments.forEach(function(rec,giai){
      if (!instrGiai && giai.indexOf(proto.instrument)!==-1) instrGiai = giai;
    });
    instrGiai = instrGiai || ("urn:epc:id:giai:"+prefix+"."+proto.instrument+"-1000");
    // Mint consumable lots for this run
    var lots = {};
    (proto.consumables||[]).forEach(function(cid) {
      var cat = CONSUMABLE_CATALOG.find(function(c){return c.id===cid;});
      if (cat) {
        var lgtin = "urn:epc:class:lgtin:"+cat.vendorPrefix+"."+cat.itemRef+".LOT"+String(Math.floor(Math.random()*9000)+1000);
        try { registerThing({id:lgtin,type:"consumable-lot",party:cat.vendorPrefix,source:"protocol-run",
          metadata:{name:cat.name,runId:runId}}); } catch(_e){}
        lots[cid] = {lgtin, name:cat.name};
      }
    });
    // Result GDTI
    var gdti = "urn:epc:id:gdti:"+prefix+"."+proto.gdtiBase+"."+runId.slice(-8);
    try { registerThing({id:gdti,type:"document",party:prefix,source:"protocol-run",
      metadata:{name:proto.name+" Result",adfSchema:proto.adfSchema,runId:runId}}); } catch(_e){}
    protocolRunState = { active:protocolId, step:0, runId, prefix, labGln,
      instrGiai, mintedIds:{lots, resultGdti:gdti}, events:[], done:false };
    return { ok:true, runId, protocolId, name:proto.name, totalSteps:proto.steps.length,
      instrGiai, resultGdti:gdti, lots };
  }

  function protocolStep() {
    if (!protocolRunState.active) return { ok:false, error:"no active run" };
    var proto = PROTOCOL_LIBRARY[protocolRunState.active];
    if (!proto) return { ok:false, error:"protocol not found" };
    var idx = protocolRunState.step;
    if (idx >= proto.steps.length || protocolRunState.done) {
      protocolRunState.done = true;
      return { ok:true, done:true, runId:protocolRunState.runId,
        totalEvents:protocolRunState.events.length, resultGdti:protocolRunState.mintedIds.resultGdti };
    }
    var step = proto.steps[idx];
    var subjectId = protocolRunState.instrGiai;
    var ev = { subjectId, type:step.epcisType, bizStep:step.bizStep,
      readPoint:protocolRunState.labGln, assertedBy:protocolRunState.prefix,
      source:"protocol-run", payload:{stepId:step.id, stepName:step.name,
        stage:step.stage, runId:protocolRunState.runId, silaCall:step.silaCall||null} };
    try { writeGraphEvent(ev); } catch(_e){}
    if (idx===proto.steps.length-1 && protocolRunState.mintedIds.resultGdti) {
      try { recordEdgeEvent({fromId:subjectId, toId:protocolRunState.mintedIds.resultGdti,
        rel:"PRODUCES", assertedBy:protocolRunState.prefix, source:"protocol-run"}); } catch(_e){}
    }
    var rec = { stepIdx:idx, stepId:step.id, stage:step.stage, name:step.name,
      epcisType:step.epcisType, bizStep:step.bizStep, subject:subjectId,
      silaCall:step.silaCall, at:new Date().toISOString() };
    protocolRunState.events.push(rec);
    protocolRunState.step++;
    return { ok:true, done:false, stepIdx:idx, step:rec,
      progress:Math.round((protocolRunState.step/proto.steps.length)*100),
      remaining:proto.steps.length-protocolRunState.step, runId:protocolRunState.runId };
  }

  function protocolReset() {
    protocolRunState = { active:null, step:0, runId:null, prefix:null,
      labGln:null, instrGiai:null, mintedIds:{}, events:[], done:false };
    return { ok:true };
  }

  function protocolStatus() {
    var proto = protocolRunState.active ? PROTOCOL_LIBRARY[protocolRunState.active] : null;
    return { active:protocolRunState.active, name:proto?proto.name:null,
      step:protocolRunState.step, totalSteps:proto?proto.steps.length:0,
      progress:proto?Math.round((protocolRunState.step/proto.steps.length)*100):0,
      done:protocolRunState.done, runId:protocolRunState.runId,
      events:protocolRunState.events.slice(-6), mintedIds:protocolRunState.mintedIds };
  }

  // ╔══════════════════════════════════════════════════════════════════════════╗
  // ║  IDENTITY SPINE RESOLVER                                                 ║
  // ║  One function. One URN. Complete ground truth.                          ║
  // ║  SiLA + Allotrope + Sensors + Graph → Physical AI context              ║
  // ╚══════════════════════════════════════════════════════════════════════════╝

  function resolveIdentitySpine(giai) {
    var simRec = simCiv.instruments.get(giai);
    if (!simRec) return { ok:false, error:"not-found", giai };

    // ── 1. IDENTITY ──────────────────────────────────────────────────────────
    var identity = {
      giai,
      model:    simRec.model,
      type:     simRec.type,
      vendor:   simRec.vendor,
      prefix:   simRec.prefix,
      sector:   simRec.sector,
      carriers: ["rfid-epc: RFID-"+simRec.giai, "qr-urn: QR-"+simRec.giai],
      bootedAt: simRec.bootedAt,
    };

    // ── 2. SiLA 2 DRIVER ─────────────────────────────────────────────────────
    var driver = SILA_DRIVERS[simRec.type] || null;
    var sila = driver ? {
      feature:    driver.feature,
      version:    driver.version,
      commands:   driver.commands,
      properties: driver.properties,
      observables:driver.observables,
      epcisStep:  driver.epcisStep,
      description:"SiLA 2 Rapid Integration driver — one driver runs on any cloud",
      claim: "ThingDaddy binds the SiLA 2 feature to the GS1 GIAI — the identity governs which commands are permitted via toolActionPolicy",
    } : null;

    // ── 3. ALLOTROPE ADF ─────────────────────────────────────────────────────
    var adfFamily = simRec.adf ? ALLOTROPE_TECHNIQUE_FAMILIES.find(function(f){
      return f.adfSchema===simRec.adf;
    }) : null;
    // Find matching protocols in the library
    var matchedProtocols = Object.values(PROTOCOL_LIBRARY).filter(function(p){
      return p.instrument===simRec.model.split(" ").slice(-2).join("").slice(0,4)||
             p.adfSchema===simRec.adf ||
             (adfFamily && p.family===adfFamily.tech);
    });
    var allotrope = {
      adfSchema:    simRec.adf,
      family:       adfFamily ? adfFamily.tech : null,
      conceptCount: adfFamily ? adfFamily.count : 0,
      protocols:    adfFamily ? adfFamily.protocols.slice(0,6) : [],
      sampleGdti:   adfFamily ? ("urn:epc:id:gdti:"+ALLOTROPE_VENDOR_PREFIX+"."+adfFamily.gdtiBase+".0001") : null,
      runnableProtocols: matchedProtocols.map(function(p){return{id:p.id,name:p.name,steps:p.steps.length};}),
      description:  "Allotrope Foundation ADF schema — every protocol result gets a GDTI URN @id. The ontology becomes addressable.",
      claim: "ThingDaddy binds the Allotrope ADF schema to the GS1 GIAI — 2,590 protocol concepts become addressable through identity",
    };

    // ── 4. SENSORS (CPIs) ─────────────────────────────────────────────────────
    var sensorDetails = (simRec.sensorIds||[]).map(function(cpi) {
      var sd = simCiv.sensors.get(cpi);
      if (!sd) return null;
      var lastVal = simRec.lastReading[sd.param];
      var isAlert = lastVal!=null && lastVal>sd.alertMax;
      var rule = "toolActionPolicy: IF "+sd.param+" > "+sd.alertMax+" THEN DENY SiLA command";
      return { cpi, param:sd.param, lastValue:lastVal!=null?lastVal:null,
        nominalMin:sd.nominalMin, nominalMax:sd.nominalMax, alertMax:sd.alertMax,
        vendorName:sd.vendorName, partName:sd.partName,
        isAlert, rule,
        governance: isAlert ?
          "🚨 ALERT — "+sd.param+"="+lastVal+" exceeds alertMax="+sd.alertMax+" → SiLA command DENIED" :
          "✅ IN RANGE — "+sd.param+(lastVal!=null?" = "+lastVal:"")+" within limits → SiLA command PERMITTED" };
    }).filter(Boolean);
    var sensors = {
      count:   sensorDetails.length,
      cpis:    sensorDetails,
      description: "Each embedded sensor is a CPI (Component Part Identifier) — a unique GS1 identity for the chip inside the instrument. Rules travel with the CPI. Governance is automatic.",
      claim: "ThingDaddy embeds sensor CPIs in the parent GIAI — sensor readings govern SiLA command execution in real time",
    };

    // ── 5. GRAPH CONTEXT ─────────────────────────────────────────────────────
    var evs = [];
    try { evs = (queryEvents&&queryEvents({subjectId:giai}))||[]; } catch(_e){}
    var edges2 = [];
    try { var eList=edgesBy.get(giai)||[]; eList.forEach(function(e){edges2.push(e);}); } catch(_e){}
    // Pharma context
    var pharmaCtx = pharmaCiv.instrIndex.get(giai);
    var graph = {
      eventCount:   evs.length,
      recentEvents: evs.slice(-4).reverse(),
      edgeCount:    edges2.length,
      edges:        edges2.slice(0,8),
      pharmaContext: pharmaCtx || null,
      description: "Every event in the instrument's lifecycle is in the graph — commissioning, protocol runs, maintenance, alerts. Every edge is a typed relationship.",
      claim: "ThingDaddy's graph is the audit trail — WHO · WHERE · WHEN · WHAT GOVERNED IT · WHAT IT PRODUCED",
    };

    // ── 6. PHYSICAL AI CONTEXT ────────────────────────────────────────────────
    var physicalAI = {
      mcpCall:    "ThingDaddy_MCP.resolve('"+giai+"')",
      resolves: {
        HOW:       sila ? (sila.feature+" — "+sila.commands.length+" commands available") : "no SiLA driver",
        WHAT:      allotrope.adfSchema+" — "+allotrope.conceptCount+" protocol concepts · "+allotrope.runnableProtocols.length+" runnable",
        GOVERNED:  sensors.cpis.map(function(s){return s.param+": "+s.governance.slice(0,40);}).join(" | "),
        WHO:       graph.pharmaContext ? (graph.pharmaContext.companyName+" · "+graph.pharmaContext.labName) : "vendor fleet",
        WHERE:     simRec.site,
        WHEN:      simRec.bootedAt,
        PRODUCED:  graph.eventCount+" EPCIS events · "+graph.edgeCount+" graph edges",
      },
      groundTruth: "No hallucination possible. Every fact is provenanced to a specific CPI, GIAI, LGTIN, GSRN, or GDTI.",
      claim: "This is what makes Physical AI possible. One MCP call. Complete context. Governed by identity.",
    };

    return {
      ok: true, giai,
      identity, sila, allotrope, sensors, graph, physicalAI,
      summary: {
        model:    simRec.model,
        vendor:   simRec.vendor,
        adf:      simRec.adf,
        sila:     sila ? sila.feature : null,
        sensors:  sensors.count,
        events:   graph.eventCount,
        edges:    graph.edgeCount,
        governed: sensors.cpis.some(function(s){return s.isAlert;}),
      }
    };
  }

  // ── End of Identity Spine + Protocol Library engine ───────────────────────

  // ╔══════════════════════════════════════════════════════════════════════════╗
  // ║  LAYER 1 — GSRN CATALOG + MANUFACTURING GLN TAXONOMY                    ║
  // ║                                                                          ║
  // ║  GSRN = GS1 Service Relation Number                                     ║
  // ║  The identity for ANY intelligent agent — organic or digital            ║
  // ║                                                                          ║
  // ║  Organic:  scientists · QA managers · physicians · patients             ║
  // ║  Digital:  Claude AI · ThingDaddy conductor · SiLA orchestrator        ║
  // ║            Allele Typer SW · LIMS agents · ERP bots                    ║
  // ║                                                                          ║
