  // ── GSRN state ────────────────────────────────────────────────────────────
  var gsrnCiv = {
    booted:   false,
    agents:   new Map(),   // gsrn → agent record
    organic:  new Map(),   // gsrn → organic person record
    actions:  [],          // rolling action log
  };

  // ── Boot GSRN civilization ────────────────────────────────────────────────
  function gsrnBoot() {
    if (gsrnCiv.booted) return gsrnStats();

    // 1. Register all digital agents
    DIGITAL_AGENTS.forEach(function(agent) {
      try { registerThing({ id:agent.gsrn, type:"GSRN", party:"0085126",
        source:"thingdaddy-agent", metadata:{ name:agent.name, role:agent.role,
          version:agent.version, organic:false, canAuthorize:(GSRN_ROLES[agent.role]||{}).canAuthorize||[] } }); } catch(_e){}
      gsrnCiv.agents.set(agent.gsrn, agent);
    });

    // 2. Register organic operators for each pharma company lab
    PHARMA_COMPANIES.forEach(function(co) {
      var cd = pharmaCiv.companies.get(co.prefix);
      if (!cd) return;
      var labIdx = 0;
      cd.labs.forEach(function(lab) {
        // Lab scientist per lab
        var sciGsrn = "urn:epc:id:gsrn:" + co.prefix + ".SCI-" + String(labIdx+1).padStart(3,"0");
        try { registerThing({ id:sciGsrn, type:"GSRN", party:co.prefix, source:"gdsn",
          metadata:{ name:co.name+" Scientist "+String(labIdx+1), role:"lab-scientist",
            lab:lab.glnId, organic:true } }); } catch(_e){}
        // QA manager per company
        var qaGsrn = "urn:epc:id:gsrn:" + co.prefix + ".QA-MGR-001";
        try { registerThing({ id:qaGsrn, type:"GSRN", party:co.prefix, source:"gdsn",
          metadata:{ name:co.name+" QA Manager", role:"qa-manager", organic:true } }); } catch(_e){}
        // Wire OPERATED_BY edges for instruments in this lab
        lab.assignedGIAIs.forEach(function(giai) {
          try { recordEdgeEvent({ fromId:giai, toId:sciGsrn, rel:"OPERATED_BY",
            assertedBy:co.prefix, source:"gsrn-boot" }); } catch(_e){}
          try { recordEdgeEvent({ fromId:giai, toId:DIGITAL_AGENTS[0].gsrn, rel:"AI_MONITORED_BY",
            assertedBy:"0085126", source:"gsrn-boot" }); } catch(_e){}
        });
        gsrnCiv.organic.set(sciGsrn, { gsrn:sciGsrn, role:"lab-scientist", company:co.name, lab:lab.glnId });
        labIdx++;
      });
    });

    // 3. Register hospital physician + patient GSRNs
    PHARMA_HOSPITALS.forEach(function(hosp) {
      // Physicians
      for (var p=0; p<3; p++) {
        var phyGsrn = "urn:epc:id:gsrn:" + hosp.prefix + ".PHY-" + String(p+1).padStart(3,"0");
        try { registerThing({ id:phyGsrn, type:"GSRN", party:hosp.prefix, source:"gudid",
          metadata:{ name:hosp.name+" Physician "+String(p+1), role:"physician", organic:true } }); } catch(_e){}
        gsrnCiv.organic.set(phyGsrn, { gsrn:phyGsrn, role:"physician", hospital:hosp.name });
      }
      // De-identified patients
      for (var q=0; q<5; q++) {
        var patGsrn = "urn:epc:id:gsrn:" + hosp.prefix + ".PAT-DE-" + String(90000+q);
        try { registerThing({ id:patGsrn, type:"GSRN", party:hosp.prefix, source:"gudid",
          metadata:{ role:"patient", organic:true, deIdentified:true } }); } catch(_e){}
        gsrnCiv.organic.set(patGsrn, { gsrn:patGsrn, role:"patient", hospital:hosp.name, deIdentified:true });
      }
    });

    // 4. Register pharmacist GSRNs at retail pharmacy
    PHARMA_RETAIL.forEach(function(ret) {
      var pharmGsrn = "urn:epc:id:gsrn:" + ret.prefix + ".PHARM-001";
      try { registerThing({ id:pharmGsrn, type:"GSRN", party:ret.prefix, source:"gdsn",
        metadata:{ name:ret.name+" Pharmacist", role:"pharmacist", organic:true } }); } catch(_e){}
      gsrnCiv.organic.set(pharmGsrn, { gsrn:pharmGsrn, role:"pharmacist", company:ret.name });
    });

    // 5. Register manufacturing instruments with GLN type context
    MFG_INSTRUMENTS.forEach(function(instr) {
      var giai = "urn:epc:id:giai:" + instr.vendorPrefix + "." + instr.id + "-MFG-001";
      try { registerThing({ id:giai, type:"instrument", party:instr.vendorPrefix, source:"gdsn",
        metadata:{ model:instr.model, type:instr.type, glnType:instr.glnType,
          adfSchema:instr.adfSchema, silaFeature:instr.silaFeature,
          description:instr.description, regulation:instr.regulation } }); } catch(_e){}
      instr.sensors.forEach(function(s, si) {
        var cpi = "urn:epc:id:cpi:" + instr.vendorPrefix + "." + s.partRef + "." + instr.id + String(si);
        try { registerThing({ id:cpi, type:"sensor", party:instr.vendorPrefix, source:"gdsn",
          metadata:{ partName:s.partName, param:s.param, nominalMin:s.nominalMin,
            nominalMax:s.nominalMax, alertMax:s.alertMax, parentGiai:giai,
            glnType:instr.glnType } }); } catch(_e){}
        try { recordEdgeEvent({ fromId:giai, toId:cpi, rel:"EMBEDS_SENSOR",
          assertedBy:instr.vendorPrefix, source:"gsrn-boot" }); } catch(_e){}
      });
      // Wire to ThingDaddy AI monitor
      try { recordEdgeEvent({ fromId:giai, toId:DIGITAL_AGENTS[0].gsrn,
        rel:"AI_MONITORED_BY", assertedBy:"0085126", source:"gsrn-boot" }); } catch(_e){}
    });

    // 6. Record GSRN commissioning events for all agents
    DIGITAL_AGENTS.forEach(function(agent) {
      try { writeGraphEvent({ subjectId:agent.gsrn, type:"ObjectEvent",
        bizStep:"commissioning", assertedBy:"0085126", source:"gsrn-boot",
        payload:{ agentName:agent.name, role:agent.role, version:agent.version } }); } catch(_e){}
    });

    gsrnCiv.booted = true;
    return gsrnStats();
  }

  function gsrnStats() {
    return {
      booted:          gsrnCiv.booted,
      digitalAgents:   gsrnCiv.agents.size,
      organicPersons:  gsrnCiv.organic.size,
      mfgInstruments:  MFG_INSTRUMENTS.length,
      glnTypes:        Object.keys(GLN_TYPES).length,
      gsrnRoles:       Object.keys(GSRN_ROLES).length,
      agentList:       DIGITAL_AGENTS.map(function(a){ return { gsrn:a.gsrn, name:a.name, role:a.role }; }),
      glnTypeList:     Object.entries(GLN_TYPES).map(function(e){ return { id:e[0], label:e[1].label, icon:e[1].icon, hasInstruments:e[1].hasInstruments }; }),
    };
  }

  // ── Resolve a GLN to its full profile ────────────────────────────────────
  function resolveGLN(glnId) {
    // Find from pharma labs first
    var labRec = pharmaCiv.labIndex.get(glnId);
    if (labRec) {
      var co = PHARMA_COMPANIES.find(function(c){ return c.prefix===labRec.companyPrefix; });
      var glnTypeDef = GLN_TYPES["research-lab"];
      var instrDetails = labRec.assignedGIAIs.map(function(giai) {
        var simRec = simCiv.instruments.get(giai);
        var driver = simRec ? (SILA_DRIVERS[simRec.type]||null) : null;
        var adfFam = simRec ? ALLOTROPE_TECHNIQUE_FAMILIES.find(function(f){return f.adfSchema===simRec.adf;}) : null;
        return { giai, model:simRec?simRec.model:giai, type:simRec?simRec.type:"instrument",
          vendor:simRec?simRec.vendor:"unknown", adf:simRec?simRec.adf:null,
          silaFeature:driver?driver.feature:null, sensorCount:(simRec?simRec.sensorIds:[]).length,
          allotropeConcepts:adfFam?adfFam.count:0 };
      });
      // Find scientist GSRN for this lab
      var sciGsrn = null;
      gsrnCiv.organic.forEach(function(rec,gsrn){ if (rec.lab===glnId) sciGsrn = gsrn; });
      return { ok:true, glnId, glnType:"research-lab", glnTypeDef,
        name:labRec.lab.name, address:labRec.lab.address, country:labRec.lab.country, focus:labRec.lab.focus,
        company:labRec.companyName, companyPrefix:labRec.companyPrefix,
        pgln:co?"urn:epc:id:pgln:"+co.prefix+".0":null,
        instruments:instrDetails, instrumentCount:instrDetails.length,
        consumables:labRec.consumables, operatorGsrn:sciGsrn,
        digitalAgent:DIGITAL_AGENTS[0].gsrn };
    }
    return { ok:false, error:"GLN not found in registry", glnId };
  }

  // ── Resolve a GSRN to its full profile ───────────────────────────────────
  function resolveGSRN(gsrn) {
    // Check digital agents
    var agent = gsrnCiv.agents.get(gsrn);
    if (agent) {
      var role = GSRN_ROLES[agent.role] || {};
      var evs = []; try { evs = (queryEvents&&queryEvents({subjectId:gsrn}))||[]; } catch(_e){}
      return { ok:true, gsrn, type:"digital", name:agent.name, role:agent.role,
        roleLabel:role.label, icon:role.icon, organic:false,
        canAuthorize:role.canAuthorize||[], regulatedBy:role.regulatedBy||"",
        version:agent.version, eventCount:evs.length, recentEvents:evs.slice(-4).reverse() };
    }
    // Check organic
    var person = gsrnCiv.organic.get(gsrn);
    if (person) {
      var role2 = GSRN_ROLES[person.role] || {};
      var evs2 = []; try { evs2 = (queryEvents&&queryEvents({subjectId:gsrn}))||[]; } catch(_e){}
      return { ok:true, gsrn, type:"organic", name:person.hospital||person.company||"Unknown",
        role:person.role, roleLabel:role2.label, icon:role2.icon, organic:true,
        deIdentified:!!person.deIdentified,
        canAuthorize:role2.canAuthorize||[], regulatedBy:role2.regulatedBy||"",
        lab:person.lab||null, hospital:person.hospital||null,
        eventCount:evs2.length, recentEvents:evs2.slice(-4).reverse() };
    }
    return { ok:false, error:"GSRN not found", gsrn };
  }

  // ── Get all GSRNs by role or type ─────────────────────────────────────────
  function listGSRNs(filter) {
    var results = [];
    // Digital agents
    gsrnCiv.agents.forEach(function(agent,gsrn) {
      if (!filter || filter==="digital" || filter===agent.role) {
        var role = GSRN_ROLES[agent.role]||{};
        results.push({ gsrn, name:agent.name, role:agent.role, roleLabel:role.label,
          icon:role.icon||"🤖", organic:false, version:agent.version });
      }
    });
    // Organic
    gsrnCiv.organic.forEach(function(person,gsrn) {
      if (!filter || filter==="organic" || filter===person.role) {
        var role = GSRN_ROLES[person.role]||{};
        results.push({ gsrn, name:person.hospital||person.company||"Unknown",
          role:person.role, roleLabel:role.label, icon:role.icon||"👤",
          organic:true, deIdentified:!!person.deIdentified });
      }
    });
    return results;
  }

  // ── Record an action with GSRN attribution ────────────────────────────────
  function gsrnAction(gsrn, targetId, action, payload) {
    var rec = { gsrn, targetId, action, payload:payload||{}, at:new Date().toISOString() };
    gsrnCiv.actions.push(rec);
    if (gsrnCiv.actions.length > 100) gsrnCiv.actions.shift();
    try { writeGraphEvent({ subjectId:targetId, type:"ObjectEvent",
      bizStep:action, assertedBy:gsrn, source:"gsrn-action",
      payload:Object.assign({ gsrn:gsrn, action:action }, payload||{}) }); } catch(_e){}
    try { recordEdgeEvent({ fromId:gsrn, toId:targetId, rel:action.toUpperCase().replace(/-/g,"_"),
      assertedBy:gsrn, source:"gsrn-action" }); } catch(_e){}
    return rec;
  }

