  // ── Generate cloud bindings for a GIAI ───────────────────────────────────
  function buildCloudBindings(giai) {
    // Parse prefix and serial from GIAI
    var parts = giai.replace("urn:epc:id:giai:","").split(".");
    var prefix = parts[0] || "0085126";
    var serial = parts.slice(1).join(".") || "INSTRUMENT-001";
    var simRec = simCiv.instruments.get(giai);
    var driver = simRec ? (SILA_DRIVERS[simRec.type]||null) : null;

    var bindings = {};
    CLOUD_PLATFORMS.forEach(function(cloud) {
      var propId = cloud.idPattern(prefix, serial);
      bindings[cloud.id] = {
        platform:     cloud.name,
        color:        cloud.color,
        icon:         cloud.icon,
        proprietaryId: propId,
        propIdField:  cloud.propIdField,
        sdkLang:      cloud.sdkLang,
        sdkVersion:   cloud.sdkVersion,
        shadowTopic:  cloud.shadowTopic(serial),
        eventBus:     cloud.eventBus,
        edgeRuntime:  cloud.edgeRuntime,
        epcisExport:  cloud.epcisExport,
        resolution:   cloud.resolution,
        // SiLA command translation for first available command
        silaExample:  driver ? cloud.silaTranslation(driver.feature, driver.commands[0]||"Command", giai) : null,
      };
    });

    // Build the reverse mapping table (proprietary ID → GIAI)
    var reverseMap = {};
    Object.entries(bindings).forEach(function(kv) {
      reverseMap[kv[1].proprietaryId] = giai;
    });

    // Find matching SiLA translations
    var silaTranslations = {};
    if (driver) {
      var firstCmd = driver.feature + "." + (driver.commands[0]||"Execute");
      if (SILA_CLOUD_TRANSLATIONS[firstCmd]) {
        Object.entries(SILA_CLOUD_TRANSLATIONS[firstCmd]).forEach(function(kv) {
          silaTranslations[kv[0]] = kv[1](giai, serial);
        });
      }
    }

    return {
      giai, prefix, serial,
      model:         simRec ? simRec.model : giai,
      vendor:        simRec ? simRec.vendor : "unknown",
      silaFeature:   driver ? driver.feature : null,
      silaCommands:  driver ? driver.commands : [],
      adfSchema:     simRec ? simRec.adf : null,
      bindings,
      reverseMap,
      silaTranslations,
      deploymentKey: "ThingDaddy GIAI → "+Object.keys(bindings).length+" cloud IDs",
      patentClaim:   "TD-NEW-06: Universal Physical Identity Bridge — one GS1 GIAI resolves to all proprietary cloud IDs bidirectionally",
    };
  }

  // ── Build a full lab deployment manifest ─────────────────────────────────
  function buildLabDeploymentManifest(labGlnOrPrefix) {
    var instruments = [];
    // Get instruments from pharma lab or simCiv fleet
    var labRec = pharmaCiv.labIndex.get(labGlnOrPrefix);
    if (labRec) {
      labRec.assignedGIAIs.forEach(function(giai) {
        instruments.push(buildCloudBindings(giai));
      });
    } else {
      // Fall back to simCiv fleet filtered by prefix
      simCiv.instruments.forEach(function(rec, giai) {
        if (!labGlnOrPrefix || rec.prefix === labGlnOrPrefix || instruments.length < 5) {
          instruments.push(buildCloudBindings(giai));
        }
      });
      instruments = instruments.slice(0, 5);
    }

    var manifest = {
      manifestId:   "TDAG-DEPLOY-" + Date.now(),
      labGln:       labGlnOrPrefix,
      instruments:  instruments,
      cloudPlatforms: CLOUD_PLATFORMS.map(function(c){ return { id:c.id, name:c.name, color:c.color }; }),
      totalBindings: instruments.length * CLOUD_PLATFORMS.length,
      gsrnAgents:   DIGITAL_AGENTS.map(function(a){ return a.gsrn; }),
      deployCmd:    "ThingDaddy.deploy(manifest) → "+instruments.length+" instruments × "+CLOUD_PLATFORMS.length+" clouds = "+instruments.length*CLOUD_PLATFORMS.length+" bindings",
      epcisEndpoint:"https://epcis.thingdaddy.com/v2/capture",
      dscsa:        true,
      regulation:   ["21 CFR 211","DSCSA 2023","EU GMP Annex 1","ICH Q10"],
    };
    return manifest;
  }

  // ── Extend resolveIdentitySpine to include cloud bindings ─────────────────
  var _originalResolveIdentitySpine = resolveIdentitySpine;
  resolveIdentitySpine = function(giai) {
    var base = _originalResolveIdentitySpine(giai);
    if (!base || !base.ok) return base;
    try {
      base.cloudBindings = buildCloudBindings(giai);
    } catch(_e) { base.cloudBindings = null; }
    return base;
  };

