  // ── Resolve a company's full role set ─────────────────────────────────────
  function resolveCompanyRoles(prefix) {
    var roleIds = COMPANY_ROLES[prefix];
    if (!roleIds) {
      // Infer from sector if not explicitly mapped
      var rec = TD_PREFIX_TABLE.find(function(r){ return r.prefix===prefix; });
      var sector = rec ? rec.sector : "general";
      var sectorDefaults = {
        "pharmaceutical": ["manufacturer","lab-operator","distributor","clinical-sponsor"],
        "instrument":     ["instrument-provider","component-supplier","manufacturer"],
        "medical-device": ["manufacturer","component-supplier","distributor"],
        "food-beverage":  ["manufacturer","lab-operator","distributor"],
        "logistics":      ["distributor"],
        "testing-lab":    ["testing-lab","lab-operator"],
        "semiconductor":  ["manufacturer","component-supplier"],
        "industrial":     ["manufacturer","component-supplier"],
        "cmo":            ["manufacturer","lab-operator"],
        "cro":            ["testing-lab","clinical-sponsor","lab-operator"],
      };
      roleIds = sectorDefaults[sector] || ["manufacturer"];
    }
    return roleIds.map(function(rid) {
      return Object.assign({ id:rid }, ROLE_TEMPLATES[rid]);
    }).filter(function(r){ return r.label; });
  }

  // ── Assemble a company's full civilization presence from its roles ────────
  function assembleCompanyCivilization(prefix) {
    var rec = TD_PREFIX_TABLE.find(function(r){ return r.prefix===prefix; }) || { prefix:prefix, name:"Company "+prefix };
    var roles = resolveCompanyRoles(prefix);

    // Collect all layers this company touches
    var layers = {};
    roles.forEach(function(role) {
      if (!layers[role.layer]) layers[role.layer] = [];
      layers[role.layer].push(role);
    });

    // Collect all key types this company mints across all roles
    var allKeyTypes = {};
    roles.forEach(function(role) {
      (role.keyTypes||[]).forEach(function(kt){ allKeyTypes[kt] = true; });
    });

    // Collect all edges this company forms across all roles
    var allEdges = [];
    roles.forEach(function(role) {
      (role.edges||[]).forEach(function(edge){
        allEdges.push(Object.assign({ role:role.id, roleLabel:role.label }, edge));
      });
    });

    // Workflow sources: which libraries to pull from
    var workflowSources = {};
    roles.forEach(function(role) {
      if (role.workflowSource) workflowSources[role.workflowSource] = true;
    });

    // Pull actual workflows based on role
    var workflows = [];
    if (workflowSources["instrument-library"] || workflowSources["both-libraries"]) {
      // Pull canonical protocols from the Protocol Library
      try {
        Object.values(PROTOCOL_LIBRARY||{}).slice(0,6).forEach(function(p){
          workflows.push({ source:"instrument-library", id:p.id, name:p.name, steps:p.steps.length, type:"analytical" });
        });
      } catch(_e){}
    }
    if (workflowSources["component-library"] || workflowSources["both-libraries"]) {
      // Pull CPI governance rules from component registry
      workflows.push({ source:"component-library", type:"governance", name:"CPI alertMax thresholds", desc:"Sensor governance rules wired to toolActionPolicy" });
    }

    return {
      prefix: rec.prefix,
      name: rec.name,
      sector: rec.sector,
      roles: roles,
      roleCount: roles.length,
      roleLabels: roles.map(function(r){ return r.label; }),
      layers: Object.keys(layers),
      layerDetail: layers,
      keyTypes: Object.keys(allKeyTypes),
      edges: allEdges,
      edgeCount: allEdges.length,
      workflows: workflows,
      workflowSources: Object.keys(workflowSources),
      isMultiRole: roles.length > 1,
      summary: rec.name + " has " + roles.length + " roles across " + Object.keys(layers).length + " civilization layers",
    };
  }

  // ── Role library stats ────────────────────────────────────────────────────
  function roleLibraryStats() {
    var roleUsage = {};
    Object.values(COMPANY_ROLES).forEach(function(roles) {
      roles.forEach(function(r){ roleUsage[r] = (roleUsage[r]||0)+1; });
    });
    return {
      totalRoleTemplates: Object.keys(ROLE_TEMPLATES).length,
      mappedCompanies: Object.keys(COMPANY_ROLES).length,
      roleUsage: roleUsage,
      avgRolesPerCompany: (Object.values(COMPANY_ROLES).reduce(function(s,r){return s+r.length;},0) / Object.keys(COMPANY_ROLES).length).toFixed(1),
      layers: [...new Set(Object.values(ROLE_TEMPLATES).map(function(r){return r.layer;}))],
    };
  }

