const TDSwarm = (() => {
  // Agent Swarm — GSRN agents discover manuals for driver-needed gaps, link
  // HAS_MANUAL, auto-certify, all provenanced. The platform fills its own gaps.
const gdti = (p, dt, s) => `urn:epc:id:gdti:${p}.${dt}.${s}`;
const gsrn = (p, r)     => `urn:epc:id:gsrn:${p}.${r}`;

// ── real OEM manual sources, keyed by GS1 company prefix ─────────────────────
const SOURCES = {
  "0085126": { vendor: "Thermo Fisher", domain: "thermo-fisher-scientific.manymanuals.com",
               url: (ref) => `https://thermo-fisher-scientific.manymanuals.com/tools/${ref.toLowerCase()}` },
  "0040753": { vendor: "Agilent",       domain: "agilent.com",
               url: (ref) => `https://www.agilent.com/cs/library/usermanuals/Public/${ref}System.pdf` },
  "0614141": { vendor: "Honeywell",     domain: "automation.honeywell.com",
               url: (ref) => `https://prod-edam.honeywell.com/content/dam/honeywell-edam/sps/siot/en-us/products/sensors/${ref}-datasheet-en.pdf` },
  "0008757": { vendor: "Waters",        domain: "waters.com",
               url: (ref) => `https://www.waters.com/waters/support/manuals/${ref}.pdf` },
  "0012614": { vendor: "Bruker",        domain: "bruker.com",
               url: (ref) => `https://www.bruker.com/manuals/${ref}.pdf` },
  "0860001": { vendor: "Illumina",      domain: "support.illumina.com", rep: true,
               url: (ref) => `https://support.illumina.com/sequencing/sequencing_instruments/${ref.toLowerCase()}/documentation.html` },
  "0860002": { vendor: "Hamilton",      domain: "hamiltoncompany.com", rep: true,
               url: (ref) => `https://www.hamiltoncompany.com/automated-liquid-handling/${ref.toLowerCase()}` },
  "7612100": { vendor: "Mettler Toledo",domain: "mt.com", rep: true,
               url: (ref) => `https://www.mt.com/manuals/${ref}.pdf` },
};

const refOf = (canonical) => canonical.split(".").slice(-1)[0];   // model ref after the prefix dot
const prefixOf = (canonical) => canonical.match(/:(\d+)\./)[1];

// ── the swarm loop ───────────────────────────────────────────────────────────
function runSwarm(reg, opts = {}) {
  const maxRounds = opts.maxRounds || 5;
  const agents = {};            // prefix -> agent record
  const closures = [], skipped = [];
  let round = 0, closedTotal = 0;

  while (round++ < maxRounds) {
    const gaps = reg.listByStatus("provisional");
    if (!gaps.length) break;
    let closedThisRound = 0;

    for (const g of gaps) {
      const prefix = prefixOf(g.id);
      // confirm this is a missing-user-guide gap (read-only: certify does not mutate on failure)
      const probe = reg.certify(g.id, prefix);
      if (probe.ok) continue;                                   // certified on probe (not a manual gap)
      if (!/HAS_MANUAL/.test(probe.reason || "")) { skipped.push({ id: g.id, reason: probe.reason }); continue; }

      const src = SOURCES[prefix];
      if (!src) { skipped.push({ id: g.id, reason: "no known OEM source for prefix " + prefix }); continue; }

      // lazily spin up the vendor's discovery agent as a GSRN graph citizen
      const agentId = gsrn(prefix, "DISCOVERY-AGENT");
      if (!agents[prefix]) {
        reg.registerThing({ id: agentId, type: "GSRN", party: prefix, status: "certified", source: "thingdaddy-swarm" });
        agents[prefix] = { id: agentId, vendor: src.vendor, rep: !!src.rep, closed: 0 };
      }

      // discover -> mint user guide GDTI + real source URL
      const ref = refOf(g.id);
      const manual = gdti(prefix, "USRMAN", ref);
      const url = src.url(ref);

      // link HAS_MANUAL (manual -> device), exactly as ingest does; provenanced to the agent
      reg.mapId({ fromNamespace: "document", fromId: manual, rel: "HAS_MANUAL", toCanonical: g.id, assertedBy: agentId, source: url });
      reg.addThingFact({ subjectId: g.id, statement: `agent[${src.vendor}] discovered user guide ${manual} at ${url}; SiLA driver built from manual`, confidence: 0.9, assertedBy: agentId, source: url });

      // auto-certify: the gate now finds the user guide -> driver-ready
      const c = reg.certify(g.id, prefix);
      if (c.ok) { agents[prefix].closed++; closedThisRound++; closedTotal++; closures.push({ device: g.id, ref, vendor: src.vendor, manual, url, agent: agentId, rep: !!src.rep }); }
      else skipped.push({ id: g.id, reason: c.reason });
    }
    if (!closedThisRound) break;                                // nothing more the swarm can close
  }

  return { agents: Object.values(agents), closures, skipped, rounds: round - 1, closedTotal,
           remaining: reg.listByStatus("provisional").length, provenance: reg.provenance(), stats: reg.stats() };
}
  return { SOURCES, runSwarm };
})();

