function gs1Check(digits) {
  // GS1 standard mod-10: from the RIGHTMOST data digit, weight 3,1,3,1...
  const arr = String(digits).replace(/\D/g,"").split("").map(Number);
  let sum = 0;
  for (let i = arr.length - 1, w = 3; i >= 0; i--, w = (w === 3 ? 1 : 3)) {
    sum += arr[i] * w;
  }
  return ((10 - (sum % 10)) % 10).toString();
}
function rnd(n) { return Array.from({length:n},()=>Math.floor(Math.random()*10)).join(""); }
function rndA(n) { const c="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"; return Array.from({length:n},()=>c[Math.floor(Math.random()*36)]).join(""); }
function padL(s,n,c="0") { return String(s).padStart(n,c); }

// Canonical count of ThingDaddy GS1 identification types. GMN (Global Model
// Number / Digital Link) is a web-resolution URI, not one of the 13 keys — it
// is still minted, just never counted. SINGLE SOURCE OF TRUTH: every visible
// count derives from this (never from raw Object.keys length), so 13 cannot
// drift back to 14.
const TD_TYPE_COUNT = 13;
const countTdTypes = (obj) => Object.keys(obj||{}).filter(k=>k!=="GMN").length;

// Decode any browser-renderable image (PNG / JPEG / HEIC / …) and re-encode to a
// size-capped JPEG before sending to the image API. Full-resolution phone
// screenshots routinely blow past the API's per-image size/dimension limits and
// get rejected; this caps the long edge and flattens to a media_type the API
// always accepts (also rescuing HEIC photos that can't be sent raw).
// Downscale an image (given as a data: URL) to a size-capped JPEG via canvas.
// IMPORTANT: the <img> source is the data: URL itself, NOT URL.createObjectURL()
// — blob: URLs are blocked by the artifact sandbox CSP, which is exactly what
// produced "image could not be decoded". Rejects if the browser can't decode the
// format (e.g. HEIC in-sandbox); the caller then falls back to the raw bytes.
function scaleDataUrlToJpeg(dataUrl, maxEdge = 1568, quality = 0.85) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      try {
        const longest = Math.max(img.naturalWidth, img.naturalHeight) || 1;
        const scale = Math.min(1, maxEdge / longest);
        const w = Math.max(1, Math.round(img.naturalWidth * scale));
        const h = Math.max(1, Math.round(img.naturalHeight * scale));
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext("2d");
        ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, w, h);
        ctx.drawImage(img, 0, 0, w, h);
        resolve({ b64: canvas.toDataURL("image/jpeg", quality).split(",")[1], media: "image/jpeg" });
      } catch (err) { reject(err); }
    };
    img.onerror = () => reject(new Error("decode failed"));
    img.src = dataUrl;
  });
}

// ─── GS1 EPC TDS partition helpers ────────────────────────────────────────────
// Reference length fills so prefix+ref equals the GS1 standard total length.
function refLen(prefix, total) { return Math.max(0, total - String(prefix).length); }
function numRef(prefix, total) { return rnd(refLen(prefix, total)); }            // numeric reference
// Indicator digit (0-9) for SGTIN/ITIP/LGTIN
function indicator() { return String(Math.floor(Math.random()*10)); }
// Build a valid GTIN-14 from prefix + itemRef (prefix+itemRef must be 13 long) + check
// ─── Session unique-ID registry — guarantees no collisions in context ─────────
// Every issued EPC URN is recorded; serials are allocated monotonically per
// (prefix, type) so the same physical thing keeps one ID and no two things collide.
const TD_ID_REGISTRY = {
  issued: new Set(),          // every EPC URN ever minted this session
  counters: {},               // `${prefix}:${type}` -> next serial
  byKey: {},                  // stable key -> URN (so re-asking returns the SAME id)
};
function tdNextSerial(prefix, type, width) {
  const k = `${prefix}:${type}`;
  const n = (TD_ID_REGISTRY.counters[k] = (TD_ID_REGISTRY.counters[k] || 0) + 1);
  return String(n).padStart(width, "0");
}
// Register a minted URN; if it somehow collides, bump until unique.
function tdRegister(urn) {
  let u = urn, guard = 0;
  while (TD_ID_REGISTRY.issued.has(u) && guard < 9999) {
    // append/increment a uniquifier before the last segment
    u = urn.replace(/(\d+)$/, (m) => String(Number(m) + (++guard)));
    if (u === urn) { u = urn + "-" + (++guard); }
  }
  TD_ID_REGISTRY.issued.add(u);
  return u;
}
// Stable issuance: same (prefix,type,key) → same URN; new key → new unique URN.
function tdIssue(prefix, type, key, mint) {
  const stableKey = `${prefix}:${type}:${key||"default"}`;
  if (TD_ID_REGISTRY.byKey[stableKey]) return TD_ID_REGISTRY.byKey[stableKey];
  const urn = tdRegister(mint());
  TD_ID_REGISTRY.byKey[stableKey] = urn;
  return urn;
}

function gtin14(prefix, ind, itemRef) {
  const body = String(ind) + String(prefix) + itemRef;          // 13 digits
  return body + gs1Check(body);                                 // +check = 14
}
// SGTIN EPC: companyPrefix.indicator+itemRef(=13-prefixLen incl indicator).serial
function sgtinParts(prefix) {
  const ind = indicator();
  const itemRef = rnd(refLen(prefix, 12));                      // ind + itemRef total = 13-prefixLen... TDS: prefix+itemRef = 13, itemRef includes indicator as leading digit
  return { ind, itemRef, serial: rnd(9) };
}

function makeGLN(p, r="000001") {
  // GLN-13 = prefix + locationRef (prefix+ref MUST total 12) + check digit.
  // padStart never truncates, so the ref is coerced to the exact partition width
  // (a 7-digit prefix leaves 5 ref digits; "000001" alone would overflow to 14).
  const w = Math.max(0, 12 - String(p).length);
  const refDigits = String(r ?? "1").replace(/\D/g, "").padStart(w, "0");
  const b = String(p) + (w ? refDigits.slice(-w) : "");
  return b + gs1Check(b);
}
// GLN/PGLN refs must be NUMERIC and prefix+ref === 12 digits (check digit dropped in URN).
// Self-correcting: any value passed in is coerced to the right length, so every
// existing call site (bare or "000001") emits a spec-valid partition.
const _glnRef      = (p, r) => { const w = refLen(p, 12); const s = String(r ?? "1").replace(/\D/g,"").padStart(w,"0"); return w ? s.slice(-w) : ""; };
const makeGLNurn   = (p, r="1") => `urn:epc:id:sgln:${p}.${_glnRef(p,r)}.0`;
const makePGLNurn  = (p, r="1") => `urn:epc:id:pgln:${p}.${_glnRef(p,r)}`;
const makeGIAIurn  = (p, s)          => `urn:epc:id:giai:${p}.${s}`;
const makeGTINurn  = (p, i, s=0)     => `urn:epc:id:sgtin:${p}.${i}.${s}`;
const makeLGTINurn = (p, i, l)       => `urn:epc:class:lgtin:${p}.${i}.${l}`;
const makeGDTIurn  = (p, d, s)       => `urn:epc:id:gdti:${p}.${d}.${s}`;
const makeGSRNurn  = (p, s)          => `urn:epc:id:gsrn:${p}.${s}`;
const makeCPIurn   = (p, r, s)       => `urn:epc:id:cpi:${p}.${r}.${s}`;
const makeGMNurn  = (p, m)          => `(8013)${p}${m}`;   // GMN = model number, class association (element string) — NOT an EPC, NOT a unique ID
const makeSSCCurn  = (p, s)          => `urn:epc:id:sscc:${p}.${s}`;

