// Safe EPC extractor — handles both string and {epc,gs1} object formats
const safeEPC = (v) => {
  if (!v) return "";
  if (typeof v === "string") return v;
  return v.epc || v.id || v.gs1 || JSON.stringify(v);
};
const safeGS1 = (v) => {
  if (!v) return "";
  if (typeof v === "string") return v;
  return v.gs1 || v.epc || "";
};

