// ── ErrorBoundary — converts any render crash into a visible, readable message ──
// instead of a blank white screen. Critically, it surfaces the actual error text
// on-device, so a failing module can be diagnosed instead of silently blanking.
class ModuleErrorBoundary extends React.Component {
  constructor(props){ super(props); this.state = { hasError:false, msg:"", stack:"" }; }
  static getDerivedStateFromError(error){ return { hasError:true, msg:String(error&&error.message||error), stack:String(error&&error.stack||"") }; }
  componentDidCatch(error, info){ /* could log to a service here */ }
  componentDidUpdate(prev){ if(prev.routeKey !== this.props.routeKey && this.state.hasError){ this.setState({hasError:false, msg:"", stack:""}); } }
  render(){
    if(this.state.hasError){
      return React.createElement('div', {style:{padding:"32px 22px",maxWidth:760,margin:"0 auto"}},
        React.createElement('div', {style:{padding:"18px 20px",borderRadius:12,background:"#FEF2F2",border:"1px solid #FCA5A5"}},
          React.createElement('div', {style:{fontSize:15,fontWeight:800,color:"#B91C1C",marginBottom:6}}, "⚠️ This view hit an error"),
          React.createElement('div', {style:{fontSize:12,color:"#7F1D1D",lineHeight:1.6,marginBottom:10}}, "The rest of the platform is fine — use the navigation above to continue. Error detail (helpful for fixing):"),
          React.createElement('div', {style:{fontSize:11,fontFamily:"monospace",color:"#991B1B",background:"#fff",padding:"10px 12px",borderRadius:8,border:"1px solid #FECACA",wordBreak:"break-word"}}, this.state.msg||"(no message)"),
          this.state.stack ? React.createElement('div', {style:{fontSize:9,fontFamily:"monospace",color:"#9CA3AF",marginTop:8,whiteSpace:"pre-wrap",maxHeight:160,overflow:"auto"}}, this.state.stack.split("\n").slice(0,6).join("\n")) : null
        )
      );
    }
    return this.props.children;
  }
}

