function CodeBlock({ code }) {
  return (
    <pre style={{margin:0,padding:"16px 20px",overflowX:"auto",fontSize:11,lineHeight:1.7,
      color:"#C8E0FF",background:GD.dark,tabSize:4,minHeight:300,maxHeight:440,overflowY:"auto"}}>
      {(code||"").split("\n").map((line,i)=>{
        const isComment = line.trim().startsWith("#");
        const isDecorator = line.trim().startsWith("@");
        const c = isComment?"#5A8A6A":isDecorator?GD.orange:"#C8E0FF";
        return (
          <span key={i} style={{display:"block",color:c,minHeight:"1.7em"}}>
            <span style={{color:"#2A4060",userSelect:"none",marginRight:12,fontSize:9}}>
              {String(i+1).padStart(3," ")}
            </span>
            {line.replace(/\t/g,"  ")}
          </span>
        );
      })}
    </pre>
  );
}

// ── SDK Module is now "SiLA 2 gRPC" in new flow (Step 4)
function SDKModule() {
  const { ids, prefix, activeCompany } = useIDs();
  const [selLayer,setSelLayer] = useState("sila"); // SiLA-only view (clean flow; richer multi-layer views later for mature users)
  const [tab,setTab] = useState("code");
  const [copied,setCopied] = useState(false);
  const [simState,setSimState] = useState({});
  const [simRunning,setSimRunning] = useState(false);
  const [simProgress,setSimProgress] = useState(0);
  const [simLog,setSimLog] = useState([]);
  const logRef = useRef(null);

  const layer = SDK_LAYERS.find(l=>l.id===selLayer);

  useEffect(()=>{
    if(logRef.current) logRef.current.scrollTop=logRef.current.scrollHeight;
  },[simLog]);

  const copyCode = () => {
    navigator.clipboard?.writeText(layer.code||"");
    setCopied(true); setTimeout(()=>setCopied(false),1500);
  };

  const runSim = async () => {
    if(simRunning) return;
    setSimRunning(true); setSimState({}); setSimLog([]); setSimProgress(0);
    const log = msg => setSimLog(p=>[...p,{ts:new Date().toLocaleTimeString(),msg}]);
    log("🚀 ThingDaddy AI Simulation Engine initializing...");
    log("🔗 Connecting to Claude Sonnet 4...");
    await new Promise(r=>setTimeout(r,500));

    for(let i=0;i<LIVE_SCENARIOS.length;i++){
      const s=LIVE_SCENARIOS[i];
      setSimState(p=>({...p,[s.id]:{status:"RUNNING",score:0}}));
      log(`▶ ${s.id}: ${s.method} -- ${s.instrument}`);
      await new Promise(r=>setTimeout(r,300));

      const prompt=`You are the ThingDaddy AI Simulation Engine. Simulate a ${s.type} run.
Scenario: ${s.id} | Method: ${s.method} | Instrument: ${s.instrument}
TD:GTIN: ${s.gtin} | Reagent TD:LGTIN: ${s.lot}
Return ONLY valid JSON (no markdown):
{"status":"PASS","score":0.94,"narrative":"one precise scientific sentence","findings":["finding 1","finding 2"]}`;

      try {
        const resp = await fetch("https://api.anthropic.com/v1/messages",{
          method:"POST",headers:{"Content-Type":"application/json"},
          body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:1000,
            messages:[{role:"user",content:prompt}]})
        });
        const data = await resp.json();
        const text = data.content?.[0]?.text||"{}";
        const parsed = JSON.parse(text.replace(/```json|```/g,"").trim());
        setSimState(p=>({...p,[s.id]:{
          status:parsed.status||"PASS",
          score:parsed.score||0.92,
          narrative:parsed.narrative||"",
          findings:parsed.findings||[],
        }}));
        log(`✅ ${s.id} → ${parsed.status} (${((parsed.score||0.92)*100).toFixed(1)}%) -- ${(parsed.narrative||"").slice(0,55)}...`);
      } catch {
        const st=["PASS","PASS","PASS","WARNING"][i%4];
        const sc=0.88+Math.random()*0.11;
        setSimState(p=>({...p,[s.id]:{status:st,score:sc,
          narrative:`${s.method} completed within specification on all ThingDaddy ID nodes.`,
          findings:[`TD:GTIN resolved: ${s.gtin.slice(0,40)}...`,`TD:LGTIN: ${s.lot}`]}}));
        log(`✅ ${s.id} → ${st} (${(sc*100).toFixed(1)}%)`);
      }
      setSimProgress(Math.round((i+1)/LIVE_SCENARIOS.length*100));
      await new Promise(r=>setTimeout(r,250));
    }
    log("📊 All scenarios complete.");
    setSimRunning(false);
  };

  const doneCount=Object.values(simState).filter(r=>r.status&&r.status!=="RUNNING").length;
  const passCount=Object.values(simState).filter(r=>r.status==="PASS").length;
  const SIM_COLORS={"PASS":GD.greenDk,"FAIL":GD.red,"WARNING":GD.yellow,"RUNNING":GD.blue,"QUEUED":GD.grayLt};

  return (
    <div style={{padding:"20px"}}>
      {(()=>{ try { const KEYS=["pump","ms","balance","cytometer","sequencer","diagnostics"];
        return <TDArtifactPanel icon="🔌" title="SiLA 2 — Feature Definitions (FDL)" sub="the real XML artifact a maker publishes, once"
        items={KEYS.map(k=>({label:k+" FDL",filename:TDSiLA.FEATURES[k].f.split("/")[1]+".sila.xml",gen:()=>tdFDL(k),
          note:"SiLA 2 v1.1 FeatureDefinition XML — validates against sila_base FeatureDefinition.xsd. Published to the registry; users connect it, never receive maker access."}))}/>; } catch(_e){ return null; } })()}
      <CompanySearchHeader label="the SiLA driver" accent={GD.teal} />
      <LiveIDsBanner module="SDK Explorer" />
      {Object.keys(ids).length > 0 && (
        <div style={{marginBottom:16,padding:"10px 14px",background:"#F8FAFC",
          border:"1px solid #E5E7EB",borderRadius:8}}>
          <div style={{fontSize:10,fontWeight:700,color:"#2A8F36",marginBottom:8,letterSpacing:".06em"}}>
            🔗 LIVE GS1 IDs — Prefix {prefix} — injected into all SDK code below
          </div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:4}}>
            {[["GIAI","Asset Identity"],["GTIN","Product Class"],["GLN","Location"],
              ["GDTI","Document"],["CPI","Component/Sensor"],["LGTIN","Lot/Batch"],
              ["GSRN","Service/Person"],["SSCC","Shipment"]].map(([k,label])=>
              ids[k] ? (
                <div key={k} style={{display:"flex",gap:6,alignItems:"baseline"}}>
                  <span style={{fontSize:9,fontWeight:700,color:"#00A09C",minWidth:44}}>{k}</span>
                  <span style={{fontSize:9,color:"#374151",fontFamily:"'Fira Code',monospace",wordBreak:"break-all"}}>
                    {ids[k].epc||ids[k].id}
                  </span>
                </div>
              ) : null
            )}
          </div>
        </div>
      )}
      <div style={{margin:"0 0 20px",padding:"12px 16px",borderRadius:10,background:GD.teal+"10",border:`1px solid ${GD.teal}33`}}>
        <span style={{fontSize:12,fontWeight:800,color:GD.teal}}>SiLA 2 — the universal driver framework. </span>
        <span style={{fontSize:12,color:GD.gray,lineHeight:1.6}}>Your in-context IDs flow into every field of the SiLA driver below. ADF, Cloud, ERP, and CAD are downstream surfaces with their own tabs — the same semantically-mapped URNs flow into each, in its own phase.</span>
      </div>

      {(()=>{ try { return <TDEcoPanel/>; } catch(_e){ return null; } })()}

      {(()=>{ try { return <TDConductorPanel/>; } catch(_e){ return null; } })()}

      {(()=>{ try { return <TDConfiguratorDemo activeCompany={activeCompany}/>; } catch(_e){ return null; } })()}
      {(()=>{ try { return <TDDirectoryDemo activeCompany={activeCompany}/>; } catch(_e){ return null; } })()}

      {(()=>{ try { return <TDHeliosPanel/>; } catch(_e){ return null; } })()}

      {layer && layer.id==="sila" && (()=>{ try {
        const feats = Object.values(TDSiLA.FEATURES);
        const tot = feats.reduce((a,F)=>({c:a.c+F.cmds.length,p:a.p+(F.props||[]).length}),{c:0,p:0});
        return (
          <div style={{margin:"0 0 20px",border:`1px solid ${GD.teal}33`,borderRadius:10,overflow:"hidden"}}>
            <div style={{padding:"10px 14px",background:`${GD.teal}10`,borderBottom:`1px solid ${GD.teal}22`}}>
              <span style={{fontSize:13,fontWeight:800,color:GD.teal}}>⚗️ Real SiLA 2 Feature Library</span>
              <span style={{fontSize:11,color:GD.gray,marginLeft:8}}>{feats.length} Features · {tot.c} Commands · {tot.p} Properties — mapped across all 30 protocol stacks</span>
            </div>
            <div style={{padding:"12px 14px",display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(300px,1fr))",gap:10}}>
              {feats.map((F,i)=>(
                <div key={i} style={{border:"1px solid #E5E7EB",borderRadius:8,padding:"10px 12px",background:"#fff"}}>
                  <div style={{fontSize:11,fontWeight:700,color:GD.dark,fontFamily:"'Fira Code',monospace",wordBreak:"break-all",marginBottom:6}}>{F.f}</div>
                  <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:(F.props&&F.props.length?6:0)}}>
                    {F.cmds.map((c,j)=>(<span key={j} style={{fontSize:10,padding:"2px 7px",borderRadius:999,background:`${GD.teal}14`,border:`1px solid ${GD.teal}40`,color:GD.dark}}>{c}</span>))}
                  </div>
                  {(F.props||[]).map((p,j)=>(<span key={j} style={{fontSize:9,padding:"1px 6px",marginRight:4,borderRadius:4,background:"#F1F5F9",color:GD.gray}}>◷ {p}</span>))}
                </div>
              ))}
            </div>
          </div>
        );
      } catch(_e){ return null; } })()}

      {layer && (
        <Card style={{borderTop:`4px solid ${layer.color}`,overflow:"hidden"}}>
          <div style={{padding:"12px 16px",background:`${layer.color}08`,
            borderBottom:"1px solid #E5E7EB",display:"flex",alignItems:"center",
            justifyContent:"space-between",flexWrap:"wrap",gap:8}}>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <span style={{fontSize:22}}>{layer.icon}</span>
              <div>
                <div style={{fontSize:14,fontWeight:800,color:layer.color}}>{layer.label}</div>
                <div style={{fontSize:11,color:GD.gray,marginTop:1}}>{layer.desc}</div>
              </div>
            </div>
            <div style={{display:"flex",gap:6}}>
              {["code",...(layer.id==="sim"?["simulate"]:[])].map(t=>(
                <Btn key={t} small onClick={()=>setTab(t)} variant={tab===t?"primary":"outline"}>
                  {t==="simulate"?"▶ Live Demo":"{ } Code"}
                </Btn>
              ))}
            </div>
          </div>

          {tab==="code" && (
            <div style={{position:"relative"}}>
              <button onClick={copyCode} style={{position:"absolute",top:10,right:12,zIndex:10,
                fontSize:9,padding:"4px 10px",background:copied?GD.greenDk:GD.darkMid,
                color:GD.white,border:"none",borderRadius:3,cursor:"pointer",
                fontFamily:"inherit",fontWeight:700}}>
                {copied?"✓ COPIED":"⎘ COPY"}
              </button>
              <CodeBlock code={(() => {
                // Substitute live generated IDs into the displayed code
                let c = (layer.buildCode ? layer.buildCode(ids, prefix||"0085126") : layer.code) || "";
                if(Object.keys(ids).length > 0) {
                  const giai  = ids["GIAI"]?.epc  || "";
                  const gtin  = ids["GTIN"]?.epc   || "";
                  const gln   = ids["GLN"]?.epc    || "";
                  const gdti  = ids["GDTI"]?.epc   || "";
                  const cpi   = ids["CPI"]?.epc    || "";
                  const lgtin = ids["LGTIN"]?.epc  || "";
                  const gsrn  = ids["GSRN"]?.epc   || "";
                  const gmn   = ids["GMN"]?.epc    || "";
                  const sscc  = ids["SSCC"]?.epc   || "";
                  const pgln  = ids["PGLN"]?.epc   || "";
                  const pfx   = prefix || "0085126";
                  if(giai)  c = c.replace(/urn:epc:id:giai:[^\s"']+/g, giai);
                  if(gtin)  c = c.replace(/urn:epc:id:sgtin:[^\s"']+/g, gtin);
                  if(gln)   c = c.replace(/urn:epc:id:sgln:[^\s"']+/g, gln);
                  if(gdti)  c = c.replace(/urn:epc:id:gdti:[^\s"']+/g, gdti);
                  if(cpi)   c = c.replace(/urn:epc:id:cpi:[^\s"']+/g, cpi);
                  if(lgtin) c = c.replace(/urn:epc:class:lgtin:[^\s"']+/g, lgtin);
                  if(gsrn)  c = c.replace(/urn:epc:id:gsrn:[^\s"']+/g, gsrn);
                  if(sscc)  c = c.replace(/urn:epc:id:sscc:[^\s"']+/g, sscc);
                  if(pgln)  c = c.replace(/urn:epc:id:pgln:[^\s"']+/g, pgln);
                  if(pfx)   c = c.replace(/0046727|0085126/g, pfx);
                }
                return c;
              })()} />
            </div>
          )}

          {tab==="simulate" && layer.id==="sim" && (
            <div style={{padding:"16px",display:"flex",flexDirection:"column",gap:12}}>
              <div style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",
                background:GD.offWhite,borderRadius:8,border:"1px solid #E5E7EB",flexWrap:"wrap"}}>
                <Btn onClick={runSim} disabled={simRunning} variant={simRunning?"ghost":"primary"}>
                  {simRunning?"⏳ Running AI Simulation...":"▶ Run 6 AI Scenarios"}
                </Btn>
                {simRunning && (
                  <div style={{flex:1,minWidth:150}}>
                    <div style={{display:"flex",justifyContent:"space-between",fontSize:10,color:GD.gray,marginBottom:3}}>
                      <span>Progress</span><span>{simProgress}%</span>
                    </div>
                    <div style={{height:5,background:"#E5E7EB",borderRadius:3,overflow:"hidden"}}>
                      <div style={{height:"100%",width:`${simProgress}%`,background:GD.green,transition:"width .3s"}}/>
                    </div>
                  </div>
                )}
                {doneCount>0&&!simRunning && (
                  <div style={{fontSize:12,fontWeight:700,color:GD.greenDk}}>
                    {"✓ "}{passCount}/{doneCount}{" PASSED -- "}{Math.round(passCount/doneCount*100)}% pass rate
                  </div>
                )}
              </div>

              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(270px,1fr))",gap:10}}>
                {LIVE_SCENARIOS.map(s=>{
                  const r=simState[s.id];
                  const st=r?.status||"QUEUED";
                  const c=SIM_COLORS[st]||GD.gray;
                  return (
                    <Card key={s.id} style={{borderTop:`3px solid ${c}`,opacity:st==="QUEUED"?.6:1}}>
                      <div style={{padding:"12px 14px"}}>
                        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:6}}>
                          <div>
                            <div style={{fontSize:10,color:GD.grayLt,fontWeight:600}}>{s.id} {"·"} {s.type}</div>
                            <div style={{fontSize:12,fontWeight:700,color:GD.dark,marginTop:2}}>{s.method}</div>
                          </div>
                          <span style={{fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:12,
                            background:`${c}18`,color:c,whiteSpace:"nowrap"}}>
                            {st==="RUNNING"?"⏳ ":st==="PASS"?"✓ ":st==="FAIL"?"✗ ":st==="WARNING"?"⚠ ":"○ "}{st}
                          </span>
                        </div>
                        <div style={{fontSize:10,color:GD.gray,marginBottom:4}}>{"🔬 "}{s.instrument}</div>
                        <div style={{fontSize:9,color:GD.grayLt,fontFamily:"'Fira Code',monospace",marginBottom:r?.score?8:0}}>
                          {s.gtin.length>44?s.gtin.slice(0,44)+"…":s.gtin}
                        </div>
                        {(r?.score||0)>0 && (
                          <div>
                            <div style={{display:"flex",justifyContent:"space-between",fontSize:9,color:GD.gray,marginBottom:2}}>
                              <span>Quality Score</span>
                              <span style={{fontWeight:700,color:c}}>{(r.score*100).toFixed(1)}%</span>
                            </div>
                            <div style={{height:4,background:"#E5E7EB",borderRadius:2,overflow:"hidden"}}>
                              <div style={{height:"100%",width:`${r.score*100}%`,background:c,transition:"width .6s"}}/>
                            </div>
                          </div>
                        )}
                        {r?.narrative && (
                          <div style={{fontSize:9,color:GD.gray,marginTop:8,lineHeight:1.5,fontStyle:"italic"}}>
                            {'"'}{r.narrative.slice(0,90)}{r.narrative.length>90?"…":""}{'"'}
                          </div>
                        )}
                        {(r?.findings||[]).slice(0,2).map((f,i)=>(
                          <div key={i} style={{fontSize:9,color:GD.greenDk,marginTop:3}}>{"› "}{f.slice(0,58)}</div>
                        ))}
                      </div>
                    </Card>
                  );
                })}
              </div>

              {simLog.length>0 && (
                <div style={{background:GD.dark,borderRadius:8,padding:"12px 16px"}}>
                  <div style={{fontSize:10,fontWeight:700,color:GD.green,marginBottom:6,letterSpacing:".08em"}}>
                    {"▸ SIMULATION CONSOLE"}
                  </div>
                  <div ref={logRef} style={{maxHeight:150,overflowY:"auto"}}>
                    {simLog.map((l,i)=>(
                      <div key={i} style={{fontSize:10,lineHeight:1.6,color:"#86EFAC"}}>
                        <span style={{color:"#4A7A6A",marginRight:8}}>{l.ts}</span>{l.msg}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </Card>
      )}
    
      <StandardExplainer solutionKey="sila"/>
      </div>
  );
}

// ════════════════════════════════════════════════════════════════════════════════
// MODULE 3 — ALLOTROPE ADF PROTOCOL MAP
// ════════════════════════════════════════════════════════════════════════════════
const ADF_SCHEMAS = [
  {schema:"liquid-chromatography",sector:"Life Science",instruments:"Vanquish UHPLC · Waters Acquity"},
  {schema:"gas-chromatography",sector:"Life Science",instruments:"Agilent 8890 · Shimadzu GC-2030"},
  {schema:"cell-imaging",sector:"Life Science",instruments:"CellInsight CX7 · ImageXpress"},
  {schema:"colony-picking",sector:"Life Science",instruments:"QPix 420 · Sias PickStation"},
  {schema:"liquid-handling",sector:"Life Science",instruments:"Biomek i7 · HydroFlex"},
  {schema:"microscopy (confocal)",sector:"Life Science",instruments:"Leica STELLARIS · Zeiss LSM"},
  {schema:"microscopy (STED)",sector:"Life Science",instruments:"Zeiss Elyra 7"},
  {schema:"microscopy (fluorescence)",sector:"Life Science",instruments:"Nikon N-STORM"},
  {schema:"gas-chromatography (GC-MS)",sector:"Life Science",instruments:"Thermo TRACE 1600"},
  {schema:"plate-washing",sector:"Life Science",instruments:"BioTek EL406 · AquaMax 4000"},
  {schema:"hematology",sector:"Medical",instruments:"XN-Series · DxH 900"},
  {schema:"immunoassay",sector:"Medical",instruments:"Alinity i · ARCHITECT"},
  {schema:"immunoassay (POC)",sector:"Medical",instruments:"i-STAT · Cobas h 232"},
  {schema:"surgical",sector:"Medical",instruments:"da Vinci Xi · Mako"},
  {schema:"respiratory",sector:"Medical",instruments:"AirSense 11 · AirCurve 10"},
  {schema:"fetal-monitoring",sector:"Medical",instruments:"Monica AN24 · Avalon FM20"},
  {schema:"laser-therapy",sector:"Medical",instruments:"Lumenis Pulse · Fotona SP"},
  {schema:"perfusion",sector:"Medical",instruments:"Stöckert S5 · Terumo FX15"},
  {schema:"robotics",sector:"Industrial",instruments:"IRB 6700 · KR QUANTEC"},
  {schema:"motor-control",sector:"Industrial",instruments:"ACS 880 · PowerFlex 525"},
  {schema:"flow-control",sector:"Industrial",instruments:"SIPOS APOS · Flowserve"},
  {schema:"general-instrument",sector:"All",instruments:"Any ThingDaddy-registered device"},
  {schema:"plate-reading",sector:"Life Science",instruments:"PHERAstar FSX · Synergy H1"},
];

const SEC_COLORS = {"Life Science":GD.teal,"Medical":GD.red,"Industrial":GD.orange,"All":GD.gray};


// Full ADF protocol map — the workflow stages every ADF schema follows, with the
// in-context IDs that anchor each stage. Clicking a card opens this complete map.
function adfProtocolMap(schema, ids, prefix){
  const has = Object.keys(ids||{}).length>0;
  const id = (t)=> has && ids[t] ? (ids[t].epc||ids[t].id) : `urn:epc:id:${t.toLowerCase()}:${prefix||"<prefix>"}.…`;
  return [
    {stage:"1 · Sample / Material", afo:"AFO:0000010 (material)", desc:"The physical sample or material entering the protocol — identified as a unique instance.", idType:"GIAI", id:id("GIAI"), color:"#00A09C"},
    {stage:"2 · Instrument / Device", afo:"AFO:0000524 (device)", desc:"The instrument executing the method (e.g. the UHPLC). The device itself is a uniquely identified asset.", idType:"GIAI", id:id("GIAI"), color:"#1D4ED8"},
    {stage:"3 · Method / Recipe", afo:"AFT:method-document", desc:"The method or recipe document driving the run — versioned, identified, reproducible.", idType:"GDTI", id:id("GDTI"), color:"#7C3AED"},
    {stage:"4 · Lot / Batch", afo:"AFO:0002658 (batch)", desc:"The lot or batch context — class-level, lot-scoped identity.", idType:"LGTIN", id:id("LGTIN"), color:"#D97706"},
    {stage:"5 · Component / Consumable", afo:"AFO:component", desc:"Columns, reagents, consumables — each a uniquely identified component/part.", idType:"CPI", id:id("CPI"), color:"#DC2626"},
    {stage:"6 · Result / Data Cube", afo:"AFO:0000787 (data cube)", desc:"The ADF data cube capturing the result — bound to every identity above, fully provenanced.", idType:"GDTI", id:id("GDTI"), color:"#16A34A"},
  ];
}

// Build the actual Allotrope ASM document (standardized JSON representation of the
// ADM) for a protocol, anchored to the company's live in-context IDs. Per the
// Allotrope Framework: AFO ontology -> ADM data model -> ASM (JSON) / ADF (RDF in HDF5).
function buildASMDocument(schema, ids, prefix, instruments){
  const tech=(schema||"general-instrument").toLowerCase().replace(/[^a-z0-9]+/g,"-");
  const id=(t,fb)=> (ids&&ids[t]&&(ids[t].epc||ids[t].id)) || `urn:epc:id:${t.toLowerCase()}:${prefix||"<prefix>"}.${fb}`;
  const now=new Date().toISOString();
  const agg=`${tech} aggregate document`;
  const doc={};
  doc["$asm.manifest"]=`http://purl.allotrope.org/manifests/${tech}/REC/2024/09/${tech}.manifest`;
  doc[agg]={
    "device system document":{
      "asset management identifier": id("GIAI","ASSET0001"),
      "product manufacturer": (instruments||"").split("·")[0].trim()||"Registered manufacturer",
      "model number": (instruments||"").split("·")[0].trim()||"—",
      "equipment serial number": "SN-"+(prefix||"0000000"),
      "device document":[{"device identifier": id("GIAI","ASSET0001"),"device type": tech,
        "device component document":[{"component identifier": id("CPI","CMP0001.000001"),"component type":"column / sensor / consumable"}]}]
    },
    "data system document":{
      "data system instance identifier":"THINGDADDY-IN-CONTEXT-ENGINE",
      "software name":"ThingDaddy Unified Platform",
      "ASM converter name":"thingdaddy.asm.converter","ASM converter version":"1.0.0"
    }
  };
  doc[agg][`${tech} document`]=[{
    "analyst":"thingnet-ai (GSRN agent)",
    "measurement aggregate document":{
      "measurement document":[{
        "measurement identifier": id("GDTI","RESULT.0000001"),
        "measurement time": now,
        "sample document":{
          "sample identifier": id("LGTIN","632.LOT000001"),
          "batch identifier": "LOT-"+new Date().getFullYear()+"Q1",
          "description":"lot/batch-scoped material under test"
        },
        "device control aggregate document":{
          "device control document":[{"device identifier": id("GIAI","ASSET0001")}]
        },
        "processed data aggregate document":{
          "processed data document":[{"data processing document":{
            "method identifier": id("GDTI","66.0000001"),
            "method description":"versioned method/recipe document driving the run"
          }}]
        }
      }]
    }
  }];
  doc["thingdaddy in-context document"]={
    "td_pgln": `urn:epc:id:pgln:${prefix||"<prefix>"}.0`,
    "td_giai": id("GIAI","ASSET0001"), "td_cpi": id("CPI","CMP0001.000001"),
    "td_lgtin": id("LGTIN","632.LOT000001"), "td_gdti": id("GDTI","66.0000001"),
    "note":"Every ASM identifier above resolves through the ThingDaddy In-Context registry — EPCIS 2.0 provenance attaches to the same IDs."
  };
  return doc;
}

function AdfModule() {
  const { ids, prefix, activeCompany } = useIDs();
  const [filter,setFilter]=useState("All");
  const [selSchema,setSelSchema]=useState(null);
  const [adfView,setAdfView]=useState("graph"); // graph | steps
  const sectors=["All","Life Science","Medical","Industrial"];
  const shown=filter==="All"?ADF_SCHEMAS:ADF_SCHEMAS.filter(s=>s.sector===filter);
  // Full ADF protocol map overlay — opens when a schema card is clicked
  const ProtocolDetail = ()=>{
    if(!selSchema) return null;
    const c = SEC_COLORS[selSchema.sector]||GD.gray;
    const stages = adfProtocolMap(selSchema.schema, ids, prefix);
    return (
      <div onClick={()=>setSelSchema(null)} style={{position:"fixed",inset:0,background:"rgba(2,6,23,.6)",zIndex:100,display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"24px 12px",overflowY:"auto"}}>
        <div onClick={e=>e.stopPropagation()} style={{background:"#fff",borderRadius:14,maxWidth:760,width:"100%",boxShadow:"0 20px 60px rgba(0,0,0,.3)",overflow:"hidden"}}>
          <div style={{padding:"16px 18px",background:`linear-gradient(135deg,#0F172A,${c}22)`,display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
            <div>
              <div style={{fontSize:10,fontWeight:700,color:c,letterSpacing:".1em",marginBottom:3}}>ALLOTROPE ADF · FULL PROTOCOL MAP</div>
              <div style={{fontSize:18,fontWeight:800,color:"#fff",fontFamily:"'Fira Code',monospace"}}>{selSchema.schema}</div>
              <div style={{fontSize:11,color:"#94A3B8",marginTop:3}}>{selSchema.instruments}</div>
            </div>
            <button onClick={()=>setSelSchema(null)} style={{background:"transparent",border:"none",color:"#94A3B8",fontSize:22,cursor:"pointer",lineHeight:1}}>×</button>
          </div>
          <div style={{display:"flex",gap:0,borderBottom:"1px solid #E5E7EB"}}>
            {[["graph","→ ADM Flow"],["steps","≡ Protocol Steps"],["asm","{ } ASM JSON"]].map(([k,lbl])=>(
              <button key={k} onClick={()=>setAdfView(k)}
                style={{flex:1,padding:"11px",fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"inherit",
                  background:adfView===k?"#fff":"#F8FAFC",color:adfView===k?c:GD.gray,
                  border:"none",borderBottom:adfView===k?`2px solid ${c}`:"2px solid transparent"}}>{lbl}</button>
            ))}
          </div>
          {adfView==="graph" ? (
          <div style={{padding:"18px"}}>
            <div style={{fontSize:12,color:GD.gray,marginBottom:8,lineHeight:1.6}}>
              The Allotrope Framework: <b>AFO</b> (vocabulary → taxonomy → ontology, 2,400+ classes) defines the terms; <b>ADMs</b> (~65 interoperable data models, Apr 2026) are the blueprints; each model is delivered as <b>ASM</b> (standardized JSON) or <b>ADF</b> (RDF graphs in an HDF5 container). This protocol is one ADM flow — every node anchored to an in-context ThingDaddy ID.
            </div>
            <div style={{display:"flex",alignItems:"center",gap:4,flexWrap:"wrap",marginBottom:10,fontSize:9,fontWeight:700,color:GD.gray}}>
              {["Vocabulary","Taxonomy","Ontology (AFO)","Data Model (ADM)","ASM / ADF"].map((t,i)=>(
                <React.Fragment key={t}>
                  {i>0 && <span style={{color:"#CBD5E1"}}>{"→"}</span>}
                  <span style={{padding:"3px 8px",borderRadius:5,background:i<3?"#FFF7ED":"#EFF6FF",border:`1px solid ${i<3?"#FDBA74":"#93C5FD"}`,color:i<3?"#C2410C":"#1D4ED8"}}>{t}</span>
                </React.Fragment>
              ))}
            </div>
            {(()=>{
              const W=680,H=132,n=stages.length,gap=W/n;
              const pts=stages.map((st,i)=>({st,x:gap/2+i*gap,y:52}));
              return (
                <div>
                  <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",display:"block",margin:"0 auto"}}>
                    <defs>
                      <marker id="adfArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
                        <path d="M 0 0 L 10 5 L 0 10 z" fill="#94A3B8"/>
                      </marker>
                    </defs>
                    {pts.slice(0,-1).map((q,i)=>(
                      <line key={"a"+i} x1={q.x+20} y1={q.y} x2={pts[i+1].x-22} y2={pts[i+1].y} stroke="#94A3B8" strokeWidth="2" markerEnd="url(#adfArrow)"/>
                    ))}
                    {pts.map((q,i)=>(<g key={"n"+i}>
                      <circle cx={q.x} cy={q.y} r="17" fill={q.st.color}/>
                      <text x={q.x} y={q.y+4.5} textAnchor="middle" fontSize="12" fontWeight="800" fill="#fff">{i+1}</text>
                      <text x={q.x} y={q.y-26} textAnchor="middle" fontSize="9.5" fontWeight="800" fill={GD.dark}>{q.st.stage.split("· ")[1]}</text>
                      <text x={q.x} y={q.y+33} textAnchor="middle" fontSize="7.5" fill={GD.gray} fontFamily="'Fira Code',monospace">{q.st.afo.split(" ")[0]}</text>
                      <text x={q.x} y={q.y+46} textAnchor="middle" fontSize="8" fontWeight="800" fill={q.st.color} fontFamily="'Fira Code',monospace">{q.st.idType}</text>
                    </g>))}
                  </svg>
                  <div style={{marginTop:6}}>
                    {stages.map((st,i)=>(
                      <div key={i} style={{display:"flex",alignItems:"center",gap:8,fontSize:10,padding:"4px 0",borderTop:i?"1px solid #F1F3F5":"none"}}>
                        <span style={{width:18,height:18,borderRadius:9,background:st.color,color:"#fff",fontSize:10,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{i+1}</span>
                        <span style={{fontWeight:700,color:GD.dark,minWidth:88}}>{st.stage.split("· ")[1]}</span>
                        <span style={{color:GD.gray,fontFamily:"'Fira Code',monospace",fontSize:9}}>{st.afo}</span>
                        <span style={{marginLeft:"auto",fontSize:8,color:"#374151",fontFamily:"'Fira Code',monospace",wordBreak:"break-all",textAlign:"right"}}>{st.id}</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })()}
          </div>
          ) : adfView==="asm" ? (
          <div style={{padding:"18px"}}>
            {(()=>{ try {
              const asm=buildASMDocument(selSchema.schema, ids, prefix, selSchema.instruments);
              const txt=JSON.stringify(asm,null,2);
              return (
                <div>
                  <div style={{fontSize:12,color:GD.gray,marginBottom:10,lineHeight:1.6}}>
                    The actual <b>Allotrope Simple Model (ASM)</b> document for this protocol — the ADM rendered as standardized JSON. Note <span style={{fontFamily:"'Fira Code',monospace",fontSize:10,background:"#F1F5F9",padding:"1px 5px",borderRadius:4}}>asset management identifier</span>: the standard's own field, carrying the live ThingDaddy GIAI. (ADF is the same model as RDF graphs in an HDF5 container.)
                  </div>
                  <div style={{display:"flex",gap:8,marginBottom:8}}>
                    <button onClick={()=>{ try{
                      const blob=new Blob([txt],{type:"application/json"});
                      const u=URL.createObjectURL(blob); const aEl=document.createElement("a");
                      aEl.href=u; aEl.download=`${selSchema.schema.replace(/[^a-z0-9]+/gi,"-")}.asm.json`; aEl.click();
                      setTimeout(()=>URL.revokeObjectURL(u),2000);
                    }catch(_e){} }}
                      style={{fontSize:11,fontWeight:700,padding:"6px 14px",borderRadius:7,border:"none",cursor:"pointer",background:c,color:"#fff"}}>⬇ Download .asm.json</button>
                    <button onClick={()=>{ try{ navigator.clipboard && navigator.clipboard.writeText(txt); }catch(_e){} }}
                      style={{fontSize:11,fontWeight:700,padding:"6px 14px",borderRadius:7,cursor:"pointer",background:"#fff",color:GD.dark,border:"1px solid #E5E7EB"}}>⧉ Copy</button>
                  </div>
                  <pre style={{margin:0,padding:"12px",borderRadius:9,background:"#0F172A",color:"#E2E8F0",fontSize:9,lineHeight:1.55,maxHeight:380,overflow:"auto",fontFamily:"'Fira Code',monospace",whiteSpace:"pre-wrap",wordBreak:"break-all"}}>{txt}</pre>
                </div>
              );
            } catch(_e){ return <div style={{fontSize:12,color:GD.gray}}>ASM render unavailable.</div>; } })()}
          </div>
          ) : (
          <div style={{padding:"18px"}}>
            <div style={{fontSize:12,color:GD.gray,marginBottom:14,lineHeight:1.6}}>
              The ADF framework is constant; this protocol's vocabulary fills it. Each stage below is anchored to a unique, in-context ThingDaddy ID — so the entire run is provenanced end to end, from sample to data cube.
            </div>
            {stages.map((st,i)=>(
              <div key={i} style={{display:"flex",gap:12,marginBottom:12}}>
                <div style={{flexShrink:0,display:"flex",flexDirection:"column",alignItems:"center"}}>
                  <div style={{width:30,height:30,borderRadius:15,background:st.color,color:"#fff",fontSize:13,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center"}}>{i+1}</div>
                  {i<stages.length-1 && <div style={{width:2,flex:1,background:"#E5E7EB",marginTop:2}}/>}
                </div>
                <div style={{flex:1,paddingBottom:6}}>
                  <div style={{fontSize:13,fontWeight:800,color:GD.dark}}>{st.stage}</div>
                  <div style={{fontSize:9,color:GD.gray,fontFamily:"'Fira Code',monospace",marginBottom:3}}>{st.afo}</div>
                  <div style={{fontSize:11,color:GD.gray,lineHeight:1.5,marginBottom:5}}>{st.desc}</div>
                  <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
                    <span style={{fontSize:9,fontWeight:700,padding:"2px 7px",borderRadius:4,background:`${st.color}15`,color:st.color}}>{st.idType}</span>
                    <span style={{fontSize:9,color:"#374151",fontFamily:"'Fira Code',monospace",wordBreak:"break-all"}}>{st.id}</span>
                  </div>
                </div>
              </div>
            ))}
            <div style={{marginTop:8,padding:"10px 14px",borderRadius:9,background:`${c}10`,border:`1px solid ${c}33`}}>
              <span style={{fontSize:11,fontWeight:700,color:c}}>Same framework, swapped vocabulary. </span>
              <span style={{fontSize:11,color:GD.gray}}>This is the ADF skeleton expressed for {selSchema.schema}. The identical structure carries any industry's protocol — only the vocabulary changes — and every stage stays anchored to the company's in-context IDs.</span>
            </div>
          </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div style={{padding:"24px 20px"}}>
      {(()=>{ try { return <TDArtifactPanel icon="🧬" title="Allotrope — official sources" sub="AFO 2,400+ classes · ~65 ADMs (Apr 2026) · ASM JSON / ADF HDF5"
        items={[
          {label:"Reference index",filename:"allotrope_references.json",gen:()=>JSON.stringify({
            foundation:"https://www.allotrope.org",
            data_models:"Allotrope Foundation Datasets — JSON schemas per analytical device",
            open_source_converters:"Benchling Allotropy GitHub — instrument output → ASM",
            aws_mcp:"AWS Allotrope MCP Server — ASM tooling for agents",
            framework:["Vocabulary → Taxonomy → Ontology (AFO)","ADM data models (~65, Apr 2026)","ASM = standardized JSON","ADF = RDF graphs in HDF5"],
            thingdaddy_binding:"ASM 'asset management identifier' carries the live ThingDaddy GIAI — the standard's own slot for managed identity"},null,2),
            note:"Open a protocol card below → { } ASM JSON tab to see the live document with your IDs in the standard's fields."},
        ]}/>; } catch(_e){ return null; } })()}
      <ProtocolDetail />
      <CompanySearchHeader label="the Allotrope ADF workflow" accent={GD.purple} />
      <LiveIDsBanner module="Allotrope ADF" />
      <div style={{display:"flex",gap:8,marginBottom:16,flexWrap:"wrap"}}>
        {sectors.map(s=>(
          <button key={s} onClick={()=>setFilter(s)}
            style={{fontSize:11,padding:"5px 14px",borderRadius:20,cursor:"pointer",fontFamily:"inherit",fontWeight:600,
              background:filter===s?SEC_COLORS[s]||GD.green:GD.offWhite,
              color:filter===s?GD.white:GD.gray,border:filter===s?"none":`1px solid #E5E7EB`}}>
            {s}
          </button>
        ))}
        <div style={{marginLeft:"auto",fontSize:12,color:GD.gray,lineHeight:"28px"}}>{shown.length} schemas · {(()=>{ try { return TDCatalog.allProtocols().length; } catch(_e){ return 30; } })()} protocol stacks</div>
      </div>
      {(()=>{ try {
        const ps = TDCatalog.allProtocols();
        return (
          <div style={{margin:"4px 0 12px",padding:"10px 12px",border:`1px solid ${GD.purple}33`,borderRadius:10,background:"#FAF8FF"}}>
            <div style={{fontSize:12,fontWeight:700,color:GD.purple,marginBottom:6}}>⚗️ {ps.length} Allotrope protocol stacks — all live, pre-built &amp; In-Context ID'd</div>
            <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
              {ps.map((p,i)=>{
                const isFlag = p.source==="flagship";
                const match = shown.find(s=>s.schema && p.name && (s.schema.toLowerCase().includes(p.name.toLowerCase().split(" ")[0]) || p.name.toLowerCase().includes((s.schema||"").split("-")[0])));
                return (
                  <span key={i} title={p.id+" · live workflow"} onClick={()=>{ try{ if(match) setSelSchema(match); }catch(_e){} }}
                    style={{fontSize:11,padding:"3px 8px",borderRadius:999,cursor:"pointer",
                      background:isFlag?GD.greenLt:"#F0FDF4",
                      border:`1px solid ${GD.green}66`,color:GD.dark,
                      display:"inline-flex",alignItems:"center",gap:4}}>
                    <span style={{width:6,height:6,borderRadius:999,background:GD.green,flexShrink:0}}/>{p.name}
                  </span>
                );
              })}
            </div>
            <div style={{fontSize:10,color:GD.gray,marginTop:6}}>● Every stack is a full workflow — instruments, embedded sensors, consumables, SiLA functions, and ADF export — built through the same factory as the four reference protocols. Tap to open its ADF.</div>
          </div>
        );
      } catch(_e){ return null; } })()}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))",gap:10}}>
        {shown.map(s=>{
          const c=SEC_COLORS[s.sector]||GD.gray;
          return (
            <Card key={s.schema} style={{borderLeft:`4px solid ${c}`,cursor:"pointer"}} onClick={()=>setSelSchema(s)}>
              <div style={{padding:"12px 14px"}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
                  <div style={{fontSize:13,fontWeight:700,color:GD.dark,marginBottom:2,fontFamily:"'Fira Code',monospace"}}>{s.schema}</div>
                  <span style={{fontSize:9,fontWeight:700,color:c,whiteSpace:"nowrap"}}>open ADF →</span>
                </div>
                <div style={{display:"flex",gap:6,marginBottom:8}}>
                  <Tag color={c}>{s.sector}</Tag>
                </div>
                <div style={{fontSize:11,color:GD.gray}}>{s.instruments}</div>
                <div style={{marginTop:10,display:"flex",gap:4,flexWrap:"wrap"}}>
                  {["td_giai","td_cpi","td_lgtin","td_gdti"].map(f=>(
                    <span key={f} style={{fontSize:9,padding:"2px 6px",borderRadius:3,
                      background:`${c}12`,color:c,fontFamily:"'Fira Code',monospace",fontWeight:700}}>{f}</span>
                  ))}
                </div>
                {Object.keys(ids).length > 0 && (
                  <div style={{marginTop:8,paddingTop:8,borderTop:"1px solid #F3F4F6"}}>
                    {[
                      ["td_giai", ids["GIAI"]?.epc],
                      ["td_cpi",  ids["CPI"]?.epc],
                      ["td_lgtin",ids["LGTIN"]?.epc],
                      ["td_gdti", ids["GDTI"]?.epc],
                    ].filter(([,v])=>v).map(([k,v])=>(
                      <div key={k} style={{display:"flex",gap:4,marginBottom:2}}>
                        <span style={{fontSize:8,fontWeight:700,color:"#00A09C",minWidth:60,flexShrink:0}}>{k}</span>
                        <span style={{fontSize:8,color:"#374151",fontFamily:"'Fira Code',monospace",
                          wordBreak:"break-all",lineHeight:1.4}}>{v}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </Card>
          );
        })}
      </div>
    
      <StandardExplainer solutionKey="adf"/>
      </div>
  );
}

