// MODULE 4 — CONCERT & SYMPHONY
// ════════════════════════════════════════════════════════════════════════════════
const CONCERT_IDS = [
  {id:"GIAI",role:"The instrument itself",example:"giai:0085126.TF-QS12K-VQH-001",color:GD.teal},
  {id:"GMN", role:"The instrument family",example:"gmn:0085126:THERMO-FISHER-QS12K",color:GD.greenDk},
  {id:"CPID",role:"The active sensor",   example:"cpi:0614141.ELEM-TEMP.SN20240789",color:GD.purple},
  {id:"GTIN",role:"What is being made",  example:"7612345000016 — Cosentyx 150mg",color:GD.blue},
  {id:"GLN", role:"The concert hall",    example:"7612345000005 — Novartis Basel",color:GD.orange},
  {id:"sGLN",role:"The musician's seat", example:"sgln:7612345.000000.LAB01-BAY3",color:GD.red},
  {id:"GDTI",role:"The score / SOP",     example:"gdti:7612345.METHOD.HCD-SOP-v12",color:GD.teal},
  {id:"GSRN",role:"The named conductor", example:"gsrn:0000000.CLAUDE-SONNET-4-AGENT",color:GD.greenDk},
  {id:"SSCC",role:"The instrument case", example:"00761234500000001",color:GD.gray},
  {id:"GSIN",role:"The tour booking",    example:"gsin:7612345.DHL-20250415-0001",color:GD.blue},
  {id:"GRAI",role:"Instrument history",  example:"grai:0614141.CALIB-RACK.SN047",color:GD.orange},
  {id:"GCN", role:"Conductor stops show",example:"gcn:7612345.QC-HOLD-BATCH-B240115",color:GD.red},
];

const INDUSTRIES = [
  {ind:"Pharmaceutical",color:GD.blue,tension:"CPID temp 9.3°C (spec: 2-8°C). £18.4M Cosentyx batch at risk.",resolution:"GCN fires to DHL GLN, AIG GLN, Swissmedic GLN, Novartis QA GSRN in 2 seconds. Subrogation to DHL. Full resolution 4 hours."},
  {ind:"Aerospace",color:GD.orange,tension:"Ply 187 fibre CPID 0.32% outside GDTI tolerance. FAA DER must co-sign. Line paused.",resolution:"Claude AI THINK reviews 12 ADF records. Localises to one Hexcel tow spool GTIN. DER co-signs in 47 min."},
  {ind:"Automotive",color:GD.teal,tension:"KUKA electrode GRAI 952/1,000. Tomorrow needs 180 welds. Line will stop mid-vehicle.",resolution:"ThingWord fires 14 hours early. EUR 82, auto-approved. Replaced in tonight's shift. Zero disruption."},
  {ind:"Space / SpaceX",color:GD.purple,tension:"Raptor 3 bearing CPID 3.2mm/s trending up. 23% failure probability above 3.5mm/s.",resolution:"SKF ThingWord. Ceramic hybrid bearing, FAA-approved, $18K. Approved in 4 minutes. $12M avoided."},
  {ind:"Legal",color:GD.greenDk,tension:"Claude AI: GCN material-ip-risk on doc #412. £2.4B deal at risk.",resolution:"Freshfields IP ThingWord. IP transfer agreed. Deal closes. £18M Clifford Chance fee."},
  {ind:"Healthcare",color:GD.red,tension:"da Vinci EndoWrist GRAI 9/10. Tomorrow RALP needs 2-3. Discovery 16:23.",resolution:"ThingWord at 16:25. GTIN confirmed in OR supply. CPID authenticated. 07:30 proceeds."},
];


function ConcertModule() {
  const { ids, prefix, activeCompany } = useIDs();
  const [view,setView]=useState("ids");
  const [selID,setSelID]=useState(null);
  const [selInd,setSelInd]=useState(null);
  // Map CONCERT_IDS type to generated URN
  const liveURN = (idType) => {
    const map = {
      "GIAI":ids["GIAI"]?.epc,"GMN":ids["GMN"]?.epc,"CPID":ids["CPI"]?.epc,
      "GTIN":ids["GTIN"]?.epc,"GLN":ids["GLN"]?.epc,"sGLN":ids["GLN"]?.epc,
      "GDTI":ids["GDTI"]?.epc,"GSRN":ids["GSRN"]?.epc,"SSCC":ids["SSCC"]?.epc,
      "GSIN":ids["GSIN"]?.epc,"GRAI":ids["GRAI"]?.epc,"GCN":ids["GCN"]?.epc,
    };
    return map[idType] || null;
  };
  return (
    <div style={{padding:"24px 20px"}}>
      <CompanySearchHeader label="the orchestration" accent={GD.purple} />
      <LiveIDsBanner module="Concert + Symphony" />
      <div style={{display:"flex",gap:8,marginBottom:20}}>
        {[["ids",`${TD_TYPE_COUNT} Universal IDs`],["industries","6 Industries"],["timeline","Timeline"]].map(([v,l])=>(
          <Btn key={v} onClick={()=>setView(v)} variant={view===v?"primary":"outline"} small>{l}</Btn>
        ))}
      </div>

      {view==="ids" && (
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:7}}>
          {CONCERT_IDS.map(item=>{
            const sel=selID===item.id;
            return (
              <Card key={item.id} style={{borderTop:`2px solid ${item.color}`,cursor:"pointer"}}
                onClick={()=>setSelID(sel?null:item.id)}>
                <div style={{padding:"7px 9px",background:sel?`${item.color}08`:GD.white}}>
                  <div style={{fontSize:12,fontWeight:800,color:item.color,marginBottom:2}}>{item.id}</div>
                  <div style={{fontSize:9,color:GD.gray,marginBottom:4}}>{item.role}</div>
                  {ids[item.id] ? (
                    <div style={{fontSize:8,color:item.color,fontFamily:"'Fira Code',monospace",
                      wordBreak:"break-all",background:`${item.color}10`,
                      padding:"3px 5px",borderRadius:3,border:`1px solid ${item.color}33`,
                      display:"flex",alignItems:"flex-start",gap:4}}>
                      <span style={{color:"#3DB54A",fontWeight:900,flexShrink:0}}>●</span>
                      {ids[item.id].epc||ids[item.id].id}
                    </div>
                  ) : (
                    <div style={{fontSize:10,color:GD.grayLt,fontFamily:"'Fira Code',monospace",wordBreak:"break-all"}}>{item.example}</div>
                  )}
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {view==="industries" && (
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:12}}>
          {INDUSTRIES.map(ind=>{
            const sel=selInd===ind.ind;
            return (
              <Card key={ind.ind} style={{borderTop:`4px solid ${ind.color}`,cursor:"pointer"}}
                onClick={()=>setSelInd(sel?null:ind.ind)}>
                <div style={{padding:"14px 16px",background:sel?`${ind.color}08`:GD.white}}>
                  <div style={{fontSize:14,fontWeight:800,color:ind.color,marginBottom:8}}>{ind.ind}</div>
                  <div style={{fontSize:11,fontWeight:600,color:GD.gray,marginBottom:4}}>⚡ Tension</div>
                  <div style={{fontSize:11,color:GD.dark,lineHeight:1.5,marginBottom:sel?12:0}}>{ind.tension}</div>
                  {sel && <>
                    <div style={{height:1,background:"#F3F4F6",margin:"10px 0"}}/>
                    <div style={{fontSize:11,fontWeight:600,color:GD.greenDk,marginBottom:4}}>✅ Resolution</div>
                    <div style={{fontSize:11,color:GD.dark,lineHeight:1.5}}>{ind.resolution}</div>
                  </>}
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {view==="timeline" && (
        <div style={{maxWidth:700}}>
          {[
            {t:"T+0:00",e:"HMT310 CPID fluorescence 0.9847. GRAI: 8,142/8,500. ThingWords AI fires.",ids:"GIAI · CPID · GMN · GRAI"},
            {t:"T+0:07",e:"EDI 850 auto-generated to Honeywell. GIAI in MAN(8004). Zero human touchpoints.",ids:"+ GDTI · GSRN · GLN buyer/seller · GTIN"},
            {t:"T+6h",  e:"DHL Freiburg hub. Temp CPID: 7.8°C (within spec). SSCC scanned.",ids:"+ SSCC · GSIN · GINC · GLN DHL"},
            {t:"T+72h", e:"Novartis Basel Goods-In. RFID gate reads SSCC. WMS routes to Lab 1 Bay 3.",ids:"+ sGLN (Goods-In) · All prior IDs"},
            {t:"T+72h+20m",e:"New HMT310 CPID authenticated: prefix OK · GEPIR registered · GRAI day 0.",ids:"+ CPID new · GRAI new · Old CPID (DESTROY)"},
            {t:"T+72h+23m",e:"CPID fluorescence 0.9993. GDTI 3-way match. SAP payment released. Zero deviation.",ids:"All 13 IDs in ADF MaintenanceRecord"},
          ].map((step,i)=>(
            <div key={i} style={{display:"flex",gap:12,marginBottom:12}}>
              <div style={{width:90,flexShrink:0,textAlign:"right"}}>
                <span style={{fontSize:10,fontWeight:700,color:GD.green,fontFamily:"'Fira Code',monospace"}}>{step.t}</span>
              </div>
              <div style={{width:2,background:GD.green,flexShrink:0,borderRadius:2}}/>
              <Card style={{flex:1}}>
                <div style={{padding:"10px 12px"}}>
                  <div style={{fontSize:12,color:GD.dark,lineHeight:1.5,marginBottom:4}}>{step.e}</div>
                  <div style={{fontSize:10,color:GD.teal,fontFamily:"'Fira Code',monospace"}}>{step.ids}</div>
                </div>
              </Card>
            </div>
          ))}
        </div>
      )}
    
      <StandardExplainer solutionKey="symphony"/>
      </div>
  );
}

