// MODULE 5 — SEMANTIC RETROFIT
// ════════════════════════════════════════════════════════════════════════════════
const LEGACY_SYSTEMS = [
  {id:"SAP_PM",   label:"SAP Plant Maintenance",  field:"Equipment Number",   placeholder:"10023847",   tdType:"TD:GIAI",color:GD.teal},
  {id:"MAXIMO",   label:"IBM Maximo",              field:"Asset Number",       placeholder:"AST-00042371",tdType:"TD:GIAI",color:GD.teal},
  {id:"LIMS",     label:"LabWare / Labvantage",   field:"Instrument Code",    placeholder:"TF-VNQ-001", tdType:"TD:GIAI",color:GD.teal},
  {id:"AWS_IOT",  label:"AWS IoT Core",            field:"Thing Name",         placeholder:"UHPLC-Floor2",tdType:"TD:GIAI",color:GD.purple},
  {id:"SAP_MM",   label:"SAP Material Master",     field:"Material Number",    placeholder:"MAT-DOVE-200",tdType:"TD:GTIN",color:GD.green},
  {id:"VEEVA",    label:"Veeva / MasterControl",   field:"Document Number",    placeholder:"SOP-QA-HPLC",tdType:"TD:GDTI",color:GD.orange},
  {id:"BMS",      label:"Building Mgmt / IWMS",    field:"Location Code",      placeholder:"LAB01-F2-BAY3",tdType:"TD:sGLN",color:GD.blue},
  {id:"HR",       label:"HR / SAP HCM",            field:"Employee ID",        placeholder:"EMP-00421",  tdType:"TD:GSRN",color:GD.green},
];

const PHASES = [
  {n:"1",name:"AUDIT",  color:GD.teal,   weeks:"2-4w",desc:"TD:AUDIT scans all systems in 48-72h. Complete legacy ID inventory with confidence scores.",steps:["Automated connectors scan all source systems","Every ID mapped to candidate ThingDaddy type","Confidence scoring and manual review queue","Gap analysis: unresolvable assets flagged","Executive report: cost of ID chaos quantified"]},
  {n:"2",name:"MAP",    color:GD.blue,   weeks:"4-6w",desc:"Deterministic rules assign every legacy ID its canonical GS1 EPC URN equivalent.",steps:["15 physical asset mapping rules (EQUNR→GIAI)","14 digital asset rules (PO→GDTI, SOP→GDTI)","Cross-system deduplication via GEPIR verification","Low-confidence mappings routed to human review","All rules stored permanently in TD:VAULT"]},
  {n:"3",name:"BRIDGE", color:GD.green,  weeks:"4-8w",desc:"TD:BRIDGE microservice deployed alongside existing systems. Zero database changes.",steps:["REST/GraphQL microservice — Docker/K8s","40+ TD:SYNC pre-built connectors","TD:WATCH real-time change detection","TD:VERIFY EPCIS 2.0 immutable audit trail","TD:ASK AI interface for Claude + LLMs"]},
  {n:"4",name:"SEED",   color:GD.orange, weeks:"4-8w",desc:"Every new asset born with a ThingDaddy ID from Go-Live forward.",steps:["PO intercept: GIAI template at purchase order","Goods receipt: GIAI finalised on serial number","Document first-save: GDTI assigned instantly","IoT provisioning: GIAI overwrites thing name","CAD first-save: 5 TD parameters embedded"]},
];

function buildURN(sysId, legacyId, prefix="0085126") {
  const rules = {
    SAP_PM: `urn:epc:id:giai:${prefix}.${legacyId.replace(/\s/g,"-")}`,
    MAXIMO: `urn:epc:id:giai:${prefix}.${legacyId.replace(/\s/g,"-")}`,
    LIMS:   `urn:epc:id:giai:${prefix}.${legacyId.replace(/\s/g,"-")}`,
    AWS_IOT:`urn:epc:id:giai:${prefix}.${legacyId.replace(/[\s-]/g,"_").slice(0,24)}`,
    SAP_MM: `urn:epc:id:sgtin:${prefix}.${legacyId.replace(/\s/g,"-")}.LOT001`,
    VEEVA:  `urn:epc:id:gdti:${prefix}.DOC.${legacyId.replace(/\s/g,"-")}`,
    BMS:    `urn:epc:id:sgln:${prefix}.${legacyId.replace(/\s/g,"-")}.0`,
    HR:     `urn:epc:id:gsrn:${prefix}.${legacyId.replace(/\s/g,"-")}`,
  };
  return rules[sysId] || `urn:epc:id:giai:${prefix}.${legacyId}`;
}


function RetrofitModule() {
  const { ids, prefix: ctxPrefix } = useIDs();
  const [view,setView]=useState("bridge");
  const [selSys,setSelSys]=useState(LEGACY_SYSTEMS[0]);
  const [legacyId,setLegacyId]=useState("");
  const [prefix,setPrefix]=useState(ctxPrefix||"0085126");
  const [result,setResult]=useState(null);

  // Auto-sync prefix from ID Generator when it changes
  useEffect(()=>{ if(ctxPrefix) setPrefix(ctxPrefix); },[ctxPrefix]);

  // Auto-populate legacyId from GIAI if generated
  useEffect(()=>{
    if(ids["GIAI"]?.epc && selSys.id==="SAP_PM") {
      const parts = ids["GIAI"].epc.split(".");
      setLegacyId(parts[parts.length-1]||"");
    }
  },[ids, selSys.id]);

  const resolve = () => {
    const id = legacyId.trim() || selSys.placeholder;
    setResult({
      legacyId:id, system:selSys.label, tdType:selSys.tdType,
      urn:buildURN(selSys.id, id, prefix),
      confidence:(0.92+Math.random()*0.07).toFixed(3),
      resolvedAt:new Date().toISOString(),
    });
  };

  return (
    <div style={{padding:"24px 20px"}}>
      <CompanySearchHeader label="the legacy retrofit" accent={GD.orange} />
      <div style={{display:"flex",gap:8,marginBottom:20,flexWrap:"wrap"}}>
        {[["bridge","TD:BRIDGE"],["phases","4 Phases"],["packages","Packages"]].map(([v,l])=>(
          <Btn key={v} onClick={()=>setView(v)} variant={view===v?"primary":"outline"} small>{l}</Btn>
        ))}
      </div>

      {view==="bridge" && (
        <div style={{maxWidth:660}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(160px,1fr))",gap:8,marginBottom:18}}>
            {LEGACY_SYSTEMS.map(s=>(
              <div key={s.id} onClick={()=>{setSelSys(s);setResult(null);setLegacyId("");}}
                style={{cursor:"pointer",padding:"10px 12px",borderRadius:8,textAlign:"center",
                  background:selSys.id===s.id?`${s.color}12`:GD.white,
                  border:`2px solid ${selSys.id===s.id?s.color:"#E5E7EB"}`,transition:"all .15s"}}>
                <div style={{fontSize:11,fontWeight:700,color:selSys.id===s.id?s.color:GD.dark}}>{s.label}</div>
                <div style={{fontSize:9,color:GD.gray,marginTop:2}}>{s.field}</div>
              </div>
            ))}
          </div>
          <Card style={{marginBottom:14}}>
            <div style={{padding:"16px 18px"}}>
              <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
                <div style={{flex:"0 0 130px"}}>
                  <label style={{fontSize:11,fontWeight:600,color:GD.gray,display:"block",marginBottom:4}}>GS1 Prefix</label>
                  <input value={prefix} onChange={e=>setPrefix(e.target.value)}
                    style={{width:"100%",padding:"8px 10px",borderRadius:6,border:`1.5px solid ${GD.darkBrd}`,
                      fontSize:12,fontFamily:"'Fira Code',monospace",outline:"none",boxSizing:"border-box"}}/>
                </div>
                <div style={{flex:"0 0 220px"}}>
                  <label style={{fontSize:11,fontWeight:600,color:GD.gray,display:"block",marginBottom:4}}>Or pick company</label>
                  <CompanyDropdown value={prefix} onChange={(pfx)=>setPrefix(pfx)} />
                </div>
                <div style={{flex:1,minWidth:180}}>
                  <label style={{fontSize:11,fontWeight:600,color:GD.gray,display:"block",marginBottom:4}}>{selSys.field}</label>
                  <input value={legacyId} onChange={e=>setLegacyId(e.target.value)}
                    placeholder={selSys.placeholder} onKeyDown={e=>e.key==="Enter"&&resolve()}
                    style={{width:"100%",padding:"8px 10px",borderRadius:6,border:`1.5px solid ${GD.darkBrd}`,
                      fontSize:12,fontFamily:"'Fira Code',monospace",outline:"none",boxSizing:"border-box"}}/>
                </div>
              </div>
              <Btn onClick={resolve} style={{width:"100%"}}>▶ Resolve to ThingDaddy GS1 URN</Btn>
            </div>
          </Card>
          {result && (
            <Card style={{borderTop:`4px solid ${GD.green}`}}>
              <div style={{padding:"16px 18px"}}>
                <div style={{fontSize:11,fontWeight:700,color:GD.greenDk,marginBottom:10,letterSpacing:".08em"}}>✓ RESOLVED — TD:BRIDGE RESPONSE</div>
                {[["Legacy ID",result.legacyId,GD.dark],["Source System",result.system,GD.gray],[result.tdType,result.urn,GD.green],["Confidence",`${(result.confidence*100).toFixed(1)}%`,GD.teal],["EPCIS Logged",result.resolvedAt,GD.gray]].map(([k,v,c])=>(
                  <div key={k} style={{display:"flex",gap:10,padding:"6px 0",borderBottom:`1px solid ${GD.offWhite}`}}>
                    <div style={{minWidth:110,fontSize:11,fontWeight:600,color:GD.grayLt,flexShrink:0}}>{k}</div>
                    <div style={{fontSize:11,color:c,wordBreak:"break-all",fontFamily:"'Fira Code',monospace"}}>{v}</div>
                  </div>
                ))}
              </div>
            </Card>
          )}
        </div>
      )}

      {view==="phases" && (
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))",gap:12}}>
          {PHASES.map(p=>(
            <Card key={p.n} style={{borderTop:`4px solid ${p.color}`}}>
              <div style={{padding:"14px 16px"}}>
                <div style={{display:"flex",alignItems:"baseline",gap:8,marginBottom:6}}>
                  <span style={{fontSize:24,fontWeight:900,color:p.color}}>PHASE {p.n}</span>
                  <span style={{fontSize:14,fontWeight:700,color:GD.dark}}>{p.name}</span>
                  <GreenBadge>{p.weeks}</GreenBadge>
                </div>
                <div style={{fontSize:12,color:GD.gray,marginBottom:10,lineHeight:1.5}}>{p.desc}</div>
                {(p.steps||[]).map((s,i)=>(
                  <div key={i} style={{display:"flex",gap:6,marginBottom:5}}>
                    <span style={{color:p.color,flexShrink:0,fontWeight:700}}>▸</span>
                    <span style={{fontSize:11,color:GD.dark}}>{s}</span>
                  </div>
                ))}
              </div>
            </Card>
          ))}
        </div>
      )}

      {view==="packages" && (
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(240px,1fr))",gap:12}}>
          {[
            {name:"TD:START",price:"$25,000",weeks:"4w",color:GD.teal,desc:"Single site · 3 systems · Complete legacy ID inventory"},
            {name:"TD:MAP",price:"$45,000",weeks:"6w",color:GD.blue,desc:"One system fully retrofitted · All assets mapped to GS1 URN"},
            {name:"TD:DIGITAL",price:"$35,000",weeks:"5w",color:GD.purple,desc:"All documents, certs, contracts assigned TD:GDTI"},
            {name:"TD:SEED",price:"$60,000",weeks:"8w",color:GD.orange,desc:"Every new asset born with ThingDaddy ID from Go-Live"},
            {name:"TD:SYNC",price:"$120K-350K",weeks:"16w",color:GD.greenDk,desc:"Full enterprise retrofit · All connectors · AI ready"},
            {name:"TD:FULL",price:"$250K-600K",weeks:"24w",color:GD.red,desc:"Legacy solved + Forward locked. Total transformation."},
          ].map(pkg=>(
            <Card key={pkg.name} style={{borderTop:`4px solid ${pkg.color}`}}>
              <div style={{padding:"14px 16px"}}>
                <div style={{fontSize:16,fontWeight:800,color:pkg.color,marginBottom:4}}>{pkg.name}</div>
                <div style={{fontSize:22,fontWeight:900,color:GD.dark,marginBottom:2}}>{pkg.price}</div>
                <GreenBadge>{pkg.weeks}</GreenBadge>
                <div style={{fontSize:12,color:GD.gray,marginTop:10,lineHeight:1.5}}>{pkg.desc}</div>
              </div>
            </Card>
          ))}
        </div>
      )}
    
      <StandardExplainer solutionKey="retrofit"/>
      </div>
  );
}

