const AVAIL_COLOR = (a) => {
  const s = (a||"").toLowerCase();
  if (s.includes("public") || s.includes("open") || s.includes("free")) return "#16A34A";
  if (s.includes("licensed") || s.includes("enterprise")) return "#D97706";
  return "#6B7280";
};

