const SDK_SECTOR_NORM = (r) => {
  const c = (r.category||"") + " " + (r.type||"");
  const s = c.toLowerCase();
  if (s.match(/genomic|chromatograph|mass spec|bioprocess|purification|spectroscopy|plate reader|clinical|imaging|informatics/)) return "Life Sciences";
  if (s.match(/industrial|process|robotics|vision|grid|energy/)) return "Industrial";
  if (s.match(/cloud|enterprise/)) return "Enterprise";
  return r.category || "Other";
};

