function TDEcoPanel(){
  const [selKey,setSelKey]=React.useState(null);
  const [data]=React.useState(()=>{ try{
    const reg=TDIncontext.createRegistry(); const r=TDEcoLibrary.buildAll(reg);
    const tesla=[...r.E.nodes.values()].find(n=>n.name==="Tesla");
    return {built:r.built,E:r.E,reach:tesla?r.E.graphReach(tesla.party):null};
  }catch(_e){return null;} });
  try{
    if(!data) return null;
    const spec=selKey?TDEcoLibrary.LIB.find(l=>l.key===selKey):null;
    const REL_STYLE={up:{c:"#F59E0B",t:"supplies →"},down:{c:"#3B82F6",t:"← distributes/serves market"},horiz:{c:"#8B5CF6",t:"partners with"},serve:{c:"#0D9488",t:"services"}};
    const W=340,H=300,cx=W/2,cy=H/2,R=108;
    return (
      <div style={{margin:"0 0 20px",border:`1px solid ${GD.green}44`,borderRadius:10,overflow:"hidden"}}>
        <div style={{padding:"10px 14px",background:"#111827"}}>
          <span style={{fontSize:13,fontWeight:800,color:"#fff"}}>🌐 Six Ecosystems — the graph is the asset </span>
          <span style={{fontSize:11,fontWeight:800,color:"#FFCD11"}}>(live)</span>
          <span style={{fontSize:11,color:"#9CA3AF",marginLeft:8}}>{data.E.nodes.size} companies · {data.E.edges.length} typed edges · tap a hub</span>
        </div>
        <div style={{padding:"12px 14px"}}>
          <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:8}}>
            {data.built.map((b,i)=>{
              const k=TDEcoLibrary.LIB[i].key; const on=k===selKey;
              return (<button key={k} onClick={()=>setSelKey(on?null:k)}
                style={{fontSize:11,padding:"4px 10px",borderRadius:999,cursor:"pointer",
                  background:on?GD.dark:GD.greenLt,border:`1px solid ${on?GD.dark:GD.green+"55"}`,color:on?"#fff":GD.dark,fontWeight:on?800:500}}>
                {b.hub} · {b.partners} partners</button>);
            })}
          </div>
          {!spec && data.reach && <div style={{fontSize:11,color:GD.gray}}>
            <b style={{color:GD.dark}}>Everything connects:</b> Tesla reaches {data.reach.reached} of {data.E.nodes.size} companies across all six ecosystems — shared nodes (Qualcomm, Honeywell, Bosch, Thermo) stitch the worlds into one graph.
          </div>}
          {spec && (()=>{ try{
            const ring=spec.ring.slice(0,12);
            const pts=ring.map((p,i)=>{const a=-Math.PI/2+i*2*Math.PI/ring.length;return {x:cx+R*Math.cos(a),y:cy+R*Math.sin(a),p};});
            return (
              <div>
                <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",maxWidth:420,display:"block",margin:"4px auto"}}>
                  {pts.map((q,i)=>(<line key={"l"+i} x1={cx} y1={cy} x2={q.x} y2={q.y} stroke={(REL_STYLE[q.p.dir]||REL_STYLE.horiz).c} strokeWidth="1.6" opacity="0.85"/>))}
                  {pts.map((q,i)=>(<g key={"n"+i}>
                    <circle cx={q.x} cy={q.y} r="7" fill="#fff" stroke={(REL_STYLE[q.p.dir]||REL_STYLE.horiz).c} strokeWidth="2"/>
                    <text x={q.x} y={q.y + (q.y>cy?20:-13)} textAnchor="middle" fontSize="8.5" fill={GD.dark}>{q.p.name.split(" (")[0].slice(0,16)}</text>
                  </g>))}
                  <circle cx={cx} cy={cy} r="26" fill={GD.dark}/>
                  <text x={cx} y={cy+3} textAnchor="middle" fontSize="9" fontWeight="800" fill="#fff">{spec.hub.name.split(" ")[0]}</text>
                </svg>
                <div style={{fontSize:10,color:GD.gray,textAlign:"center",marginBottom:8}}>
                  <span style={{color:"#F59E0B"}}>● suppliers</span>  <span style={{color:"#3B82F6"}}>● customers/distributors</span>  <span style={{color:"#8B5CF6"}}>● partners</span>  <span style={{color:"#0D9488"}}>● services</span>
                </div>
                {spec.ring.map((p,i)=>(
                  <div key={i} style={{display:"flex",alignItems:"center",gap:8,fontSize:11,padding:"4px 0",borderTop:i?"1px solid #F1F3F5":"none"}}>
                    <span style={{width:8,height:8,borderRadius:99,background:(REL_STYLE[p.dir]||REL_STYLE.horiz).c,flexShrink:0}}/>
                    <span style={{color:GD.dark,fontWeight:600,flex:1}}>{p.name}</span>
                    <span style={{color:GD.gray,fontSize:10}}>{p.industry}</span>
                    <span style={{fontFamily:"'Fira Code',monospace",fontSize:9,color:GD.green}}>{p.prefix}</span>
                  </div>
                ))}
              </div>
            );
          }catch(_e){return null;} })()}
        </div>
      </div>
    );
  }catch(_e){return null;}
}


