const SEED_SECTORS = [...new Set(TD_SEED_ID_UNIVERSE.map(x=>x.sector))];

// ── SEED RESULT: maps an existing ID to a ThingDaddy URN ─────────────────────
function buildSeedURN(prefix, idType, existingId) {
  const clean = (existingId||"").trim().replace(/[^a-zA-Z0-9\-_.]/g,"-").toUpperCase();
  const ts    = Date.now().toString(36).toUpperCase();
  switch(idType) {
    case "GTIN":  return makeGTINurn(prefix, clean.slice(0,6)||"PROD01", 0);
    case "GLN":   return makeGLNurn(prefix,"000001");
    case "PGLN":  return makePGLNurn(prefix);
    case "GIAI":  return makeGIAIurn(prefix, clean||"ASSET-"+ts);
    case "LGTIN": return makeLGTINurn(prefix,"PROD001",clean||"LOT-"+ts);
    case "GDTI":  return makeGDTIurn(prefix,"DOC-"+ts,clean||"001");
    case "GSRN":  return makeGSRNurn(prefix,"SVC-"+clean||"SVC-"+ts);
    case "CPI":   return makeCPIurn(prefix,"COMP-"+ts,clean||"001");
    case "GMN":   return makeGMNurn(prefix,"MODEL-"+clean);
    case "SSCC":  return makeSSCCurn(prefix,"9"+clean.slice(0,12).replace(/\D/g,"").padStart(12,"0"));
    default:      return makeGIAIurn(prefix, clean||"ITEM-"+ts);
  }
}

function SeedModule() {
  const { ids, prefix, activeCompany } = useIDs();
  const [selSector, setSelSector]   = useState("All");
  const [search,    setSearch]      = useState("");
  const [entries,   setEntries]     = useState([
    {id:"", idType:"", mappedType:"", urn:"", existingId:"", sector:"", status:"", source:""}
  ]);
  const [results,   setResults]     = useState([]);
  const [aiLoading, setAiLoading]   = useState(false);
  const [bulkText,  setBulkText]    = useState("");
  const [bulkMode,  setBulkMode]    = useState(false);
  const [view,      setView]        = useState("map"); // map | bulk | graph | export

  // Filter ID types
  const filtered = TD_SEED_ID_UNIVERSE.filter(t=>{
    const inSector = selSector==="All" || t.sector===selSector;
    const q = search.toLowerCase();
    const inSearch = !q || t.id.toLowerCase().includes(q) || t.desc.toLowerCase().includes(q) || t.map.toLowerCase().includes(q);
    return inSector && inSearch;
  });

  // Map a single entry
  const mapEntry = (entry) => {
    if(!prefix||!entry.existingId) return entry;
    const urn = buildSeedURN(prefix, entry.mappedType, entry.existingId);
    return {...entry, urn, status:"MAPPED"};
  };

  // AI-powered bulk ID recognition
  const runAIBulk = async () => {
    if(!bulkText.trim()) return;
    setAiLoading(true);
    try {
      const resp = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:1000,
          messages:[{role:"user", content:
            `You are a ThingDaddy ID mapping engine. Parse this list of IDs and identify each type.\n\n${bulkText}\n\n` +
            `For each line, identify: id_type (GTIN/GLN/VIN/SAP_MATERIAL/SAP_PLANT/SAP_VENDOR/SAP_SERIAL/SAP_BATCH/` +
            `MAXIMO_ASSET/AWS_IOT_ARN/AZURE_DEVICE/OPC_UA/HART_TAG/NATO_NSN/CAGE_CODE/DOD_UID/FDA_UDI/NDC_DRUG/` +
            `MANUAL_NUMBER/SDS_NUMBER/PATENT/DUNS/LEI/ISBN/VIN/OEM_PART/UNKNOWN), ` +
            `the ThingDaddy mapping (GTIN/GLN/PGLN/GIAI/LGTIN/GDTI/GSRN/CPI/GMN/SSCC), ` +
            `and the sector. Return ONLY a JSON array:\n` +
            `[{"original":"raw id","id_type":"type","td_map":"GIAI","sector":"Cloud/IoT","company":"if determinable","confidence":"high|medium|low"}]`
          }]
        })
      });
      const data = await resp.json();
      const raw  = (data.content?.[0]?.text||"[]").replace(/```json|```/g,"").trim();
      const parsed = JSON.parse(raw);
      const mapped = parsed.map(item=>({
        existingId:  item.original,
        id:          item.id_type,
        mappedType:  item.td_map,
        sector:      item.sector,
        company:     item.company||"",
        confidence:  item.confidence,
        urn:         prefix ? buildSeedURN(prefix, item.td_map, item.original) : "",
        status:      item.confidence==="high"?"MAPPED":"NEEDS_REVIEW",
      }));
      setResults(prev=>[...prev,...mapped]);
    } catch(e) { console.error(e); }
    setAiLoading(false);
  };

  const addResult = (type, existingId) => {
    if(!prefix||!existingId.trim()) return;
    const urn = buildSeedURN(prefix, type.map, existingId);
    setResults(prev=>[{
      existingId, id:type.id, mappedType:type.map,
      sector:type.sector, urn, status:"MAPPED", company:"",
    },...prev]);
  };

  const exportCSV = () => {
    const header = "Existing ID,ID Type,Sector,ThingDaddy URN,TD Type,Status\n";
    const rows = results.map(r=>`"${r.existingId}","${r.id}","${r.sector}","${r.urn}","${r.mappedType}","${r.status}"`).join("\n");
    const blob = new Blob([header+rows], {type:"text/csv"});
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `thingdaddy_seed_${Date.now()}.csv`;
    a.click();
  };

  const TD_MAP_COLOR = {
    GTIN:"#16A34A",GLN:"#0891B2",PGLN:"#6D28D9",GIAI:"#2563EB",
    LGTIN:"#DC2626",GDTI:"#D97706",GSRN:"#DB2877",CPI:"#7C3AED",
    GMN:"#059669",SSCC:"#EA580C",
  };

  return (
    <div style={{fontFamily:"'Inter',system-ui,sans-serif",background:"#F8FAFC",minHeight:"100vh"}}>

      {/* HEADER */}
      <div style={{background:"#111827",padding:"16px 24px"}}>
        <div style={{fontSize:10,fontWeight:700,color:"#4B5563",letterSpacing:".15em",marginBottom:4}}>
          THINGDADDY PLATFORM · DIGITAL CIVILIZATION NETWORK
        </div>
        <div style={{fontSize:22,fontWeight:900,color:"#fff",marginBottom:4}}>
          🌱 TD:SEED — Universal ID Mapping Engine
        </div>
        <div style={{fontSize:12,color:"#6B7280",marginBottom:14}}>
          Map any existing ID from any system to a ThingDaddy URN · 86 ID types · 11 sectors ·
          SAP · AWS IoT · VIN · DUNS · CAGE · UDI · OPC UA · HART · and more
        </div>
        <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}>
          <div>
            <div style={{fontSize:10,color:"#4B5563",marginBottom:4}}>GS1 PREFIX (your company)</div>
            <input value={prefix} onChange={e=>setPrefix(e.target.value.replace(/\D/g,""))}
              placeholder="e.g. 239132 (Dana) or 0860009 (Tesla)"
              style={{padding:"8px 14px",borderRadius:8,border:"1.5px solid #374151",
                background:"#1F2937",color:"#fff",fontFamily:"monospace",fontSize:13,
                outline:"none",width:280}}/>
          </div>
          <div style={{display:"flex",gap:6,marginTop:18}}>
            {[["map","🗂️","Map IDs"],["bulk","📋","Bulk Import"],["graph","🌐","ID Graph"],["export","📤","Export"]].map(([v,icon,label])=>(
              <button key={v} onClick={()=>setView(v)}
                style={{padding:"8px 16px",borderRadius:8,cursor:"pointer",fontFamily:"inherit",
                  fontSize:11,fontWeight:view===v?700:400,border:"none",
                  background:view===v?"#3DB54A":"#1F2937",
                  color:view===v?"#fff":"#9CA3AF"}}>
                {icon} {label}
              </button>
            ))}
          </div>
          <div style={{marginLeft:"auto",textAlign:"right"}}>
            <div style={{fontSize:24,fontWeight:900,color:"#3DB54A"}}>{results.length}</div>
            <div style={{fontSize:10,color:"#4B5563"}}>IDs mapped</div>
          </div>
        </div>
      </div>

      <div style={{padding:"20px 24px"}}>

        {/* ── MAP VIEW ── */}
        {view==="map" && (
          <div style={{display:"grid",gridTemplateColumns:"1fr 380px",gap:20}}>
            <div>
              {/* Sector + search filters */}
              <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:14,alignItems:"center"}}>
                <div style={{position:"relative"}}>
                  <input value={search} onChange={e=>setSearch(e.target.value)}
                    placeholder="🔍 Search ID types..."
                    style={{padding:"8px 14px",borderRadius:20,border:"1px solid #E5E7EB",
                      background:"#fff",fontFamily:"inherit",fontSize:12,outline:"none",width:220}}/>
                </div>
                {["All",...SEED_SECTORS].map(s=>(
                  <button key={s} onClick={()=>setSelSector(s)}
                    style={{padding:"6px 14px",borderRadius:16,cursor:"pointer",fontFamily:"inherit",
                      fontSize:10,fontWeight:selSector===s?700:400,border:"none",
                      background:selSector===s?(SECTOR_COLORS[s]||"#3DB54A")+"22":"#F3F4F6",
                      color:selSector===s?(SECTOR_COLORS[s]||"#3DB54A"):"#6B7280",
                      outline:selSector===s?`1.5px solid ${SECTOR_COLORS[s]||"#3DB54A"}`:"none"}}>
                    {s}
                  </button>
                ))}
              </div>

              {/* ID type cards */}
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(300px,1fr))",gap:8}}>
                {filtered.map((type,i)=>{
                  const [localId,setLocalId] = [null,null]; // stateless card
                  return (
                    <div key={i} style={{background:"#fff",borderRadius:10,padding:"12px 14px",
                      border:"1px solid #E5E7EB",display:"flex",flexDirection:"column",gap:8}}>
                      <div style={{display:"flex",alignItems:"center",gap:8}}>
                        <span style={{fontSize:20}}>{type.icon}</span>
                        <div style={{flex:1}}>
                          <div style={{fontSize:12,fontWeight:700,color:"#111827"}}>{type.id}</div>
                          <div style={{fontSize:10,color:"#6B7280"}}>{type.desc}</div>
                        </div>
                        <div style={{display:"flex",gap:4,alignItems:"center"}}>
                          <span style={{fontSize:9,color:"#6B7280"}}>→</span>
                          <span style={{fontSize:10,fontWeight:800,padding:"2px 8px",borderRadius:8,
                            background:(TD_MAP_COLOR[type.map]||"#6B7280")+"15",
                            color:TD_MAP_COLOR[type.map]||"#6B7280"}}>
                            TD:{type.map}
                          </span>
                        </div>
                      </div>
                      <div style={{display:"flex",gap:6}}>
                        <input
                          placeholder={`e.g. ${type.example}`}
                          onKeyDown={e=>{if(e.key==="Enter"&&e.target.value.trim())addResult(type,e.target.value);}}
                          style={{flex:1,padding:"6px 10px",borderRadius:6,border:"1px solid #E5E7EB",
                            fontFamily:"monospace",fontSize:11,outline:"none"}}/>
                        <button
                          onClick={e=>{
                            const inp=e.target.previousSibling;
                            if(inp.value.trim()) addResult(type,inp.value);
                          }}
                          style={{padding:"6px 12px",borderRadius:6,border:"none",cursor:"pointer",
                            background:(SECTOR_COLORS[type.sector]||"#3DB54A")+"18",
                            color:SECTOR_COLORS[type.sector]||"#3DB54A",
                            fontFamily:"inherit",fontSize:10,fontWeight:700}}>
                          Map →
                        </button>
                      </div>
                      <div style={{fontSize:9,color:"#9CA3AF",
                        padding:"3px 8px",background:"#F8FAFC",borderRadius:6,fontFamily:"monospace"}}>
                        sector: {type.sector} · maps to TD:{type.map}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Live results panel */}
            <div style={{position:"sticky",top:20,height:"fit-content"}}>
              <div style={{background:"#0F172A",borderRadius:12,overflow:"hidden",
                border:"1px solid #1F2937"}}>
                <div style={{padding:"12px 16px",background:"#1F2937",display:"flex",
                  justifyContent:"space-between",alignItems:"center"}}>
                  <div style={{fontSize:12,fontWeight:700,color:"#fff"}}>
                    Mapped ThingDaddy IDs
                  </div>
                  {results.length>0&&(
                    <button onClick={exportCSV}
                      style={{fontSize:10,padding:"4px 10px",borderRadius:6,border:"none",
                        cursor:"pointer",background:"#3DB54A",color:"#fff",fontFamily:"inherit",fontWeight:700}}>
                      Export CSV
                    </button>
                  )}
                </div>
                <div style={{maxHeight:580,overflowY:"auto",padding:"10px 14px"}}>
                  {results.length===0&&(
                    <div style={{textAlign:"center",padding:24,color:"#374151",fontSize:12}}>
                      Enter an existing ID above and click Map → to generate a ThingDaddy URN
                    </div>
                  )}
                  {results.map((r,i)=>(
                    <div key={i} style={{marginBottom:8,padding:"8px 10px",borderRadius:8,
                      background:"#1E293B",border:"1px solid #334155"}}>
                      <div style={{display:"flex",gap:6,alignItems:"center",marginBottom:4}}>
                        <span style={{fontSize:8,fontWeight:700,padding:"1px 6px",borderRadius:4,
                          background:(SECTOR_COLORS[r.sector]||"#3DB54A")+"22",
                          color:SECTOR_COLORS[r.sector]||"#3DB54A"}}>
                          {r.sector}
                        </span>
                        <span style={{fontSize:9,fontWeight:700,color:"#E2E8F0"}}>{r.id}</span>
                        <span style={{marginLeft:"auto",fontSize:9,fontWeight:800,
                          padding:"1px 6px",borderRadius:4,
                          background:(TD_MAP_COLOR[r.mappedType]||"#6B7280")+"22",
                          color:TD_MAP_COLOR[r.mappedType]||"#6B7280"}}>
                          TD:{r.mappedType}
                        </span>
                      </div>
                      <div style={{fontSize:9,fontFamily:"monospace",color:"#94A3B8",marginBottom:3,
                        wordBreak:"break-all"}}>
                        {r.existingId}
                      </div>
                      <div style={{fontSize:8,fontFamily:"monospace",color:"#22C55E",
                        wordBreak:"break-all",lineHeight:1.5}}>
                        → {r.urn}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* ── BULK IMPORT ── */}
        {view==="bulk" && (
          <div style={{maxWidth:800}}>
            <div style={{fontSize:16,fontWeight:900,color:"#111827",marginBottom:6}}>
              Bulk ID Import + AI Classification
            </div>
            <div style={{fontSize:12,color:"#6B7280",marginBottom:16,lineHeight:1.7}}>
              Paste any list of IDs — SAP numbers, AWS ARNs, VINs, part numbers, serial numbers,
              DUNS, CAGE codes, GTINs — one per line. Claude AI identifies the type and
              maps each to a ThingDaddy URN automatically.
            </div>
            <textarea value={bulkText} onChange={e=>setBulkText(e.target.value)}
              placeholder={`Paste IDs here — one per line. Mixed types OK. Examples:\n5404041561097\narn:aws:iot:us-east-1:123456789012:thing/pump-001\n1HGBH41JXMN109186\n000000000012345678\nSN-DANA-ES9000R-2024001\nBATCH-2024-Q3-001\n0069-0105-68\nES9000R-SN2024001\n006466876`}
              style={{width:"100%",height:260,padding:"14px",borderRadius:10,
                border:"1.5px solid #E5E7EB",fontFamily:"monospace",fontSize:12,
                outline:"none",resize:"vertical",boxSizing:"border-box",lineHeight:1.8}}/>
            <div style={{display:"flex",gap:10,marginTop:10,alignItems:"center"}}>
              <button onClick={runAIBulk} disabled={aiLoading||!bulkText.trim()||!prefix}
                style={{padding:"12px 24px",borderRadius:8,border:"none",cursor:"pointer",
                  fontFamily:"inherit",fontSize:13,fontWeight:700,
                  background:aiLoading||!bulkText.trim()||!prefix?"#E5E7EB":"#3DB54A",
                  color:aiLoading||!bulkText.trim()||!prefix?"#9CA3AF":"#fff"}}>
                {aiLoading?"🤖 Classifying...":"🤖 AI Classify + Map All"}
              </button>
              {!prefix&&(
                <span style={{fontSize:11,color:"#DC2626"}}>
                  ⚠️ Enter your GS1 prefix above first
                </span>
              )}
              <span style={{fontSize:11,color:"#6B7280"}}>
                {bulkText.split("\n").filter(l=>l.trim()).length} IDs ready
              </span>
            </div>

            {results.length>0&&(
              <div style={{marginTop:20}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
                  <div style={{fontSize:14,fontWeight:700,color:"#111827"}}>
                    {results.length} IDs Mapped
                  </div>
                  <button onClick={exportCSV}
                    style={{padding:"8px 16px",borderRadius:8,border:"none",cursor:"pointer",
                      background:"#3DB54A",color:"#fff",fontFamily:"inherit",fontSize:12,fontWeight:700}}>
                    📤 Export CSV
                  </button>
                </div>
                <div style={{background:"#0F172A",borderRadius:10,overflow:"hidden"}}>
                  <table style={{width:"100%",borderCollapse:"collapse",fontSize:10}}>
                    <thead><tr style={{background:"#1F2937"}}>
                      {["Original ID","Type","Sector","ThingDaddy URN","TD Type","Status"].map(h=>(
                        <th key={h} style={{padding:"8px 12px",textAlign:"left",
                          color:"#6B7280",fontWeight:700,fontSize:9,whiteSpace:"nowrap"}}>{h}</th>
                      ))}
                    </tr></thead>
                    <tbody>
                      {results.map((r,i)=>(
                        <tr key={i} style={{borderTop:"1px solid #1E293B",
                          background:i%2===0?"#0F172A":"#111827"}}>
                          <td style={{padding:"6px 12px",fontFamily:"monospace",color:"#94A3B8",
                            maxWidth:160,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                            {r.existingId}
                          </td>
                          <td style={{padding:"6px 12px",color:"#E2E8F0",whiteSpace:"nowrap"}}>{r.id}</td>
                          <td style={{padding:"6px 12px"}}>
                            <span style={{fontSize:9,padding:"1px 6px",borderRadius:4,
                              background:(SECTOR_COLORS[r.sector]||"#6B7280")+"22",
                              color:SECTOR_COLORS[r.sector]||"#6B7280"}}>{r.sector}</span>
                          </td>
                          <td style={{padding:"6px 12px",fontFamily:"monospace",color:"#22C55E",
                            maxWidth:240,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",
                            fontSize:9}}>{r.urn}</td>
                          <td style={{padding:"6px 12px"}}>
                            <span style={{fontSize:9,fontWeight:800,padding:"1px 6px",borderRadius:4,
                              background:(TD_MAP_COLOR[r.mappedType]||"#6B7280")+"22",
                              color:TD_MAP_COLOR[r.mappedType]||"#6B7280"}}>TD:{r.mappedType}</span>
                          </td>
                          <td style={{padding:"6px 12px"}}>
                            <span style={{fontSize:9,color:r.status==="MAPPED"?"#22C55E":"#FCD34D"}}>
                              {r.status==="MAPPED"?"✓":"⚠"}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        )}

        {/* ── ID GRAPH ── */}
        {view==="graph" && (
          <div>
            <div style={{fontSize:16,fontWeight:900,color:"#111827",marginBottom:16}}>
              ThingDaddy Universal ID Mapping Graph
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))",gap:10}}>
              {SEED_SECTORS.map(sector=>{
                const types  = TD_SEED_ID_UNIVERSE.filter(t=>t.sector===sector);
                const color  = SECTOR_COLORS[sector]||"#6B7280";
                const mapped = results.filter(r=>r.sector===sector).length;
                return (
                  <div key={sector} style={{background:"#fff",borderRadius:10,
                    border:`1.5px solid ${color}33`,overflow:"hidden"}}>
                    <div style={{height:3,background:color}}/>
                    <div style={{padding:"12px 14px"}}>
                      <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
                        <div style={{fontSize:13,fontWeight:800,color}}>{sector}</div>
                        {mapped>0&&(
                          <span style={{fontSize:10,fontWeight:700,color,
                            background:color+"15",padding:"2px 8px",borderRadius:10}}>
                            {mapped} mapped
                          </span>
                        )}
                      </div>
                      {types.map(t=>(
                        <div key={t.id} style={{display:"flex",gap:6,marginBottom:4,
                          alignItems:"center",fontSize:10}}>
                          <span>{t.icon}</span>
                          <span style={{color:"#374151",flex:1}}>{t.id}</span>
                          <span style={{fontSize:9,fontWeight:700,padding:"1px 5px",borderRadius:4,
                            background:(TD_MAP_COLOR[t.map]||"#6B7280")+"15",
                            color:TD_MAP_COLOR[t.map]||"#6B7280"}}>→{t.map}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ── EXPORT ── */}
        {view==="export" && (
          <div style={{maxWidth:700}}>
            <div style={{fontSize:16,fontWeight:900,color:"#111827",marginBottom:6}}>Export + Integration</div>
            <div style={{fontSize:12,color:"#6B7280",marginBottom:20}}>
              Export your mapped IDs in multiple formats for integration with ERP, IoT platforms, and EPCIS systems.
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              {[
                {icon:"📄",label:"CSV Export",         desc:"Flat file — Excel, SAP import, any system",     action:exportCSV},
                {icon:"🔗",label:"EPCIS XML",          desc:"GS1 EPCIS 2.0 commissioning events per mapped ID"},
                {icon:"📡",label:"JSON-LD Graph",      desc:"Knowledge graph for AI/SPARQL query"},
                {icon:"⚡",label:"MQTT Publish",       desc:"Publish all GIAIs to MQTT broker"},
                {icon:"☁️",label:"AWS IoT Shadow",     desc:"Create device shadows for all mapped GIAIs"},
                {icon:"🗂️",label:"SAP IDOC",           desc:"SAP inbound IDOC for material/equipment master"},
              ].map(({icon,label,desc,action})=>(
                <div key={label} style={{background:"#fff",borderRadius:10,padding:16,
                  border:"1px solid #E5E7EB",cursor:action?"pointer":"default"}}
                  onClick={action}>
                  <div style={{fontSize:22,marginBottom:8}}>{icon}</div>
                  <div style={{fontSize:13,fontWeight:700,color:"#111827",marginBottom:4}}>{label}</div>
                  <div style={{fontSize:11,color:"#6B7280",marginBottom:10}}>{desc}</div>
                  {action?(
                    <div style={{fontSize:10,fontWeight:700,color:"#3DB54A"}}>
                      {results.length} records ready →
                    </div>
                  ):(
                    <div style={{fontSize:10,color:"#9CA3AF"}}>Coming soon — contact ThingDaddy</div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

