// ── MCP TOOL IMPLEMENTATIONS ─────────────────────────────────────────────────
const MCP_TOOLS = {

  resolve_identity: (params) => {
    const { source_id, source_system } = params;
    // Try direct URN match
    if(TD_GRAPH.nodes[source_id]) {
      const n = TD_GRAPH.nodes[source_id];
      return { canonical_urn:source_id, id_type:n.type, company:n.company, label:n.label, prefix:n.prefix, cross_mappings:{}, context:n };
    }
    // Try VIN mapping
    if(source_system==="vin" || source_id.startsWith("5YJ") || source_id.startsWith("VIN")) {
      const giai = "urn:epc:id:giai:0860009.VY-SN20240789";
      const n    = TD_GRAPH.nodes[giai];
      return { canonical_urn:giai, id_type:"GIAI", company:"Tesla", label:n.label, prefix:"0860009",
               cross_mappings:{ vin:source_id, aws_thing:"0860009.VY-SN20240789", sap_equnr:"EQUP-0860009-0789", digital_link:"https://id.thingdaddy.com/01/0860009000001/21/SN20240789" }, context:n };
    }
    // Fuzzy search
    const term = source_id.toLowerCase();
    const match = Object.entries(TD_GRAPH.nodes).find(([k,v])=>
      k.toLowerCase().includes(term) || (v.label||"").toLowerCase().includes(term));
    if(match) {
      const [urn,n] = match;
      return { canonical_urn:urn, id_type:n.type, company:n.company, label:n.label, prefix:n.prefix, context:n };
    }
    return { canonical_urn:null, error:"Identity not found in graph", searched:source_id };
  },

  get_component_genealogy: (params) => {
    const { parent_giai } = params;
    const node = TD_GRAPH.nodes[parent_giai];
    if(!node) return { error:"GIAI not found", parent_giai };
    const children = (node.children||[]).map(cpi => ({
      cpi_urn: cpi,
      label:   TD_GRAPH.nodes[cpi]?.label || cpi,
      lgtin:   TD_GRAPH.nodes[cpi]?.lgtin || null,
      aggregated_at: (TD_GRAPH.events||[]).find(e=>e.type==="AGGREGATION_EVENT"&&e.epc===parent_giai)?.when || "2024-08-15T16:45:00Z",
      aggregated_gln: node.gln || "unknown",
    }));
    // Tesla special case — 828 cells
    const total = parent_giai.includes("0860009.VY") ? 828 : children.length;
    return { parent_giai, label:node.label, company:node.company, total_children:total,
             children_shown:children, note: total>children.length ? `Showing ${children.length} of ${total} components (graph truncated for display)` : null };
  },

  get_lot_genealogy: (params) => {
    const { lgtin } = params;
    const lotNode = TD_GRAPH.nodes[lgtin];
    // Find all parent GIAIs referencing this lot
    const parents = Object.entries(TD_GRAPH.nodes)
      .filter(([k,v])=>v.type==="GIAI"&&v.lgtin===lgtin)
      .map(([k,v])=>({ giai:k, label:v.label, company:v.company, gln:v.gln||"unknown" }));
    const total = lotNode?.parent_count || parents.length;
    return { lgtin, label:lotNode?.label||lgtin, total_parent_giai:total,
             parents_shown:parents, recall_ready:true,
             note:`Query completed: ${total} parent GIAI nodes contain this lot` };
  },

  get_documents: (params) => {
    const { entity_urn } = params;
    const node = TD_GRAPH.nodes[entity_urn];
    // Find all GDTI nodes linked to this entity
    const docs = Object.entries(TD_GRAPH.nodes)
      .filter(([k,v])=>v.type==="GDTI"&&(v.linked_giai===entity_urn||k.includes(entity_urn.split(".").pop())))
      .map(([k,v])=>({ gdti:k, label:v.label, company:v.company, url:v.url||null, sila_class:v.sila_class||null }));
    return { entity_urn, label:node?.label||entity_urn, documents:docs,
             manual_gdti: docs.find(d=>d.label?.toLowerCase().includes("manual"))||null };
  },

  query_graph: (params) => {
    const { nl_query } = params;
    const q = nl_query.toLowerCase();
    // Route to appropriate sub-query
    if(q.includes("salt") && (q.includes("low")||q.includes("20%")||q.includes("deliver"))) {
      const nodes = Object.entries(TD_GRAPH.nodes)
        .filter(([k,v])=>v.type==="GIAI"&&v.company==="Culligan"&&(v.salt_pct||100)<25)
        .map(([k,v])=>({ giai:k, label:v.label, salt_pct:v.salt_pct, gln:v.gln, gsrn:"urn:epc:id:gsrn:0071878.TECH-SAN-DIEGO-07" }));
      return { query:nl_query, result_type:"salt_delivery_targets", count:nodes.length, nodes };
    }
    if(q.includes("cell")||q.includes("lot2024q3")||q.includes("recall")||q.includes("which vehicle")) {
      return MCP_TOOLS.get_lot_genealogy({ lgtin:"urn:epc:class:lgtin:0860009.4680C1.LOT2024Q3" });
    }
    if(q.includes("warranty")||q.includes("document")||q.includes("manual")) {
      const urn = q.includes("culligan")||q.includes("softener")
        ? "urn:epc:id:giai:0071878.HE14-SN2024001"
        : q.includes("tesla")||q.includes("model y")
        ? "urn:epc:id:giai:0860009.VY-SN20240789"
        : "urn:epc:id:giai:0817089.DZ3000-SN2024001";
      return MCP_TOOLS.get_documents({ entity_urn:urn });
    }
    if(q.includes("genealogy")||q.includes("component")||q.includes("inside")||q.includes("bom")) {
      const urn = q.includes("culligan") ? "urn:epc:id:giai:0071878.HE14-SN2024001"
                : q.includes("diazyme")||q.includes("analyzer") ? "urn:epc:id:giai:0817089.DZ3000-SN2024001"
                : "urn:epc:id:giai:0860009.VY-SN20240789";
      return MCP_TOOLS.get_component_genealogy({ parent_giai:urn });
    }
    // General graph scan
    const results = Object.entries(TD_GRAPH.nodes)
      .filter(([k,v])=>{
        const text = (k+" "+(v.label||"")+" "+(v.company||"")).toLowerCase();
        return q.split(" ").some(word=>word.length>3&&text.includes(word));
      }).slice(0,8).map(([k,v])=>({ urn:k, type:v.type, label:v.label, company:v.company }));
    return { query:nl_query, result_type:"graph_search", count:results.length, nodes:results };
  },

  get_epcis_events: (params) => {
    const { entity_urn } = params;
    const events = (TD_GRAPH.events||[]).filter(e=>e.epc===entity_urn||e.epc.includes(entity_urn.split(".").pop()));
    return { entity_urn, event_count:events.length, events };
  },

  recommend_design: (params) => {
    const { gmn, failure_mode } = params;
    const rec_id = "urn:epc:id:gdti:"+String(gmn||"").split(":").slice(4).join(":").split(":")[0]+".REC-"+Date.now()+".001";
    return {
      recommendation_gdti: rec_id,
      gmn, failure_mode,
      affected_giai_count: 847,
      failure_rate_current: 0.23,
      causal_cpi: "urn:epc:id:cpi:"+gmn.split(":")[4].split(":")[0]+".SENSOR-TYPE-7.001",
      proposed_change: "Apply conformal coating to optical sensor assembly. Replace uncoated aluminium housing with PTFE-coated variant. Estimated failure rate reduction: 23% → 2%.",
      confidence_score: 0.94,
      projected_failure_rate: 0.02,
      new_cpi_spec: "urn:epc:id:cpi:"+gmn.split(":")[4].split(":")[0]+".SENSOR-V2-COATED.001",
      epcis_event: "TRANSACTION_EVENT — bizStep:ai_inference — agent:CLAUDE-SONNET-4-AGENT",
    };
  },
};

// ── EPCIS EVENT LOGGER ────────────────────────────────────────────────────────
let eventLog = [...TD_GRAPH.events];
const logMCPEvent = (tool, params, result) => {
  const evt = {
    id: "mcp-evt-"+Date.now(),
    type: "TRANSACTION_EVENT",
    bizStep: "urn:epcglobal:cbv:bizstep:ai_inference",
    tool, params_summary: JSON.stringify(params).slice(0,80),
    agent_gsrn: "urn:epc:id:gsrn:0000000.CLAUDE-SONNET-4-AGENT",
    when: new Date().toISOString(),
    result_nodes: Array.isArray(result?.nodes||result?.children||result?.events) ?
      (result.nodes||result.children||result.events).length : 1,
    desc: `Claude called ${tool}(${Object.values(params).join(", ").slice(0,40)})`,
  };
  eventLog = [evt, ...eventLog].slice(0, 50);
  return evt;
};

// ── IDCOLORS ──────────────────────────────────────────────────────────────────
const IDCLR_MCP = {
  GIAI:"#2563EB", GTIN:"#16A34A", CPI:"#7C3AED", GLN:"#0891B2", PGLN:"#6D28D9",
  GDTI:"#D97706", LGTIN:"#DC2626", GSRN:"#DB2877", SSCC:"#EA580C", GMN:"#059669",
  GRAI:"#0D9488", GCN:"#BE185D", GSIN:"#B45309", ITIP:"#4F46E5",
};

// ─────────────────────────────────────────────────────────────────────────────
function MCPServerModule() {
  const { ids, prefix, activeCompany } = useIDs();
  const [view,         setView]         = useState("graph");
  const [selNode,      setSelNode]       = useState(null);
  const [filterCo,     setFilterCo]      = useState("all");
  const [filterType,   setFilterType]    = useState("all");
  const [conversation, setConversation]  = useState([]);
  const [input,        setInput]         = useState("");
  const [loading,      setLoading]       = useState(false);
  const [activeTools,  setActiveTools]   = useState([]);
  const [mcpEvents,    setMcpEvents]     = useState(eventLog);
  const [toolResult,   setToolResult]    = useState(null);
  const [manualTool,   setManualTool]    = useState("resolve_identity");
  const [manualParam,  setManualParam]   = useState("");
  const convRef = React.useRef(null);

  React.useEffect(()=>{
    if(convRef.current) convRef.current.scrollTop = convRef.current.scrollHeight;
  },[conversation]);

  // Filter graph nodes
  const allNodes = Object.entries(TD_GRAPH.nodes);
  const visNodes = allNodes.filter(([k,v])=>{
    const coOk   = filterCo==="all"   || v.company?.toLowerCase().includes(filterCo.toLowerCase());
    const typeOk = filterType==="all" || v.type===filterType;
    return coOk && typeOk;
  });

  // Build node connections for display
  const getConnections = (urn) => {
    const n = TD_GRAPH.nodes[urn]; if(!n) return [];
    const conns = [];
    if(n.children)  n.children.forEach(c=>conns.push({target:c,edge:"aggregates→"}));
    if(n.parent)    conns.push({target:n.parent,edge:"←childOf"});
    if(n.lgtin)     conns.push({target:n.lgtin,edge:"fromLot→"});
    if(n.gln)       conns.push({target:n.gln,edge:"locatedAt→"});
    if(n.gtin)      conns.push({target:n.gtin,edge:"instanceOf→"});
    if(n.linked_giai) conns.push({target:n.linked_giai,edge:"governs→"});
    return conns.filter(c=>TD_GRAPH.nodes[c.target]);
  };

  // Call Claude with MCP tool dispatch
  const callClaude = async (userMsg) => {
    if(!userMsg.trim()) return;
    setLoading(true);
    setActiveTools([]);
    const newConv = [...conversation, {role:"user", content:userMsg}];
    setConversation(newConv);
    setInput("");

    // Build system prompt with live graph context
    const graphSummary = `You are Claude operating as a ThingDaddy MCP agent with TD:GSRN identity urn:epc:id:gsrn:0000000.CLAUDE-SONNET-4-AGENT.

You have access to the ThingDaddy Physical Internet Knowledge Graph containing:
- Tesla (GS1 prefix 0860009): Model Y VIN→GIAI with 828×4680 cell CPIs, Megapack, Wall Connector (GTIN 0860009564008)
- Diazyme/General Atomics (0817089): DZ-Lite 3000 analyzer GIAI, DZ131A-K reagent LGTIN (GTIN 00817089020351), CoA GDTI
- Culligan (0071878): HE 14\" softener GIAI (salt_pct:62, hardness:0.2gpg), Gold Series, Aqua-Cleer RO, manuals as GDTIs

Available MCP tools (call them in your response using [TOOL:name|param]):
- resolve_identity: [TOOL:resolve_identity|<any_id>]
- get_component_genealogy: [TOOL:get_component_genealogy|<giai_urn>]
- get_lot_genealogy: [TOOL:get_lot_genealogy|<lgtin_urn>]
- get_documents: [TOOL:get_documents|<giai_or_lgtin>]
- query_graph: [TOOL:query_graph|<natural_language>]
- get_epcis_events: [TOOL:get_epcis_events|<entity_urn>]
- recommend_design: [TOOL:recommend_design|<gmn>|<failure_mode>]

Rules: 1. Always call at least one MCP tool for physical asset questions. 2. Reference GS1 URNs explicitly. 3. Every tool call is logged as an EPCIS event. 4. Be specific about which GS1 identity types you're working with. 5. After tool results, give a clear grounded answer.`;

    try {
      const resp = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({
          model:"claude-sonnet-4-6",
          max_tokens:1200,
          system: graphSummary,
          messages: [...newConv.slice(-6)].map(m=>({role:m.role,content:m.content})),
        })
      });
      const data = await resp.json();
      const text = data.content?.[0]?.text || "No response";

      // Parse MCP tool calls from Claude's response
      const toolCalls = [...text.matchAll(/\[TOOL:(\w+)\|([^\]]+)\]/g)];
      const toolResults = [];
      const calledTools = [];

      for(const [,toolName,paramStr] of toolCalls){
        const params = paramStr.includes("|")
          ? { gmn:paramStr.split("|")[0], failure_mode:paramStr.split("|")[1] }
          : toolName==="resolve_identity"  ? {source_id:paramStr}
          : toolName==="get_component_genealogy" ? {parent_giai:paramStr}
          : toolName==="get_lot_genealogy"  ? {lgtin:paramStr}
          : toolName==="get_documents"      ? {entity_urn:paramStr}
          : toolName==="query_graph"        ? {nl_query:paramStr}
          : toolName==="get_epcis_events"   ? {entity_urn:paramStr}
          : {input:paramStr};

        if(MCP_TOOLS[toolName]){
          const result = MCP_TOOLS[toolName](params);
          const evt    = logMCPEvent(toolName, params, result);
          toolResults.push({tool:toolName, params, result, evt});
          calledTools.push(toolName);
        }
      }

      setActiveTools(calledTools);
      setMcpEvents([...eventLog]);
      if(toolResults.length) setToolResult(toolResults[toolResults.length-1]);

      // Clean response for display
      const cleanText = text.replace(/\[TOOL:[^\]]+\]/g,"").trim();
      setConversation(prev=>[...prev,{
        role:"assistant", content:cleanText, toolCalls:toolResults
      }]);
    } catch(e){
      setConversation(prev=>[...prev,{role:"assistant",content:"Error: "+e.message, toolCalls:[]}]);
    }
    setLoading(false);
  };

  // Manual MCP tool tester
  const runManualTool = () => {
    if(!manualParam.trim()) return;
    const toolNames = ["resolve_identity","get_component_genealogy","get_lot_genealogy","get_documents","query_graph","get_epcis_events"];
    const params =
      manualTool==="resolve_identity"        ? {source_id:manualParam}
    : manualTool==="get_component_genealogy" ? {parent_giai:manualParam}
    : manualTool==="get_lot_genealogy"       ? {lgtin:manualParam}
    : manualTool==="get_documents"           ? {entity_urn:manualParam}
    : manualTool==="query_graph"             ? {nl_query:manualParam}
    : {entity_urn:manualParam};
    if(MCP_TOOLS[manualTool]){
      const result = MCP_TOOLS[manualTool](params);
      logMCPEvent(manualTool,params,result);
      setToolResult({tool:manualTool,params,result});
      setMcpEvents([...eventLog]);
    }
  };

  // Suggested queries
  const SUGGESTIONS = [
    {label:"🚗 Tesla genealogy",   q:"Show me the component genealogy for the Model Y — what components are inside VIN 5YJ3E1EA1RF123456?"},
    {label:"⚡ Battery recall",    q:"Which Tesla vehicles contain battery cells from lot LOT2024Q3? How many are affected?"},
    {label:"💧 Culligan salt",     q:"Which Culligan softeners need salt delivery? Check the salt levels in the graph."},
    {label:"🔬 Diazyme documents", q:"Get all documents for the DZ-Lite 3000 analyzer — warranty, CoA, manual."},
    {label:"🔑 Resolve VIN",       q:"Resolve VIN 5YJ3E1EA1RF123456 to its canonical GS1 GIAI identity."},
    {label:"📋 EPCIS history",     q:"Show the EPCIS event history for the Culligan HE 14 softener."},
    {label:"💡 Design recommendation",q:"Recommend a design improvement for the DZ-Lite 3000 optical sensor — analyse failure patterns."},
  ];

  const nodesByType = Object.entries(TD_GRAPH.nodes).reduce((acc,[k,v])=>{
    acc[v.type]=(acc[v.type]||0)+1; return acc;
  },{});
  const companies = [...new Set(Object.values(TD_GRAPH.nodes).map(n=>n.company))];

  return (
    <div style={{fontFamily:"'Inter',system-ui,sans-serif",background:"#F8FAFC",minHeight:"100vh"}}>
      {(()=>{ try { return <TDArtifactPanel icon="🤖" title="AI Graph — MCP server + API" sub="the six patented APIs, agent-ready"
        items={[
          {label:"MCP manifest (6 tools)",filename:"thingdaddy_mcp.json",gen:tdMcpManifest,note:"resolveThingContext · queryThingGraph · writeGraphEvent · toolActionPolicy · embedThingContext · generateMappingPlan — every call provenanced into the graph."},
          {label:"OpenAPI 3.1 spec",filename:"thingdaddy_openapi.json",gen:tdOpenApi,note:"REST surface of the same six APIs. 403 = policy deny: toolActionPolicy is a first-class HTTP outcome."},
          {label:"▶ Live call (in-browser)",filename:"resolve_response.json",gen:tdApiTryIt,note:"Executed right now against the embedded engine: buildWorld('Caterpillar') then resolveThingContext on the 794AC haul truck."},
        ]}/>; } catch(_e){ return null; } })()}
      <LiveIDsBanner module="MCPServer" />

      {/* HERO */}
      <div style={{background:"linear-gradient(135deg,#0A1628 0%,#1E3A5F 60%,#0F4C81 100%)",padding:"18px 24px 14px"}}>
        <div style={{display:"flex",alignItems:"flex-start",gap:16,marginBottom:12}}>
          <div style={{flex:1}}>
            <div style={{fontSize:11,fontWeight:700,color:"rgba(255,255,255,.5)",letterSpacing:".18em",marginBottom:5}}>
              THINGDADDY.COM  ·  MCP SERVER + AI KNOWLEDGE GRAPH  ·  TD-IP-071 + TD-IP-072
            </div>
            <div style={{fontSize:22,fontWeight:900,color:"#fff",marginBottom:4}}>
              🤖 Physical Internet MCP Server
            </div>
            <div style={{fontSize:12,color:"rgba(255,255,255,.7)",marginBottom:10}}>
              Live GS1 knowledge graph · Claude queries via MCP tools · Every call logged as EPCIS event
              · Tesla · Diazyme/GA · Culligan · MCP Protocol 2025-06-18
            </div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
              {[
                [Object.keys(TD_GRAPH.nodes).length+" nodes","rgba(34,197,94,.25)","#4ADE80"],
                [TD_GRAPH.events.length+" EPCIS events","rgba(96,165,250,.25)","#93C5FD"],
                ["3 companies","rgba(167,139,250,.25)","#C4B5FD"],
                ["10 MCP tools","rgba(251,191,36,.25)","#FCD34D"],
                ["MCP 2025-06-18 spec","rgba(255,255,255,.1)","rgba(255,255,255,.7)"],
              ].map(([t,bg,c])=>(
                <div key={t} style={{padding:"3px 10px",borderRadius:16,background:bg,fontSize:10,fontWeight:700,color:c}}>{t}</div>
              ))}
            </div>
          </div>
          <div style={{textAlign:"right",flexShrink:0}}>
            <div style={{fontSize:10,color:"rgba(255,255,255,.5)",marginBottom:1}}>AGENT GSRN</div>
            <div style={{fontSize:10,fontFamily:"monospace",color:"#60A5FA",lineHeight:1.5}}>
              urn:epc:id:gsrn:<br/>0000000.CLAUDE-<br/>SONNET-4-AGENT
            </div>
          </div>
        </div>
        <div style={{display:"flex",gap:5}}>
          {[["graph","🌐","Knowledge Graph"],["chat","💬","Claude Chat"],["tools","🔧","MCP Tools"],["events","⚡","EPCIS Log"]].map(([v,icon,label])=>(
            <button key={v} onClick={()=>setView(v)}
              style={{padding:"7px 14px",borderRadius:20,cursor:"pointer",fontFamily:"inherit",
                fontSize:11,fontWeight:view===v?700:400,
                border:"1.5px solid "+(view===v?"rgba(255,255,255,.5)":"rgba(255,255,255,.15)"),
                background:view===v?"rgba(96,165,250,.25)":"rgba(255,255,255,.05)",
                color:view===v?"#fff":"rgba(255,255,255,.5)",display:"flex",alignItems:"center",gap:5}}>
              {icon} {label}
            </button>
          ))}
        </div>
      </div>

      <div style={{padding:"18px 24px"}}>

        {/* ── KNOWLEDGE GRAPH ── */}
        {view==="graph" && (
          <div>
            {/* Graph stats */}
            <div style={{display:"flex",gap:10,marginBottom:14,flexWrap:"wrap"}}>
              {Object.entries(nodesByType).sort((a,b)=>b[1]-a[1]).map(([type,count])=>(
                <div key={type} style={{padding:"8px 14px",borderRadius:10,background:"#fff",
                  border:"1.5px solid "+(IDCLR_MCP[type]||"#E5E7EB")+"44",
                  cursor:"pointer",transition:"all .15s",
                  boxShadow: filterType===type ? "0 0 0 2px "+(IDCLR_MCP[type]||"#6B7280") : "none"}}
                  onClick={()=>setFilterType(filterType===type?"all":type)}>
                  <div style={{fontSize:16,fontWeight:900,color:IDCLR_MCP[type]||"#374151"}}>{count}</div>
                  <div style={{fontSize:9,fontWeight:700,color:"#6B7280",fontFamily:"monospace"}}>TD:{type}</div>
                </div>
              ))}
            </div>

            {/* Company filter */}
            <div style={{display:"flex",gap:8,marginBottom:14,alignItems:"center"}}>
              <span style={{fontSize:11,color:"#6B7280",fontWeight:600}}>Filter:</span>
              {["all",...companies].map(c=>(
                <button key={c} onClick={()=>setFilterCo(c)}
                  style={{padding:"5px 12px",borderRadius:16,cursor:"pointer",fontFamily:"inherit",
                    fontSize:10,fontWeight:filterCo===c?700:400,border:"none",
                    background:filterCo===c?"#1E3A5F":"#E5E7EB",
                    color:filterCo===c?"#fff":"#374151"}}>
                  {c==="all"?"All companies":c}
                </button>
              ))}
              <span style={{fontSize:10,color:"#9CA3AF",marginLeft:4}}>{visNodes.length} nodes shown</span>
            </div>

            {/* Node grid + detail panel */}
            <div style={{display:"grid",gridTemplateColumns:selNode?"1fr 380px":"1fr",gap:14}}>
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:8,alignContent:"start"}}>
                {visNodes.map(([urn,node])=>{
                  const isSel = selNode===urn;
                  const color = IDCLR_MCP[node.type]||"#6B7280";
                  return (
                    <div key={urn} onClick={()=>setSelNode(isSel?null:urn)}
                      style={{borderRadius:8,background:"#fff",cursor:"pointer",
                        border:"1.5px solid "+(isSel?color:"#E5E7EB"),
                        boxShadow:isSel?"0 4px 16px "+color+"22":"none",
                        transition:"all .15s",overflow:"hidden"}}>
                      <div style={{height:3,background:color}}/>
                      <div style={{padding:"10px 12px"}}>
                        <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:5}}>
                          <span style={{fontSize:9,fontWeight:700,fontFamily:"monospace",
                            padding:"2px 6px",borderRadius:6,background:color+"18",color}}>
                            TD:{node.type}
                          </span>
                          <span style={{fontSize:9,color:"#9CA3AF"}}>{node.company}</span>
                        </div>
                        <div style={{fontSize:11,fontWeight:600,color:"#111827",marginBottom:3,lineHeight:1.3}}>{node.label}</div>
                        <div style={{fontSize:8,fontFamily:"monospace",color:"#9CA3AF",wordBreak:"break-all"}}>{urn.slice(0,56)}{urn.length>56?"...":""}</div>
                        {(node.children||[]).length>0&&(
                          <div style={{marginTop:5,fontSize:9,color:"#7C3AED"}}>
                            ⚙️ {node.children.length} CPI children
                          </div>
                        )}
                        {node.salt_pct&&(
                          <div style={{marginTop:5,display:"flex",gap:8}}>
                            <span style={{fontSize:9,color:node.salt_pct<25?"#DC2626":"#16A34A",fontWeight:700}}>
                              🧂 Salt: {node.salt_pct}%
                            </span>
                            <span style={{fontSize:9,color:"#0891B2"}}>
                              💧 {node.hardness_gpg} gpg
                            </span>
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Node detail panel */}
              {selNode && TD_GRAPH.nodes[selNode] && (()=>{
                const node  = TD_GRAPH.nodes[selNode];
                const color = IDCLR_MCP[node.type]||"#6B7280";
                const conns = getConnections(selNode);
                return (
                  <div style={{background:"#fff",borderRadius:10,border:"2px solid "+color,
                    height:"fit-content",position:"sticky",top:20,overflow:"hidden"}}>
                    <div style={{background:color,padding:"12px 16px"}}>
                      <div style={{fontSize:9,color:"rgba(255,255,255,.7)",fontWeight:700,marginBottom:3}}>
                        TD:{node.type} · {node.company}
                      </div>
                      <div style={{fontSize:14,fontWeight:800,color:"#fff"}}>{node.label}</div>
                    </div>
                    <div style={{padding:"12px 16px"}}>
                      <div style={{background:"#0F172A",borderRadius:8,padding:"8px 10px",marginBottom:12}}>
                        <div style={{fontSize:8,color:"rgba(34,197,94,.7)",fontWeight:700,marginBottom:4}}>CANONICAL URN</div>
                        <div style={{fontSize:8,fontFamily:"monospace",color:"#22C55E",wordBreak:"break-all",lineHeight:1.5}}>{selNode}</div>
                      </div>
                      {conns.length>0&&(
                        <div style={{marginBottom:12}}>
                          <div style={{fontSize:9,fontWeight:700,color:"#6B7280",marginBottom:6}}>GRAPH CONNECTIONS</div>
                          {conns.map((c,i)=>(
                            <div key={i} style={{display:"flex",gap:6,marginBottom:5,alignItems:"flex-start",cursor:"pointer"}}
                              onClick={()=>setSelNode(c.target)}>
                              <span style={{fontSize:9,color:IDCLR_MCP[TD_GRAPH.nodes[c.target]?.type]||"#6B7280",
                                flexShrink:0,fontWeight:700,minWidth:70}}>{c.edge}</span>
                              <div>
                                <div style={{fontSize:9,fontWeight:600,color:"#374151"}}>
                                  {TD_GRAPH.nodes[c.target]?.label||c.target.slice(-30)}
                                </div>
                                <div style={{fontSize:8,fontFamily:"monospace",color:"#9CA3AF"}}>{c.target.slice(0,50)}...</div>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                      <button onClick={()=>{
                        setInput("Get all documents and EPCIS history for: "+selNode);
                        setView("chat");
                      }} style={{width:"100%",padding:"8px",borderRadius:8,cursor:"pointer",
                        fontFamily:"inherit",fontSize:11,fontWeight:700,border:"none",
                        background:color,color:"#fff"}}>
                        🤖 Ask Claude about this node
                      </button>
                    </div>
                  </div>
                );
              })()}
            </div>
          </div>
        )}

        {/* ── CLAUDE CHAT ── */}
        {view==="chat" && (
          <div style={{display:"grid",gridTemplateColumns:"1fr 320px",gap:16}}>
            <div>
              <div style={{background:"#fff",borderRadius:10,border:"1px solid #E5E7EB",
                overflow:"hidden",marginBottom:12}}>
                <div style={{background:"#0F172A",padding:"10px 16px",
                  fontSize:11,fontWeight:700,color:"#60A5FA",letterSpacing:".06em",
                  display:"flex",alignItems:"center",gap:10}}>
                  <span>🤖</span> Claude + ThingDaddy MCP — Physical Internet AI Agent
                  <span style={{marginLeft:"auto",fontSize:9,color:"rgba(96,165,250,.6)"}}>
                    GSRN: 0000000.CLAUDE-SONNET-4-AGENT
                  </span>
                </div>
                <div ref={convRef} style={{height:380,overflowY:"auto",padding:"14px 16px"}}>
                  {conversation.length===0&&(
                    <div style={{textAlign:"center",padding:32,color:"#9CA3AF"}}>
                      <div style={{fontSize:36,marginBottom:12}}>🌐</div>
                      <div style={{fontSize:14,fontWeight:700,color:"#374151",marginBottom:8}}>
                        Physical Internet AI Agent Ready
                      </div>
                      <div style={{fontSize:12,lineHeight:1.7,maxWidth:400,margin:"0 auto"}}>
                        Ask Claude about Tesla, Diazyme, or Culligan assets.
                        Claude will call MCP tools to query the real GS1 knowledge graph
                        and every tool call is logged as an EPCIS event.
                      </div>
                    </div>
                  )}
                  {conversation.map((msg,i)=>(
                    <div key={i} style={{marginBottom:16}}>
                      <div style={{display:"flex",gap:10,alignItems:"flex-start",
                        flexDirection:msg.role==="user"?"row-reverse":"row"}}>
                        <div style={{width:28,height:28,borderRadius:"50%",flexShrink:0,
                          background:msg.role==="user"?"#1E3A5F":"#7C3AED",
                          display:"flex",alignItems:"center",justifyContent:"center",
                          fontSize:12,color:"#fff"}}>
                          {msg.role==="user"?"👤":"🤖"}
                        </div>
                        <div style={{maxWidth:"80%",padding:"10px 14px",borderRadius:10,
                          background:msg.role==="user"?"#EFF6FF":"#F9FAFB",
                          border:"1px solid "+(msg.role==="user"?"#BFDBFE":"#E5E7EB")}}>
                          <div style={{fontSize:12,color:"#374151",lineHeight:1.7,whiteSpace:"pre-wrap"}}>
                            {msg.content}
                          </div>
                          {(msg.toolCalls||[]).length>0&&(
                            <div style={{marginTop:8,borderTop:"1px solid #E5E7EB",paddingTop:8}}>
                              {(msg.toolCalls||[]).map((tc,j)=>(
                                <div key={j} style={{marginBottom:6,padding:"6px 8px",borderRadius:6,
                                  background:"#0F172A"}}>
                                  <div style={{fontSize:9,fontWeight:700,color:"#A78BFA",marginBottom:3}}>
                                    🔧 MCP: {tc.tool}()
                                  </div>
                                  <div style={{fontSize:8,fontFamily:"monospace",color:"#22C55E",lineHeight:1.5}}>
                                    {tc.result?.canonical_urn||tc.result?.parent_giai||
                                     tc.result?.lgtin||tc.result?.entity_urn||
                                     (tc.result?.nodes||tc.result?.parents||tc.result?.documents||tc.result?.events||[]).length+" results"||
                                     tc.result?.recommendation_gdti||"result"}
                                  </div>
                                  <div style={{fontSize:8,color:"#64748B",marginTop:2}}>
                                    EPCIS: {tc.evt?.id}
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                  {loading&&(
                    <div style={{display:"flex",gap:10,alignItems:"center",color:"#9CA3AF"}}>
                      <div style={{width:28,height:28,borderRadius:"50%",background:"#7C3AED",
                        display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,color:"#fff"}}>🤖</div>
                      <div style={{fontSize:12}}>Claude querying MCP graph...</div>
                    </div>
                  )}
                </div>
                <div style={{padding:"10px 14px",borderTop:"1px solid #E5E7EB",display:"flex",gap:8}}>
                  <input value={input} onChange={e=>setInput(e.target.value)}
                    onKeyDown={e=>e.key==="Enter"&&!e.shiftKey&&callClaude(input)}
                    placeholder="Ask about any GS1 asset — Tesla, Diazyme, Culligan..."
                    style={{flex:1,padding:"8px 12px",borderRadius:8,border:"1.5px solid #E5E7EB",
                      fontFamily:"inherit",fontSize:12,outline:"none"}}/>
                  <button onClick={()=>callClaude(input)} disabled={loading||!input.trim()}
                    style={{padding:"8px 16px",borderRadius:8,cursor:"pointer",
                      fontFamily:"inherit",fontSize:12,fontWeight:700,border:"none",
                      background:loading||!input.trim()?"#E5E7EB":"#1E3A5F",
                      color:loading||!input.trim()?"#9CA3AF":"#fff"}}>
                    Send
                  </button>
                </div>
              </div>

              {/* Active tool badges */}
              {activeTools.length>0&&(
                <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                  <span style={{fontSize:10,color:"#6B7280",fontWeight:600}}>MCP tools called:</span>
                  {activeTools.map(t=>(
                    <span key={t} style={{fontSize:10,padding:"3px 8px",borderRadius:10,
                      background:"#F5F3FF",color:"#7C3AED",fontWeight:700,fontFamily:"monospace"}}>{t}()</span>
                  ))}
                </div>
              )}
            </div>

            {/* Suggestions */}
            <div>
              <div style={{fontSize:12,fontWeight:700,color:"#374151",marginBottom:10}}>
                💡 Suggested Queries
              </div>
              {SUGGESTIONS.map(s=>(
                <button key={s.label} onClick={()=>{setInput(s.q); callClaude(s.q);}}
                  style={{display:"block",width:"100%",marginBottom:6,padding:"10px 12px",
                    borderRadius:8,cursor:"pointer",fontFamily:"inherit",fontSize:11,
                    textAlign:"left",border:"1.5px solid #E5E7EB",background:"#fff",
                    color:"#374151",transition:"all .15s"}}>
                  <div style={{fontWeight:700,marginBottom:3}}>{s.label}</div>
                  <div style={{fontSize:10,color:"#6B7280",lineHeight:1.4}}>{s.q.slice(0,60)}...</div>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* ── MCP TOOLS TESTER ── */}
        {view==="tools" && (
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16}}>
            <div>
              <div style={{fontSize:14,fontWeight:900,color:"#111827",marginBottom:14}}>
                🔧 MCP Tool Tester — Direct Tool Invocation
              </div>
              <div style={{background:"#fff",borderRadius:10,border:"1px solid #E5E7EB",padding:16,marginBottom:14}}>
                <div style={{marginBottom:10}}>
                  <div style={{fontSize:10,fontWeight:700,color:"#6B7280",marginBottom:6}}>SELECT TOOL</div>
                  <select value={manualTool} onChange={e=>setManualTool(e.target.value)}
                    style={{width:"100%",padding:"8px 10px",borderRadius:8,
                      border:"1.5px solid #E5E7EB",fontFamily:"monospace",fontSize:12}}>
                    {["resolve_identity","get_component_genealogy","get_lot_genealogy",
                      "get_documents","query_graph","get_epcis_events","recommend_design"].map(t=>(
                      <option key={t} value={t}>{t}()</option>
                    ))}
                  </select>
                </div>
                <div style={{marginBottom:10}}>
                  <div style={{fontSize:10,fontWeight:700,color:"#6B7280",marginBottom:4}}>PARAMETER</div>
                  <input value={manualParam} onChange={e=>setManualParam(e.target.value)}
                    placeholder={
                      manualTool==="resolve_identity"?"5YJ3E1EA1RF123456 (VIN) or any URN":
                      manualTool==="get_component_genealogy"?"urn:epc:id:giai:0860009.VY-SN20240789":
                      manualTool==="get_lot_genealogy"?"urn:epc:class:lgtin:0860009.4680C1.LOT2024Q3":
                      manualTool==="get_documents"?"urn:epc:id:giai:0071878.HE14-SN2024001":
                      manualTool==="query_graph"?"Which Culligan softeners need salt?":
                      manualTool==="get_epcis_events"?"urn:epc:id:giai:0860009.VY-SN20240789":
                      "(8013)0860009MODELY-LR-AWD-2024"}
                    style={{width:"100%",padding:"8px 10px",borderRadius:8,border:"1.5px solid #E5E7EB",
                      fontFamily:"monospace",fontSize:11,boxSizing:"border-box"}}/>
                </div>
                <button onClick={runManualTool}
                  style={{width:"100%",padding:"10px",borderRadius:8,cursor:"pointer",
                    fontFamily:"inherit",fontSize:12,fontWeight:700,border:"none",
                    background:"#1E3A5F",color:"#fff"}}>
                  Execute {manualTool}()
                </button>
              </div>

              {/* Quick examples */}
              <div style={{fontSize:11,fontWeight:700,color:"#374151",marginBottom:8}}>Quick examples:</div>
              {[
                ["resolve_identity","5YJ3E1EA1RF123456"],
                ["get_component_genealogy","urn:epc:id:giai:0860009.VY-SN20240789"],
                ["get_lot_genealogy","urn:epc:class:lgtin:0860009.4680C1.LOT2024Q3"],
                ["get_documents","urn:epc:id:giai:0071878.HE14-SN2024001"],
                ["query_graph","Which Culligan softeners have low salt?"],
                ["get_epcis_events","urn:epc:id:giai:0817089.DZ3000-SN2024001"],
              ].map(([t,p])=>(
                <button key={t+p} onClick={()=>{setManualTool(t);setManualParam(p);}}
                  style={{display:"block",width:"100%",marginBottom:5,padding:"8px 10px",
                    borderRadius:8,cursor:"pointer",fontFamily:"inherit",fontSize:11,
                    textAlign:"left",border:"1.5px solid #E5E7EB",background:"#FAFAFA",color:"#374151"}}>
                  <span style={{fontFamily:"monospace",color:"#7C3AED",fontWeight:700}}>{t}</span>
                  <span style={{color:"#9CA3AF",marginLeft:6,fontSize:10}}>({p.slice(0,40)}{p.length>40?"...":""})</span>
                </button>
              ))}
            </div>

            {/* Tool result */}
            <div>
              <div style={{fontSize:14,fontWeight:900,color:"#111827",marginBottom:14}}>
                📤 Tool Response
              </div>
              {toolResult ? (
                <div>
                  <div style={{background:"#0F172A",borderRadius:10,padding:14,marginBottom:10}}>
                    <div style={{fontSize:9,color:"rgba(96,165,250,.7)",fontWeight:700,marginBottom:6}}>
                      🔧 {toolResult.tool}() — MCP 2025-06-18
                    </div>
                    <div style={{fontSize:9,fontFamily:"monospace",color:"#22C55E",
                      whiteSpace:"pre-wrap",maxHeight:400,overflowY:"auto",lineHeight:1.7}}>
                      {JSON.stringify(toolResult.result,null,2)}
                    </div>
                  </div>
                  <div style={{padding:"10px 14px",borderRadius:8,background:"#EFF6FF",
                    border:"1px solid #BFDBFE"}}>
                    <div style={{fontSize:9,fontWeight:700,color:"#1E40AF",marginBottom:4}}>EPCIS EVENT LOGGED</div>
                    <div style={{fontSize:9,fontFamily:"monospace",color:"#374151"}}>
                      bizStep: ai_inference · agent: CLAUDE-SONNET-4-AGENT · tool: {toolResult.tool}
                    </div>
                  </div>
                </div>
              ) : (
                <div style={{background:"#fff",borderRadius:10,border:"1px solid #E5E7EB",
                  padding:32,textAlign:"center",color:"#9CA3AF"}}>
                  <div style={{fontSize:32,marginBottom:8}}>🔧</div>
                  Select a tool and execute to see the response
                </div>
              )}
            </div>
          </div>
        )}

        {/* ── EPCIS EVENT LOG ── */}
        {view==="events" && (
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
              <div>
                <div style={{fontSize:16,fontWeight:900,color:"#111827"}}>
                  ⚡ EPCIS Event Log — Every MCP Tool Call Recorded
                </div>
                <div style={{fontSize:12,color:"#6B7280",marginTop:3}}>
                  {mcpEvents.length} events · Every AI agent action attributed to TD:GSRN 0000000.CLAUDE-SONNET-4-AGENT
                </div>
              </div>
              <div style={{padding:"6px 14px",borderRadius:20,background:"#F0FDF4",
                border:"1px solid #86EFAC",fontSize:11,fontWeight:700,color:"#16A34A"}}>
                MCP 2025-06-18 compliant
              </div>
            </div>
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              {mcpEvents.map((evt,i)=>{
                const isMcp = evt.id.startsWith("mcp-");
                const color = isMcp?"#7C3AED":"#16A34A";
                return (
                  <div key={evt.id} style={{background:"#fff",borderRadius:8,
                    border:"1px solid "+(isMcp?"#DDD6FE":"#BBF7D0"),overflow:"hidden",
                    display:"flex",gap:0}}>
                    <div style={{width:4,background:color,flexShrink:0}}/>
                    <div style={{flex:1,padding:"10px 14px"}}>
                      <div style={{display:"flex",gap:10,alignItems:"center",marginBottom:4,flexWrap:"wrap"}}>
                        <span style={{fontSize:9,fontWeight:700,padding:"2px 8px",borderRadius:10,
                          background:color+"18",color}}>{evt.type}</span>
                        <span style={{fontSize:9,fontFamily:"monospace",color:"#6B7280"}}>{evt.bizStep?.split(":").pop()}</span>
                        {evt.tool&&<span style={{fontSize:9,padding:"2px 8px",borderRadius:8,
                          background:"#F5F3FF",color:"#7C3AED",fontFamily:"monospace",fontWeight:700}}>
                          🔧 {evt.tool}()
                        </span>}
                        <span style={{fontSize:9,color:"#9CA3AF",marginLeft:"auto"}}>{evt.when}</span>
                      </div>
                      <div style={{fontSize:11,color:"#374151",fontWeight:500,marginBottom:3}}>{evt.desc}</div>
                      <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                        <span style={{fontSize:8,fontFamily:"monospace",color:evt.epc?.includes("0860009")?"#CC0000":evt.epc?.includes("0817089")?"#16A34A":"#005487"}}>
                          {evt.epc}
                        </span>
                        {evt.agent_gsrn&&<span style={{fontSize:8,fontFamily:"monospace",color:"#DB2877"}}>
                          agent: {evt.agent_gsrn.split(".").pop()}
                        </span>}
                        {evt.result_nodes&&<span style={{fontSize:8,color:"#6B7280"}}>
                          {evt.result_nodes} nodes returned
                        </span>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

