// ── UNIVERSAL LIVE EVENT GENERATOR ──────────────────────────────────────────
const genLiveEvents = (enterprise) => {
  const events = [];
  (enterprise.divisions||[]).forEach(div=>{
    (div.alerts||[]).forEach(a=>{
      events.push({id:"a-"+div.id,sev:a.sev,sub:div.name,icon:div.icon,msg:a.msg,time:a.ts});
    });
    events.push({id:"e-"+div.id,sev:"info",sub:div.name,icon:div.icon,
      msg:`${div.name}: EPCIS stream nominal — ${div.epcis_rate.toLocaleString()}/min`,
      time:new Date().toLocaleTimeString()});
  });
  return events;
};

