function AuditModule() {
  const { ids, prefix, addProvenance } = useIDs();
  const pfx = prefix || "0085126";
  const epc = (t) => ids?.[t]?.epc || "";

  // Every Big-4 firm + the ThingDaddy tool they integrate
  const FIRMS = [
    {id:"ey",   name:"EY Helix",         icon:"🔷", color:"#FFE600", textColor:"#2E2E38", tool:"TD:Helix Connector",   agent:"EY.ai Assurance",  desc:"100% journal-entry population — every TD ID matched to its EPCIS evidence chain, replacing statistical sampling."},
    {id:"kpmg", name:"KPMG Clara",       icon:"🔵", color:"#00338D", textColor:"#fff",    tool:"TD:Clara Agent",       agent:"KPMG Clara AI",    desc:"Multi-agent workbench — ThingDaddy registers as the physical-evidence agent alongside KPMG's transaction agents."},
    {id:"pwc",  name:"PwC Agent OS",     icon:"🟠", color:"#D04A02", textColor:"#fff",    tool:"TD:Governed Plugin",   agent:"PwC ChatPwC",      desc:"Governed plugin (REGULATED tier) — an EPCIS audit trail is logged for every AI agent action."},
    {id:"dtt",  name:"Deloitte Zora AI", icon:"🟢", color:"#86BC25", textColor:"#2E2E38", tool:"TD:Zora Traverse",     agent:"Deloitte Omnia",   desc:"Transaction enrichment — GDTI→GIAI→GLN traverse links every transaction to its physical and locational identity."},
  ];

  // ISA 230 assertions span ALL identity types, not just assets
  const ASSERTIONS = [
    {a:"EXISTENCE",     color:"#3DB54A", types:["GIAI","GTIN","LGTIN","SSCC"], evidence:"EPCIS OBSERVE chain proves the asset, product, lot, or shipment physically exists and was seen at a read point."},
    {a:"COMPLETENESS",  color:"#00A09C", types:["GIAI","GLN","GTIN","CPI"],    evidence:"GS1 registry reconciled against the financial register — nothing recorded is missing, nothing physical is unrecorded."},
    {a:"VALUATION",     color:"#1D4ED8", types:["GMN","GTIN","LGTIN"],         evidence:"GMN cohort life + LGTIN lot history support depreciation, impairment, and inventory valuation."},
    {a:"RIGHTS & OBLIGATIONS", color:"#D97706", types:["PGLN","GLN","GDTI"],   evidence:"PGLN ownership + GDTI title/contract documents prove rights and obligations over each item."},
    {a:"PRESENTATION",  color:"#7C3AED", types:["GLN","GDTI","GSRN"],          evidence:"GLN segment allocation + GDTI disclosure + GSRN responsibility map support financial-statement presentation."},
    {a:"CUTOFF",        color:"#DB2877", types:["SSCC","GDTI","LGTIN"],        evidence:"SSCC shipment timestamps + GDTI transaction dates fix the period each event belongs to."},
  ];

  // The full identity set under audit — every type, with its audit role
  const AUDIT_SCOPE = [
    {type:"PGLN",  role:"Legal entity / ownership",         color:"#6D28D9"},
    {type:"GLN",   role:"Location & segment reporting",     color:"#0891B2"},
    {type:"GIAI",  role:"Fixed-asset existence",            color:"#2563EB"},
    {type:"GTIN",  role:"Inventory / trade items",          color:"#16A34A"},
    {type:"LGTIN", role:"Lot valuation & recall",           color:"#DC2626"},
    {type:"GDTI",  role:"Documents, contracts, titles",     color:"#D97706"},
    {type:"GSRN",  role:"Responsibility & service",         color:"#DB2877"},
    {type:"CPI",   role:"Component / BOM completeness",      color:"#7C3AED"},
    {type:"GMN",   role:"Model cohort valuation",           color:"#059669"},
    {type:"SSCC",  role:"Shipment cutoff & logistics",      color:"#EA580C"},
    {type:"GRAI",  role:"Returnable asset register",        color:"#0D9488"},
    {type:"GCN",   role:"Coupon / rebate liability",        color:"#BE185D"},
    {type:"ITIP",  role:"Multi-piece item integrity",       color:"#4F46E5"},
    {type:"UPUI",  role:"Serialized pharma traceability",   color:"#9333EA"},
  ];

  const [selFirm, setSelFirm] = React.useState(null);
  const [selAssertion, setSelAssertion] = React.useState(ASSERTIONS[0]);
  const [running, setRunning] = React.useState(false);
  const [log, setLog] = React.useState([]);
  const [done, setDone] = React.useState(false);

  const runAudit = async () => {
    if(running) return;
    setRunning(true); setDone(false); setLog([]);
    const firm = selFirm || FIRMS[0];
    const steps = [
      `${firm.tool} connecting to ThingDaddy EPCIS repository…`,
      `Loading identity universe for prefix ${pfx} — 13 ID types in scope`,
      `Reconciling GIAI fixed-asset register against general ledger…`,
      `Tracing GTIN + LGTIN inventory to EPCIS commissioning events…`,
      `Verifying PGLN ownership + GDTI title documents…`,
      `Matching SSCC shipment timestamps for cutoff testing…`,
      `Running ${selAssertion.a} assertion across ${selAssertion.types.join(", ")}…`,
      `${firm.agent}: 100% population tested — 0 exceptions, no sampling required`,
      `✅ Audit evidence package signed & sealed (ISA 230 compliant)`,
    ];
    for(let i=0;i<steps.length;i++){
      await new Promise(r=>setTimeout(r, 380));
      setLog(prev=>[...prev, {t:new Date().toLocaleTimeString(), m:steps[i], last:i===steps.length-1}]);
    }
    setRunning(false); setDone(true);
    // Real-time audit provenance — every client ID the auditor touches is logged into the graph
    const firmName = (selFirm||FIRMS[0]).agent;
    (selAssertion.types||[]).forEach(t => {
      const e = epc(t);
      if (e && addProvenance) addProvenance({
        type: t, epc: e, gs1: ids?.[t]?.gs1, source: "audit",
        prefix: pfx, company: null,
        use: `${firmName} · ${selAssertion.a} assertion verified`,
        auditor: firmName,
      });
    });
  };

  return (
    <div style={{padding:"24px 20px", maxWidth:1100, margin:"0 auto"}}>
      <CompanySearchHeader label="the audit" accent={'#DC2626'} />
      {/* Hero */}
      <div style={{marginBottom:18, padding:"16px 18px", background:"linear-gradient(135deg,#0F172A,#1E1B4B)", borderRadius:10, border:"1px solid #7C3AED44"}}>
        <div style={{fontSize:11, fontWeight:700, color:"#A78BFA", letterSpacing:".14em", marginBottom:4}}>THINGDADDY · AUDIT SDK · TD-UID-041</div>
        <div style={{fontSize:18, fontWeight:800, color:"#fff", marginBottom:4}}>ISA 230 AI Co-Audit Engine — All 13 Identity Types</div>
        <div style={{fontSize:12, color:"#94A3B8", lineHeight:1.6}}>Audit covers <strong style={{color:"#fff"}}>any and all assets</strong> — entities, locations, products, lots, documents, components, services, shipments. EPCIS event chains provide every ISA 230 assertion for {prefix?`prefix ${prefix}`:"any company"} with zero sampling.</div>
      </div>

      {/* Audit scope — all ID types */}
      <div style={{fontSize:12, fontWeight:700, color:GD.dark, marginBottom:8}}>Identity universe under audit ({AUDIT_SCOPE.length} types)</div>
      <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(180px,1fr))", gap:6, marginBottom:18}}>
        {AUDIT_SCOPE.map(s=>{
          const live = epc(s.type);
          return (
            <div key={s.type} style={{padding:"9px 11px", borderRadius:7, background:"#fff", border:`1px solid ${s.color}22`, borderLeft:`3px solid ${s.color}`}}>
              <div style={{display:"flex", alignItems:"center", gap:6, marginBottom:2}}>
                <span style={{fontSize:11, fontWeight:800, color:s.color, fontFamily:"monospace"}}>{s.type}</span>
                {live && <span style={{width:5, height:5, borderRadius:"50%", background:"#22C55E", display:"inline-block"}}/>}
              </div>
              <div style={{fontSize:9, color:GD.gray, lineHeight:1.35}}>{s.role}</div>
              {live && <div style={{fontSize:7, fontFamily:"monospace", color:s.color, marginTop:3, wordBreak:"break-all"}}>{live}</div>}
            </div>
          );
        })}
      </div>

      {/* Big-4 firm cards — each integrates a TD tool */}
      <div style={{fontSize:12, fontWeight:700, color:GD.dark, marginBottom:8}}>Select audit firm — each integrates a dedicated ThingDaddy tool</div>
      <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(240px,1fr))", gap:10, marginBottom:18}}>
        {FIRMS.map(f=>(
          <div key={f.id} onClick={()=>setSelFirm(selFirm?.id===f.id?null:f)}
            style={{cursor:"pointer", padding:"14px 16px", borderRadius:10, background:selFirm?.id===f.id?f.color:"#fff", border:`2px solid ${selFirm?.id===f.id?f.color:"#E5E7EB"}`, transition:"all .15s"}}>
            <div style={{display:"flex", alignItems:"center", gap:8, marginBottom:6}}>
              <span style={{fontSize:18}}>{f.icon}</span>
              <span style={{fontSize:14, fontWeight:800, color:selFirm?.id===f.id?f.textColor:GD.dark}}>{f.name}</span>
            </div>
            <div style={{display:"inline-block", fontSize:9, fontWeight:700, fontFamily:"monospace", padding:"2px 7px", borderRadius:4, marginBottom:6, background:selFirm?.id===f.id?"rgba(255,255,255,.25)":GD.greenLt, color:selFirm?.id===f.id?f.textColor:GD.greenDk}}>{f.tool}</div>
            <div style={{fontSize:10, lineHeight:1.5, color:selFirm?.id===f.id?f.textColor:GD.gray}}>{f.desc}</div>
          </div>
        ))}
      </div>

      {/* Assertions */}
      <div style={{fontSize:12, fontWeight:700, color:GD.dark, marginBottom:8}}>ISA 230 assertions — click to scope the audit run</div>
      <div style={{display:"flex", gap:6, flexWrap:"wrap", marginBottom:18}}>
        {ASSERTIONS.map(as=>(
          <button key={as.a} onClick={()=>setSelAssertion(as)}
            style={{padding:"7px 12px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:11, fontWeight:700,
              border:`1.5px solid ${selAssertion.a===as.a?as.color:"#E5E7EB"}`,
              background:selAssertion.a===as.a?as.color+"15":"#fff", color:selAssertion.a===as.a?as.color:GD.gray}}>
            {as.a}
          </button>
        ))}
      </div>
      <div style={{padding:"12px 14px", borderRadius:8, background:selAssertion.color+"0C", border:`1px solid ${selAssertion.color}33`, marginBottom:18}}>
        <div style={{fontSize:12, fontWeight:700, color:selAssertion.color, marginBottom:4}}>{selAssertion.a}</div>
        <div style={{fontSize:11, color:GD.dark, lineHeight:1.5, marginBottom:6}}>{selAssertion.evidence}</div>
        <div style={{display:"flex", gap:5, flexWrap:"wrap"}}>
          {selAssertion.types.map(t=>(
            <span key={t} style={{fontSize:9, fontWeight:700, fontFamily:"monospace", padding:"2px 7px", borderRadius:4, background:selAssertion.color+"18", color:selAssertion.color}}>TD:{t}{epc(t)?" ✓":""}</span>
          ))}
        </div>
      </div>

      {/* Run audit */}
      <button onClick={runAudit} disabled={running}
        style={{width:"100%", padding:"13px", borderRadius:9, border:"none", cursor:running?"wait":"pointer", fontFamily:"inherit", fontSize:14, fontWeight:800, background:running?GD.gray:GD.dark, color:"#fff", marginBottom:14}}>
        {running ? "⏳ Running AI co-audit…" : `▶ Run ${(selFirm||FIRMS[0]).name} audit — ${selAssertion.a} across all identity types`}
      </button>

      {/* Log */}
      {log.length > 0 && (
        <div style={{padding:"14px 16px", borderRadius:9, background:"#0F172A", fontFamily:"monospace"}}>
          {log.map((l,i)=>(
            <div key={i} style={{fontSize:10, color:l.last?"#22C55E":"#94A3B8", marginBottom:4, lineHeight:1.5}}>
              <span style={{color:"#475569"}}>{l.t}</span>  {l.m}
            </div>
          ))}
          {done && (
            <div style={{marginTop:10, padding:"10px 12px", borderRadius:6, background:"#16A34A18", border:"1px solid #16A34A44"}}>
              <div style={{fontSize:11, fontWeight:700, color:"#22C55E"}}>✅ ISA 230 evidence package complete — {(selFirm||FIRMS[0]).agent} · 100% population · 0 exceptions</div>
            </div>
          )}
        </div>
      )}
    
      <StandardExplainer solutionKey="audit"/>
      </div>
  );
}
function SupplyChainFlow() {
  const { ids, prefix, activeCompany } = useIDs();
  const TD_COLORS = {PGLN:"#6D28D9",GLN:"#0891B2",GIAI:"#2563EB",GTIN:"#16A34A",LGTIN:"#DC2626",GDTI:"#D97706",GSRN:"#DB2877",CPI:"#7C3AED",GMN:"#059669",SSCC:"#EA580C"};
  const STAGES=[
    {icon:"✏️",label:"Design",    tids:["CPI","GMN","GDTI"],  color:"#2563EB", epcis:"OBJECT_EVENT / ADD — bizStep:design_release"},
    {icon:"🏭",label:"Manufacture",tids:["GIAI","CPI","LGTIN"],color:"#D97706", epcis:"OBJECT_EVENT / ADD — bizStep:commissioning"},
    {icon:"✅",label:"Inspect",   tids:["GIAI","GDTI","GSRN"], color:"#7C3AED", epcis:"OBJECT_EVENT / OBSERVE — bizStep:inspecting"},
    {icon:"📦",label:"Pack",      tids:["SSCC","GIAI","LGTIN"],color:"#0891B2", epcis:"AGGREGATION_EVENT — parent:SSCC children:GIAI"},
    {icon:"🚢",label:"Ship",      tids:["SSCC","GLN","PGLN"],  color:"#6D28D9", epcis:"OBJECT_EVENT / OBSERVE — bizStep:shipping"},
    {icon:"🏪",label:"Receive",   tids:["SSCC","GLN","GDTI"],  color:"#059669", epcis:"OBJECT_EVENT / ADD — bizStep:receiving"},
    {icon:"🔧",label:"Install",   tids:["GIAI","GLN","GSRN"],  color:"#DC2626", epcis:"OBJECT_EVENT / ADD — bizStep:installation"},
    {icon:"📡",label:"Operate",   tids:["GIAI","LGTIN","GSRN"],color:"#3DB54A", epcis:"OBJECT_EVENT / OBSERVE — bizStep:sensor_reading"},
    {icon:"🔩",label:"Maintain",  tids:["GIAI","CPI","GDTI"],  color:"#F07B2A", epcis:"OBJECT_EVENT / OBSERVE — bizStep:maintaining"},
    {icon:"🗑️",label:"Dispose",   tids:["GIAI","GDTI","PGLN"], color:"#6B7280", epcis:"OBJECT_EVENT / DELETE — bizStep:decommissioning"},
  ];
  const [sel,setSel]=useState(null);
  const selS=STAGES.find(s=>s.label===sel);
  return(
    <div style={{padding:"24px 20px"}}>
      <LiveIDsBanner module="Supply Chain"/>
      <div style={{fontSize:20,fontWeight:800,color:GD.dark,marginBottom:4}}>ThingDaddy Supply Chain — 10 GS1 Stages</div>
      <div style={{fontSize:12,color:GD.gray,marginBottom:16}}>Every stage has specific ThingDaddy IDs + EPCIS events. {prefix?`Active: ${prefix}`:"Register a company to load live URNs."}</div>
      <div style={{display:"flex",gap:4,overflowX:"auto",paddingBottom:10,flexWrap:"wrap"}}>
        {STAGES.map((s,i)=>(
          <div key={s.label} style={{display:"flex",alignItems:"center",flexShrink:0}}>
            <div onClick={()=>setSel(sel===s.label?null:s.label)}
              style={{textAlign:"center",padding:"10px 12px",borderRadius:8,cursor:"pointer",minWidth:82,
                background:sel===s.label?s.color+"22":"#fff",border:`2px solid ${sel===s.label?s.color:s.color+"33"}`,transition:"all .15s"}}>
              <div style={{fontSize:20,marginBottom:3}}>{s.icon}</div>
              <div style={{fontSize:10,fontWeight:700,color:s.color,marginBottom:4}}>{s.label}</div>
              <div style={{display:"flex",gap:2,flexWrap:"wrap",justifyContent:"center"}}>
                {s.tids.map(id=><span key={id} style={{fontSize:7,padding:"1px 3px",borderRadius:4,background:(TD_COLORS[id]||s.color)+"18",color:TD_COLORS[id]||s.color,fontFamily:"monospace",fontWeight:700}}>{id}</span>)}
              </div>
            </div>
            {i<STAGES.length-1&&<div style={{fontSize:12,color:"#D1D5DB",margin:"0 2px",flexShrink:0}}>→</div>}
          </div>
        ))}
      </div>
      {selS&&(
        <div style={{marginTop:12,padding:"14px 16px",borderRadius:8,background:"#0F172A",border:`1px solid ${selS.color}44`}}>
          <div style={{fontSize:12,fontWeight:700,color:selS.color,marginBottom:6}}>{selS.icon} {selS.label}</div>
          <div style={{fontSize:10,color:"#94A3B8",marginBottom:8,fontFamily:"monospace"}}>{selS.epcis}</div>
          <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:8}}>
            {selS.tids.map(id=><span key={id} style={{padding:"3px 8px",borderRadius:6,background:(TD_COLORS[id]||"#374151")+"22",color:TD_COLORS[id]||"#94A3B8",fontSize:10,fontWeight:700,fontFamily:"monospace"}}>TD:{id}</span>)}
          </div>
          {prefix&&selS.tids.map(id=>ids[id]?.epc&&(
            <div key={id} style={{fontSize:8,fontFamily:"monospace",color:"#22C55E",marginBottom:2,padding:"2px 8px",background:"#111827",borderRadius:3}}>
              {id}: {ids[id].epc}
            </div>
          ))}
          {!prefix&&<div style={{fontSize:10,color:"#4B5563"}}>Register a company to see live URNs for this stage</div>}
        </div>
      )}
    </div>
  );
}
