// AGENT 2 — TD:DEMO AGENT
// Builds a full interactive demo for any registered company or prefix
// ═══════════════════════════════════════════════════════════════════════════════

function DemoAgent({ setActiveModule }) {
  const { ids, prefix, setIds, setPrefix, addParty } = useIDs();
  const [step, setStep] = useState("input"); // input | building | demo
  const [companyInput, setCompanyInput] = useState({ prefix:"", company:"", sector:"", gln:"" });
  const [building, setBuilding] = useState(false);
  const [buildLog, setBuildLog] = useState([]);
  const [buildProgress, setBuildProgress] = useState(0);
  const [demo, setDemo] = useState(null);
  const [activeTab, setActiveTab] = useState("overview");
  const [selEvent, setSelEvent] = useState(null);
  const [liveIDs, setLiveIDs] = useState({});
  const [genDone, setGenDone] = useState(false);
  const [selProduct, setSelProduct] = useState(0);
  const [registeredList, setRegisteredList] = useState([]);
  const [batchInput, setBatchInput] = useState("");
  const [batchMode, setBatchMode] = useState(false);
  const [builtDemos, setBuiltDemos] = useState([]);
  const logRef = React.useRef(null);

  useEffect(() => { if(logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight; }, [buildLog]);

  const addLog = (msg, color="#94A3B8") => setBuildLog(p=>[...p,{t:new Date().toLocaleTimeString(),msg,color}]);

  const buildDemo = async (company, prefix, sector, gln) => {
    const co = company || companyInput.company;
    const pfx = prefix || companyInput.prefix;
    const sec = sector || companyInput.sector;
    if (!co && !pfx) return;

    setBuilding(true); setStep("building"); setBuildLog([]); setBuildProgress(0); setDemo(null);
    addLog(`🤖 TD:Demo Agent — building full demo for: ${co||pfx}`, "#60A5FA");
    addLog(`🧠 Calling Claude AI to generate complete company intelligence...`, "#A78BFA");

    const prompt = `You are ThingDaddy's Demo Intelligence Agent. Build a COMPLETE, REALISTIC demo profile for:

Company: "${co || "Unknown"}"
GS1 Prefix: "${pfx || "TBD"}"
Sector: "${sec || "Unknown"}"
GLN: "${gln || companyInput.gln || "TBD"}"

Return ONLY valid JSON (no markdown):
{
  "company": "Official full name",
  "shortName": "Short name for display",
  "sector": "Exact sector: Life Sciences | Automotive | Healthcare | Industrial | Energy | Chemicals | Defence | Food & Beverage | Pharma | Retail/CPG",
  "subSector": "Specific subsector",
  "icon": "Single emoji representing the company",
  "color": "#hexcolor matching sector (e.g. #1E3A5F for automotive)",
  "gradient": "CSS gradient string e.g. linear-gradient(135deg,#0A0A0A 0%,#1E3A5F 55%,#0F4C81 100%)",
  "country": "Country",
  "hq": "City, Country",
  "website": "URL",
  "description": "3 sentences: what they make, why ThingDaddy matters, key numbers",
  "tagline": "Short punchy tagline for the demo hero",
  "badges": [
    {"label":"GS1 Prefix: XXXXXXX","color":"#93C5FD"},
    {"label":"Key achievement or certification","color":"#4ADE80"},
    {"label":"Another badge","color":"#FCD34D"}
  ],
  "confirmed_gtin": "A real GTIN if publicly known, else null",
  "confirmed_gtin_product": "Product name for that GTIN if known",
  "divisions": [
    {"id":"div1","label":"Division Name","icon":"emoji","color":"#hex","full":"Full division name","desc":"2-sentence description","products":["Product 1","Product 2","Product 3","Product 4"],"ot_protocols":["OPC UA","MQTT"],"gln":"urn:epc:id:sgln:PREFIX.DIV001.0","pgln":"urn:epc:id:pgln:PREFIX.DIV001"},
    {"id":"div2","label":"Division 2","icon":"emoji","color":"#hex","full":"Full division name","desc":"2-sentence description","products":["Product A","Product B","Product C"],"ot_protocols":["OPC UA","Modbus"],"gln":"urn:epc:id:sgln:PREFIX.DIV002.0","pgln":"urn:epc:id:pgln:PREFIX.DIV002"},
    {"id":"div3","label":"Division 3","icon":"emoji","color":"#hex","full":"Full division name","desc":"2-sentence description","products":["Item X","Item Y"],"ot_protocols":["PROFINET","MQTT"],"gln":"urn:epc:id:sgln:PREFIX.DIV003.0","pgln":"urn:epc:id:pgln:PREFIX.DIV003"}
  ],
  "id_use_cases": {
    "GTIN": "Specific GTIN use case for this company",
    "GIAI": "Specific GIAI use case",
    "CPI": "Specific CPI use case",
    "GLN": "Specific GLN use case",
    "GDTI": "Specific GDTI use case",
    "SSCC": "Specific SSCC use case",
    "GSRN": "Specific GSRN use case",
    "GMN": "Specific GMN use case",
    "GRAI": "Specific GRAI use case",
    "GCN": "Specific GCN use case",
    "PGLN": "Specific PGLN use case",
    "LGTIN": "Specific LGTIN use case",
    "ITIP": "Specific ITIP use case",
    "UPUI": "Specific UPUI use case if relevant"
  },
  "epcis_chain": [
    {"step":"1","icon":"emoji","color":"#hex","stage":"Stage Name","title":"Event Title","ids":["GIAI","CPI"],"epcis":"OBJECT_EVENT / ADD","ot":"OT system description","urns":["TD:GIAI  urn description","TD:CPI  urn description"]},
    {"step":"2","icon":"emoji","color":"#hex","stage":"Stage Name","title":"Event Title","ids":["GIAI","GDTI"],"epcis":"OBJECT_EVENT / OBSERVE","ot":"OT system description","urns":["URN 1","URN 2"]}
  ],
  "sila_class": "CompanyNameInstrumentProvider",
  "adf_schema": "CompanyNameResultSchema",
  "sila_methods": ["GetStatus(giai) → StatusResult","RunMethod(giai, gdti) → RunResult","GetResults(giai) → DataResult"],
  "platform_map": [
    {"module":"🔑 Generate IDs","color":"#hex","use":"How this company uses ThingDaddy IDs specifically"},
    {"module":"📡 EPCIS Chain","color":"#hex","use":"Specific EPCIS use case"},
    {"module":"⚗️ SiLA 2 SDK","color":"#hex","use":"SiLA driver specifics"},
    {"module":"🧬 Allotrope ADF","color":"#hex","use":"ADF schema specifics"},
    {"module":"🔌 MCP Server","color":"#hex","use":"MCP tool specifics"},
    {"module":"📋 Audit","color":"#hex","use":"Audit use case specifics"}
  ],
  "linkedin_signals": ["Job title showing IoT/AI pain","Another role title","Third signal"],
  "td_opportunity": "2-paragraph ThingDaddy sales pitch specific to this company's products and sector",
  "mcp_tools": ["tool_call_1 example","tool_call_2 example","tool_call_3 example"],
  "standards": ["Standard 1","Standard 2","Standard 3"],
  "ot_systems": ["System 1","System 2","System 3"]
}

IMPORTANT: Make the EPCIS chain have exactly 8 steps. Make divisions array have 2-4 entries. Replace PREFIX with the actual GS1 prefix ${pfx||"0000000"} in all URNs.`;

    try {
      setBuildProgress(20);
      const resp = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body: JSON.stringify({model:"claude-sonnet-4-6",max_tokens:4000,messages:[{role:"user",content:prompt}]})
      });
      const data = await resp.json();
      const text = data.content?.[0]?.text||"{}";
      const cleaned = text.replace(/```json\n?|```\n?/g,"").trim();
      addLog(`✅ AI profile generated`, "#22C55E");
      setBuildProgress(40);

      const profile = JSON.parse(cleaned);
      const p = pfx || profile.prefix || "0000000";

      addLog(`🔑 Generating all 13 ThingDaddy IDs for prefix ${p}...`, "#A78BFA");
      await new Promise(r=>setTimeout(r,100));
      const genIds = {};
      ID_TYPES.forEach(t => { genIds[t.id] = t.gen(p); });
      setLiveIDs(genIds); setGenDone(true);
      if(setPrefix) setPrefix(p);
      if(setIds) setIds(genIds);
      setBuildProgress(60);

      addLog(`📡 Building EPCIS lifecycle chain...`, "#A78BFA");
      await new Promise(r=>setTimeout(r,100));
      // Patch URNs in epcis_chain with real generated IDs
      const epcis = (profile.epcis_chain||[]).map(e=>({...e,
        liveUrns: e.ids.map(id=>genIds[id]?.epc||`urn:epc:id:${id.toLowerCase()}:${p}.demo`)
      }));
      setBuildProgress(75);

      addLog(`⚗️ Generating SiLA 2 driver code...`, "#A78BFA");
      await new Promise(r=>setTimeout(r,100));
      const proto = Object.entries(INDUSTRY_PROTOCOLS).find(([k])=>profile.sector?.includes(k))?.[1]||INDUSTRY_PROTOCOLS["Industrial"];
      const dev = profile.divisions?.[0]?.products?.[0]||"Asset";
      const silaCode = `# ThingDaddy SiLA 2 Driver — ${profile.company}
# Auto-generated by TD:Demo Agent
# SiLA 2 Feature Class: ${profile.sila_class}

from sila2.framework import Feature, FullyQualifiedIdentifier
from dataclasses import dataclass

GIAI = "${genIds["GIAI"]?.epc||"urn:epc:id:giai:"+p+".ASSET001"}"
PGLN = "${genIds["PGLN"]?.epc||makePGLNurn(p)}"
PREFIX = "${p}"

@dataclass
class ${(profile.sila_class||"InstrumentProvider").replace(/[^A-Za-z0-9]/g,"")}:
    td_giai:  str = GIAI
    td_pgln:  str = PGLN
    td_prefix:str = PREFIX

class ${profile.sila_class||"InstrumentProvider"}(Feature):
${(profile.sila_methods||[]).map(m=>`    def ${m.split("(")[0]}(self, giai: str) -> dict:\n        # EPCIS event fired on completion\n        return {"status":"OK","giai":giai}`).join("\n\n")}`;

      const adfCode = `# Allotrope ADF Schema — ${profile.company}
# Schema: ${profile.adf_schema}
{
  "@context": "https://allotrope.org/adf/",
  "@type": "${profile.adf_schema}",
  "equipment_serial_number": "${genIds["GIAI"]?.epc||"urn:epc:id:giai:"+p+".ASSET001"}",
  "reagent_lot": "${genIds["LGTIN"]?.epc||makeLGTINurn(p,"000001","LOT001")}",
  "document_reference": "${genIds["GDTI"]?.epc||makeGDTIurn(p,"DOC001","001")}",
  "location": "${genIds["GLN"]?.epc||makeGLNurn(p)}",
  "operator": "${genIds["GSRN"]?.epc||makeGSRNurn(p,"OPR001")}",
  "measurement_time": "${new Date().toISOString()}"
}`;
      setBuildProgress(88);

      addLog(`💼 Analyzing LinkedIn IoT/AI hiring signals...`, "#A78BFA");
      await new Promise(r=>setTimeout(r,100));
      setBuildProgress(95);

      addLog(`🎉 Demo complete! Full ThingDaddy profile ready.`, "#4ADE80");
      setBuildProgress(100);

      const fullDemo = { profile, prefix:p, genIds, epcis, silaCode, adfCode, proto };
      setDemo(fullDemo);
      setBuiltDemos(prev=>[...prev,{id:Date.now(),company:profile.company,prefix:p,sector:profile.sector,icon:profile.icon}]);
      setActiveTab("overview");
      setSelProduct(0);
      setTimeout(()=>setStep("demo"),400);

    } catch(e) {
      addLog(`❌ Error: ${e.message}`, "#F87171");
      setStep("input");
    } finally {
      setBuilding(false);
    }
  };

  const TD_COLORS = {PGLN:"#6D28D9",GLN:"#0891B2",GIAI:"#2563EB",GTIN:"#16A34A",LGTIN:"#DC2626",GDTI:"#D97706",GSRN:"#DB2877",CPI:"#7C3AED",GMN:"#059669",SSCC:"#EA580C",GRAI:"#0D9488",GCN:"#BE185D",GSIN:"#B45309",ITIP:"#4F46E5"};

  const TABS = [
    {id:"overview",label:"🏠 Overview"},{id:"divisions",label:"🏢 Divisions"},
    {id:"epcis",label:"📡 EPCIS Chain"},{id:"ids14",label:"🔑 All 13 IDs"},
    {id:"sila",label:"⚗️ SiLA 2 + ADF"},{id:"linkedin",label:"💼 LinkedIn Intel"},
    {id:"platform",label:"🗺 Platform Map"},{id:"mcp",label:"🔌 MCP Tools"},
  ];

  if(step==="input") return (
    <div style={{padding:"24px",fontFamily:"inherit"}}>
      <div style={{marginBottom:24,padding:"20px 24px",background:"linear-gradient(135deg,#0A0A0A,#064E3B,#065F46)",borderRadius:12,border:"1px solid #22C55E44"}}>
        <div style={{display:"flex",alignItems:"flex-start",gap:16}}>
          <div style={{fontSize:40}}>🎬</div>
          <div style={{flex:1}}>
            <div style={{fontSize:10,fontWeight:700,color:"#4ADE80",letterSpacing:".18em",marginBottom:4}}>THINGDADDY · AI DEMO BUILDER</div>
            <div style={{fontSize:24,fontWeight:900,color:"#fff",marginBottom:6}}>TD:Demo Agent</div>
            <div style={{fontSize:13,color:"#86EFAC",lineHeight:1.6,marginBottom:12}}>
              Enter any registered company prefix or GLN. The agent builds a full interactive demo — identical in depth to the Dana, Tesla, Culligan, and General Atomics demos — with all 13 IDs, 8-step EPCIS chain, SiLA 2 driver code, Allotrope ADF schema, LinkedIn intelligence, and MCP tools.
            </div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
              {["Claude AI Demo Builder","All 13 ID Types","8-Step EPCIS","SiLA 2 Code Gen","ADF Schema","LinkedIn Intel","MCP Server Tools","AI Value Pitch"].map(t=>(
                <span key={t} style={{fontSize:10,padding:"3px 10px",borderRadius:20,background:"#064E3B",border:"1px solid #22C55E44",color:"#4ADE80",fontWeight:600}}>{t}</span>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Built demos list */}
      {builtDemos.length > 0 && (
        <div style={{marginBottom:20,padding:"14px 16px",background:GD.white,borderRadius:8,border:`1px solid ${GD.green}44`}}>
          <div style={{fontSize:12,fontWeight:700,color:GD.dark,marginBottom:10}}>✅ {builtDemos.length} Demo{builtDemos.length>1?"s":""} Built This Session</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {builtDemos.map(d=>(
              <button key={d.id} onClick={()=>{setStep("demo");}} style={{padding:"6px 14px",borderRadius:20,border:`1px solid ${GD.green}44`,background:GD.greenLt,color:GD.greenDk,fontSize:11,fontWeight:600,cursor:"pointer",fontFamily:"inherit"}}>
                {d.icon} {d.company} ({d.prefix})
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Mode */}
      <div style={{display:"flex",gap:8,marginBottom:20}}>
        {[["single","🏢 Single Company"],["batch","📋 Batch Build"]].map(([m,l])=>(
          <button key={m} onClick={()=>setBatchMode(m==="batch")} style={{padding:"8px 18px",borderRadius:8,border:"none",cursor:"pointer",fontFamily:"inherit",fontSize:12,fontWeight:batchMode===(m==="batch")?700:400,background:batchMode===(m==="batch")?GD.green+"22":"#F3F4F6",color:batchMode===(m==="batch")?GD.green:GD.gray,outline:batchMode===(m==="batch")?`1.5px solid ${GD.green}`:"1.5px solid #E5E7EB"}}>{l}</button>
        ))}
      </div>

      {/* ── GEPIR auto-fill: one tap loads a verified company and builds the entire demo ── */}
      <div style={{marginBottom:18,padding:"14px 16px",borderRadius:10,background:"#EFF6FF",border:"1px solid #3253DC44"}}>
        <div style={{fontSize:12,fontWeight:800,color:"#1E3A8A",marginBottom:4}}>⚡ Register from GS1 GEPIR — registration first, then the demo builds</div>
        <div style={{fontSize:11,color:GD.gray,marginBottom:10,lineHeight:1.5}}>⚖️ No registration → no prefix → nothing happens. Tapping a company REGISTERS it first (establishing its prefix in the database), and only then does the pipeline run: registration → prefix → 13 IDs → EPCIS → SiLA/ADF → AI graph.</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          {[
            {company:"Qualcomm, Incorporated", prefix:"0706166", gln:"0706166000006", sector:"Semiconductors", icon:"🔲"},
            {company:"Tata Steel Ltd", prefix:"8905346", gln:"890534600000", sector:"Industrial", icon:"🏭"},
            {company:"Tata Consumer Products GB Limited", prefix:"5014328", gln:"501432800000", sector:"Food & Beverage", icon:"🫖"},
          ].map(g=>(
            <button key={g.prefix} onClick={()=>{
                // ⚖️ UNBREAKABLE RULE: register FIRST. addParty establishes the prefix
                // (the entity's DNA) and writes it into the registry + AI graph. Only
                // after the entity exists by registration do we build its demo.
                if(typeof addParty==="function") addParty({orgName:g.company,company:g.company,prefix:g.prefix,gln:g.gln,country:"United States",sector:g.sector,source:"GS1 GEPIR (verified)"});
                setCompanyInput({company:g.company,prefix:g.prefix,sector:g.sector,gln:g.gln});
                buildDemo(g.company,g.prefix,g.sector,g.gln);
              }}
              disabled={building}
              style={{padding:"8px 14px",borderRadius:8,border:"1px solid #3253DC55",background:"#fff",color:"#1E3A8A",cursor:building?"not-allowed":"pointer",fontFamily:"inherit",fontSize:11,fontWeight:700,opacity:building?0.6:1}}>
              {g.icon} {g.company.split(",")[0].split(" ").slice(0,2).join(" ")} · {g.prefix} →
            </button>
          ))}
        </div>
      </div>

      {!batchMode ? (
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16,marginBottom:20}}>
          {[
            {key:"company",label:"Company Name",ph:"e.g. Siemens AG, Roche, Boeing"},
            {key:"prefix",label:"GS1 Prefix",ph:"e.g. 4012345"},
            {key:"sector",label:"Sector (optional)",ph:"e.g. Industrial, Life Sciences"},
            {key:"gln",label:"GLN (optional)",ph:"e.g. 4012345000002"},
          ].map(f=>(
            <div key={f.key}>
              <div style={{fontSize:11,fontWeight:700,color:GD.gray,marginBottom:5,letterSpacing:".06em",textTransform:"uppercase"}}>{f.label}</div>
              <input value={companyInput[f.key]} onChange={e=>setCompanyInput(p=>({...p,[f.key]:e.target.value}))}
                placeholder={f.ph} style={{width:"100%",padding:"10px 12px",borderRadius:6,border:`1.5px solid ${GD.darkBrd}`,fontSize:13,fontFamily:"inherit",color:GD.dark,background:GD.white,outline:"none",boxSizing:"border-box"}}/>
            </div>
          ))}
        </div>
      ) : (
        <div style={{marginBottom:20}}>
          <div style={{fontSize:11,fontWeight:700,color:GD.gray,marginBottom:5,letterSpacing:".06em",textTransform:"uppercase"}}>Companies (Company,Prefix,Sector — one per line)</div>
          <textarea value={batchInput} onChange={e=>setBatchInput(e.target.value)} rows={6}
            placeholder={"Siemens AG,4012345,Industrial\nRoche,7610084,Life Sciences\nBoeing,0888000,Defence"}
            style={{width:"100%",padding:"12px",borderRadius:6,border:`1.5px solid ${GD.darkBrd}`,fontSize:12,fontFamily:"monospace",color:GD.dark,background:GD.white,outline:"none",boxSizing:"border-box",resize:"vertical"}}/>
        </div>
      )}

      <button onClick={()=>buildDemo()} disabled={building} style={{
        padding:"13px 36px",borderRadius:8,border:"none",cursor:building?"not-allowed":"pointer",
        fontFamily:"inherit",fontSize:14,fontWeight:700,
        background:building?"#374151":`linear-gradient(135deg,${GD.greenDk},${GD.green})`,
        color:"#fff",boxShadow:`0 4px 14px ${GD.green}44`,opacity:building?0.7:1,
      }}>
        {building ? "🤖 Building Demo..." : "🎬 Build Full Demo"}
      </button>

      {buildLog.length>0 && (
        <div ref={logRef} style={{marginTop:16,background:GD.dark,borderRadius:8,padding:"12px 16px",height:120,overflowY:"auto"}}>
          {buildLog.map((l,i)=><div key={i} style={{fontSize:10,fontFamily:"monospace",marginBottom:3}}><span style={{color:"#374151",marginRight:8}}>{l.t}</span><span style={{color:l.color}}>{l.msg}</span></div>)}
        </div>
      )}
    </div>
  );

  if(step==="building") return (
    <div style={{padding:"40px 24px",textAlign:"center",maxWidth:600,margin:"0 auto",fontFamily:"inherit"}}>
      <div style={{fontSize:56,marginBottom:20,animation:"spin 2s linear infinite"}}>🤖</div>
      <div style={{fontSize:22,fontWeight:800,color:GD.dark,marginBottom:8}}>Building Full Demo</div>
      <div style={{fontSize:14,color:GD.gray,marginBottom:24}}>{companyInput.company||companyInput.prefix}</div>
      <div style={{height:8,background:"#F3F4F6",borderRadius:4,overflow:"hidden",marginBottom:20}}>
        <div style={{height:"100%",width:`${buildProgress}%`,background:`linear-gradient(90deg,${GD.greenDk},${GD.green},${GD.teal})`,borderRadius:4,transition:"width .4s ease"}}/>
      </div>
      <div style={{fontSize:13,color:GD.gray,marginBottom:24}}>{buildProgress}% complete</div>
      <div ref={logRef} style={{background:GD.dark,borderRadius:8,padding:"12px 16px",height:160,overflowY:"auto",textAlign:"left"}}>
        {buildLog.map((l,i)=><div key={i} style={{fontSize:10,fontFamily:"monospace",marginBottom:3}}><span style={{color:"#374151",marginRight:8}}>{l.t}</span><span style={{color:l.color}}>{l.msg}</span></div>)}
      </div>
    </div>
  );

  if(!demo) return null;
  const { profile, prefix:p, genIds, epcis, silaCode, adfCode } = demo;

  return (
    <div style={{fontFamily:"inherit",minHeight:"100vh",background:"#F8FAFC"}}>
      {/* Hero */}
      <div style={{background:profile.gradient||"linear-gradient(135deg,#0A0A0A 0%,#1E3A5F 100%)",padding:"20px 24px 16px",position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",inset:0,background:"radial-gradient(circle at 80% 50%,rgba(255,255,255,.04),transparent 60%)",pointerEvents:"none"}}/>
        <div style={{position:"relative"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:4}}>
            <button onClick={()=>setStep("input")} style={{fontSize:11,color:"rgba(255,255,255,.5)",background:"none",border:"1px solid rgba(255,255,255,.2)",borderRadius:4,padding:"3px 10px",cursor:"pointer",fontFamily:"inherit"}}>← Back</button>
            <div style={{fontSize:10,fontWeight:700,color:"rgba(255,255,255,.4)",letterSpacing:".18em"}}>THINGDADDY · AI-GENERATED DEMO</div>
          </div>
          <div style={{fontSize:24,fontWeight:900,color:"#fff",marginBottom:4}}>{profile.icon} {profile.company}</div>
          <div style={{fontSize:13,color:"rgba(255,255,255,.75)",marginBottom:10}}>{profile.tagline}</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {(profile.badges||[]).map((b,i)=>(
              <div key={i} style={{padding:"4px 12px",borderRadius:20,background:"rgba(255,255,255,.12)",border:"1px solid rgba(255,255,255,.25)",fontSize:11,fontWeight:700,color:b.color||"#fff"}}>{b.label}</div>
            ))}
            {genDone && <div style={{padding:"4px 12px",borderRadius:20,background:"rgba(61,181,74,.2)",border:"1px solid rgba(61,181,74,.5)",fontSize:11,fontWeight:700,color:"#4ADE80"}}>✓ 13 IDs live</div>}
          </div>
        </div>
      </div>

      {/* Tab bar */}
      <div style={{background:GD.white,borderBottom:"2px solid #E5E7EB",display:"flex",overflowX:"auto"}}>
        {TABS.map(t=>(
          <button key={t.id} onClick={()=>setActiveTab(t.id)} style={{padding:"10px 14px",border:"none",cursor:"pointer",fontFamily:"inherit",fontSize:11,fontWeight:activeTab===t.id?700:400,background:"transparent",color:activeTab===t.id?profile.color||GD.green:GD.gray,borderBottom:activeTab===t.id?`3px solid ${profile.color||GD.green}`:"3px solid transparent",whiteSpace:"nowrap"}}>{t.label}</button>
        ))}
        <div style={{marginLeft:"auto",display:"flex",alignItems:"center",padding:"0 14px",gap:8}}>
          <button onClick={()=>{setStep("input");setDemo(null);}} style={{fontSize:11,padding:"5px 12px",borderRadius:6,border:`1px solid ${GD.green}`,background:GD.greenLt,color:GD.greenDk,cursor:"pointer",fontFamily:"inherit",fontWeight:600}}>🎬 Build New Demo</button>
        </div>
      </div>

      {/* Tab content */}
      <div style={{padding:"20px 24px"}}>

        {/* Overview */}
        {activeTab==="overview" && (
          <div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16,marginBottom:16}}>
              <div style={{background:GD.white,border:`2px solid ${profile.color||GD.green}33`,borderRadius:10,padding:18}}>
                <div style={{fontSize:16,fontWeight:800,color:profile.color||GD.dark,marginBottom:8}}>{profile.icon} {profile.company}</div>
                <div style={{fontSize:12,color:GD.gray,lineHeight:1.7,marginBottom:12}}>{profile.description}</div>
                <div style={{marginBottom:10}}>
                  {[["HQ",profile.hq],["Sector",profile.sector],["Sub-sector",profile.subSector],["Website",profile.website]].map(([k,v])=>v&&(
                    <div key={k} style={{display:"flex",gap:8,padding:"4px 0",borderBottom:"1px solid #F3F4F6"}}>
                      <div style={{minWidth:70,fontSize:11,color:GD.gray,fontWeight:600}}>{k}</div>
                      <div style={{fontSize:11,color:GD.dark}}>{v}</div>
                    </div>
                  ))}
                </div>
                <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>{(profile.standards||[]).map(s=><span key={s} style={{fontSize:9,padding:"2px 7px",borderRadius:10,background:`${profile.color||GD.green}12`,color:profile.color||GD.green,fontWeight:600}}>{s}</span>)}</div>
              </div>
              <div style={{background:"#0F172A",borderRadius:10,padding:16}}>
                <div style={{fontSize:10,fontWeight:700,color:"#22C55E",letterSpacing:".1em",marginBottom:10}}>THINGDADDY GS1 IDs — PREFIX {p}</div>
                {Object.entries(genIds).slice(0,6).map(([type,r])=>(
                  <div key={type} style={{display:"flex",gap:6,marginBottom:5}}>
                    <span style={{fontSize:9,fontWeight:800,padding:"1px 5px",borderRadius:3,background:(TD_COLORS[type]||"#374151")+"22",color:TD_COLORS[type]||"#94A3B8",flexShrink:0,fontFamily:"monospace",minWidth:42,textAlign:"center"}}>{type}</span>
                    <span style={{fontSize:8,fontFamily:"monospace",color:"#22C55E",wordBreak:"break-all",lineHeight:1.4}}>{r.epc}</span>
                  </div>
                ))}
                <div style={{marginTop:8,padding:"6px 10px",background:"#1F2937",borderRadius:5}}>
                  <div style={{fontSize:9,color:"#9CA3AF"}}>OT Systems: {(profile.ot_systems||[]).slice(0,3).join(" · ")}</div>
                </div>
              </div>
            </div>
            {/* ThingDaddy opportunity */}
            <div style={{background:GD.offWhite,borderRadius:10,padding:16}}>
              <div style={{fontSize:14,fontWeight:700,color:GD.dark,marginBottom:8}}>🎯 ThingDaddy Opportunity</div>
              <div style={{fontSize:13,color:GD.dark,lineHeight:1.7}}>{profile.td_opportunity}</div>
            </div>
          </div>
        )}

        {/* Divisions */}
        {activeTab==="divisions" && (
          <div>
            <div style={{display:"flex",gap:8,marginBottom:16,flexWrap:"wrap"}}>
              {(profile.divisions||[]).map((d,i)=>(
                <button key={d.id} onClick={()=>setSelProduct(i)} style={{padding:"7px 14px",borderRadius:20,border:`1.5px solid ${selProduct===i?d.color:"#E5E7EB"}`,background:selProduct===i?d.color+"18":"transparent",color:selProduct===i?d.color:GD.gray,cursor:"pointer",fontFamily:"inherit",fontSize:11,fontWeight:selProduct===i?700:400}}>
                  {d.icon} {d.label}
                </button>
              ))}
            </div>
            {profile.divisions?.[selProduct] && (() => { const div=profile.divisions[selProduct]; return (
              <div style={{background:GD.white,border:`2px solid ${div.color}33`,borderRadius:10,padding:20}}>
                <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}><span style={{fontSize:32}}>{div.icon}</span><div><div style={{fontSize:18,fontWeight:800,color:div.color}}>{div.full||div.label}</div><div style={{fontSize:11,color:GD.gray}}>{div.desc?.slice(0,80)}</div></div></div>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16}}>
                  <div>
                    <div style={{fontSize:10,fontWeight:700,color:GD.gray,letterSpacing:".1em",marginBottom:8}}>KEY PRODUCTS</div>
                    {(div.products||[]).map(pr=><div key={pr} style={{fontSize:11,color:GD.dark,marginBottom:3}}>▸ {pr}</div>)}
                  </div>
                  <div>
                    <div style={{fontSize:10,fontWeight:700,color:GD.gray,letterSpacing:".1em",marginBottom:8}}>OT PROTOCOLS</div>
                    <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
                      {(div.ot_protocols||[]).map(pr=><span key={pr} style={{fontSize:10,padding:"3px 8px",borderRadius:10,background:div.color+"12",color:div.color,fontWeight:600}}>{pr}</span>)}
                    </div>
                    <div style={{marginTop:10}}>
                      <div style={{fontSize:9,fontWeight:700,color:GD.gray,marginBottom:4}}>GLN:</div>
                      <div style={{fontSize:8,fontFamily:"monospace",color:GD.teal,wordBreak:"break-all"}}>{div.gln}</div>
                      <div style={{fontSize:9,fontWeight:700,color:GD.gray,marginBottom:4,marginTop:6}}>PGLN:</div>
                      <div style={{fontSize:8,fontFamily:"monospace",color:GD.purple,wordBreak:"break-all"}}>{div.pgln}</div>
                    </div>
                  </div>
                </div>
              </div>
            );})()}
          </div>
        )}

        {/* EPCIS Chain */}
        {activeTab==="epcis" && (
          <div>
            <div style={{fontSize:16,fontWeight:800,color:GD.dark,marginBottom:4}}>EPCIS Lifecycle Chain — {profile.company}</div>
            <div style={{fontSize:12,color:GD.gray,marginBottom:14}}>8-step AI-generated lifecycle: from manufacturing through to end-of-life disposal</div>
            <div style={{display:"flex",gap:4,overflowX:"auto",paddingBottom:8,flexWrap:"wrap"}}>
              {epcis.map(e=>(
                <div key={e.step} onClick={()=>setSelEvent(selEvent===e.step?null:e.step)}
                  style={{flexShrink:0,padding:"8px 12px",borderRadius:8,cursor:"pointer",background:selEvent===e.step?e.color+"22":"#F3F4F6",border:`1.5px solid ${selEvent===e.step?e.color:"#E5E7EB"}`,minWidth:110,transition:"all .15s"}}>
                  <div style={{fontSize:16,marginBottom:2}}>{e.icon}</div>
                  <div style={{fontSize:9,fontWeight:700,color:selEvent===e.step?e.color:GD.dark,marginBottom:2}}>Step {e.step}</div>
                  <div style={{fontSize:10,color:selEvent===e.step?e.color:GD.gray,lineHeight:1.3}}>{e.title}</div>
                  <div style={{display:"flex",gap:3,flexWrap:"wrap",marginTop:4}}>
                    {(e.ids||[]).slice(0,3).map(id=><span key={id} style={{fontSize:7,padding:"1px 4px",borderRadius:4,background:(TD_COLORS[id]||"#374151")+"20",color:TD_COLORS[id]||GD.gray,fontFamily:"monospace",fontWeight:700}}>{id}</span>)}
                  </div>
                </div>
              ))}
            </div>
            {selEvent && (()=>{const e=epcis.find(x=>x.step===selEvent);if(!e)return null;return(
              <div style={{marginTop:10,padding:"14px 16px",borderRadius:8,background:"#0F172A",border:`1px solid ${e.color}44`}}>
                <div style={{fontSize:12,fontWeight:700,color:e.color,marginBottom:8}}>{e.icon} {e.title}</div>
                <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:8}}>
                  {(e.ids||[]).map(id=><span key={id} style={{padding:"3px 8px",borderRadius:6,background:(TD_COLORS[id]||"#374151")+"22",color:TD_COLORS[id]||"#94A3B8",fontSize:10,fontWeight:700,fontFamily:"monospace"}}>TD:{id}</span>)}
                </div>
                <div style={{fontSize:10,color:"#94A3B8",marginBottom:6,fontFamily:"monospace"}}>{e.epcis}</div>
                <div style={{fontSize:9,color:"#64748B",marginBottom:8}}>OT: {e.ot}</div>
                {(e.liveUrns||e.urns||[]).map((u,i)=><div key={i} style={{fontSize:9,fontFamily:"monospace",color:"#22C55E",marginBottom:2,padding:"2px 8px",background:"#111827",borderRadius:3}}>{u}</div>)}
              </div>
            );})()}
          </div>
        )}

        {/* All 13 IDs */}
        {activeTab==="ids14" && (
          <div>
            <div style={{fontSize:16,fontWeight:800,color:GD.dark,marginBottom:4}}>All 13 ThingDaddy IDs — {profile.company}</div>
            <div style={{fontSize:12,color:GD.gray,marginBottom:14}}>Generated live from prefix <strong>{p}</strong> with industry-specific use cases</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(340px,1fr))",gap:10}}>
              {Object.entries(genIds).map(([type,r])=>{
                const useCase = profile.id_use_cases?.[type];
                return (
                  <div key={type} style={{padding:"10px 14px",borderRadius:8,background:GD.white,border:`2px solid ${(TD_COLORS[type]||"#E5E7EB")}22`}}>
                    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}>
                      <span style={{padding:"2px 8px",borderRadius:6,background:TD_COLORS[type]||"#E5E7EB",color:"#fff",fontSize:10,fontWeight:800,fontFamily:"monospace"}}>TD:{type}</span>
                      <span style={{fontSize:10,color:GD.gray}}>{ID_TYPES.find(t=>t.id===type)?.cat||""}</span>
                    </div>
                    <div style={{fontSize:8,fontFamily:"monospace",color:TD_COLORS[type]||GD.teal,wordBreak:"break-all",lineHeight:1.5,padding:"3px 8px",background:`${TD_COLORS[type]||"#E5E7EB"}08`,borderRadius:4,marginBottom:4}}>{r.epc}</div>
                    {useCase && <div style={{fontSize:10,color:GD.gray,lineHeight:1.4,fontStyle:"italic"}}>{useCase}</div>}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* SiLA 2 + ADF */}
        {activeTab==="sila" && (
          <div>
            <div style={{display:"flex",gap:10,marginBottom:14,flexWrap:"wrap"}}>
              <div style={{padding:"8px 14px",borderRadius:6,background:"#F0FDF4",border:"1px solid #22C55E33"}}>
                <div style={{fontSize:9,fontWeight:700,color:GD.gray,marginBottom:2}}>SILA 2 CLASS</div>
                <div style={{fontSize:13,fontFamily:"monospace",color:GD.teal,fontWeight:700}}>{profile.sila_class}</div>
              </div>
              <div style={{padding:"8px 14px",borderRadius:6,background:"#F5F3FF",border:"1px solid #7C3AED33"}}>
                <div style={{fontSize:9,fontWeight:700,color:GD.gray,marginBottom:2}}>ADF SCHEMA</div>
                <div style={{fontSize:13,fontFamily:"monospace",color:GD.purple,fontWeight:700}}>{profile.adf_schema}</div>
              </div>
            </div>
            <div style={{marginBottom:14}}>
              <div style={{fontSize:12,fontWeight:700,color:GD.dark,marginBottom:8}}>SiLA 2 gRPC Driver Code</div>
              <pre style={{background:GD.dark,borderRadius:8,padding:"14px 16px",fontSize:10,color:"#C8E0FF",overflowX:"auto",lineHeight:1.7,maxHeight:320,overflowY:"auto",margin:0}}>{silaCode}</pre>
            </div>
            <div>
              <div style={{fontSize:12,fontWeight:700,color:GD.dark,marginBottom:8}}>Allotrope ADF JSON-LD</div>
              <pre style={{background:GD.dark,borderRadius:8,padding:"14px 16px",fontSize:10,color:"#C8E0FF",overflowX:"auto",lineHeight:1.7,margin:0}}>{adfCode}</pre>
            </div>
          </div>
        )}

        {/* LinkedIn Intelligence */}
        {activeTab==="linkedin" && (
          <div>
            <div style={{marginBottom:20,padding:"16px",background:"linear-gradient(135deg,#EFF6FF,#F0F9FF)",borderRadius:10,border:"1px solid #1D4ED822"}}>
              <div style={{fontSize:14,fontWeight:700,color:"#1D4ED8",marginBottom:8}}>💼 LinkedIn IoT/AI Hiring Signals → Pain Points → ThingDaddy Pitch</div>
              <div style={{fontSize:12,color:GD.gray,lineHeight:1.6}}>These open roles at <strong>{profile.company}</strong> indicate unresolved IoT, AI, and digital transformation challenges that ThingDaddy directly addresses.</div>
            </div>
            <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:20}}>
              {(profile.linkedin_signals||[]).map((s,i)=>(
                <div key={i} style={{padding:"8px 14px",borderRadius:20,background:"#EFF6FF",border:"1px solid #1D4ED844",fontSize:12,fontWeight:500,color:"#1D4ED8",display:"flex",alignItems:"center",gap:6}}>
                  <span style={{fontSize:10}}>🔍</span>{s}
                </div>
              ))}
            </div>
            <div style={{background:GD.offWhite,borderRadius:10,padding:18}}>
              <div style={{fontSize:14,fontWeight:700,color:GD.dark,marginBottom:14}}>ThingDaddy Value Proposition — {profile.sector}</div>
              {(() => {
                const vp = getValueProp(profile.sector);
                return (
                  <div>
                    <div style={{fontSize:14,fontStyle:"italic",color:GD.teal,fontWeight:600,marginBottom:14}}>"{vp.headline}"</div>
                    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:20}}>
                      <div>
                        <div style={{fontSize:10,fontWeight:700,color:GD.red,letterSpacing:".1em",marginBottom:8}}>PAIN POINTS</div>
                        {(vp.pain_points||[]).map((pp,i)=>(
                          <div key={i} style={{display:"flex",gap:8,marginBottom:8,fontSize:12,color:GD.dark}}>
                            <span style={{color:GD.red,flexShrink:0,marginTop:1}}>✗</span>{pp}
                          </div>
                        ))}
                      </div>
                      <div>
                        <div style={{fontSize:10,fontWeight:700,color:GD.green,letterSpacing:".1em",marginBottom:8}}>THINGDADDY SOLVES</div>
                        {(vp.td_solutions||[]).map((s,i)=>(
                          <div key={i} style={{display:"flex",gap:8,marginBottom:8,fontSize:12,color:GD.dark}}>
                            <span style={{color:GD.green,flexShrink:0,marginTop:1}}>✓</span>{s}
                          </div>
                        ))}
                      </div>
                    </div>
                    <div style={{marginTop:16,display:"flex",gap:8,flexWrap:"wrap"}}>
                      {(vp.roi_metrics||[]).map((m,i)=>(
                        <div key={i} style={{padding:"8px 14px",borderRadius:8,background:GD.dark,color:GD.green,fontSize:12,fontWeight:700}}>{m}</div>
                      ))}
                    </div>
                  </div>
                );
              })()}
            </div>
          </div>
        )}

        {/* Platform Map */}
        {activeTab==="platform" && (
          <div>
            <div style={{fontSize:16,fontWeight:800,color:GD.dark,marginBottom:14}}>ThingDaddy Platform Module Map — {profile.company}</div>
            {(profile.platform_map||[]).map((m,i)=>(
              <div key={i} style={{display:"flex",gap:12,padding:"12px 0",borderBottom:"1px solid #F3F4F6",alignItems:"flex-start"}}>
                <div style={{width:180,fontSize:12,fontWeight:700,color:m.color||GD.green,flexShrink:0}}>{m.module}</div>
                <div style={{fontSize:12,color:GD.dark,flex:1,lineHeight:1.6}}>{m.use}</div>
              </div>
            ))}
          </div>
        )}

        {/* MCP Tools */}
        {activeTab==="mcp" && (
          <div>
            <div style={{fontSize:16,fontWeight:800,color:GD.dark,marginBottom:4}}>MCP Server Integration — {profile.company}</div>
            <div style={{fontSize:12,color:GD.gray,marginBottom:14}}>These MCP tools are auto-registered and available to Claude agents, AI assistants, and automation workflows via the ThingDaddy MCP server.</div>
            <div style={{background:"#0F172A",borderRadius:10,padding:16,marginBottom:14}}>
              <div style={{fontSize:10,fontWeight:700,color:"#A78BFA",letterSpacing:".1em",marginBottom:10}}>REGISTERED MCP TOOLS FOR PREFIX {p}</div>
              {[
                `query_assets(prefix="${p}", company="${profile.company}")`,
                `get_epcis_chain(giai="${genIds["GIAI"]?.epc||"urn:epc:id:giai:"+p+".ASSET001"}", events_limit=50)`,
                `lookup_company(prefix="${p}") → full ThingDaddy profile`,
                `generate_ids(prefix="${p}", id_types=["GIAI","CPI","LGTIN","GDTI"])`,
                `get_linkedin_signals(company="${profile.company}", filter="IoT|AI|OT|Digital")`,
                `build_sila_driver(giai="${genIds["GIAI"]?.epc}", class="${profile.sila_class}")`,
                `get_adf_schema(schema="${profile.adf_schema}", instrument="${profile.divisions?.[0]?.products?.[0]||"Asset"}")`,
                `get_value_proposition(sector="${profile.sector}", company="${profile.company}")`,
                ...concat(profile.mcp_tools||[]),
              ].map((t,i)=>(
                <div key={i} style={{padding:"7px 10px",borderRadius:5,background:"#1F2937",border:"1px solid #7C3AED22",marginBottom:5,fontFamily:"monospace",fontSize:11,color:"#C4B5FD"}}>{t}</div>
              ))}
            </div>
            <div style={{padding:"14px 16px",background:GD.tealLt,borderRadius:8,border:"1px solid #00A09C33"}}>
              <div style={{fontSize:12,fontWeight:700,color:GD.teal,marginBottom:6}}>How to connect</div>
              <pre style={{fontSize:11,color:GD.ink||GD.dark,fontFamily:"monospace",margin:0,whiteSpace:"pre-wrap"}}>{`# Add to Claude Desktop config (claude_desktop_config.json):
{
  "mcpServers": {
    "thingdaddy": {
      "url": "https://mcp.thingdaddy.com/sse",
      "headers": { "X-Prefix": "${p}" }
    }
  }
}`}</pre>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}




function SemanticGraphModule() {
  const { ids, prefix, provenance, parties } = useIDs();
  // Build live anchor nodes from the provenance ledger — every generated ID, with lineage
  const liveAnchors = React.useMemo(() => {
    const byEpc = {};
    (provenance||[]).forEach(p => {
      if (!p.epc || byEpc[p.epc]) return;
      byEpc[p.epc] = {
        anchor_type: p.type,
        anchor_id: p.epc,
        anchor_label: `${p.company || p.prefix || "TD"} · ${p.type}`,
        industry: "Live / Provenance",
        live: true,
        provenance: { created: p.ts, source: p.source, prefix: p.prefix, company: p.company, gs1: p.gs1 },
        associations: [],
      };
    });
    return Object.values(byEpc);
  }, [provenance]);
  const [anchors,     setAnchors]     = useState(SEED_ASSOCIATIONS);
  // ── Loop-B import: render the exact edges the agent fleet produced ──────────
  // Paste loopB_seed_associations.json (from thingdaddy_agent_fleet_loopB.py) or
  // set window.TD_LOOPB_GRAPH = [...]. Loop-B anchors merge on top of the seed,
  // carrying each edge's verified/candidate/exception state and source.
  const loopBAnchors = React.useMemo(() => {
    try {
      const g = (typeof window !== "undefined" && window.TD_LOOPB_GRAPH) || null;
      if (!Array.isArray(g)) return [];
      return g.map(a => ({ ...a, industry: a.industry || "Loop-B / Relationship", loopB: true }));
    } catch (_e) { return []; }
  }, []);
  // Merge live provenance nodes on top of seed associations
  const allAnchors = React.useMemo(() => [...liveAnchors, ...loopBAnchors, ...anchors], [liveAnchors, loopBAnchors, anchors]);

  // ── Viewer lens — each user has scoped visibility into the graph ─────────────
  // e.g. KPMG auditing Thermo Fisher sees ONLY Thermo Fisher's IDs + audit provenance.
  const VIEWERS = [
    {id:"all",     label:"Platform (all)",      org:null,                          role:"Full graph",          color:GD.green},
    {id:"kpmg_tf", label:"KPMG → Thermo Fisher", org:"Thermo Fisher", scope:"0085126", role:"External Auditor", color:"#00338D"},
    {id:"ey_pfizer",label:"EY → Pfizer",        org:"Pfizer",        scope:"0030034", role:"External Auditor", color:"#FFE600", text:"#2E2E38"},
    {id:"tf_self", label:"Thermo Fisher (owner)",org:"Thermo Fisher", scope:"0085126", role:"Asset Owner",      color:"#E03C31"},
    {id:"pfizer_self",label:"Pfizer (owner)",   org:"Pfizer",        scope:"0030034", role:"Asset Owner",      color:"#0093D0"},
    {id:"ai_claude", label:"🤖 AI Model (Claude)", org:null,           role:"AI Consumer",     color:"#D4A373", redact:true},
  ];
  // Redact private values for AI/model consumers — structure stays, secrets masked
  const redactURN = (urn, type) => {
    if (!urn) return urn;
    // Keep the scheme + ID type, mask company prefix + serial
    // urn:epc:id:giai:0085126.QS7-SN2024-0001  →  urn:epc:id:giai:●●●●●●●.●●●●●●●●
    return urn.replace(/(urn:epc:[^:]+:[a-z]+:)(.+)/i, (m, head, tail) =>
      head + tail.replace(/[A-Za-z0-9]/g, "●"));
  };
  const [viewer, setViewer] = useState(VIEWERS[0]);

  // Scope anchors + provenance to the current viewer's organization/prefix
  const scopedAnchors = React.useMemo(() => {
    if (!viewer.scope) return allAnchors;
    return allAnchors.filter(a =>
      (a.anchor_id||"").includes(viewer.scope) ||
      (a.anchor_label||"").toLowerCase().includes((viewer.org||"").toLowerCase()) ||
      (a.provenance?.company||"").toLowerCase().includes((viewer.org||"").toLowerCase()) ||
      (a.provenance?.prefix||"").includes(viewer.scope)
    );
  }, [allAnchors, viewer]);

  const scopedProvenance = React.useMemo(() => {
    if (!viewer.scope) return (provenance||[]);
    return (provenance||[]).filter(p =>
      (p.epc||"").includes(viewer.scope) ||
      (p.prefix||"").includes(viewer.scope) ||
      (p.company||"").toLowerCase().includes((viewer.org||"").toLowerCase())
    );
  }, [provenance, viewer]);
  const [selAnchor,   setSelAnchor]   = useState(SEED_ASSOCIATIONS[0]);
  const [addMode,     setAddMode]     = useState(false);
  const [aiLoading,   setAiLoading]   = useState(false);
  const [aiLog,       setAiLog]       = useState([]);
  const [newAnchor,   setNewAnchor]   = useState({type:"GIAI",id:"",label:"",industry:"Life Sciences"});
  const [filterType,  setFilterType]  = useState("All");
  const [view,        setView]        = useState("graph"); // graph | matrix | sparql

  const addLog = (msg,color="#94A3B8") =>
    setAiLog(prev=>[{msg,color,t:new Date().toLocaleTimeString()},...prev].slice(0,40));

  // AI-powered association discovery
  const discoverAssociations = async (anchor) => {
    setAiLoading(true);
    addLog(`🤖 Discovering associations for ${anchor.anchor_label}...`,"#60A5FA");
    try {
      const resp = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:1500,
          messages:[{role:"user",content:
            `You are a ThingDaddy semantic graph engine. Discover ALL associated IDs for this asset:\n\n` +
            `Anchor: ${anchor.anchor_label}\n` +
            `ID Type: ${anchor.anchor_type}\n` +
            `ThingDaddy ID: ${anchor.anchor_id}\n` +
            `Industry: ${anchor.industry}\n\n` +
            `Find ALL associated things:\n` +
            `1. User manuals, datasheets, IFUs, SDS, certificates (→ GDTI)\n` +
            `2. Consumables, reagents, spare parts the device uses (→ GTIN)\n` +
            `3. Components/sub-assemblies installed inside it (→ CPI)\n` +
            `4. Lot numbers for consumables (→ LGTIN)\n` +
            `5. Model family / product line (→ GMN)\n` +
            `6. Owner company + locations (→ PGLN, GLN)\n` +
            `7. SiLA 2 driver spec + ADF schema (→ GDTI)\n` +
            `8. Protocols / SOPs it runs (→ GDTI)\n` +
            `9. Service contracts / warranties (→ GCN)\n\n` +
            `For each association use the ThingDaddy prefix from the anchor ID.\n` +
            `Return ONLY JSON array:\n` +
            `[{"rel":"HAS_MANUAL","type":"GDTI","id":"urn:epc:id:gdti:PREFIX.DOC-XXX.2024","label":"descriptive name","confirmed":true,"url":"source url if known","notes":""}]`
          }]
        })
      });
      const data = await resp.json();
      const raw  = (data.content?.[0]?.text||"[]").replace(/```json|```/g,"").trim();
      const found = JSON.parse(raw);
      addLog(`✅ Found ${found.length} associations`,"#22C55E");
      found.forEach(a=>addLog(`  ${a.rel} → ${a.type}: ${a.label}`,"#94A3B8"));
      // Merge with existing, dedup by id
      setAnchors(prev=>prev.map(a=>{
        if(a.anchor_id!==anchor.anchor_id) return a;
        const existing = new Set(a.associations.map(x=>x.id));
        const newOnes  = found.filter(f=>!existing.has(f.id));
        return {...a, associations:[...a.associations,...newOnes]};
      }));
      setSelAnchor(prev=>({...prev,
        associations:[...prev.associations,...found.filter(f=>!new Set(prev.associations.map(x=>x.id)).has(f.id))]
      }));
    } catch(e){ addLog(`⚠️ ${e.message}`,"#F87171"); }
    setAiLoading(false);
  };

  // Register new anchor and discover its associations
  const registerAnchor = async () => {
    if(!newAnchor.id||!newAnchor.label) return;
    const anchor = {
      anchor_type:  newAnchor.type,
      anchor_id:    newAnchor.id,
      anchor_label: newAnchor.label,
      industry:     newAnchor.industry,
      associations: [],
    };
    setAnchors(prev=>[anchor,...prev]);
    setSelAnchor(anchor);
    setAddMode(false);
    await discoverAssociations(anchor);
  };

  const assocByType = (sel) => {
    if(!sel) return {};
    const grouped = {};
    (sel.associations||[]).forEach(a=>{
      if(!grouped[a.type]) grouped[a.type]=[];
      grouped[a.type].push(a);
    });
    return grouped;
  };

  const filtered = selAnchor ? (filterType==="All"
    ? selAnchor.associations
    : selAnchor.associations.filter(a=>a.type===filterType)) : [];

  const grouped = assocByType(selAnchor);
  // Step 2: the AI Graph now reads through the In-Context engine. We register the
  // selected anchor as the canonical and map each association as an edge, then
  // resolve it back — proving the graph is a view over TDIncontext, not static data.
  let tdResolved = null;
  try {
    if (selAnchor && selAnchor.anchor_id) {
      const reg = TDIncontext.createRegistry();
      reg.registerThing({ id: selAnchor.anchor_id, type: selAnchor.anchor_type, party: TDIncontext.partyFromEpc(selAnchor.anchor_id), rules: [] });
      (selAnchor.associations||[]).forEach(a => reg.mapId({ fromNamespace: a.type||"gs1", fromId: a.id, rel: a.rel, toCanonical: selAnchor.anchor_id, assertedBy: TDIncontext.partyFromEpc(a.id), source: a.label }));
      tdResolved = reg.resolveThingContext(selAnchor.anchor_id);
    }
  } catch (_e) { tdResolved = null; }
  const typeOrder = ["PGLN","GLN","GDTI","GTIN","LGTIN","CPI","GMN","GSRN","GIAI","GCN","SSCC"];
  const narrow = (typeof window !== "undefined" ? window.innerWidth : 1024) < 860;

  return (
    <div style={{fontFamily:"'Inter',system-ui,sans-serif",background:"#030712",minHeight:"100vh",color:"#fff"}}>
      {(()=>{ try { return <TDArtifactPanel icon="🤖" title="AI Graph — MCP server + API" sub="the six patented APIs, agent-ready"
        items={[
          {label:"MCP manifest (6 tools)",filename:"thingdaddy_mcp.json",gen:tdMcpManifest},
          {label:"OpenAPI 3.1 spec",filename:"thingdaddy_openapi.json",gen:tdOpenApi},
          {label:"▶ Live call (in-browser)",filename:"resolve_response.json",gen:tdApiTryIt,note:"Runs the embedded engine live."},
        ]}/>; } catch(_e){ return null; } })()}
      {/* ── Viewer lens selector — scoped visibility per user/org ── */}
      <div style={{margin:"0 0 12px",padding:"12px 14px",borderRadius:10,background:GD.white,border:"1px solid #E5E7EB"}}>
        <div style={{fontSize:10,fontWeight:700,color:GD.gray,letterSpacing:".08em",marginBottom:8}}>👁️ VIEWING AS — each user sees only their scoped graph</div>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          {VIEWERS.map(vw=>{
            const sel = viewer.id===vw.id;
            return (
              <button key={vw.id} onClick={()=>setViewer(vw)}
                style={{padding:"6px 12px",borderRadius:8,cursor:"pointer",fontFamily:"inherit",fontSize:11,fontWeight:700,
                  border:`1.5px solid ${sel?vw.color:"#E5E7EB"}`,
                  background:sel?vw.color:GD.white,color:sel?(vw.text||"#fff"):GD.gray}}>
                {vw.label}
              </button>
            );
          })}
        </div>
        {(viewer.scope || viewer.redact) && (
          <div style={{marginTop:10,padding:"8px 12px",borderRadius:6,background:viewer.color+(viewer.text?"22":"15"),border:`1px solid ${viewer.color}44`}}>
            <div style={{fontSize:11,fontWeight:700,color:viewer.text||viewer.color}}>
              {viewer.role}: {viewer.label}
            </div>
            <div style={{fontSize:10,color:GD.gray,marginTop:2,lineHeight:1.5}}>
              {viewer.redact
                ? "AI models see the graph STRUCTURE — ID types, counts, relationships, and event patterns — while company names, full URNs, and serials are redacted (●●●). Reasoning and analytics without exposing private identity data."
                : viewer.role==="External Auditor"
                ? `${viewer.label.split(" → ")[0]} sees ONLY ${viewer.org}'s IDs and events (prefix ${viewer.scope}). Every ID it touches creates real-time audit provenance — no visibility into other companies.`
                : `${viewer.org} sees only its own assets (prefix ${viewer.scope}) — full ownership view of its IDs and lineage.`}
            </div>
            <div style={{fontSize:9,color:viewer.color,fontWeight:700,marginTop:6}}>
              Scoped to {scopedAnchors.length} graph node{scopedAnchors.length===1?"":"s"} · {scopedProvenance.length} provenance event{scopedProvenance.length===1?"":"s"}
            </div>
          </div>
        )}
      </div>

      {/* Provenance ledger summary — every ID in context flows into this graph */}
      {(scopedProvenance||[]).length > 0 && (
        <div style={{margin:"0 0 14px",padding:"12px 14px",borderRadius:10,background:"#0F172A",border:`1px solid ${GD.green}33`}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:8}}>
            <div>
              <div style={{fontSize:10,fontWeight:700,color:GD.green,letterSpacing:".1em"}}>🔗 LIVE PROVENANCE LEDGER</div>
              <div style={{fontSize:11,color:"rgba(255,255,255,.6)",marginTop:2}}>
                {scopedProvenance.length} ID event{provenance.length===1?"":"s"} captured in context — every generated ThingDaddy ID is a graph node with full lineage
              </div>
            </div>
            <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
              {Object.entries((scopedProvenance||[]).reduce((a,p)=>{a[p.type]=(a[p.type]||0)+1;return a;},{})).slice(0,8).map(([t,n])=>(
                <span key={t} style={{fontSize:9,fontWeight:700,fontFamily:"monospace",padding:"2px 7px",borderRadius:4,background:GD.green+"22",color:"#22C55E"}}>{t}·{n}</span>
              ))}
            </div>
          </div>
          {/* Most recent events */}
          <div style={{marginTop:10,display:"grid",gap:3,maxHeight:120,overflowY:"auto"}}>
            {scopedProvenance.slice(0,6).map((p,i)=>(
              <div key={i} style={{fontSize:8,fontFamily:"monospace",color:"rgba(255,255,255,.5)",lineHeight:1.5}}>
                <span style={{color:"#475569"}}>{(p.ts||"").slice(11,19)}</span>{" "}
                <span style={{color:GD.green}}>{p.type}</span>{" "}
                <span style={{color:"#94A3B8"}}>{viewer.redact ? redactURN(p.epc, p.type) : p.epc}</span>
                {p.use && <span style={{color:"#A78BFA"}}>{"  · "+p.use}</span>}
                {p.company && !viewer.redact && <span style={{color:"#F59E0B"}}>{"  · "+p.company}</span>}
                <span style={{color:"#475569"}}>{"  ("+(p.source||"")+")"}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* HEADER */}
      <div style={{background:"#030712",borderBottom:"1px solid #1F2937",padding:"14px 24px"}}>
        <div style={{fontSize:9,fontWeight:700,color:"#4B5563",letterSpacing:".15em",marginBottom:4}}>
          THINGDADDY PLATFORM · THE DIGITAL CIVILIZATION NETWORK
        </div>
        <div style={{display:"flex",alignItems:"center",gap:14,flexWrap:"wrap"}}>
          <div>
            <div style={{fontSize:22,fontWeight:900,color:"#fff"}}>
              🕸️ TD:GRAPH — Semantic Association Engine
            </div>
            <div style={{fontSize:11,color:"#4B5563"}}>
              Every ID connected to its associated things · 79 edge types · AI discovery · SPARQL queries
            </div>
          </div>
          <div style={{marginLeft:"auto",display:"flex",gap:8}}>
            {[["graph","🕸️","Graph"],["matrix","📊","Matrix"],["sparql","🔍","Query"]].map(([v,i,l])=>(
              <button key={v} onClick={()=>setView(v)}
                style={{padding:"7px 14px",borderRadius:8,border:"none",cursor:"pointer",
                  fontFamily:"inherit",fontSize:11,fontWeight:view===v?700:400,
                  background:view===v?"#3DB54A22":"#111827",
                  color:view===v?"#3DB54A":"#4B5563",
                  outline:view===v?"1.5px solid #3DB54A":"1.5px solid #1F2937"}}>
                {i} {l}
              </button>
            ))}
            <button onClick={()=>setAddMode(true)}
              style={{padding:"7px 16px",borderRadius:8,border:"none",cursor:"pointer",
                fontFamily:"inherit",fontSize:11,fontWeight:700,background:"#3DB54A",color:"#fff"}}>
              + New Asset
            </button>
          </div>
        </div>
      </div>

      <div style={narrow
        ? {display:"flex",flexDirection:"column"}
        : {display:"grid",gridTemplateColumns:"280px minmax(260px,1fr) 300px",height:"calc(100vh - 100px)",overflowX:"auto"}}>

        {/* LEFT: Anchor list */}
        <div style={{borderRight:"1px solid #1F2937",overflowY:"auto"}}>
          <div style={{padding:"10px 14px",background:"#0F172A",
            borderBottom:"1px solid #1F2937",fontSize:10,fontWeight:700,color:"#4B5563"}}>
            REGISTERED ASSETS
          </div>
          {scopedAnchors.map((a,i)=>{
            const isSel = selAnchor?.anchor_id===a.anchor_id;
            return (
              <div key={i} onClick={()=>setSelAnchor(a)}
                style={{padding:"10px 14px",cursor:"pointer",
                  borderBottom:"1px solid #1F2937",
                  background:isSel?"#111827":"transparent",
                  borderLeft:`3px solid ${isSel?(TD_EDGE_COLORS[a.anchor_type]||"#3DB54A"):"transparent"}`}}>
                <div style={{display:"flex",gap:6,alignItems:"center",marginBottom:4}}>
                  <span style={{fontSize:9,fontWeight:700,padding:"1px 5px",borderRadius:4,
                    background:(TD_EDGE_COLORS[a.anchor_type]||"#374151")+"22",
                    color:TD_EDGE_COLORS[a.anchor_type]||"#94A3B8"}}>
                    TD:{a.anchor_type}
                  </span>
                  <span style={{fontSize:9,color:"#4B5563"}}>{a.industry}</span>
                </div>
                <div style={{fontSize:12,fontWeight:700,color:isSel?"#fff":"#E2E8F0",
                  lineHeight:1.3,marginBottom:4}}>{viewer.redact ? (a.anchor_type + " · [private]") : a.anchor_label}</div>
                <div style={{fontSize:8,fontFamily:"monospace",color:"#374151",
                  wordBreak:"break-all",lineHeight:1.4,marginBottom:4}}>
                  {viewer.redact ? redactURN(a.anchor_id, a.anchor_type) : a.anchor_id}
                </div>
                <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
                  {Object.entries(assocByType(a)).map(([type,items])=>(
                    <span key={type} style={{fontSize:8,padding:"1px 5px",borderRadius:4,fontWeight:700,
                      background:(TD_EDGE_COLORS[type]||"#374151")+"22",
                      color:TD_EDGE_COLORS[type]||"#94A3B8"}}>
                      {type}:{items.length}
                    </span>
                  ))}
                </div>
              </div>
            );
          })}

          {/* Add new anchor panel */}
          {addMode&&(
            <div style={{padding:"12px 14px",borderTop:"1px solid #1F2937",background:"#111827"}}>
              <div style={{fontSize:11,fontWeight:700,color:"#fff",marginBottom:10}}>
                Register New Asset
              </div>
              {[["ID Type","type","select"],["ThingDaddy ID","id","text"],
                ["Label","label","text"],["Industry","industry","select"]].map(([label,key,type])=>(
                <div key={key} style={{marginBottom:8}}>
                  <div style={{fontSize:9,color:"#4B5563",marginBottom:3}}>{label}</div>
                  {type==="select" ? (
                    <select value={newAnchor[key]}
                      onChange={e=>setNewAnchor(p=>({...p,[key]:e.target.value}))}
                      style={{width:"100%",padding:"6px 10px",borderRadius:6,background:"#0F172A",
                        border:"1px solid #374151",color:"#E2E8F0",fontFamily:"inherit",
                        fontSize:11,outline:"none",boxSizing:"border-box"}}>
                      {key==="type"
                        ? ["GIAI","GTIN","GDTI","LGTIN","PGLN","CPI","GMN","GSRN"].map(t=>(
                            <option key={t} value={t}>{t}</option>))
                        : Object.keys(INDUSTRY_PROTOCOLS||{}).concat(["Other"]).map(ind=>(
                            <option key={ind} value={ind}>{ind}</option>))
                      }
                    </select>
                  ) : (
                    <input value={newAnchor[key]}
                      onChange={e=>setNewAnchor(p=>({...p,[key]:e.target.value}))}
                      placeholder={key==="id"?"urn:epc:id:giai:0085126.QS7-001":"Descriptive name"}
                      style={{width:"100%",padding:"6px 10px",borderRadius:6,background:"#0F172A",
                        border:"1px solid #374151",color:"#E2E8F0",fontFamily:"monospace",
                        fontSize:10,outline:"none",boxSizing:"border-box"}}/>
                  )}
                </div>
              ))}
              <div style={{display:"flex",gap:6}}>
                <button onClick={registerAnchor}
                  style={{flex:1,padding:"8px",borderRadius:6,border:"none",cursor:"pointer",
                    background:"#3DB54A",color:"#fff",fontFamily:"inherit",fontSize:11,fontWeight:700}}>
                  🤖 Register + Discover
                </button>
                <button onClick={()=>setAddMode(false)}
                  style={{padding:"8px 12px",borderRadius:6,border:"1px solid #374151",
                    background:"transparent",color:"#6B7280",cursor:"pointer",fontFamily:"inherit",fontSize:11}}>
                  ✕
                </button>
              </div>
            </div>
          )}
        </div>

        {/* CENTRE: Association view */}
        <div style={{overflowY:"auto",padding:"16px 20px"}}>
          {selAnchor&&(
            <>
              {/* Anchor card */}
              <div style={{background:"#111827",borderRadius:12,padding:"14px 18px",
                border:`2px solid ${TD_EDGE_COLORS[selAnchor.anchor_type]||"#374151"}`,
                marginBottom:16,display:"flex",gap:14,alignItems:"flex-start"}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:6,flexWrap:"wrap",rowGap:4}}>
                    <span style={{fontSize:11,fontWeight:800,padding:"2px 10px",borderRadius:20,
                      background:(TD_EDGE_COLORS[selAnchor.anchor_type]||"#374151")+"22",
                      color:TD_EDGE_COLORS[selAnchor.anchor_type]||"#94A3B8"}}>
                      TD:{selAnchor.anchor_type}
                    </span>
                    <span style={{fontSize:10,color:"#4B5563"}}>{selAnchor.industry}</span>
                    <span style={{marginLeft:"auto",fontSize:10,fontWeight:700,
                      color:"#3DB54A",background:"rgba(61,181,74,.12)",padding:"2px 8px",borderRadius:8}}>
                      {selAnchor.associations.length} associations
                    </span>
                  </div>
                  <div style={{fontSize:15,fontWeight:900,color:"#fff",marginBottom:4,overflowWrap:"break-word"}}>
                    {selAnchor.anchor_label}
                  </div>
                  <div style={{fontSize:9,fontFamily:"monospace",color:"#4B5563",wordBreak:"break-all"}}>
                    {selAnchor.anchor_id}
                  </div>
                  {tdResolved?.ok && (
                    <div style={{fontSize:9,fontWeight:700,color:"#3DB54A",marginTop:6}}>
                      &#10003; In-Context engine &#183; {tdResolved.aliases.length} edge{tdResolved.aliases.length===1?"":"s"} resolved to canonical
                    </div>
                  )}
                </div>
                <button onClick={()=>discoverAssociations(selAnchor)} disabled={aiLoading}
                  style={{padding:"8px 16px",borderRadius:8,border:"none",cursor:"pointer",
                    fontFamily:"inherit",fontSize:11,fontWeight:700,flexShrink:0,
                    background:aiLoading?"#1F2937":"#7C3AED",
                    color:aiLoading?"#4B5563":"#fff"}}>
                  {aiLoading?"🤖 Discovering...":"🤖 Discover More"}
                </button>
              </div>

              {/* Step 3 — multi-namespace resolution chain: one thing, many names, one canonical */}
              {(() => {
                try {
                  const canonical = selAnchor.anchor_id;
                  const serial = ((canonical.split(".").pop()) || "SN").replace(/[^A-Za-z0-9]/g, "");
                  const demo = TDIncontext.createRegistry();
                  demo.registerThing({ id: canonical, type: selAnchor.anchor_type, party: TDIncontext.partyFromEpc(canonical), rules: [] });
                  const chain = [
                    { ns: "Operator \u00b7 Pfizer", color: "#3DB54A", id: "urn:epc:id:giai:0030034." + serial, rel: "operatedAs" },
                    { ns: "AWS IoT", color: "#F59E0B", id: "arn:aws:iot:us-east-1:pfizer:thing/" + serial, rel: "runsOn" },
                    { ns: "SiLA 2 server", color: GD.teal, id: "urn:sila:server:" + serial, rel: "exposedBy" },
                    { ns: "Allotrope ADF", color: GD.purple, id: "AFO:equipment/" + serial, rel: "recordedBy" },
                  ];
                  chain.forEach(c => demo.mapId({ fromNamespace: c.ns, fromId: c.id, rel: c.rel, toCanonical: canonical, assertedBy: "registry", source: c.ns }));
                  const allOk = chain.every(c => { const r = demo.resolveThingContext(c.id); return r.ok && r.canonical === canonical; });
                  return (
                    <div style={{background:"#0B1220",border:"1px solid #1F2937",borderRadius:12,padding:"12px 14px",marginBottom:14}}>
                      <div style={{fontSize:10,fontWeight:800,letterSpacing:".06em",color:"#94A3B8",marginBottom:10}}>
                        🔗 ONE THING &#183; MANY NAMES — every namespace resolves to one In-Context ID
                      </div>
                      {chain.map((c,ci) => (
                        <div key={ci} style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginBottom:7}}>
                          <span style={{fontSize:9,fontWeight:800,padding:"2px 8px",borderRadius:12,background:c.color+"22",color:c.color,flexShrink:0}}>{c.ns}</span>
                          <span style={{fontSize:9,fontFamily:"monospace",color:"#64748B",wordBreak:"break-all",flex:1,minWidth:0}}>{c.id}</span>
                          <span style={{fontSize:11,fontWeight:800,color:"#3DB54A",flexShrink:0}}>&#8594; &#10003;</span>
                        </div>
                      ))}
                      <div style={{fontSize:9,fontFamily:"monospace",color:"#fff",marginTop:8,paddingTop:8,borderTop:"1px solid #1F2937",wordBreak:"break-all"}}>
                        canonical In-Context ID &#8594; {canonical}
                      </div>
                      {allOk && (
                        <div style={{fontSize:9,fontWeight:700,color:"#3DB54A",marginTop:6}}>
                          &#10003; {chain.length} namespaces resolve O(1) to the same canonical, which carries the protocol &amp; manual (GDTI)
                        </div>
                      )}
                    </div>
                  );
                } catch (_e) { return null; }
              })()}

              {/* Step 4 — rules & warranty bound to the In-Context ID (toolActionPolicy) */}
              {(() => {
                try {
                  const canonical = selAnchor.anchor_id;
                  const serial = ((canonical.split(".").pop()) || "SN").replace(/[^A-Za-z0-9]/g, "");
                  const party = TDIncontext.partyFromEpc(canonical) || "0000000";
                  const reg = TDIncontext.createRegistry();
                  reg.registerThing({ id: canonical, type: selAnchor.anchor_type, party,
                    manual: "urn:epc:id:gdti:" + party + ".MANUAL." + serial,
                    rules: [{ kind: "authorized-consumable", id: "R-OEM-CONSUMABLES", allow: ["urn:epc:id:sgtin:" + party + ".*"], warrantyImpact: true }] });
                  reg.mapId({ fromNamespace: "Operator", fromId: "urn:epc:id:giai:0030034." + serial, rel: "operatedAs", toCanonical: canonical, assertedBy: "0030034" });
                  reg.subscribe(party, "human");
                  reg.subscribe("0030034", "agent");
                  const okId = "urn:epc:id:sgtin:" + party + ".AUTHREAGENT.1";
                  const badId = "urn:epc:id:sgtin:0099999.KNOCKOFF.1";
                  const allow = reg.toolActionPolicy({ subjectId: canonical, by: "0030034", source: "lab", action: { type: "use-consumable", consumableId: okId } });
                  const deny = reg.toolActionPolicy({ subjectId: canonical, by: "0030034", source: "lab", action: { type: "use-consumable", consumableId: badId } });
                  return (
                    <div style={{background:"#0B1220",border:"1px solid #1F2937",borderRadius:12,padding:"12px 14px",marginBottom:14}}>
                      <div style={{fontSize:10,fontWeight:800,letterSpacing:".06em",color:"#94A3B8",marginBottom:4}}>
                        🛡️ RULES &amp; WARRANTY — bound to the In-Context ID
                      </div>
                      <div style={{fontSize:9,color:"#64748B",marginBottom:10}}>
                        Manual (GDTI) defines the rule · the engine enforces it on every action (toolActionPolicy)
                      </div>
                      <div style={{fontSize:9,fontFamily:"monospace",color:"#94A3B8",marginBottom:10,wordBreak:"break-all"}}>
                        rule R-OEM-CONSUMABLES &#183; allow urn:epc:id:sgtin:{party}.* &#183; warranty-impacting
                      </div>
                      <div style={{background:"#0F1E12",border:"1px solid #14532D",borderRadius:8,padding:"8px 10px",marginBottom:8}}>
                        <div style={{fontSize:10,fontWeight:800,color:"#3DB54A"}}>&#10003; ALLOWED — OEM-authorized consumable</div>
                        <div style={{fontSize:9,fontFamily:"monospace",color:"#64748B",wordBreak:"break-all",marginTop:3}}>{okId}</div>
                        <div style={{fontSize:9,color:"#64748B",marginTop:3}}>{allow.allowed ? "action recorded as a provenanced event" : "—"}</div>
                      </div>
                      <div style={{background:"#1E0F0F",border:"1px solid #7F1D1D",borderRadius:8,padding:"8px 10px"}}>
                        <div style={{fontSize:10,fontWeight:800,color:"#F87171"}}>&#10007; DENIED — third-party consumable</div>
                        <div style={{fontSize:9,fontFamily:"monospace",color:"#64748B",wordBreak:"break-all",marginTop:3}}>{badId}</div>
                        <div style={{fontSize:9,color:"#FCA5A5",marginTop:4}}>{deny.reason}</div>
                        <div style={{display:"flex",gap:8,flexWrap:"wrap",marginTop:6}}>
                          {deny.warrantyVoided && <span style={{fontSize:9,fontWeight:800,padding:"2px 8px",borderRadius:12,background:"#F59E0B22",color:"#F59E0B"}}>⚠ WARRANTY VOIDED</span>}
                          <span style={{fontSize:9,fontWeight:800,padding:"2px 8px",borderRadius:12,background:"#7C3AED22",color:"#A78BFA"}}>🔔 {deny.notified} parties notified</span>
                        </div>
                      </div>
                    </div>
                  );
                } catch (_e) { return null; }
              })()}

              {/* Hazard & MSDS — document-driven hazard class + combination assessment */}
              {(() => {
                try {
                  const canonical = selAnchor.anchor_id;
                  const party = TDIncontext.partyFromEpc(canonical) || "0000000";
                  const hazColor = { none:"#64748B", flammable:"#F59E0B", oxidizer:"#F87171", toxic:"#A78BFA", corrosive:"#22D3EE" };
                  const hazLabel = { none:"non-hazardous", flammable:"FLAMMABLE", oxidizer:"OXIDIZER", toxic:"TOXIC", corrosive:"CORROSIVE" };
                  const materials = [
                    { key:"mastermix", name:"PCR Master Mix", hazard:"none" },
                    { key:"ethanol", name:"Ethanol 70% (clean)", hazard:"flammable" },
                    { key:"bleach", name:"Hypochlorite (decon)", hazard:"oxidizer" },
                    { key:"lysis", name:"Guanidinium lysis buffer", hazard:"toxic" },
                  ].map((m,ix) => ({ ...m, msds:"urn:epc:id:gdti:" + party + ".MSDS." + (ix+1) }));
                  const incompatible = [
                    { a:"flammable", b:"oxidizer", reason:"flammable + oxidizer \u2192 fire / explosion risk", response:"isolate \u00b7 ventilate \u00b7 notify EHS" },
                    { a:"oxidizer", b:"toxic", reason:"oxidizer + toxic reagent \u2192 may release toxic gas", response:"do not combine \u00b7 evacuate \u00b7 notify EHS + safety officer" },
                  ];
                  const reg = TDIncontext.createRegistry();
                  reg.registerThing({ id:canonical, type:selAnchor.anchor_type, party, rules:[{ kind:"hazard-incompatibility", id:"R-MSDS", incompatible, warrantyImpact:true }] });
                  reg.subscribe(party, "human");
                  reg.subscribe(canonical, "ehs-safety");
                  const byKey = {}; materials.forEach(m => { byKey[m.key] = m; });
                  const safe = reg.toolActionPolicy({ subjectId:canonical, by:party, action:{ type:"combine-materials", items:[byKey.mastermix, byKey.ethanol] } });
                  const danger = reg.toolActionPolicy({ subjectId:canonical, by:party, action:{ type:"combine-materials", items:[byKey.bleach, byKey.lysis] } });
                  return (
                    <div style={{background:"#0B1220",border:"1px solid #1F2937",borderRadius:12,padding:"12px 14px",marginBottom:14}}>
                      <div style={{fontSize:10,fontWeight:800,letterSpacing:".06em",color:"#94A3B8",marginBottom:4}}>
                        🧪 HAZARD &amp; MSDS — documents carry the rules
                      </div>
                      <div style={{fontSize:9,color:"#64748B",marginBottom:10}}>
                        Each material has an MSDS (GDTI) declaring its hazard class · the engine checks every combination
                      </div>
                      {materials.map((m,mi) => (
                        <div key={mi} style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginBottom:6}}>
                          <span style={{fontSize:10,fontWeight:700,color:"#E2E8F0",flexShrink:0}}>{m.name}</span>
                          <span style={{fontSize:9,fontFamily:"monospace",color:"#475569",wordBreak:"break-all",flex:1,minWidth:0}}>{m.msds}</span>
                          <span style={{fontSize:9,fontWeight:800,padding:"2px 8px",borderRadius:12,flexShrink:0,background:hazColor[m.hazard]+"22",color:hazColor[m.hazard]}}>
                            {(m.hazard==="none" ? "✓ " : "⚠ ") + hazLabel[m.hazard]}
                          </span>
                        </div>
                      ))}
                      <div style={{background:"#0F1E12",border:"1px solid #14532D",borderRadius:8,padding:"8px 10px",marginTop:8,marginBottom:8}}>
                        <div style={{fontSize:10,fontWeight:800,color:"#3DB54A"}}>&#10003; SAFE TO COMBINE</div>
                        <div style={{fontSize:9,color:"#94A3B8",marginTop:3}}>{byKey.mastermix.name} + {byKey.ethanol.name}</div>
                        <div style={{fontSize:9,color:"#64748B",marginTop:3}}>{safe.allowed ? "no incompatible pair · combination recorded as an event" : "—"}</div>
                      </div>
                      <div style={{background:"#1E0F0F",border:"1px solid #7F1D1D",borderRadius:8,padding:"8px 10px"}}>
                        <div style={{fontSize:10,fontWeight:800,color:"#F87171"}}>&#10007; HAZARDOUS COMBINATION</div>
                        <div style={{fontSize:9,color:"#94A3B8",marginTop:3}}>{byKey.bleach.name} + {byKey.lysis.name}</div>
                        <div style={{fontSize:9,color:"#FCA5A5",marginTop:4,wordBreak:"break-word"}}>{danger.reason}</div>
                        <div style={{display:"flex",gap:8,flexWrap:"wrap",marginTop:6}}>
                          {danger.warrantyVoided && <span style={{fontSize:9,fontWeight:800,padding:"2px 8px",borderRadius:12,background:"#F59E0B22",color:"#F59E0B"}}>⚠ SAFETY BREAK LOGGED</span>}
                          <span style={{fontSize:9,fontWeight:800,padding:"2px 8px",borderRadius:12,background:"#7C3AED22",color:"#A78BFA"}}>🔔 {danger.notified} parties notified</span>
                        </div>
                      </div>
                    </div>
                  );
                } catch (_e) { return null; }
              })()}

              {/* Type filter */}
              <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:14}}>
                <button key="All" onClick={()=>setFilterType("All")}
                  style={{padding:"5px 12px",borderRadius:16,cursor:"pointer",border:"none",
                    fontFamily:"inherit",fontSize:10,fontWeight:filterType==="All"?700:400,
                    background:filterType==="All"?"#374151":"#111827",
                    color:filterType==="All"?"#fff":"#4B5563"}}>
                  All ({selAnchor.associations.length})
                </button>
                {Object.entries(grouped).map(([type,items])=>(
                  <button key={type} onClick={()=>setFilterType(filterType===type?"All":type)}
                    style={{padding:"5px 12px",borderRadius:16,cursor:"pointer",border:"none",
                      fontFamily:"inherit",fontSize:10,fontWeight:filterType===type?700:400,
                      background:filterType===type?(TD_EDGE_COLORS[type]||"#374151")+"22":"#111827",
                      color:filterType===type?(TD_EDGE_COLORS[type]||"#94A3B8"):"#4B5563",
                      outline:filterType===type?`1.5px solid ${TD_EDGE_COLORS[type]||"#374151"}`:"none"}}>
                    {type} ({items.length})
                  </button>
                ))}
              </div>

              {/* Association cards by type */}
              {view==="graph"&&typeOrder.map(type=>{
                const items = (grouped[type]||[]).filter(a=>filterType==="All"||a.type===filterType);
                if(!items.length) return null;
                const color = TD_EDGE_COLORS[type]||"#374151";
                return (
                  <div key={type} style={{marginBottom:14}}>
                    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8,
                      paddingBottom:4,borderBottom:`1px solid ${color}33`}}>
                      <span style={{fontSize:10,fontWeight:800,padding:"2px 10px",borderRadius:10,
                        background:color+"15",color}}>{type}</span>
                      <span style={{fontSize:9,color:"#4B5563"}}>{items.length} associations</span>
                    </div>
                    {items.map((assoc,i)=>(
                      <div key={i} style={{background:"#111827",borderRadius:8,padding:"10px 14px",
                        marginBottom:6,border:`1px solid ${color}22`,
                        display:"flex",gap:10,alignItems:"flex-start"}}>
                        <div style={{padding:"4px 8px",borderRadius:6,background:color+"15",
                          color,fontSize:9,fontWeight:700,flexShrink:0,whiteSpace:"nowrap"}}>
                          {assoc.rel.replace(/_/g," ")}
                        </div>
                        <div style={{flex:1}}>
                          <div style={{display:"flex",gap:6,alignItems:"center",marginBottom:3}}>
                            <span style={{fontSize:11,fontWeight:700,color:"#E2E8F0"}}>{assoc.label}</span>
                            {assoc.confirmed
                              ? <span style={{fontSize:8,color:"#22C55E",fontWeight:700}}>✓ Confirmed</span>
                              : <span style={{fontSize:8,color:"#D97706",fontWeight:700}}>⚠ AI Derived</span>
                            }
                          </div>
                          <div style={{fontSize:8,fontFamily:"monospace",color:"#4B5563",
                            wordBreak:"break-all",lineHeight:1.5}}>{assoc.id}</div>
                          {assoc.url&&(
                            <div style={{fontSize:9,color:"#60A5FA",marginTop:3}}>
                              🔗 {assoc.url}
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                );
              })}

              {/* Matrix view */}
              {view==="matrix"&&(
                <div style={{background:"#111827",borderRadius:10,overflow:"hidden",
                  border:"1px solid #1F2937"}}>
                  <table style={{width:"100%",borderCollapse:"collapse",fontSize:10}}>
                    <thead><tr style={{background:"#0F172A"}}>
                      {["Relationship","Target Type","ThingDaddy ID","Confirmed"].map(h=>(
                        <th key={h} style={{padding:"8px 12px",textAlign:"left",
                          color:"#4B5563",fontWeight:700,fontSize:9,borderBottom:"1px solid #1F2937"}}>{h}</th>
                      ))}
                    </tr></thead>
                    <tbody>
                      {filtered.map((a,i)=>(
                        <tr key={i} style={{borderBottom:"1px solid #1F2937",
                          background:i%2===0?"#0F172A":"#111827"}}>
                          <td style={{padding:"7px 12px"}}>
                            <span style={{fontSize:9,fontWeight:700,padding:"1px 6px",borderRadius:4,
                              background:(TD_EDGE_COLORS[a.type]||"#374151")+"22",
                              color:TD_EDGE_COLORS[a.type]||"#94A3B8"}}>
                              {a.rel}
                            </span>
                          </td>
                          <td style={{padding:"7px 12px"}}>
                            <span style={{fontSize:9,fontWeight:700,color:TD_EDGE_COLORS[a.type]||"#94A3B8"}}>
                              TD:{a.type}
                            </span>
                          </td>
                          <td style={{padding:"7px 12px",maxWidth:300}}>
                            <div style={{fontSize:10,color:"#E2E8F0",marginBottom:2}}>{a.label}</div>
                            <div style={{fontSize:8,fontFamily:"monospace",color:"#374151",
                              overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                              {a.id}
                            </div>
                          </td>
                          <td style={{padding:"7px 12px"}}>
                            <span style={{fontSize:10,color:a.confirmed?"#22C55E":"#D97706",fontWeight:700}}>
                              {a.confirmed?"✓":"⚠"}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}

              {/* SPARQL query view */}
              {view==="sparql"&&(
                <div>
                  <div style={{fontSize:12,color:"#4B5563",marginBottom:12}}>
                    ThingDaddy SPARQL-style query engine — query any association pattern
                  </div>
                  {[
                    {q:`SELECT * WHERE { <${selAnchor.anchor_id}> td:HAS_MANUAL ?doc }`, label:"All manuals"},
                    {q:`SELECT * WHERE { <${selAnchor.anchor_id}> td:USES_CONSUMABLE ?item }`, label:"All consumables"},
                    {q:`SELECT * WHERE { <${selAnchor.anchor_id}> td:CONTAINS_PART ?part }`, label:"All parts/CPIs"},
                    {q:`SELECT ?doc WHERE { <${selAnchor.anchor_id}> ?rel ?doc . ?doc a td:GDTI }`, label:"All documents"},
                    {q:`SELECT * WHERE { <${selAnchor.anchor_id}> td:OPERATED_BY ?agent . ?agent a td:GSRN }`, label:"All operators"},
                  ].map(({q,label})=>{
                    // Execute query client-side
                    const relMatch = q.match(/td:(\w+)\s+\?/);
                    const typeMatch= q.match(/a td:(\w+)/);
                    const results  = selAnchor.associations.filter(a=>{
                      if(relMatch&&!q.includes("?rel")) return a.rel===relMatch[1];
                      if(typeMatch) return a.type===typeMatch[1];
                      return true;
                    });
                    return (
                      <div key={label} style={{marginBottom:10,background:"#111827",
                        borderRadius:8,overflow:"hidden",border:"1px solid #1F2937"}}>
                        <div style={{padding:"8px 12px",background:"#0F172A",
                          display:"flex",justifyContent:"space-between"}}>
                          <span style={{fontSize:10,fontFamily:"monospace",color:"#60A5FA"}}>{label}</span>
                          <span style={{fontSize:9,color:"#22C55E",fontWeight:700}}>
                            {results.length} results
                          </span>
                        </div>
                        <div style={{padding:"8px 12px",fontFamily:"monospace",fontSize:9,
                          color:"#A78BFA",lineHeight:1.5}}>{q}</div>
                        {results.length>0&&(
                          <div style={{padding:"8px 12px",borderTop:"1px solid #1F2937"}}>
                            {results.map((r,i)=>(
                              <div key={i} style={{fontSize:9,color:"#22C55E",marginBottom:3,
                                display:"flex",gap:8}}>
                                <span style={{color:"#4B5563",flexShrink:0}}>→</span>
                                <span style={{fontFamily:"monospace",wordBreak:"break-all"}}>{r.id}</span>
                                <span style={{color:"#94A3B8",flexShrink:0}}>{r.label}</span>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </>
          )}
        </div>

        {/* RIGHT: Log + edge schema */}
        <div style={{borderLeft:"1px solid #1F2937",overflowY:"auto"}}>
          {/* Log */}
          <div style={{padding:"10px 14px",borderBottom:"1px solid #1F2937",
            background:"#0F172A",maxHeight:200,overflowY:"auto"}}>
            <div style={{fontSize:9,fontWeight:700,color:"#374151",marginBottom:6}}>AI LOG</div>
            {aiLog.length===0&&<div style={{fontSize:10,color:"#374151"}}>Ready</div>}
            {aiLog.map((l,i)=>(
              <div key={i} style={{fontSize:9,color:l.color,marginBottom:2,lineHeight:1.4}}>
                {l.t} {l.msg}
              </div>
            ))}
          </div>

          {/* Edge schema for selected anchor type */}
          {selAnchor&&(
            <div style={{padding:"10px 14px"}}>
              <div style={{fontSize:9,fontWeight:700,color:"#374151",marginBottom:8,letterSpacing:".1em"}}>
                TD:{selAnchor.anchor_type} EDGE SCHEMA
              </div>
              {(TD_EDGE_SCHEMA[selAnchor.anchor_type]||[]).map((edge,i)=>{
                const hasAssoc = selAnchor.associations.some(a=>a.rel===edge.rel);
                return (
                  <div key={i} style={{display:"flex",gap:6,marginBottom:5,
                    padding:"5px 8px",borderRadius:6,
                    background:hasAssoc?"#0F2A0F":"#0F172A",
                    border:`1px solid ${hasAssoc?"#22C55E22":"#1F2937"}`}}>
                    <span style={{fontSize:11,flexShrink:0}}>{edge.icon}</span>
                    <div style={{flex:1}}>
                      <div style={{display:"flex",gap:4,alignItems:"center"}}>
                        <span style={{fontSize:9,fontWeight:700,color:"#E2E8F0"}}>{edge.rel}</span>
                        <span style={{fontSize:8,padding:"0px 4px",borderRadius:3,
                          background:(TD_EDGE_COLORS[edge.target]||"#374151")+"22",
                          color:TD_EDGE_COLORS[edge.target]||"#94A3B8"}}>→{edge.target}</span>
                        {edge.required&&<span style={{fontSize:7,color:"#DC2626",fontWeight:700}}>REQ</span>}
                        {hasAssoc&&<span style={{fontSize:8,color:"#22C55E",fontWeight:700,marginLeft:"auto"}}>✓</span>}
                      </div>
                      <div style={{fontSize:8,color:"#374151",lineHeight:1.3}}>{edge.desc}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    
      <StandardExplainer solutionKey="graph"/>
      </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════════
// GUDID XML IMPORTER — FDA Global Unique Device Identification Database
// Parses FDA GUDID delta/full XML feed → maps every device to ThingDaddy IDs
// Handles GS1 (GTIN) and HIBCC device identifiers
// Maps: GTIN/GIAI + GMN + GDTI(510K) + CPI + LGTIN + PGLN(DUNS) + GSRN
// ═══════════════════════════════════════════════════════════════════════════

// Parse FDA GUDID XML — returns array of normalised device records
const parseGUDIDXml = (xmlText) => {
  const parser = new DOMParser();
  const doc    = parser.parseFromString(xmlText, "application/xml");
  const err    = doc.querySelector("parsererror");
  if(err) throw new Error("XML parse error: " + err.textContent.slice(0,100));

  const getText = (el, tag) => el?.querySelector(tag)?.textContent?.trim() || "";
  const getBool = (el, tag) => getText(el,tag).toLowerCase()==="true";
  const devices = Array.from(doc.querySelectorAll("device"));

  return devices.map(dev => {
    // Identifiers — may have GS1 (GTIN) or HIBCC DI
    const identifiers = Array.from(dev.querySelectorAll("identifier")).map(id=>({
      deviceId:          getText(id,"deviceId"),
      deviceIdType:      getText(id,"deviceIdType"),
      issuingAgency:     getText(id,"deviceIdIssuingAgency"),
      pkgQuantity:       getText(id,"pkgQuantity"),
    }));
    const primaryId = identifiers.find(i=>i.deviceIdType==="Primary") || identifiers[0] || {};

    // GMDN terms
    const gmdnTerms = Array.from(dev.querySelectorAll("gmdn")).map(g=>({
      code:        getText(g,"gmdnCode"),
      name:        getText(g,"gmdnPTName"),
      definition:  getText(g,"gmdnPTDefinition"),
      implantable: getBool(g,"implantable"),
    }));

    // Product codes (FDA)
    const productCodes = Array.from(dev.querySelectorAll("fdaProductCode")).map(p=>({
      code: getText(p,"productCode"),
      name: getText(p,"productCodeName"),
    }));

    // Premarket submissions (510K etc.)
    const submissions = Array.from(dev.querySelectorAll("premarketSubmission")).map(s=>({
      number:     getText(s,"submissionNumber"),
      supplement: getText(s,"supplementNumber"),
    }));

    // Contacts
    const contact = dev.querySelector("customerContact");

    const dunsNum   = getText(dev,"dunsNumber").replace(/\D/g,"");
    const companyName= getText(dev,"companyName");
    const brandName  = getText(dev,"brandName");
    const diNum      = primaryId.deviceId || "";
    const agency     = primaryId.issuingAgency || "";

    // ── THINGDADDY ID DERIVATION ──────────────────────────────────────────
    // Prefix strategy:
    // 1. If GS1 issuing agency: DI is a GTIN → extract prefix (first 7 digits)
    // 2. If HIBCC: DI starts with letter(s) then digits — use DUNS as PGLN basis
    // 3. Always generate PGLN from DUNS if available
    let prefix    = "";
    let gtin_urn  = "";
    let giai_urn  = "";
    let gmn_urn   = "";
    let gdti_urns = [];
    let cpi_urn   = "";
    let pgln_urn  = "";
    let lgtin_urn = "";

    // PGLN from DUNS — universal
    if(dunsNum) {
      // Use DUNS as a synthetic prefix basis — pad/hash to 7 digits
      const dunsPfx = dunsNum.slice(-7).padStart(7,"0");
      pgln_urn = makePGLNurn(dunsPfx,"000001");
    }

    if(agency === "GS1" && /^\d+$/.test(diNum)) {
      // Pure numeric GS1 DI = GTIN
      prefix   = diNum.length >= 13 ? diNum.slice(0,7) : diNum.slice(0,6);
      gtin_urn = makeGTINurn(prefix, diNum.slice(prefix.length,-1)||"PROD001", 0);
      pgln_urn = pgln_urn || makePGLNurn(prefix,"000001");
    } else {
      // HIBCC or other — use DUNS-derived prefix
      const dunsPfx = dunsNum ? dunsNum.slice(-7).padStart(7,"0") : "0000000";
      prefix   = dunsPfx;
      giai_urn = makeGIAIurn(dunsPfx, diNum.replace(/\s/g,"-"));
    }

    // GMN from model number
    const modelNum = getText(dev,"versionModelNumber");
    if(modelNum && prefix) {
      gmn_urn = makeGMNurn(prefix, modelNum.replace(/[^A-Z0-9]/gi,"-").toUpperCase().slice(0,20));
    }

    // GDTI from 510K submissions
    gdti_urns = submissions.map(s =>
      prefix ? makeGDTIurn(prefix, s.number.replace(/\s/g,""), s.supplement||"001") : ""
    ).filter(Boolean);

    // CPI from catalog number
    const catNum = getText(dev,"catalogNumber");
    if(catNum && prefix) {
      cpi_urn = makeCPIurn(prefix, catNum.replace(/[^A-Z0-9]/gi,"-").slice(0,15), "001");
    }

    // LGTIN if lotBatch=true
    if(getBool(dev,"lotBatch") && prefix) {
      lgtin_urn = makeLGTINurn(prefix, diNum.slice(0,10)||"PROD001", "LOT-FDA");
    }

    return {
      // FDA source fields
      recordKey:       getText(dev,"publicDeviceRecordKey"),
      status:          getText(dev,"deviceRecordStatus"),
      publishDate:     getText(dev,"devicePublishDate"),
      distributionStatus: getText(dev,"deviceCommDistributionStatus"),
      companyName,
      brandName,
      description:     getText(dev,"deviceDescription"),
      dunsNumber:      dunsNum,
      catalogNumber:   catNum,
      modelNumber:     modelNum,
      deviceId:        diNum,
      issuingAgency:   agency,
      lotBatch:        getBool(dev,"lotBatch"),
      serialNumber:    getBool(dev,"serialNumber"),
      singleUse:       getBool(dev,"singleUse"),
      rx:              getBool(dev,"rx"),
      otc:             getBool(dev,"otc"),
      mriStatus:       getText(dev,"MRISafetyStatus"),
      phone:           getText(contact,"phone"),
      email:           getText(contact,"email"),
      gmdnTerms,
      productCodes,
      submissions,
      // ThingDaddy IDs derived
      prefix,
      pgln_urn,
      gtin_urn,
      giai_urn,
      gmn_urn,
      gdti_urns,
      cpi_urn,
      lgtin_urn,
      td_ids: [
        pgln_urn,
        gtin_urn||giai_urn,
        gmn_urn,
        cpi_urn,
        ...gdti_urns,
        lgtin_urn,
      ].filter(Boolean),
    };
  });
};


function GUDIDImporter({ onImport }) {
  const { ids, prefix, activeCompany } = useIDs();
  const [xmlText,    setXmlText]    = useState("");
  const [devices,    setDevices]    = useState([]);
  const [error,      setError]      = useState("");
  const [parsing,    setParsing]    = useState(false);
  const [selDevice,  setSelDevice]  = useState(null);
  const [filter,     setFilter]     = useState("");
  const [aiLoading,  setAiLoading]  = useState(false);
  const [aiLog,      setAiLog]      = useState([]);
  const fileRef = React.useRef(null);

  const handleFile = (e) => {
    const file = e.target.files?.[0];
    if(!file) return;
    const reader = new FileReader();
    reader.onload = ev => setXmlText(ev.target.result);
    reader.readAsText(file);
  };

  const parseXML = () => {
    setParsing(true); setError("");
    try {
      const parsed = parseGUDIDXml(xmlText);
      setDevices(parsed);
      setAiLog([`✅ Parsed ${parsed.length} GUDID device records`,
                `📦 GS1 DIs: ${parsed.filter(d=>d.issuingAgency==="GS1").length}`,
                `🏷️  HIBCC DIs: ${parsed.filter(d=>d.issuingAgency==="HIBCC").length}`,
                `🏢 Unique companies: ${new Set(parsed.map(d=>d.companyName)).size}`,
                `📄 510K submissions: ${parsed.reduce((a,d)=>a+d.submissions.length,0)}`,
      ]);
    } catch(e) {
      setError(e.message);
    }
    setParsing(false);
  };

  // AI enrichment — look up missing prefixes for HIBCC devices
  const enrichWithAI = async () => {
    const hibccDevices = devices.filter(d=>d.issuingAgency==="HIBCC" && d.companyName);
    if(!hibccDevices.length) return;
    setAiLoading(true);
    setAiLog(prev=>[...prev, `🤖 Enriching ${hibccDevices.length} HIBCC devices with GS1 prefix lookup...`]);
    try {
      const companies = [...new Set(hibccDevices.map(d=>d.companyName))].slice(0,10);
      const resp = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:800,
          messages:[{role:"user", content:
            `GS1 prefix lookup for these medical device companies. For each, find their GS1 company prefix if known.\n\n` +
            companies.map((c,i)=>`${i+1}. ${c}`).join("\n") + "\n\n" +
            `Return ONLY JSON array: [{"company":"exact name","gs1_prefix":"7 digit prefix or empty","confidence":"high|medium|low","address":"HQ address","country":""}]`
          }]
        })
      });
      const data = await resp.json();
      const raw  = (data.content?.[0]?.text||"[]").replace(/```json|```/g,"").trim();
      const enriched = JSON.parse(raw);
      const enrichMap = {};
      enriched.forEach(e=>{ enrichMap[e.company] = e; });
      setDevices(prev=>prev.map(d=>{
        const info = enrichMap[d.companyName];
        if(info?.gs1_prefix && d.issuingAgency==="HIBCC") {
          const p = info.gs1_prefix;
          return {...d, prefix:p,
            pgln_urn: makePGLNurn(p,"000001"),
            giai_urn: makeGIAIurn(p, d.deviceId.replace(/\s/g,"-")),
            gmn_urn:  d.modelNumber ? makeGMNurn(p,d.modelNumber.replace(/[^A-Z0-9]/gi,"-").toUpperCase().slice(0,20)) : d.gmn_urn,
            td_ids:   [makePGLNurn(p,"000001"), makeGIAIurn(p,d.deviceId.replace(/\s/g,"-"))].filter(Boolean),
            gs1_enriched: true,
          };
        }
        return d;
      }));
      setAiLog(prev=>[...prev,
        `✅ Enriched ${enriched.filter(e=>e.gs1_prefix).length} of ${companies.length} companies with GS1 prefixes`
      ]);
    } catch(e) {
      setAiLog(prev=>[...prev, `⚠️ Enrichment error: ${e.message}`]);
    }
    setAiLoading(false);
  };

  const exportCSV = () => {
    const rows = devices.map(d=>[
      `"${d.companyName}"`,`"${d.brandName}"`,`"${d.description.slice(0,50)}"`,
      `"${d.deviceId}"`,`"${d.issuingAgency}"`,`"${d.dunsNumber}"`,
      `"${d.prefix}"`,`"${d.pgln_urn}"`,`"${d.gtin_urn||d.giai_urn}"`,
      `"${d.gmn_urn}"`,`"${d.cpi_urn}"`,`"${d.gdti_urns.join("|")}"`,
      `"${d.phone}"`,`"${d.email}"`,
    ].join(",")).join("\n");
    const header = "Company,Brand,Description,DI,Agency,DUNS,Prefix,PGLN,GTIN/GIAI,GMN,CPI,GDTI(510K),Phone,Email\n";
    const blob = new Blob([header+rows],{type:"text/csv"});
    const a = document.createElement("a"); a.href=URL.createObjectURL(blob);
    a.download=`gudid_thingdaddy_${Date.now()}.csv`; a.click();
  };

  const filtered = devices.filter(d=>{
    if(!filter) return true;
    const q = filter.toLowerCase();
    return d.companyName.toLowerCase().includes(q)||
           d.brandName.toLowerCase().includes(q)||
           d.description.toLowerCase().includes(q)||
           d.deviceId.toLowerCase().includes(q);
  });

  const STATUS_COLORS = {"GS1":"#16A34A","HIBCC":"#2563EB","ICCBBA":"#7C3AED"};

  return (
    <div style={{fontFamily:"'Inter',system-ui,sans-serif",background:"#F8FAFC",minHeight:"100vh"}}>
      {/* HEADER */}
      <div style={{background:"#111827",padding:"16px 24px"}}>
        <div style={{fontSize:10,fontWeight:700,color:"#4B5563",letterSpacing:".15em",marginBottom:4}}>
          THINGDADDY PLATFORM · TD:SEED · MASS POPULATION
        </div>
        <div style={{fontSize:22,fontWeight:900,color:"#fff",marginBottom:4}}>
          🏥 FDA GUDID XML Importer
        </div>
        <div style={{fontSize:12,color:"#6B7280"}}>
          Import FDA GUDID delta or full XML feed · Maps every device to ThingDaddy IDs ·
          GTIN · GIAI · GMN · GDTI(510K) · CPI · PGLN(DUNS) · LGTIN · AI prefix enrichment
        </div>
      </div>

      <div style={{padding:"20px 24px"}}>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:20}}>

          {/* LEFT: Input */}
          <div>
            {/* File upload */}
            <div style={{background:"#fff",borderRadius:12,padding:16,border:"1.5px solid #E5E7EB",marginBottom:12}}>
              <div style={{fontSize:12,fontWeight:700,color:"#111827",marginBottom:10}}>
                GUDID XML Source
              </div>
              <div style={{display:"flex",gap:8,marginBottom:10}}>
                <input ref={fileRef} type="file" accept=".xml,.txt" style={{display:"none"}}
                  onChange={handleFile}/>
                <button onClick={()=>fileRef.current?.click()}
                  style={{padding:"9px 18px",borderRadius:8,border:"1.5px solid #E5E7EB",
                    background:"#F8FAFC",cursor:"pointer",fontFamily:"inherit",
                    fontSize:12,fontWeight:700,color:"#374151"}}>
                  📁 Load XML File
                </button>
                <div style={{fontSize:11,color:"#6B7280",alignSelf:"center"}}>
                  FDA daily delta feed or full GUDID export
                </div>
              </div>
              <textarea value={xmlText} onChange={e=>setXmlText(e.target.value)}
                placeholder={`Paste GUDID XML here, or load a file above.\n\nSupports:\n• FDA GUDID daily delta XML (gudid.nlm.nih.gov)\n• Full GUDID export\n• Individual device XML records\n\nExample: <?xml version="1.0" encoding="UTF-8"?>\n<gudid xmlns="http://www.fda.gov/cdrh/gudid"...`}
                style={{width:"100%",height:200,padding:12,borderRadius:8,
                  border:"1px solid #E5E7EB",fontFamily:"monospace",fontSize:11,
                  outline:"none",resize:"vertical",boxSizing:"border-box",lineHeight:1.6}}/>
              <div style={{display:"flex",gap:8,marginTop:10,alignItems:"center"}}>
                <button onClick={parseXML} disabled={parsing||!xmlText.trim()}
                  style={{padding:"10px 20px",borderRadius:8,border:"none",cursor:"pointer",
                    fontFamily:"inherit",fontSize:13,fontWeight:700,
                    background:!xmlText.trim()?"#E5E7EB":"#1E3A5F",
                    color:!xmlText.trim()?"#9CA3AF":"#fff"}}>
                  {parsing?"Parsing...":"⚡ Parse + Map to ThingDaddy IDs"}
                </button>
                {devices.length>0&&(
                  <>
                    <button onClick={enrichWithAI} disabled={aiLoading}
                      style={{padding:"10px 16px",borderRadius:8,border:"none",cursor:"pointer",
                        fontFamily:"inherit",fontSize:12,fontWeight:700,
                        background:aiLoading?"#E5E7EB":"#7C3AED",color:aiLoading?"#9CA3AF":"#fff"}}>
                      {aiLoading?"🤖 Enriching...":"🤖 AI Enrich Prefixes"}
                    </button>
                    <button onClick={exportCSV}
                      style={{padding:"10px 16px",borderRadius:8,border:"none",cursor:"pointer",
                        fontFamily:"inherit",fontSize:12,fontWeight:700,
                        background:"#3DB54A",color:"#fff"}}>
                      📤 Export CSV
                    </button>
                  </>
                )}
              </div>
              {error&&<div style={{marginTop:8,color:"#DC2626",fontSize:11}}>❌ {error}</div>}
            </div>

            {/* Parse log */}
            {aiLog.length>0&&(
              <div style={{background:"#0F172A",borderRadius:10,padding:"10px 14px"}}>
                {aiLog.map((l,i)=>(
                  <div key={i} style={{fontSize:11,color:l.startsWith("✅")?"#22C55E":l.startsWith("⚠️")?"#FCD34D":"#94A3B8",marginBottom:3}}>
                    {l}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* RIGHT: Stats + selected device */}
          <div>
            {devices.length>0&&(
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:12}}>
                {[
                  {label:"Devices",    val:devices.length,         color:"#3DB54A"},
                  {label:"Companies",  val:new Set(devices.map(d=>d.companyName)).size, color:"#2563EB"},
                  {label:"GS1 GTIN",   val:devices.filter(d=>d.issuingAgency==="GS1").length,   color:"#16A34A"},
                  {label:"HIBCC GIAI", val:devices.filter(d=>d.issuingAgency==="HIBCC").length,  color:"#7C3AED"},
                  {label:"With 510K",  val:devices.filter(d=>d.submissions.length>0).length,     color:"#D97706"},
                  {label:"TD:IDs gen", val:devices.reduce((a,d)=>a+d.td_ids.length,0),          color:"#DB2877"},
                ].map(s=>(
                  <div key={s.label} style={{background:"#fff",borderRadius:8,padding:"10px 12px",
                    border:"1px solid #E5E7EB",textAlign:"center"}}>
                    <div style={{fontSize:9,color:"#6B7280",marginBottom:3}}>{s.label}</div>
                    <div style={{fontSize:20,fontWeight:900,color:s.color}}>{s.val}</div>
                  </div>
                ))}
              </div>
            )}

            {selDevice&&(
              <div style={{background:"#0F172A",borderRadius:12,padding:16,
                border:"1px solid #22C55E44",marginBottom:12,maxHeight:420,overflowY:"auto"}}>
                <div style={{fontSize:13,fontWeight:800,color:"#fff",marginBottom:4}}>
                  {selDevice.brandName||selDevice.companyName}
                </div>
                <div style={{fontSize:11,color:"#94A3B8",marginBottom:10}}>{selDevice.description}</div>
                <div style={{fontSize:9,fontWeight:700,color:"rgba(34,197,94,.7)",marginBottom:8,letterSpacing:".1em"}}>
                  THINGDADDY IDs GENERATED
                </div>
                {selDevice.td_ids.map((u,i)=>(
                  <div key={i} style={{fontSize:9,fontFamily:"monospace",color:"#22C55E",
                    marginBottom:4,wordBreak:"break-all",lineHeight:1.5}}>
                    {u}
                  </div>
                ))}
                <div style={{marginTop:10,paddingTop:10,borderTop:"1px solid #1E293B"}}>
                  {[
                    ["Company",   selDevice.companyName],
                    ["Brand",     selDevice.brandName],
                    ["DI",        `${selDevice.deviceId} (${selDevice.issuingAgency})`],
                    ["DUNS",      selDevice.dunsNumber],
                    ["Prefix",    selDevice.prefix],
                    ["GMDN",      selDevice.gmdnTerms[0]?.name||"—"],
                    ["510K",      selDevice.submissions[0]?.number||"—"],
                    ["Rx/OTC",    `${selDevice.rx?"Rx":""}${selDevice.otc?" OTC":""}`],
                    ["Lot/Serial",`${selDevice.lotBatch?"LotBatch ":""}${selDevice.serialNumber?"Serial":""}`],
                    ["Contact",   `${selDevice.phone} ${selDevice.email}`],
                  ].map(([k,v])=>v&&v!=="—"&&(
                    <div key={k} style={{display:"flex",gap:8,marginBottom:4,fontSize:10}}>
                      <span style={{color:"#6B7280",minWidth:70,flexShrink:0}}>{k}</span>
                      <span style={{color:"#E2E8F0",wordBreak:"break-all"}}>{v}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Device table */}
        {devices.length>0&&(
          <div style={{marginTop:16}}>
            <div style={{display:"flex",gap:10,marginBottom:10,alignItems:"center"}}>
              <div style={{fontSize:14,fontWeight:800,color:"#111827"}}>
                {devices.length} Devices → ThingDaddy Registry
              </div>
              <input value={filter} onChange={e=>setFilter(e.target.value)}
                placeholder="Filter by company, brand, device..."
                style={{marginLeft:"auto",padding:"7px 14px",borderRadius:20,
                  border:"1px solid #E5E7EB",background:"#fff",fontFamily:"inherit",
                  fontSize:12,outline:"none",width:260}}/>
            </div>
            <div style={{background:"#fff",borderRadius:12,border:"1px solid #E5E7EB",overflow:"hidden"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
                <thead><tr style={{background:"#F8FAFC"}}>
                  {["Company","Brand / Description","DI (Agency)","DUNS","Prefix","ThingDaddy URNs","GMDN / 510K"].map(h=>(
                    <th key={h} style={{padding:"8px 12px",textAlign:"left",fontSize:9,
                      fontWeight:700,color:"#6B7280",borderBottom:"1px solid #E5E7EB",whiteSpace:"nowrap"}}>{h}</th>
                  ))}
                </tr></thead>
                <tbody>
                  {filtered.map((d,i)=>(
                    <tr key={d.recordKey||i}
                      onClick={()=>setSelDevice(selDevice?.recordKey===d.recordKey?null:d)}
                      style={{borderBottom:"1px solid #F3F4F6",cursor:"pointer",
                        background:selDevice?.recordKey===d.recordKey?"#EFF6FF":i%2===0?"#fff":"#FAFAFA"}}>
                      <td style={{padding:"8px 12px"}}>
                        <div style={{fontWeight:700,color:"#111827"}}>{d.companyName}</div>
                        <div style={{fontSize:9,color:"#9CA3AF"}}>{d.distributionStatus==="In Commercial Distribution"?"✓ Active":"⚠ "+d.distributionStatus}</div>
                      </td>
                      <td style={{padding:"8px 12px",maxWidth:180}}>
                        <div style={{fontWeight:600,color:"#374151"}}>{d.brandName}</div>
                        <div style={{fontSize:9,color:"#9CA3AF",lineHeight:1.4}}>{d.description.slice(0,50)}{d.description.length>50?"…":""}</div>
                      </td>
                      <td style={{padding:"8px 12px"}}>
                        <div style={{fontFamily:"monospace",fontSize:10,color:"#374151"}}>{d.deviceId}</div>
                        <span style={{fontSize:9,padding:"1px 5px",borderRadius:4,fontWeight:700,
                          background:(STATUS_COLORS[d.issuingAgency]||"#6B7280")+"15",
                          color:STATUS_COLORS[d.issuingAgency]||"#6B7280"}}>
                          {d.issuingAgency}
                        </span>
                      </td>
                      <td style={{padding:"8px 12px",fontFamily:"monospace",fontSize:10,color:"#374151"}}>
                        {d.dunsNumber||"—"}
                      </td>
                      <td style={{padding:"8px 12px",fontFamily:"monospace",fontSize:10,color:"#059669",fontWeight:700}}>
                        {d.prefix||"—"}
                      </td>
                      <td style={{padding:"8px 12px"}}>
                        <div style={{display:"flex",gap:3,flexWrap:"wrap"}}>
                          {d.td_ids.slice(0,2).map((u,j)=>(
                            <span key={j} style={{fontSize:8,fontFamily:"monospace",
                              color:"#22C55E",display:"block",lineHeight:1.4,
                              maxWidth:180,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                              {u}
                            </span>
                          ))}
                          {d.td_ids.length>2&&(
                            <span style={{fontSize:8,color:"#6B7280"}}>+{d.td_ids.length-2} more</span>
                          )}
                        </div>
                      </td>
                      <td style={{padding:"8px 12px"}}>
                        <div style={{fontSize:9,color:"#374151"}}>{d.gmdnTerms[0]?.name?.slice(0,35)||"—"}</div>
                        {d.submissions[0]&&(
                          <div style={{fontSize:9,color:"#D97706",fontWeight:600}}>
                            510K: {d.submissions[0].number}
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════════
// TD:DOCS — PDF Manual / Datasheet Importer
// Upload any product manual, datasheet, SDS, IFU, certificate, or spec sheet
// Claude AI extracts: model numbers, part numbers, company, specs, standards
// Maps everything to ThingDaddy IDs: GDTI + GIAI + GMN + CPI + GTIN + PGLN
// ═══════════════════════════════════════════════════════════════════════════

const DOC_TYPES = [
  {id:"manual",   icon:"📋", label:"User Manual / IFU",         gdti_prefix:"MAN",  map:["GDTI","GIAI","GMN"]},
  {id:"datasheet",icon:"📐", label:"Product Datasheet / Spec",  gdti_prefix:"SPEC", map:["GDTI","GTIN","GMN","CPI"]},
  {id:"sds",      icon:"⚗️", label:"Safety Data Sheet (SDS)",   gdti_prefix:"SDS",  map:["GDTI","LGTIN","GTIN"]},
  {id:"cert",     icon:"🏆", label:"Certificate (ISO/FDA/CE)",  gdti_prefix:"CERT", map:["GDTI","PGLN"]},
  {id:"ifu",      icon:"🏥", label:"Instructions For Use (IFU)",gdti_prefix:"IFU",  map:["GDTI","GTIN","GIAI"]},
  {id:"warranty", icon:"🛡️", label:"Warranty Document",         gdti_prefix:"WARR", map:["GDTI","GIAI","GTIN"]},
  {id:"patent",   icon:"📜", label:"Patent",                    gdti_prefix:"PAT",  map:["GDTI","PGLN","GMN"]},
  {id:"wiring",   icon:"⚡", label:"Wiring / Schematic",        gdti_prefix:"WIRI", map:["GDTI","GIAI","CPI"]},
  {id:"bom",      icon:"🗂️", label:"Bill of Materials (BOM)",   gdti_prefix:"BOM",  map:["GDTI","CPI","GTIN"]},
  {id:"other",    icon:"📄", label:"Other Document",            gdti_prefix:"DOC",  map:["GDTI"]},
];


// ── CloudEdgeModule — run any ThingDaddy "thing" in any cloud/edge vendor ──────
// Each vendor card carries UNIQUE code across three semantic mapping layers:
//   1. ThingDaddy ID → vendor device registry (e.g. GIAI → AWS IoT Thing ARN)
//   2. SiLA driver (this GIAI) → vendor device SDK
//   3. Allotrope ADF protocol events → vendor event bus
function CloudEdgeModule({ setActiveModule=()=>{} }) {
  const { ids, prefix, addProvenance } = useIDs();
  const pfx = prefix || "0085126";
  const baseGiai = ids?.GIAI?.epc || `urn:epc:id:giai:${pfx}.DEVICE001`;
  const gtin  = ids?.GTIN?.epc  || `urn:epc:id:sgtin:${pfx}.000001.SN001`;
  const gln   = ids?.GLN?.epc   || `urn:epc:id:sgln:${pfx}.SITE01.0`;
  const gdti  = ids?.GDTI?.epc  || `urn:epc:id:gdti:${pfx}.SOP001.DOC001`;
  const lgtin = ids?.LGTIN?.epc || `urn:epc:class:lgtin:${pfx}.BATCH01.LOT001`;
  const gsrn  = ids?.GSRN?.epc  || `urn:epc:id:gsrn:${pfx}.OPERATOR001`;
  const cpi   = ids?.CPI?.epc   || `urn:epc:id:cpi:${pfx}.SENSOR01.CPI001`;
  // safe slug for resource names
  const baseSlug = baseGiai.replace(/[^A-Za-z0-9]/g, "-");

  // ── Multi-tenant deployment scenarios ────────────────────────────────────────
  // One instrument (a Thermo Fisher qPCR) sold to multiple customers, each on
  // their own cloud. Same TD:GIAI; the platform auto-configures per customer.
  const SCENARIOS = [
    {
      id:"pfizer",   customer:"Pfizer",   cloud:"aws",   region:"us-east-1",
      instrument:"Thermo Fisher QuantStudio 7 Pro qPCR", mfrPrefix:"0085126",
      serial:"QS7-SN2024-0001",
      note:"Pfizer's physical unit (serial QS7-SN2024-0001) runs on AWS IoT Core. Its unique TD:GIAI \u2014 a digital VIN \u2014 becomes an AWS Thing ARN in Pfizer's account.",
    },
    {
      id:"novartis",  customer:"Novartis", cloud:"azure", region:"westeurope",
      instrument:"Thermo Fisher QuantStudio 7 Pro qPCR", mfrPrefix:"0085126",
      serial:"QS7-SN2024-0002",
      note:"Novartis's unit (serial QS7-SN2024-0002) \u2014 same model, DIFFERENT GIAI \u2014 runs on Azure IoT Hub as a Device Twin in Novartis's tenant.",
    },
    {
      id:"roche",     customer:"Roche",    cloud:"gcp",   region:"europe-west1",
      instrument:"Thermo Fisher QuantStudio 7 Pro qPCR", mfrPrefix:"0085126",
      serial:"QS7-SN2024-0003",
      note:"Roche's unit (serial QS7-SN2024-0003) runs on Google Cloud IoT \u2014 again a unique GIAI for this exact physical machine.",
    },
    {
      id:"siemens_mfg",customer:"Siemens (mfg line)", cloud:"siemens", region:"eu1",
      instrument:"Thermo Fisher QuantStudio 7 Pro qPCR", mfrPrefix:"0085126",
      serial:"QS7-SN2024-0004",
      note:"Unit QS7-SN2024-0004 on a Siemens Insights Hub edge line \u2014 its own GIAI maps to a MindSphere asset.",
    },
    {
      id:"airgapped", customer:"Gov / Air-gapped lab", cloud:"edge", region:"on-prem",
      instrument:"Thermo Fisher QuantStudio 7 Pro qPCR", mfrPrefix:"0085126",
      serial:"QS7-SN2024-0005",
      note:"Unit QS7-SN2024-0005 in an air-gapped facility runs on a local edge node. Its unique GIAI lives in a local device shadow.",
    },
  ];
  // Each scenario's unique GIAI = digital VIN (same model GTIN, unique serial)
  const scenarioGiai = (sc) => `urn:epc:id:giai:${sc.mfrPrefix}.${sc.serial}`;


  const [scenario, setScenario] = React.useState(null);
  // Effective GIAI = the selected unit's unique digital-VIN GIAI, else company default
  const giai = scenario ? scenarioGiai(scenario) : baseGiai;
  const slug = giai.replace(/[^A-Za-z0-9]/g, "-");

  const VENDORS = [
    {
      id:"aws", name:"AWS IoT Core", icon:"🟧", color:"#FF9900", textColor:"#232F3E",
      kind:"Cloud", registry:"IoT Thing Registry / ARN", sdk:"AWS IoT Device SDK (Python)", bus:"EventBridge + IoT Rules",
      layers:{
        id:`# 1 ── ThingDaddy ID → AWS IoT Thing + ARN
import boto3
iot = boto3.client("iot")

# GIAI becomes the AWS Thing name; full URN preserved in attributes
iot.create_thing(
    thingName="${slug}",
    attributePayload={"attributes":{
        "td_giai":  "${giai}",
        "td_gtin":  "${gtin}",
        "td_gln":   "${gln}",
        "td_gdti":  "${gdti}",
    }},
)
# Resulting ARN (the AWS-native identity for this ThingDaddy thing):
#   arn:aws:iot:us-east-1:123456789012:thing/${slug}
# SEMANTIC MAP:  TD:GIAI  ⇄  iot:Thing/ARN`,
        sila:`# 2 ── SiLA 2 driver (this GIAI) → AWS IoT Device SDK
from awsiot import mqtt_connection_builder

# The SiLA DeviceIdentificationProvider GIAI is the MQTT client_id
conn = mqtt_connection_builder.mtls_from_path(
    endpoint="xxxx-ats.iot.us-east-1.amazonaws.com",
    client_id="${slug}",          # ← SiLA td_giai
    cert_filepath="device.pem.crt",
    pri_key_filepath="private.pem.key",
)
conn.connect().result()
# Each SiLA ObservableProperty → MQTT topic:
#   td/${slug}/sila/<feature>/<property>
# SEMANTIC MAP:  SiLA Feature  ⇄  IoT MQTT topic`,
        adf:`# 3 ── Allotrope ADF events → AWS EventBridge
import boto3, json
eb = boto3.client("events")

# Every ADF result (keyed by GDTI) publishes to EventBridge
eb.put_events(Entries=[{
    "Source":       "thingdaddy.adf",
    "DetailType":   "ADF.ResultPublished",
    "Detail": json.dumps({
        "td_gdti":  "${gdti}",     # the ADF document
        "td_giai":  "${giai}",     # the instrument
        "td_lgtin": "${lgtin}",    # reagent lot
        "td_gsrn":  "${gsrn}",     # operator
    }),
}])
# SEMANTIC MAP:  ADF event  ⇄  EventBridge DetailType
#                TD:GDTI    ⇄  event detail key`,
      },
    },
    {
      id:"azure", name:"Azure IoT Hub", icon:"🟦", color:"#0078D4", textColor:"#fff",
      kind:"Cloud", registry:"Device Twin Registry", sdk:"Azure IoT Device SDK", bus:"Event Grid",
      layers:{
        id:`# 1 ── ThingDaddy ID → Azure IoT Device Twin
from azure.iot.hub import IoTHubRegistryManager
reg = IoTHubRegistryManager("<conn-str>")

# GIAI becomes the deviceId; URNs stored in twin tags
reg.create_device_with_sas("${slug}", "", "", "enabled")
reg.update_twin("${slug}", {"tags":{
    "td_giai":  "${giai}",
    "td_gtin":  "${gtin}",
    "td_gln":   "${gln}",
    "td_gdti":  "${gdti}",
}})
# SEMANTIC MAP:  TD:GIAI  ⇄  azure deviceId / twin
#                full URN ⇄  twin.tags.td_giai`,
        sila:`# 2 ── SiLA 2 driver (this GIAI) → Azure IoT Device SDK
from azure.iot.device import IoTHubDeviceClient, Message

client = IoTHubDeviceClient.create_from_connection_string(
    "HostName=...;DeviceId=${slug};SharedAccessKey=...")   # ← SiLA td_giai
client.connect()

# SiLA ObservableProperty → device-to-cloud message w/ properties
msg = Message('{"value":42}')
msg.custom_properties["td_giai"]    = "${giai}"
msg.custom_properties["sila_feature"] = "TemperatureController"
client.send_message(msg)
# SEMANTIC MAP:  SiLA Feature  ⇄  D2C message property`,
        adf:`# 3 ── Allotrope ADF events → Azure Event Grid
from azure.eventgrid import EventGridPublisherClient, EventGridEvent
from azure.core.credentials import AzureKeyCredential

client = EventGridPublisherClient("<topic-endpoint>", AzureKeyCredential("<key>"))
client.send([EventGridEvent(
    subject=f"adf/${slug}",
    event_type="ThingDaddy.ADF.ResultPublished",
    data={"td_gdti":"${gdti}","td_giai":"${giai}","td_lgtin":"${lgtin}","td_gsrn":"${gsrn}"},
    data_version="1.0",
)])
# SEMANTIC MAP:  ADF event ⇄ Event Grid event_type
#                TD:GDTI   ⇄ event subject`,
      },
    },
    {
      id:"gcp", name:"Google Cloud IoT", icon:"🟥", color:"#EA4335", textColor:"#fff",
      kind:"Cloud", registry:"Device Registry / Pub-Sub", sdk:"Cloud IoT Device SDK (MQTT)", bus:"Pub/Sub",
      layers:{
        id:`# 1 ── ThingDaddy ID → GCP IoT Device Registry
from google.cloud import iot_v1
client = iot_v1.DeviceManagerClient()
parent = client.registry_path("proj","us-central1","td-registry")

# GIAI → device_id; URNs in metadata
client.create_device(parent=parent, device={
    "id":"${slug}",
    "metadata":{
        "td_giai":  "${giai}",
        "td_gtin":  "${gtin}",
        "td_gln":   "${gln}",
        "td_gdti":  "${gdti}",
    },
})
# SEMANTIC MAP:  TD:GIAI ⇄ gcp device_id
#                full URN ⇄ device.metadata.td_giai`,
        sila:`# 2 ── SiLA 2 driver (this GIAI) → GCP MQTT bridge
import jwt, paho.mqtt.client as mqtt

client = mqtt.Client(client_id=(
  "projects/proj/locations/us-central1/registries/td-registry/devices/${slug}"))  # ← SiLA td_giai
client.username_pw_set("unused", password=jwt_token)
client.connect("mqtt.googleapis.com", 8883)

# SiLA ObservableProperty → telemetry topic:
#   /devices/${slug}/events/sila
# SEMANTIC MAP:  SiLA Feature ⇄ Pub/Sub telemetry topic`,
        adf:`# 3 ── Allotrope ADF events → Google Pub/Sub
from google.cloud import pubsub_v1, json
publisher = pubsub_v1.PublisherClient()
topic = publisher.topic_path("proj","thingdaddy-adf")

publisher.publish(topic, json.dumps({
    "td_gdti":"${gdti}","td_giai":"${giai}",
    "td_lgtin":"${lgtin}","td_gsrn":"${gsrn}",
}).encode(), eventType="ADF.ResultPublished")
# SEMANTIC MAP:  ADF event ⇄ Pub/Sub message attribute
#                TD:GDTI   ⇄ message payload key`,
      },
    },
    {
      id:"siemens", name:"Siemens Insights Hub", icon:"🟩", color:"#009999", textColor:"#fff",
      kind:"Edge/Cloud", registry:"MindSphere Asset Model", sdk:"Insights Hub Agent SDK", bus:"IoT Event Service",
      layers:{
        id:`# 1 ── ThingDaddy ID → Siemens Insights Hub Asset
# GIAI maps to the MindSphere assetId; URNs as static aspect variables
PUT /api/assetmanagement/v3/assets/{assetId}
{
  "name": "${slug}",
  "aspects": [{ "name": "ThingDaddyIdentity", "variables": [
    { "name": "td_giai",  "value": "${giai}" },
    { "name": "td_gtin",  "value": "${gtin}" },
    { "name": "td_gln",   "value": "${gln}"  },
    { "name": "td_gdti",  "value": "${gdti}" }
  ]}]
}
# SEMANTIC MAP:  TD:GIAI ⇄ MindSphere assetId
#                URN set ⇄ ThingDaddyIdentity aspect`,
        sila:`# 2 ── SiLA 2 driver (this GIAI) → Insights Hub Agent
from mindsphere import MindConnectAgent
agent = MindConnectAgent(client_id="${slug}")   # ← SiLA td_giai
agent.onboard()

# SiLA ObservableProperty → time-series datapoint
agent.upload_timeseries([{
    "dataPointId": "sila_temp",
    "qualityCode": "0",
    "value": "42",
}])
# SEMANTIC MAP:  SiLA Feature ⇄ Insights Hub datapoint`,
        adf:`# 3 ── Allotrope ADF events → IoT Event Service
POST /api/eventmanagement/v3/events
{
  "typeId": "thingdaddy.adf.ResultPublished",
  "entityId": "${slug}",
  "td_gdti":  "${gdti}",
  "td_giai":  "${giai}",
  "td_lgtin": "${lgtin}",
  "td_gsrn":  "${gsrn}"
}
# SEMANTIC MAP:  ADF event ⇄ Event Service typeId
#                TD:GDTI   ⇄ event field`,
      },
    },
    {
      id:"ptc", name:"PTC ThingWorx", icon:"🟪", color:"#7C3AED", textColor:"#fff",
      kind:"Edge/Cloud", registry:"ThingWorx Thing Model", sdk:"Edge MicroServer (EMS)", bus:"Event/Subscription",
      layers:{
        id:`// 1 ── ThingDaddy ID → ThingWorx Thing
// GIAI becomes the Thing name; URNs as Thing properties
twx.Things["${slug}"].SetPropertyValue({
    name: "td_giai",  value: "${giai}" });
twx.Things["${slug}"].SetPropertyValue({
    name: "td_gtin",  value: "${gtin}" });
twx.Things["${slug}"].SetPropertyValue({
    name: "td_gln",   value: "${gln}"  });
// SEMANTIC MAP:  TD:GIAI ⇄ ThingWorx Thing name
//                URN set ⇄ Thing properties`,
        sila:`// 2 ── SiLA 2 driver (this GIAI) → ThingWorx EMS
// EMS config.json binds the SiLA GIAI to a RemoteThing
{
  "ws_servers": [{ "host": "twx.example.com", "port": 443 }],
  "certificates": { "validate": true },
  "auto_bind": [{ "name": "${slug}", "gateway": false }]
}
// SiLA ObservableProperty → bound RemoteThing property
// SEMANTIC MAP:  SiLA Feature ⇄ RemoteThing property`,
        adf:`// 3 ── Allotrope ADF events → ThingWorx Event
// ADF result fires a ThingWorx event with the GDTI payload
twx.Things["${slug}"].adfResultPublished({
    td_gdti:  "${gdti}",
    td_giai:  "${giai}",
    td_lgtin: "${lgtin}",
    td_gsrn:  "${gsrn}"
});
// SEMANTIC MAP:  ADF event ⇄ ThingWorx Event
//                TD:GDTI   ⇄ event payload`,
      },
    },
    {
      id:"edge", name:"Edge (Greengrass/K3s)", icon:"⬛", color:"#374151", textColor:"#fff",
      kind:"Edge", registry:"Local Device Shadow", sdk:"Greengrass / containerd", bus:"Local MQTT / NATS",
      layers:{
        id:`# 1 ── ThingDaddy ID → Local edge device shadow (offline-first)
# Runs on AWS Greengrass core or a K3s edge node
shadow = {
  "state": { "reported": {
      "td_giai":  "${giai}",
      "td_gtin":  "${gtin}",
      "td_gln":   "${gln}",
      "td_gdti":  "${gdti}",
  }}}
# Syncs to cloud registry when connectivity returns
# SEMANTIC MAP:  TD:GIAI ⇄ local shadow thingName`,
        sila:`# 2 ── SiLA 2 driver (this GIAI) → edge container
# The SiLA server runs as a Greengrass component / K3s pod
component:
  name: td-sila-${slug}
  run: sila2-server --device-id "${slug}"   # ← SiLA td_giai
  ports: [50051]   # gRPC
# Telemetry buffered locally, forwarded on reconnect
# SEMANTIC MAP:  SiLA gRPC ⇄ edge component port`,
        adf:`# 3 ── Allotrope ADF events → local NATS, store-and-forward
import nats, json
nc = await nats.connect("nats://localhost:4222")
await nc.publish("adf.result", json.dumps({
    "td_gdti":"${gdti}","td_giai":"${giai}",
    "td_lgtin":"${lgtin}","td_gsrn":"${gsrn}",
}).encode())
# Edge buffers ADF events; replays to cloud bus on reconnect
# SEMANTIC MAP:  ADF event ⇄ NATS subject (store-and-forward)`,
      },
    },
  ];

  

  const [selVendor, setSelVendor] = React.useState(null);
  const [layer, setLayer] = React.useState("id");
  const [copied, setCopied] = React.useState(false);

  const LAYER_TABS = [
    {id:"id",   label:"1 · ID → Registry",  hint:"ThingDaddy ID → cloud device registry / ARN"},
    {id:"sila", label:"2 · SiLA → SDK",      hint:"SiLA 2 driver (GIAI) → cloud device SDK"},
    {id:"adf",  label:"3 · ADF → Events",    hint:"Allotrope ADF protocol → cloud event bus"},
  ];

  const v = selVendor;
  const code = v ? v.layers[layer] : "";

  return (
    <div style={{padding:"24px 20px", maxWidth:1180, margin:"0 auto"}}>
      {(()=>{ try { return <TDArtifactPanel icon="☁️" title="Cloud + Edge — binding descriptors" sub="one driver, many clouds: N+M, generated from the in-context ID"
        items={[
          {label:"AWS IoT Core",filename:"aws_iot_thing.json",gen:()=>tdCloudBinding("aws","0850063486"),note:"Thing + least-privilege policy + MQTT topics + shadow, all keyed to the GIAI."},
          {label:"Azure IoT Hub",filename:"azure_device_twin.json",gen:()=>tdCloudBinding("azure","0850063486"),note:"Device twin with desired/reported split: driver + policy gate desired, certification reported."},
          {label:"GCP IoT",filename:"gcp_device.json",gen:()=>tdCloudBinding("gcp","0850063486"),note:"Registry/device + Pub/Sub topics per telemetry and EPCIS streams."},
          {label:"Edge (Greengrass/J1939)",filename:"edge_deployment.json",gen:()=>tdCloudBinding("edge","0850063486"),note:"The same published driver runs at the edge with offline policy enforcement and EPCIS store-and-forward."},
        ]}/>; } catch(_e){ return null; } })()}
      <LiveIDsBanner module="Cloud / Edge" />
      <div style={{fontSize:20,fontWeight:800,color:GD.dark,marginBottom:4}}>ThingDaddy Cloud / Edge — Run a Thing in Any Cloud</div>
      <div style={{fontSize:12,color:GD.gray,marginBottom:16}}>
        Pick a vendor to see unique code that maps your ThingDaddy identity, SiLA driver, and Allotrope events onto that platform's native primitives. {prefix?`Active prefix: ${prefix}.`:"Register a company to inject live URNs."}
      </div>

      {/* ── Multi-tenant deployment scenario ── */}
      <div style={{marginBottom:18,padding:"16px 18px",borderRadius:12,background:"linear-gradient(135deg,#0F172A,#1E293B)",border:`1px solid ${GD.green}33`}}>
        <div style={{fontSize:11,fontWeight:700,color:GD.green,letterSpacing:".08em",marginBottom:4}}>🏭 MULTI-TENANT DEPLOYMENT — ONE INSTRUMENT, ANY CLOUD</div>
        <div style={{fontSize:12,color:"rgba(255,255,255,.6)",marginBottom:12,lineHeight:1.5}}>
          A manufacturer sells the same instrument to many customers. Each customer picks their cloud — ThingDaddy keeps one identity (TD:GIAI) and auto-configures the deployment per platform.
        </div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          {SCENARIOS.map(sc=>{
            const vd = VENDORS.find(x=>x.id===sc.cloud);
            const sel = scenario?.id===sc.id;
            return (
              <button key={sc.id} onClick={()=>{
                  setScenario(sel?null:sc);
                  if(!sel){
                    const tv = VENDORS.find(x=>x.id===sc.cloud); setSelVendor(tv); setLayer("id");
                    // Provenance: this unique unit deployed to this cloud — into the graph
                    if(addProvenance) addProvenance({
                      type:"GIAI", epc:`urn:epc:id:giai:${sc.mfrPrefix}.${sc.serial}`,
                      source:"cloud_deploy", prefix:sc.mfrPrefix, company:sc.customer,
                      use:`${sc.instrument} → ${tv?.name}`, region:sc.region,
                    });
                  }
                }}
                style={{textAlign:"left",cursor:"pointer",border:`2px solid ${sel?vd?.color:"rgba(255,255,255,.12)"}`,
                  borderRadius:10,padding:"10px 12px",background:sel?(vd?.color+"22"):"rgba(255,255,255,.04)",
                  fontFamily:"inherit",minWidth:150,flex:"1 1 150px"}}>
                <div style={{fontSize:13,fontWeight:800,color:"#fff",marginBottom:3}}>{sc.customer}</div>
                <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:4}}>
                  <span style={{fontSize:13}}>{vd?.icon}</span>
                  <span style={{fontSize:10,fontWeight:700,color:vd?.color}}>{vd?.name}</span>
                </div>
                <div style={{fontSize:9,color:"rgba(255,255,255,.4)"}}>{sc.region}</div>
              </button>
            );
          })}
        </div>
        {scenario && (
          <div style={{marginTop:12,padding:"10px 14px",borderRadius:8,background:"rgba(255,255,255,.05)",border:"1px solid rgba(255,255,255,.08)"}}>
            <div style={{fontSize:11,color:"#fff",lineHeight:1.6}}>
              <strong style={{color:GD.green}}>{scenario.instrument}</strong> → <strong>{scenario.customer}</strong> on <strong style={{color:VENDORS.find(x=>x.id===scenario.cloud)?.color}}>{VENDORS.find(x=>x.id===scenario.cloud)?.name}</strong>
            </div>
            <div style={{fontSize:10,color:"rgba(255,255,255,.55)",marginTop:4,lineHeight:1.5}}>{scenario.note}</div>
            <div style={{fontSize:9,fontFamily:"monospace",color:"#22C55E",marginTop:6,wordBreak:"break-all"}}>
              Shared identity: {giai}
            </div>
            <div style={{fontSize:10,color:GD.green,marginTop:8,fontWeight:700}}>↓ Configured for {VENDORS.find(x=>x.id===scenario.cloud)?.name} — see mapping below</div>
          </div>
        )}
      </div>

      {/* Vendor cards */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(220px,1fr))",gap:12,marginBottom:18}}>
        {VENDORS.map(vd=>{
          const sel = selVendor?.id===vd.id;
          return (
            <div key={vd.id} onClick={()=>{ setSelVendor(sel?null:vd); setLayer("id"); }}
              style={{cursor:"pointer",padding:"14px 16px",borderRadius:10,
                background:sel?vd.color:GD.white,
                border:`2px solid ${sel?vd.color:"#E5E7EB"}`,transition:"all .15s"}}>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
                <span style={{fontSize:20}}>{vd.icon}</span>
                <span style={{fontSize:14,fontWeight:800,color:sel?vd.textColor:GD.dark}}>{vd.name}</span>
              </div>
              <div style={{display:"inline-block",fontSize:9,fontWeight:700,padding:"2px 8px",borderRadius:4,marginBottom:8,
                background:sel?"rgba(255,255,255,.25)":GD.offWhite,color:sel?vd.textColor:GD.gray}}>{vd.kind}</div>
              <div style={{fontSize:10,lineHeight:1.6,color:sel?vd.textColor:GD.gray}}>
                <div>📇 {vd.registry}</div>
                <div>🔌 {vd.sdk}</div>
                <div>📡 {vd.bus}</div>
              </div>
              <div style={{marginTop:8,fontSize:10,fontWeight:700,color:sel?vd.textColor:vd.color}}>
                {sel?"▾ showing mapping":"▸ tap to open"}
              </div>
            </div>
          );
        })}
      </div>

      {/* Selected vendor — three-layer mapping */}
      {v && (
        <div style={{borderRadius:12,overflow:"hidden",border:`2px solid ${v.color}`,marginBottom:16}}>
          <div style={{background:v.color,padding:"10px 16px",display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:18}}>{v.icon}</span>
            <span style={{fontSize:14,fontWeight:800,color:v.textColor}}>{v.name} — ThingDaddy semantic mapping</span>
          </div>

          {/* Layer tabs */}
          <div style={{display:"flex",background:GD.dark}}>
            {LAYER_TABS.map(t=>(
              <button key={t.id} onClick={()=>setLayer(t.id)}
                style={{flex:1,padding:"10px 8px",border:"none",cursor:"pointer",fontFamily:"inherit",
                  background:layer===t.id?v.color:"transparent",
                  color:layer===t.id?v.textColor:"rgba(255,255,255,.6)",
                  fontSize:11,fontWeight:700,borderBottom:layer===t.id?`2px solid ${v.textColor}`:"2px solid transparent"}}>
                {t.label}
              </button>
            ))}
          </div>
          <div style={{padding:"6px 16px",background:GD.dark,fontSize:10,color:"rgba(255,255,255,.5)"}}>
            {LAYER_TABS.find(t=>t.id===layer)?.hint}
          </div>

          {/* Code */}
          <div style={{position:"relative",background:"#0B1220"}}>
            <button onClick={()=>{ navigator.clipboard?.writeText(code); setCopied(true); setTimeout(()=>setCopied(false),1400); }}
              style={{position:"absolute",top:8,right:8,zIndex:2,padding:"4px 12px",borderRadius:6,border:"none",
                cursor:"pointer",fontFamily:"inherit",fontSize:10,fontWeight:700,background:v.color,color:v.textColor}}>
              {copied?"✓ Copied":"Copy"}
            </button>
            <pre style={{margin:0,padding:"16px 18px",fontSize:10,color:"#C8E0FF",fontFamily:"'Fira Code',monospace",
              lineHeight:1.6,overflow:"auto",maxHeight:420,whiteSpace:"pre"}}>{code}</pre>
          </div>
        </div>
      )}

      {/* Footer — function mapping matrix link */}
      <div style={{padding:"14px 16px",borderRadius:10,background:GD.dark,border:`1px solid ${GD.green}22`}}>
        <div style={{fontSize:11,fontWeight:700,color:GD.green,letterSpacing:".08em",marginBottom:8}}>
          ✨ EVERY THINGDADDY FUNCTION MAPS TO EVERY CLOUD — PICK A THING, RUN IT ANYWHERE
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:8}}>
          {[
            {icon:"🔑",label:"Generate IDs",mod:"ids"},
            {icon:"⚗️",label:"SiLA Driver",mod:"sdk"},
            {icon:"🧬",label:"Allotrope ADF",mod:"adf"},
            {icon:"🔌",label:"All SDK Drivers",mod:"sdk_drivers"},
          ].map(item=>(
            <button key={item.mod} onClick={()=>setActiveModule(item.mod)}
              style={{padding:"8px 10px",borderRadius:7,border:`1px solid ${GD.green}33`,background:"#111827",
                cursor:"pointer",fontFamily:"inherit",color:"#fff",display:"flex",alignItems:"center",gap:6,fontSize:11,fontWeight:600}}>
              <span>{item.icon}</span>{item.label}
            </button>
          ))}
        </div>
      </div>
    
      <StandardExplainer solutionKey="cloud"/>
      </div>
  );
}


