// Universal SiLA driver template — the "OS driver model" every industry shares.
const SILA_BASE_FEATURES = [
  {feature:"DeviceIdentificationProvider", generic:"GetDeviceIdentity", binds:"GIAI"},
  {feature:"CommandExecutionController",   generic:"RunMethod",         binds:"GDTI"},
  {feature:"DataPublisher",                generic:"DataPackage",       binds:"LGTIN"},
  {feature:"OperatorAuthentication",       generic:"Operator",          binds:"GSRN"},
  {feature:"ConsumableTracking",           generic:"Consumable",        binds:"CPI/LGTIN"},
  {feature:"AuditTrailProvider",           generic:"Audit",             binds:"EPCIS"},
];

function SemanticTemplateModule({ setActiveModule=()=>{} }) {
  const { ids, prefix, activeCompany } = useIDs();
  const pfx = prefix || "0085126";
  const [vocab, setVocab] = React.useState(INDUSTRY_VOCABULARIES[0]);
  const [tab, setTab] = React.useState("mapping"); // mapping | vocab | template
  const [copied, setCopied] = React.useState(false);

  const epc = (t)=> ids?.[t]?.epc || `urn:epc:id:${t.toLowerCase()}:${pfx}.PLACEHOLDER`;

  // Build the pre-built template (SiLA skeleton × industry vocabulary × GS1 bindings)
  const template = `# ════════════════════════════════════════════════════════════════
# ThingDaddy Pre-Built Driver Template
#   Framework : SiLA 2 (universal driver model — the "OS driver")
#   Industry  : ${vocab.name}
#   Standards : ${vocab.standards.join(", ")}
#   Vocabulary: industry-precise M2M terms (EDI-style: ${vocab.edi.join(", ")})
# ════════════════════════════════════════════════════════════════
from sila2.server import SilaServer, Feature
from dataclasses import dataclass

@dataclass
class ThingDaddyIdentity:
    # Registry-first: every binding anchored to a registered GS1 prefix (${pfx})
    giai:  str = "${epc('GIAI')}"      # the unique instrument (digital VIN)
    gdti:  str = "${epc('GDTI')}"      # controlling document
    lgtin: str = "${epc('LGTIN')}"     # consumable / reagent lot
    gsrn:  str = "${epc('GSRN')}"      # operator (industry-qualified)

class ${vocab.id.charAt(0).toUpperCase()+vocab.id.slice(1)}DriverTemplate(Feature):
    """SiLA 2 contract + ${vocab.name} semantic profile."""

${SILA_BASE_FEATURES.map(f=>{
  const term = vocab.vocab[f.generic] || f.generic;
  return `    def ${f.generic}(self):
        # SiLA: ${f.feature}
        # ${vocab.name} term  →  ${term}
        # GS1 binding         →  TD:${f.binds}
        ...`;
}).join("\n")}

    # Industry bizSteps (EPCIS) for ${vocab.name}:
    #   ${vocab.bizSteps.join(" → ")}
`;

  return (
    <div style={{padding:"24px 20px", maxWidth:1180, margin:"0 auto"}}>
      <CompanySearchHeader label="the industry template" accent={GD.purple} />
      <LiveIDsBanner module="Semantic Templates" />
      <div style={{marginBottom:16,padding:"16px 18px",borderRadius:12,background:"linear-gradient(135deg,#0F172A,#1E1B4B)",border:`1px solid ${vocab.color}44`}}>
        <div style={{fontSize:11,fontWeight:700,color:vocab.color,letterSpacing:".12em",marginBottom:4}}>PHASE 2 · SEMANTIC MAPPING + PRE-BUILT TEMPLATES</div>
        <div style={{fontSize:18,fontWeight:800,color:"#fff",marginBottom:6}}>SiLA = the universal driver. Each industry = its own M2M vocabulary.</div>
        <div style={{fontSize:12,color:"#94A3B8",lineHeight:1.6}}>
          Like Windows or macOS provide a driver framework while each device class speaks its own language, SiLA 2 is the universal contract — but Pharma, Aerospace, Automotive and Process each need precise vocabularies, exactly as EDI built X12/EDIFACT transaction sets per industry.
        </div>
      </div>

      {/* Industry selector */}
      <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:16}}>
        {INDUSTRY_VOCABULARIES.map(v=>(
          <button key={v.id} onClick={()=>setVocab(v)}
            style={{padding:"8px 14px",borderRadius:10,cursor:"pointer",fontFamily:"inherit",fontSize:12,fontWeight:700,
              border:`2px solid ${vocab.id===v.id?v.color:"#E5E7EB"}`,
              background:vocab.id===v.id?v.color:GD.white,color:vocab.id===v.id?"#fff":GD.gray,
              display:"flex",alignItems:"center",gap:6}}>
            <span style={{fontSize:15}}>{v.icon}</span>{v.name}
            {v.horizontal && <span style={{marginLeft:6,fontSize:8,fontWeight:800,padding:"1px 5px",borderRadius:3,background:vocab.id===v.id?"rgba(255,255,255,.3)":"#37415115",color:vocab.id===v.id?"#fff":"#374151",letterSpacing:".06em"}}>H+V</span>}
          </button>
        ))}
      </div>

      {/* Tabs */}
      <div style={{display:"flex",gap:0,marginBottom:14,borderBottom:`2px solid #E5E7EB`}}>
        {[["mapping","🔀 Semantic Mapping"],["vocab","📚 Industry Vocabulary"],["template","⚙️ Pre-Built Template"]].map(([id,label])=>(
          <button key={id} onClick={()=>setTab(id)}
            style={{padding:"9px 16px",border:"none",cursor:"pointer",fontFamily:"inherit",fontSize:12,fontWeight:700,
              background:"transparent",color:tab===id?vocab.color:GD.gray,
              borderBottom:tab===id?`2px solid ${vocab.color}`:"2px solid transparent",marginBottom:-2}}>
            {label}
          </button>
        ))}
      </div>

      {/* MAPPING — generic SiLA term → industry-precise term */}
      {tab==="mapping" && (
        <div>
          <div style={{fontSize:12,color:GD.gray,marginBottom:12}}>How the universal SiLA driver contract maps to {vocab.name}'s precise vocabulary and GS1 bindings:</div>
          <div style={{display:"grid",gap:8}}>
            {SILA_BASE_FEATURES.map(f=>(
              <div key={f.feature} style={{display:"grid",gridTemplateColumns:"1fr auto 1.4fr auto",gap:10,alignItems:"center",
                padding:"10px 14px",borderRadius:8,background:GD.white,border:"1px solid #E5E7EB"}}>
                <div>
                  <div style={{fontSize:9,color:GD.gray,letterSpacing:".06em"}}>SiLA 2 (universal)</div>
                  <div style={{fontSize:12,fontWeight:700,color:GD.dark,fontFamily:"monospace"}}>{f.generic}</div>
                  <div style={{fontSize:9,color:GD.grayLt}}>{f.feature}</div>
                </div>
                <div style={{fontSize:18,color:vocab.color}}>→</div>
                <div>
                  <div style={{fontSize:9,color:GD.gray,letterSpacing:".06em"}}>{vocab.name}</div>
                  <div style={{fontSize:12,fontWeight:700,color:vocab.color}}>{vocab.vocab[f.generic]||f.generic}</div>
                </div>
                <div style={{padding:"3px 8px",borderRadius:6,background:vocab.color+"18",color:vocab.color,fontSize:10,fontWeight:700,fontFamily:"monospace"}}>TD:{f.binds}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* VOCAB — standards, EDI analogues, ID types, bizSteps */}
      {tab==="vocab" && (
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
          {[
            ["📐 Standards & Frameworks", vocab.standards, vocab.color],
            ["📨 EDI / M2M Vocabularies", vocab.edi, "#D97706"],
            ["🔑 Primary GS1 ID Types", vocab.idTypes, GD.teal],
            ["📡 EPCIS bizSteps", vocab.bizSteps, GD.green],
          ].map(([title,items,c])=>(
            <div key={title} style={{padding:"14px 16px",borderRadius:10,background:GD.white,border:`1px solid ${c}33`,borderTop:`3px solid ${c}`}}>
              <div style={{fontSize:12,fontWeight:700,color:c,marginBottom:8}}>{title}</div>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {items.map(it=>(
                  <span key={it} style={{fontSize:10,fontWeight:600,padding:"3px 9px",borderRadius:6,background:c+"12",color:c,fontFamily: title.includes("ID Types")?"monospace":"inherit"}}>{it}</span>
                ))}
              </div>
            </div>
          ))}
          <div style={{gridColumn:"1 / -1",padding:"12px 16px",borderRadius:10,background:"#FFF7ED",border:"1px solid #FED7AA"}}>
            <div style={{fontSize:11,fontWeight:700,color:"#9A3412",marginBottom:4}}>📨 Why a precise vocabulary (the EDI lesson)</div>
            <div style={{fontSize:11,color:GD.gray,lineHeight:1.6}}>
              EDI proved machine-to-machine exchange needs exact, agreed vocabularies — you can't run a supply chain on a generic message. Each industry standardized its own transaction sets and code lists. ThingDaddy templates do the same for drivers: one SiLA framework, but {vocab.name} speaks {vocab.edi[0]} and reasons in {vocab.standards[0]} terms.
            </div>
          </div>
        </div>
      )}

      {/* TEMPLATE — the pre-built driver scaffold */}
      {tab==="template" && (
        <div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
            <div style={{fontSize:12,color:GD.gray}}>Pre-built SiLA 2 driver for <strong style={{color:vocab.color}}>{vocab.name}</strong> — vocabulary + GS1 bindings pre-wired, ready to fill.</div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>{navigator.clipboard?.writeText(template);setCopied(true);setTimeout(()=>setCopied(false),1400);}}
                style={{padding:"6px 14px",borderRadius:7,border:"none",cursor:"pointer",fontFamily:"inherit",fontSize:11,fontWeight:700,background:vocab.color,color:"#fff"}}>
                {copied?"✓ Copied":"Copy template"}</button>
              <button onClick={()=>setActiveModule("sdk")}
                style={{padding:"6px 14px",borderRadius:7,border:`1px solid ${vocab.color}`,cursor:"pointer",fontFamily:"inherit",fontSize:11,fontWeight:700,background:"transparent",color:vocab.color}}>
                Open in SiLA →</button>
            </div>
          </div>
          <pre style={{margin:0,padding:"16px 18px",borderRadius:10,background:"#0B1220",fontSize:10,color:"#C8E0FF",
            fontFamily:"'Fira Code',monospace",lineHeight:1.6,overflow:"auto",maxHeight:480,whiteSpace:"pre"}}>{template}</pre>
        </div>
      )}
    
      <StandardExplainer solutionKey="templates"/>
      </div>
  );
}


