// Resolve a prefix's issuing MO. Uses the first 3 digits (GS1 Prefix), honouring
// the implied leading zero for US/UPC-origin prefixes.
function gs1IssuingMO(prefix){
  const d = String(prefix||"").replace(/\D/g,"");
  if(!d) return null;
  const p3 = d.slice(0,3).padEnd(3,"0");
  const n = parseInt(p3,10);
  for(const r of GS1_PREFIX_MO){
    const lo = parseInt(r.lo.padEnd(3,"0"),10);
    const hi = parseInt(r.hi.padEnd(3,"9"),10);
    if(n>=lo && n<=hi) return { prefix3:p3, mo:r.mo, range:`${r.lo}–${r.hi}` };
  }
  return { prefix3:p3, mo:"Reserved / unassigned by GS1 Global Office", range:"—" };
}

// ── EPC Pure Identity URN schemes (TDS Release 2.1) ──────────────────────────
// Each entry: the canonical URN template + the fields after the company prefix.
// GID, USDOD, ADI, BIC are intentionally excluded — they have NO GS1 Company
// Prefix, so they cannot map to a GS1 element string or Digital Link.
const EPC_SCHEMES = [
  { id:"sgtin", key:"SGTIN", urn:"urn:epc:id:sgtin:{cp}.{itemRefWithIndicator}.{serial}", note:"Serialised GTIN — instance-level. Indicator digit prepends the item reference.", level:"instance" },
  { id:"sscc",  key:"SSCC",  urn:"urn:epc:id:sscc:{cp}.{serialRef}", note:"Serial Shipping Container Code — logistics unit.", level:"instance" },
  { id:"sgln",  key:"SGLN",  urn:"urn:epc:id:sgln:{cp}.{locationRef}.{extension}", note:"GLN with optional extension. Extension 0 = the location itself.", level:"instance" },
  { id:"giai",  key:"GIAI",  urn:"urn:epc:id:giai:{cp}.{assetRef}", note:"Individual asset — instance-level, no separate serial (the asset ref IS unique).", level:"instance" },
  { id:"grai",  key:"GRAI",  urn:"urn:epc:id:grai:{cp}.{assetType}.{serial}", note:"Returnable asset (e.g. a reusable pallet/tote).", level:"instance" },
  { id:"gdti",  key:"GDTI",  urn:"urn:epc:id:gdti:{cp}.{docType}.{serial}", note:"Document type identifier — serialised document.", level:"instance" },
  { id:"gsrn",  key:"GSRN",  urn:"urn:epc:id:gsrn:{cp}.{serviceRef}", note:"Service relation — recipient (e.g. a patient, a member).", level:"instance" },
  { id:"cpi",   key:"CPI",   urn:"urn:epc:id:cpi:{cp}.{componentRef}.{serial}", note:"Component / Part Identifier — technical parts.", level:"instance" },
  { id:"sgcn",  key:"SGCN",  urn:"urn:epc:id:sgcn:{cp}.{couponRef}.{serial}", note:"Serialised coupon.", level:"instance" },
  { id:"itip",  key:"ITIP",  urn:"urn:epc:id:itip:{cp}.{itemRefWithIndicator}.{piece}.{total}.{serial}", note:"Individual Trade Item Piece — one piece of a multi-piece item.", level:"instance" },
  { id:"upui",  key:"UPUI",  urn:"urn:epc:id:upui:{cp}.{itemRefWithIndicator}.{tpx}", note:"Unit Pack Identifier (e.g. tobacco track-and-trace).", level:"instance" },
  { id:"pgln",  key:"PGLN",  urn:"urn:epc:id:pgln:{cp}.{partyRef}", note:"Party GLN — identifies a legal entity / party.", level:"party" },
  { id:"lgtin", key:"LGTIN", urn:"urn:epc:class:lgtin:{cp}.{itemRefWithIndicator}.{lot}", note:"GTIN + batch/lot — CLASS-level (a lot, not one instance). Note urn:epc:CLASS, not id.", level:"class" },
];

// GMN is NOT an epc:id URN — it has no EPC form. Its web form is a Digital Link:
const GMN_ELEMENT_STRING = "(8013){cp}{modelRef}{checkPair}";   // GMN is a model number, carried as a class association — never an EPC, never a unique ID

// GS1 check digit (mod-10) — used to validate GTIN/GLN/SSCC numeric keys.
function gs1CheckDigit(numeric){
  const a = String(numeric).replace(/\D/g,"").split("").map(Number);
  let sum=0;
  for(let i=a.length-1, w=3; i>=0; i--, w=(w===3?1:3)) sum += a[i]*w;
  return ((10 - (sum%10)) % 10).toString();
}

// Validate an EPC pure-identity URN against TDS structure. Returns {ok, scheme, cp, fields, mo, errors}.
function decodeEPC(urn){
  const errors = [];
  const s = String(urn||"").trim();
  if(!s) return { ok:false, errors:["Empty input."] };
  // class vs id namespace
  const m = s.match(/^urn:epc:(id|class):([a-z]+):(.+)$/);
  if(!m) return { ok:false, errors:["Not a valid EPC URN. Expected urn:epc:id:<scheme>:... or urn:epc:class:lgtin:..."] };
  const [, ns, scheme, body] = m;
  const def = EPC_SCHEMES.find(x=>x.id===scheme);
  if(!def) return { ok:false, errors:[`Unknown or unsupported EPC scheme "${scheme}". GID/USDOD/ADI/BIC have no GS1 Company Prefix and are not supported.`] };
  if(scheme==="lgtin" && ns!=="class") errors.push("LGTIN is class-level — it must use urn:epc:class:lgtin, not urn:epc:id.");
  if(scheme!=="lgtin" && ns!=="id") errors.push(`${def.key} is instance/party-level — it must use urn:epc:id:${scheme}.`);
  const parts = body.split(".");
  const cp = parts[0] || "";
  if(!/^\d+$/.test(cp)) errors.push("Company Prefix must be numeric.");
  if(cp.length < 6 || cp.length > 12) errors.push(`Company Prefix length ${cp.length} is outside the GS1 range (6–12 digits).`);
  const mo = gs1IssuingMO(cp);
  // expected field count from template
  const expectedFields = (def.urn.match(/\{[^}]+\}/g)||[]).length;
  if(parts.length !== expectedFields) errors.push(`${def.key} expects ${expectedFields} dot-separated fields; found ${parts.length}.`);
  return { ok: errors.length===0, scheme:def, ns, cp, fields:parts.slice(1), mo, errors };
}


// ═══════════════════════════════════════════════════════════════════════════
// PRE-POPULATION FROM ANY GS1 ID  ·  decode → prefix → company → registration DRAFT
//
// ⚖️ This does NOT register anything. It produces a DRAFT for the customer to
// confirm/edit. Registration still happens ONLY via addParty, on confirm.
// "If a GTIN is all we have, we decode it back to a prefix, resolve the prefix
//  to a company, and pre-fill the form. Errors? The customer edits. Then they
//  register." — the elegant way to pre-populate ThingDaddy from 2M GEPIR rows.
// ═══════════════════════════════════════════════════════════════════════════

// Extract the GS1 Company Prefix from a RAW numeric key (GTIN-8/12/13/14, GLN-13,
// SSCC-18, GIAI/GRAI variable). Uses the GCP-length table where needed; for the
// common case we infer using the issuing-MO prefix-range + standard heuristics.
function prefixFromGS1Key(raw, gcpLenHint){
  const d = String(raw||"").replace(/\D/g,"");
  if(!d) return { ok:false, error:"No digits found." };
  let core = d, keyType = "unknown";
  // Identify by length
  if(d.length===14){ keyType="GTIN-14"; core=d.slice(1,13); }      // drop indicator + check
  else if(d.length===13){ keyType="GTIN-13 / GLN-13"; core=d.slice(0,12); } // drop check
  else if(d.length===12){ keyType="GTIN-12 (UPC-A)"; core=d.slice(0,11); }  // drop check
  else if(d.length===18){ keyType="SSCC-18"; core=d.slice(1,17); }  // drop ext digit + check
  else if(d.length>=7 && d.length<=30){ keyType="GIAI/GRAI/other (variable)"; core=d; }
  else return { ok:false, error:`Length ${d.length} doesn't match a known GS1 key.` };
  // GCP length: explicit hint, else infer. GS1 GCPs are 4–12 digits; default to a
  // best-guess of the longest sensible prefix the MO table recognises.
  let gcpLen = gcpLenHint && gcpLenHint>=4 && gcpLenHint<=12 ? gcpLenHint : null;
  let matchedCompany = null;
  if(!gcpLen){
    // BEST: a known company match tells us the EXACT prefix length. Walk 6→12 and
    // look for a prefix that a real registered/known company carries.
    for(let L=6; L<=12 && L<=core.length; L++){
      const cand = core.slice(0, L);
      try{
        if(typeof GS1_REGISTRY!=="undefined"){
          const hit = GS1_REGISTRY.find(c=>String(c.prefix).replace(/\D/g,"")===cand || String(c.altPrefix||"").replace(/\D/g,"")===cand);
          if(hit){ gcpLen=L; matchedCompany=hit.company; break; }
        }
      }catch(e){}
      try{
        if(typeof TATA_GROUP_SEED!=="undefined"){
          const e2 = TATA_GROUP_SEED.entities.find(e=>e.prefixes.some(x=>x===cand));
          if(e2){ gcpLen=L; matchedCompany=e2.name; break; }
        }
      }catch(e){}
    }
    // FALLBACK: no known company. We can identify the issuing MO but NOT the exact
    // GCP length from the number alone — that requires GEPIR's GCP-length table.
    // Mark it clearly so the customer confirms. Default to the GS1-common 7.
    if(!gcpLen){ gcpLen = Math.min(7, core.length); }
  }
  const prefix = core.slice(0, gcpLen);
  const mo = (typeof gs1IssuingMO==="function") ? gs1IssuingMO(prefix) : null;
  const lengthConfirmed = !!(gcpLenHint || matchedCompany);
  return { ok:true, keyType, prefix, gcpLen, mo, matchedCompany, lengthConfirmed, inferred: !lengthConfirmed, raw:d };
}

// Resolve a prefix (or a decoded key) to a company DRAFT, using whatever sources
// we have: the corporate-group seed, the GS1_REGISTRY directory, and — in
// production — the 2M-row GEPIR table + a website lookup. Returns a DRAFT only.
function companyDraftFromPrefix(prefix){
  const p = String(prefix||"").replace(/\D/g,"");
  if(!p) return null;
  // 1) Try the Tata corporate-group seed (real GEPIR licence data)
  try{
    if(typeof TATA_GROUP_SEED!=="undefined"){
      for(const e of TATA_GROUP_SEED.entities){
        if(e.prefixes.some(x=>x===p || p.startsWith(x) || x.startsWith(p))){
          return { orgName:e.name, company:e.name, prefix:p, group:"Tata Group", source:"GEPIR (Tata licence)", _draft:true };
        }
      }
    }
  }catch(e){}
  // 2) Try the GS1_REGISTRY public directory (name + GLN + website)
  try{
    if(typeof GS1_REGISTRY!=="undefined"){
      const hit = GS1_REGISTRY.find(c=>String(c.prefix).replace(/\D/g,"")===p || String(c.altPrefix||"").replace(/\D/g,"")===p);
      if(hit) return { orgName:hit.company, company:hit.company, prefix:p, gln:hit.gln, website:hit.website, country:hit.country, source:"GS1 GEPIR (directory)", _draft:true };
    }
  }catch(e){}
  // 3) Production: this is where the 2M-row GEPIR lookup + website resolver runs.
  //    We return a minimal draft so the customer can confirm/fill the rest.
  const mo = (typeof gs1IssuingMO==="function") ? gs1IssuingMO(p) : null;
  return { orgName:"", company:"", prefix:p, gln:p+"00000", mo, source:"GEPIR prefix lookup (unresolved — customer to confirm)", _draft:true };
}


// ═══════════════════════════════════════════════════════════════════════════
// CORPORATE GROUP REGISTRY  ·  Group → Entity → Prefix → GLN  (4 levels)
// A global conglomerate holds MANY GS1 Company Prefixes, issued by MANY GS1
// Member Organisations (countries). Membership in a group is ALWAYS user-asserted
// and provenance-tagged — NEVER inferred from a name. This is why "TATA'S PIEROGI
// CO." (a real GS1 licensee) is NOT Tata Group: only a deliberate, registry-rooted
// assertion binds an entity to a group. Identity is registry-rooted, not name-matched.
// Seed data below is REAL GS1 GEPIR data (gs1.org licence registry), India/UK/US.
// ═══════════════════════════════════════════════════════════════════════════

// Each prefix carries its real licence key (GS1 GEPIR "Licence Key"), the legal
