// ════════════════════════════════════════════════════════════════════════════════
// MODULE — POPULATION AGENT  ·  id: "population_agent"  ·  group: "identity"
// Filters GEPIR namesake noise into verified / candidate / rejected tiers, then
// fires addParty() ONLY on a verified row — connecting to manual/administrative
// registration (RegisterModule / RegisterAgent) rather than bypassing it.
// ════════════════════════════════════════════════════════════════════════════════

const POP_NAMESAKE = ["food","farm","rivet","greetings","medical","record","unilam","nongjajae","cookand","cook","trading","travel","motors"];
const POP_ELECTRONICS = ["electronics","sdi","electro-mechanics","electromechanics","semiconductor","display","foundry"];

// Worked example seed — the real GEPIR "Samsung" 305-result problem.
const POP_SEED = [
  { key:"8806088",       name:"SAMSUNG ELECTRONICS CO., LTD.", mo:"GS1 Korea",         gln:"8801643000011", verifiedAnchor:true, lei:"2038003BXBLQFRWCFO70" },
  { key:"6009802063",    name:"Samsung Electronics S A",       mo:"GS1 South Africa",  lei:"2038003BXBLQFRWCFO70" },
  { key:"8801234",       name:"SAMSUNG SDI CO., LTD.",         mo:"GS1 Korea",         lei:"9884000000000000SDI1" },
  { key:"880917009",     name:"SAMSUNG FOOD",                  mo:"GS1 Korea" },
  { key:"880936353",     name:"SAMSUNG RIVET",                 mo:"GS1 Korea" },
  { key:"880962309",     name:"Samsung Farm",                  mo:"GS1 Korea" },
  { key:"542502469",     name:"SAMSUNG",                       mo:"GS1 Belgium & Lux" },
  { key:"5990080135004", name:"Samsung Zrt.",                  mo:"GS1 Hungary" },
];

function popNormalize(name){
  let n = name.toLowerCase().replace(/[.,]/g," ").replace(/\s+/g," ").trim();
  ["co ltd","co.,ltd","co., ltd","ltd","inc","corp","corporation","zrt","s a","sa","gmbh"].forEach(s=>{
    if(n.endsWith(" "+s)) n=n.slice(0,-(s.length+1)).trim();
  });
  return n;
}
function popResolve(hit, homeMO, coreToken){
  const norm = popNormalize(hit.name);
  const toks = new Set(norm.split(/[\s&-]+/));
  const reasons=[]; let score=0;
  if(hit.verifiedAnchor) return { ...hit, norm, tier:"VERIFIED", score:1.0,
    reasons:["operator-confirmed GEPIR anchor","authority LEI "+(hit.lei||"-")],
    action:"federate via addParty()" };
  if(!toks.has(coreToken)) return { ...hit, norm, tier:"REJECTED", score:0, reasons:["missing core token '"+coreToken+"'"], action:"drop — out of scope" };
  const ns=[...toks].filter(t=>POP_NAMESAKE.includes(t)); if(ns.length){ reasons.push("namesake token: "+ns.join(", ")); score-=0.6; }
  const el=POP_ELECTRONICS.some(e=>norm.includes(e)); if(el){ reasons.push("operating-line token"); score+=0.5; }
  if(hit.mo===homeMO){ reasons.push(hit.mo+" band (consistent, not proof)"); score+=0.15; }
  else { reasons.push("non-home MO ("+hit.mo+")"); score-=0.35; }
  if(hit.lei){ reasons.push("GLEIF LEI confirms group member"); score+=0.5; reasons.push("prefix not a verified anchor — hold"); }
  const tier = score>=0.35 ? "CANDIDATE" : "REJECTED";
  const action = tier==="CANDIDATE" ? (hit.lei?"authority-confirmed; verify prefix then federate":"needs GEPIR + LEI confirmation") : "namesake — exclude";
  return { ...hit, norm, tier, score:Math.round(score*100)/100, reasons, action };
}

function PopulationAgentModule({ setActiveModule = () => {} }) {
  const { addParty, parties } = useIDs();
  const [target, setTarget] = useState("Samsung");
  const [homeMO, setHomeMO] = useState("GS1 Korea");
  const [useLEI, setUseLEI] = useState(true);
  const [rows, setRows] = useState(POP_SEED);

  const resolved = rows.map(h => popResolve(useLEI ? h : { ...h, lei: undefined }, homeMO, target.toLowerCase().split(" ")[0]));
  const counts = { VERIFIED:0, CANDIDATE:0, REJECTED:0 };
  resolved.forEach(r => counts[r.tier]++);
  const tierColor = t => t==="VERIFIED"?GD.green:t==="CANDIDATE"?"#B8860B":"#C0392B";

  const federate = (r) => {
    // ⚖️ UNBREAKABLE RULE: only a VERIFIED row (confirmed prefix) may register.
    if (r.tier !== "VERIFIED" || !r.key) return;
    if (typeof addParty === "function") {
      addParty({ orgName:r.name, company:r.name, prefix:r.key, gln:r.gln||"", country:"", sector:"",
        source:"Population Agent · GEPIR-verified" });
    }
  };

  const chip = (txt,clr)=>(
    <span style={{ display:"inline-block", padding:"2px 9px", borderRadius:999, background:clr+"18",
      color:clr, fontSize:11, fontWeight:700, border:`1px solid ${clr}44`, fontFamily:"monospace" }}>{txt}</span>
  );

  return (
    <div style={{ padding:"24px 20px", maxWidth:1000 }}>
      <LiveIDsBanner module="Population Agent · entity resolution → registration" />
      <div style={{ marginBottom:16 }}>
        <div style={{ fontSize:22, fontWeight:900, color:GD.dark, marginBottom:4 }}>
          🛰️ Population Agent — Which "{target}" is THE {target}?
        </div>
        <div style={{ fontSize:13, color:"#4B5563", lineHeight:1.6 }}>
          A GEPIR search for one large brand returns hundreds of different legal entities. This agent classifies each into
          verified / candidate / rejected tiers using name signals, GS1 MO band, and an LEI authority step (TD-M-50/51),
          then registers <b>only verified rows</b> through the same <code>addParty()</code> gate as manual registration.
          <span style={{ color:GD.teal, fontWeight:600 }}> Never guessed — verified-or-exception.</span>
        </div>
      </div>

      {/* controls */}
      <div style={{ display:"flex", gap:10, flexWrap:"wrap", alignItems:"center", marginBottom:16 }}>
        <input value={target} onChange={e=>setTarget(e.target.value)} placeholder="Target brand"
          style={{ padding:"8px 12px", borderRadius:8, border:"1px solid #E5E7EB", fontFamily:"inherit", fontSize:13 }} />
        <input value={homeMO} onChange={e=>setHomeMO(e.target.value)} placeholder="Home GS1 MO"
          style={{ padding:"8px 12px", borderRadius:8, border:"1px solid #E5E7EB", fontFamily:"inherit", fontSize:13, width:200 }} />
        <label style={{ fontSize:13, color:GD.dark, display:"flex", alignItems:"center", gap:6, cursor:"pointer" }}>
          <input type="checkbox" checked={useLEI} onChange={e=>setUseLEI(e.target.checked)} /> LEI authority step
        </label>
        {chip(counts.VERIFIED+" verified", GD.green)}
        {chip(counts.CANDIDATE+" candidate", "#B8860B")}
        {chip(counts.REJECTED+" rejected", "#C0392B")}
      </div>

      {["VERIFIED","CANDIDATE","REJECTED"].map(tier=>{
        const list = resolved.filter(r=>r.tier===tier);
        if(!list.length) return null;
        return (
          <div key={tier} style={{ marginBottom:18 }}>
            <div style={{ fontSize:13, fontWeight:800, color:tierColor(tier), textTransform:"uppercase", letterSpacing:1, marginBottom:8 }}>
              {tier} · {list.length}
            </div>
            <div style={{ display:"grid", gap:8 }}>
              {list.map((r,i)=>(
                <div key={i} style={{ background:GD.white, border:"1px solid #E5E7EB", borderLeft:`4px solid ${tierColor(r.tier)}`, borderRadius:8, padding:"12px 14px" }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", flexWrap:"wrap", gap:8 }}>
                    <div style={{ fontSize:14, fontWeight:800, color:GD.dark }}>{r.name}</div>
                    <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                      {chip(r.mo, r.mo===homeMO?GD.blue:"#6B7280")}
                      {chip("score "+(r.score>=0?"+":"")+r.score.toFixed(2), tierColor(r.tier))}
                    </div>
                  </div>
                  <div style={{ fontFamily:"monospace", fontSize:11, color:"#6B7280", marginTop:4 }}>
                    key {r.key}{r.lei?"  · LEI "+r.lei:""}
                  </div>
                  <div style={{ marginTop:6, display:"flex", flexWrap:"wrap", gap:5 }}>
                    {r.reasons.map((why,j)=>(
                      <span key={j} style={{ fontSize:11, color:GD.dark, background:"#F1F5F9", borderRadius:6, padding:"3px 8px" }}>{why}</span>
                    ))}
                  </div>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginTop:8, flexWrap:"wrap", gap:8 }}>
                    <div style={{ fontSize:12, color:tierColor(r.tier), fontWeight:700 }}>→ {r.action}</div>
                    {r.tier==="VERIFIED" && (
                      <button onClick={()=>federate(r)} style={{ padding:"6px 14px", borderRadius:8, border:"none",
                        background:GD.green, color:"#fff", fontFamily:"inherit", fontWeight:700, fontSize:12, cursor:"pointer" }}>
                        Register via addParty →
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      })}

      <div style={{ background:"#FEF3C7", border:"1px solid #F59E0B", borderRadius:8, padding:"12px 14px",
        fontSize:12, color:"#92400E", lineHeight:1.5 }}>
        <b>Connects to manual / administrative registration.</b> Registering a verified row fires the same
        <code> addParty()</code> gate used by the Register module and Register Agent — establishing the prefix,
        minting the 13 IDs, and making the entity live in the platform. Candidate and rejected rows are never
        registered; they await GEPIR/LEI confirmation or are excluded. {parties?.length ? `(${parties.length} entities registered so far.)` : ""}
      </div>
    </div>
  );
}



