// GSRN passport for an agent — deterministic from the active registered prefix.
function agentGSRN(prefix, agentId) {
  const p = prefix || "0085126";
  const serial = agentId.replace(/[^0-9]/g, "").padStart(9, "0");
  return `urn:epc:id:gsrn:${p}.${serial}`;
}

function AgentBuilderRegistryModule({ setActiveModule = () => {} }) {
  const { prefix, activeCompany, addProvenance } = useIDs();
  const [famFilter, setFamFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [sel, setSel] = useState(null);
  const activePrefix = activeCompany?.prefix || prefix;

  const counts = { build44:0, partial:0, designed:0, planned:0 };
  AGENT_REGISTRY.forEach(a => counts[a.status]++);

  const shown = AGENT_REGISTRY.filter(a =>
    (famFilter === "all" || a.fam === famFilter) &&
    (statusFilter === "all" || a.status === statusFilter));

  const chip = (txt, clr, bg) => (
    <span style={{ display:"inline-block", padding:"2px 9px", borderRadius:999, background:bg||clr+"18",
      color:clr, fontSize:11, fontWeight:700, border:`1px solid ${clr}44`, fontFamily:"monospace" }}>{txt}</span>
  );

  // "Build / issue passport" — an agent proposes; we log a governed provenance entry.
  // Registration of PARTIES still happens only via addParty (unbreakable rule) — this
  // issues the agent's own GSRN passport and records it, nothing mints around the gate.
  const issuePassport = (a) => {
    const gsrn = agentGSRN(activePrefix, a.id);
    if (typeof addProvenance === "function") {
      addProvenance({ type:"GSRN", epc:gsrn, gs1:"", source:`agent-passport:${a.id}`,
        prefix:activePrefix, company: activeCompany?.orgName || activeCompany?.company || null });
    }
    setSel({ ...a, gsrn, issued:true });
  };

  return (
    <div style={{ padding:"24px 20px", maxWidth:1150 }}>
      <CompanySearchHeader label="the agent fleet" accent={GD.orange} />
      <LiveIDsBanner module="Agent Builder Registry · 33 GSRN agents · TD-A-00–32 · verified-or-exception" />

      <div style={{ marginBottom:16 }}>
        <div style={{ fontSize:22, fontWeight:900, color:GD.dark, marginBottom:4 }}>
          🤖 ThingDaddy Agent Builder Registry
        </div>
        <div style={{ fontSize:13, color:"#4B5563", lineHeight:1.6 }}>
          The living per-agent log — 33 GSRN-identified agents across 9 families (F0–F8). Every agent carries a GSRN
          passport and is governed by verified-or-exception.
          <span style={{ color:GD.teal, fontWeight:600 }}> An agent proposes; nothing mints until it passes the gate.</span>
          {activeCompany && <span> Active prefix: <b>{activePrefix}</b> ({activeCompany.orgName || activeCompany.company}).</span>}
        </div>
      </div>

      {/* status counters */}
      <div style={{ display:"flex", gap:8, flexWrap:"wrap", marginBottom:14 }}>
        {chip(`${AGENT_REGISTRY.length} agents`, GD.dark, "#F1F5F9")}
        {Object.entries(counts).map(([k,v]) => chip(`${v} ${AGENT_STATUS[k].label}`, AGENT_STATUS[k].color, AGENT_STATUS[k].bg))}
      </div>

      {/* filters */}
      <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:8 }}>
        <button onClick={()=>setFamFilter("all")} style={{ padding:"5px 11px", borderRadius:20, fontSize:11, fontWeight:700,
          cursor:"pointer", fontFamily:"inherit", border:`1px solid ${famFilter==="all"?GD.dark:"#E5E7EB"}`,
          background:famFilter==="all"?GD.dark:"#fff", color:famFilter==="all"?"#fff":GD.dark }}>All families</button>
        {AGENT_FAMILIES.map(f=>(
          <button key={f.id} onClick={()=>setFamFilter(f.id)} title={f.label}
            style={{ padding:"5px 11px", borderRadius:20, fontSize:11, fontWeight:700, cursor:"pointer", fontFamily:"inherit",
              border:`1px solid ${famFilter===f.id?f.color:"#E5E7EB"}`, background:famFilter===f.id?f.color:"#fff",
              color:famFilter===f.id?"#fff":f.color }}>{f.id}</button>
        ))}
      </div>
      <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:16 }}>
        <button onClick={()=>setStatusFilter("all")} style={{ padding:"4px 10px", borderRadius:20, fontSize:10, fontWeight:700,
          cursor:"pointer", fontFamily:"inherit", border:`1px solid ${statusFilter==="all"?GD.dark:"#E5E7EB"}`,
          background:statusFilter==="all"?GD.dark:"#fff", color:statusFilter==="all"?"#fff":GD.dark }}>All status</button>
        {Object.entries(AGENT_STATUS).map(([k,s])=>(
          <button key={k} onClick={()=>setStatusFilter(k)} style={{ padding:"4px 10px", borderRadius:20, fontSize:10, fontWeight:700,
            cursor:"pointer", fontFamily:"inherit", border:`1px solid ${statusFilter===k?s.color:"#E5E7EB"}`,
            background:statusFilter===k?s.color:"#fff", color:statusFilter===k?"#fff":s.color }}>{s.label}</button>
        ))}
      </div>

      {/* registry grouped by family */}
      {AGENT_FAMILIES.filter(f => famFilter==="all" || f.id===famFilter).map(fam=>{
        const list = shown.filter(a=>a.fam===fam.id);
        if(!list.length) return null;
        return (
          <div key={fam.id} style={{ marginBottom:18 }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:8 }}>
              {chip(fam.id, fam.color)}
              <div style={{ fontSize:14, fontWeight:800, color:GD.dark }}>{fam.label}</div>
            </div>
            <div style={{ display:"grid", gap:8 }}>
              {list.map(a=>{
                const s = AGENT_STATUS[a.status];
                return (
                  <div key={a.id} style={{ background:GD.white, border:"1px solid #E5E7EB", borderLeft:`4px solid ${fam.color}`,
                    borderRadius:8, padding:"11px 14px" }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", flexWrap:"wrap", gap:8 }}>
                      <div style={{ display:"flex", alignItems:"baseline", gap:8, flexWrap:"wrap" }}>
                        <span style={{ fontFamily:"monospace", fontSize:12, fontWeight:800, color:fam.color }}>{a.id}</span>
                        <span style={{ fontSize:14, fontWeight:800, color:GD.dark }}>{a.name}</span>
                        {a.ip && chip("IP", GD.purple)}
                      </div>
                      {chip(s.label, s.color, s.bg)}
                    </div>
                    <div style={{ fontSize:12, color:"#4B5563", marginTop:5, fontFamily:"monospace" }}>{a.io}</div>
                    <div style={{ display:"flex", gap:8, marginTop:8, flexWrap:"wrap" }}>
                      <button onClick={()=>issuePassport(a)} style={{ padding:"5px 12px", borderRadius:7, border:"none",
                        background:GD.orange, color:"#fff", fontFamily:"inherit", fontWeight:700, fontSize:11, cursor:"pointer" }}>
                        Issue GSRN passport
                      </button>
                      {a.link && (
                        <button onClick={()=>setActiveModule(a.link)} style={{ padding:"5px 12px", borderRadius:7,
                          border:`1px solid ${fam.color}`, background:"#fff", color:fam.color, fontFamily:"inherit",
                          fontWeight:700, fontSize:11, cursor:"pointer" }}>
                          Open live module →
                        </button>
                      )}
                    </div>
                    {sel && sel.id===a.id && sel.issued && (
                      <div style={{ marginTop:8, padding:"8px 12px", borderRadius:7, background:"#E8F7EA",
                        border:"1px solid #3DB54A55", fontFamily:"monospace", fontSize:11, color:"#166534", wordBreak:"break-all" }}>
                        ✓ passport issued: {sel.gsrn}
                        <div style={{ color:"#4B5563", marginTop:2 }}>governed by verified-or-exception · logged to provenance</div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}

      <div style={{ background:"#FEF3C7", border:"1px solid #F59E0B", borderRadius:8, padding:"12px 14px",
        fontSize:12, color:"#92400E", lineHeight:1.5, marginTop:6 }}>
        <b>The unbreakable rule holds for agents too.</b> Issuing a passport gives an agent a GSRN identity and scoped
        rights; it does <b>not</b> let the agent register a party around the gate. Party registration still happens only
        through <code>addParty()</code> (Register Agent TD-A-12, Population Agent TD-A-05, Demo Builder TD-A-30). Agents in
        families F1–F4 stage candidates and propose; F2 verifies; nothing mints until an entity passes verified-or-exception.
        [IP] agents (TD-A-15/18/27) are candidate inventions in the IP Capture Log (IP-C-07–10).
      </div>
    </div>
  );
}



